/**
 * Retrieve orders for a specific user with optional filters.
 *
 * @param {number|string} userId   - The user identifier.
 * @param {string|null}   status   - Optional order status to filter by.
 * @param {string|Date|null} fromDate - Optional start date (inclusive) for created_at.
 * @returns {Promise<Array>}       - Resolves to an array of order rows.
 */
async function getUserOrders(userId, status = null, fromDate = null) {
  // Base query
  let sql = 'SELECT * FROM `orders` WHERE `user_id` = ?';
  const params = [userId];

  // Optional status filter
  if (status !== null && status !== undefined && status !== '') {
    sql += ' AND `status` = ?';
    params.push(status);
  }

  // Optional date filter (created_at >= fromDate)
  if (fromDate !== null && fromDate !== undefined && fromDate !== '') {
    // Ensure a proper MySQL datetime string
    const dateStr = fromDate instanceof Date
      ? fromDate.toISOString().slice(0, 19).replace('T', ' ')
      : fromDate; // assume caller passes a valid 'YYYY-MM-DD HH:MM:SS' string
    sql += ' AND `created_at` >= ?';
    params.push(dateStr);
  }

  // Execute using the existing pool (assumed to be a mysql2/promise pool)
  const [rows] = await pool.execute(sql, params);
  return rows;
}
