import sqlite3
import hashlib
import os

DB_PATH = 'users.db'

def _get_conn():
    return sqlite3.connect(DB_PATH)

def init_db():
    with _get_conn() as conn:
        conn.execute('''
            CREATE TABLE IF NOT EXISTS users (
                username TEXT PRIMARY KEY,
                password_hash TEXT NOT NULL,
                salt TEXT NOT NULL
            )
        ''')
        conn.commit()

def _hash_password(password: str, salt: bytes = None) -> tuple:
    if salt is None:
        salt = os.urandom(16)
    hash_obj = hashlib.pbkdf2_hmac('sha256', password.encode(), salt, 100000)
    return salt.hex(), hash_obj.hex()

def _verify_password(stored_salt_hex: str, stored_hash_hex: str, password: str) -> bool:
    salt = bytes.fromhex(stored_salt_hex)
    _, computed_hash = _hash_password(password, salt)
    return computed_hash == stored_hash_hex

def register_user(username: str, password: str) -> bool:
    """Store new user. Returns True on success, False if username exists."""
    init_db()
    salt_hex, hash_hex = _hash_password(password)
    try:
        with _get_conn() as conn:
            conn.execute(
                'INSERT INTO users (username, password_hash, salt) VALUES (?, ?, ?)',
                (username, hash_hex, salt_hex)
            )
            conn.commit()
        return True
    except sqlite3.IntegrityError:
        return False

def login(username: str, password: str) -> bool:
    """Return True if credentials match a stored user."""
    init_db()
    with _get_conn() as conn:
        row = conn.execute(
            'SELECT password_hash, salt FROM users WHERE username = ?',
            (username,)
        ).fetchone()
    if not row:
        return False
    stored_hash, stored_salt = row
    return _verify_password(stored_salt, stored_hash, password)

