import secrets
import time

# In-memory token store: {token: (user_id, timestamp)}
_token_store = {}

TOKEN_EXPIRY_SECONDS = 3600  # 1 hour


def create_reset_token(user_id: int) -> str:
    """Generate a secure reset token and store it with the user_id and current timestamp."""
    token = secrets.token_urlsafe(32)
    _token_store[token] = (user_id, time.time())
    return token


def verify_reset_token(token: str) -> int | None:
    """Verify token exists and is not expired. Return user_id if valid, else None."""
    if token not in _token_store:
        return None

    user_id, created_at = _token_store[token]

    if time.time() - created_at > TOKEN_EXPIRY_SECONDS:
        del _token_store[token]  # Clean up expired token
        return None

    return user_id


def invalidate_token(token: str) -> bool:
    """Remove a token after successful password reset. Returns True if token existed."""
    if token in _token_store:
        del _token_store[token]
        return True
    return False

