import secrets
import time
from typing import Optional

# In-memory token store: token -> {"user_id": int, "created_at": float}
_token_store: dict[str, dict] = {}

TOKEN_EXPIRY_SECONDS = 3600  # 1 hour


def create_reset_token(user_id: int) -> str:
    """Generate a secure reset token and store it with timestamp."""
    token = secrets.token_urlsafe(32)
    _token_store[token] = {
        "user_id": user_id,
        "created_at": time.time()
    }
    return token


def verify_reset_token(token: str) -> Optional[int]:
    """Verify token exists and isn't expired. Returns user_id or None."""
    data = _token_store.get(token)
    if not data:
        return None

    if time.time() - data["created_at"] > TOKEN_EXPIRY_SECONDS:
        # Clean up expired token
        del _token_store[token]
