    // Explicitly select columns; avoid SELECT * in production.
    // We NEED the password_hash to verify.
    const result = await client.query(
      'SELECT id, email, password_hash, name FROM users WHERE email = $1',
      [email.toLowerCase().trim()]
    );

    const user = result.rows[0];

    // 2. User not found -> Generic 401 (prevents user enumeration)
    if (!user) {
      // Optional: Run a dummy bcrypt compare to prevent timing attacks
      await bcrypt.compare(password, '$2b$10$dummyhashdummyhashdummyhashdummyhashdummy'); 
      return res.status(401).json({ message: 'Invalid credentials' });
