```js
// POST /login – authenticate a user against the `users` table
// Expects JSON body: { email: string, password: string }
// Returns 200 + user object on success, 401 on failure

const express = require('express');
const router = express.Router();

// `pool` is assumed to be a pre‑configured pg.Pool instance
router.post('/login', async (req, res) => {
  const { email, password } = req.body;

  // Basic validation
  if (!email || !password) {
    return res.status(400).json({ error: 'Email and password are required' });
  }

  try {
    // Look up the user by email
    const result = await pool.query(
      'SELECT id, email, password_hash, name FROM users WHERE email = $1',
      [email]
    );

    if (result.rowCount === 0) {
      // No user found
      return res.status(401).json({ error: 'Invalid credentials' });
    }

    const user = result.rows[0];

    // Compare the supplied password with the stored hash
    // (Assuming you use bcrypt – adjust if you use another hashing lib)
    const bcrypt = require('bcrypt');
    const match = await bcrypt.compare(password, user.password_hash);

    if (!match) {
      return res.status(401).json({ error: 'Invalid credentials' });
    }

    // Authentication successful – omit the hash from the response
    const { password_hash, ...safeUser } = user;
    return res.status(200).json(safeUser);
  } catch (err) {
    console.error('Login error:', err);
    return res.status(500).json({ error: 'Internal server error' });
  }
});

module.exports = router;
