### Required: `config.php`
Create this file in the same directory. **Never commit this to public Git repos.**

```php
<?php
// config.php
session_start(); // Start session immediately

// Database Credentials (Use Environment Variables in production!)
$host       = '127.0.0.1';
$dbname     = 'your_database_name';
$charset    = 'utf8mb4';
$username   = 'db_user';
$password   = 'db_password';

// PDO DSN
$dsn = "mysql:host=$host;dbname=$dbname;charset=$charset";

$options = [
    PDO::ATTR_ERRMODE            => PDO::ERRMODE_EXCEPTION, // Throw exceptions on errors
    PDO::ATTR_DEFAULT_FETCH_MODE => PDO::FETCH_ASSOC,       // Return associative arrays
    PDO::ATTR_EMULATE_PREPARES   => false,                  // Use native prepared statements
];

try {
    $pdo = new PDO($dsn, $username, $password, $options);
} catch (PDOException $e) {
    // In production, log this and show a generic "Site Maintenance" page
    die("Database connection failed: " . $e->getMessage());
}

// --- Session Security Configuration (Must be before session_start() ideally, but works here if first run) ---
// Note: session_start() is called above. 
// For these cookie params to apply reliably on *first* load, set them in php.ini or .user.ini:
// session.cookie_httponly = 1
// session.cookie_secure = 1 (Requires HTTPS)
// session.cookie_samesite = "Lax" (or "Strict")
ini_set('session.cookie_httponly', 1);
ini_set('session.cookie_samesite', 'Lax');
// ini_set('session.cookie_secure', 1); // Uncomment ONLY if running on HTTPS
```

