<?php
// 1. Configuration & Setup
require_once __DIR__ . '/config.php'; // See example below for contents

// Security: Set secure session cookie parameters BEFORE session_start()
// Note: 'secure => true' requires HTTPS. Set to false if testing locally on HTTP.
session_set_cookie_params([
    'lifetime' => 0,
    'path' => '/',
    'domain' => '', // Set your domain in production
    'secure' => isset($_SERVER['HTTPS']), // True on HTTPS
    'httponly' => true, // Prevents JavaScript access
    'samesite' => 'Lax' // CSRF protection
]);

session_start();

// 2. Only process POST requests
if ($_SERVER['REQUEST_METHOD'] !== 'POST') {
    // If accessed via GET, redirect to login form (or show form here)
    header('Location: login.php');
    exit;
}

// 3. Input Validation
$username = trim($_POST['username'] ?? '');
$password = $_POST['password'] ?? ''; // Do not trim passwords (spaces can be valid)

$errors = [];

if ($username === '') {
    $errors[] = 'Username is required.';
}
if ($password === '') {
    $errors[] = 'Password is required.';
}

// 4. Database Lookup & Verification
if (empty($errors)) {
    try {
        // Prepare statement: Select only necessary columns
        $sql = "SELECT id, username, password FROM users WHERE username = :username LIMIT 1";
        $stmt = $pdo->prepare($sql);
        $stmt->execute([':username' => $username]);
        $user = $stmt->fetch(PDO::FETCH_ASSOC);

        // Verify user exists AND password matches
        // password_verify handles the hash comparison securely (timing safe)
        if ($user && password_verify($password, $user['password'])) {

            // 5. Regenerate Session ID (Prevents Session Fixation)
            session_regenerate_id(true);

            // 6. Store User Data in Session
            // Store minimal info: ID and Username. Avoid storing roles/perms if they change often; fetch those on demand.
            $_SESSION['user_id'] = (int)$user['id'];
            $_SESSION['username'] = $user['username'];
            $_SESSION['logged_in'] = true;
            $_SESSION['last_activity'] = time(); // For idle timeout logic

            // Optional: Update "last_login" timestamp in DB
            // $upd = $pdo->prepare("UPDATE users SET last_login = NOW() WHERE id = ?");
            // $upd->execute([$user['id']]);

            // 7. Redirect to Dashboard
            header('Location: dashboard.php');
            exit;

        } else {
            // Generic error message (Don't reveal if user exists or not)
            $errors[] = 'Invalid username or password.';
        }

    } catch (PDOException $e) {
        // Log the actual error server-side, show generic message to user
        error_log("Login DB Error: " . $e->getMessage());
        $errors[] = 'An system error occurred. Please try again later.';
    }
}

// 8. Failure: Redirect back to login with errors
// Store errors in session to display on the login form page
$_SESSION['login_errors'] = $errors;
// Preserve username input so user doesn't have to retype (optional)
$_SESSION['old_username'] = $username; 

header('Location: login.php');
exit;
