// 2. Secure Session Configuration (Must be before session_start())
ini_set('session.use_strict_mode', $config['session']['use_strict_mode'] ? '1' : '0');
ini_set('session.cookie_httponly', $config['session']['cookie_httponly'] ? '1' : '0');
ini_set('session.cookie_secure', $config['session']['cookie_secure'] ? '1' : '0');
ini_set('session.cookie_samesite', $config['session']['cookie_samesite']);
ini_set('session.cookie_lifetime', $config['session']['cookie_lifetime']);

// 3. Start Session
session_start();

// 4. Only Process POST Requests
if ($_SERVER['REQUEST_METHOD'] !== 'POST') {
    // If accessed via GET, redirect to login form (or show form here)
    header('Location: login.php'); 
    exit;
}

// 5. Input Validation
$username = trim($_POST['username'] ?? '');
$password = $_POST['password'] ?? ''; // Do not trim passwords (spaces can be valid)

$errors = [];

if ($username === '') {
    $errors[] = 'Username is required.';
}
if ($password === '') {
    $errors[] = 'Password is required.';
}

// 6. Database Connection & Authentication
if (empty($errors)) {
    try {
        // Build DSN
        $dsn = "mysql:host={$config['db']['host']};dbname={$config['db']['dbname']};charset={$config['db']['charset']}";
        $options = [
            PDO::ATTR_ERRMODE            => PDO::ERRMODE_EXCEPTION,
            PDO::ATTR_DEFAULT_FETCH_MODE => PDO::FETCH_ASSOC,
            PDO::ATTR_EMULATE_PREPARES   => false, // Use native prepared statements
        ];

        $pdo = new PDO($dsn, $config['db']['user'], $config['db']['pass'], $options);

        // Lookup user by username
        $stmt = $pdo->prepare('SELECT id, username, password FROM users WHERE username = :username LIMIT 1');
        $stmt->execute([':username' => $username]);
        $user = $stmt->fetch();

        // Verify User Exists & Password Matches
        // password_verify handles the hash comparison securely (timing safe)
        if ($user && password_verify($password, $user['password'])) {

            // --- LOGIN SUCCESS ---

            // 1. Regenerate Session ID (Prevents Session Fixation)
            session_regenerate_id(true);

            // 2. Store User Data in Session
            // Only store non-sensitive identifiers
            $_SESSION['user_id'] = $user['id'];
            $_SESSION['username'] = $user['username'];
            $_SESSION['logged_in'] = true;
            $_SESSION['last_activity'] = time(); // Optional: for idle timeout logic

            // 3. Redirect to Dashboard
            header('Location: dashboard.php');
            exit;

        } else {
            // Generic error message (Don't reveal if user exists or not)
            $errors[] = 'Invalid username or password.';
        }

    } catch (PDOException $e) {
        // Log the actual error for debugging (do not show to user)
        error_log('Login DB Error: ' . $e->getMessage());
        $errors[] = 'An system error occurred. Please try again later.';
    }
}

// 7. Handle Failure: Redirect back to login with error
// We use the session to flash the error message (PRG Pattern: Post-Redirect-Get)
if (!empty($errors)) {
    $_SESSION['login_errors'] = $errors;
    header('Location: login.php');
    exit;
}
