Here is a complete, secure `login.php` script. It handles **both** displaying the login form (GET) and processing the submission (POST) in a single file.

### `login.php`

```php
<?php
// 1. Configuration & Setup
require_once __DIR__ . '/config.php'; // See note below for config.php contents

// Start session securely *before* any output
// Ensure session cookie settings are secure (HTTPS required for 'secure' => true)
$sessionOptions = [
    'cookie_httponly' => true,
    'cookie_secure'   => isset($_SERVER['HTTPS']), // True only on HTTPS
    'cookie_samesite' => 'Lax',
    'use_strict_mode' => true,
];
session_start($sessionOptions);

// 2. Handle POST Request (Login Attempt)
if ($_SERVER['REQUEST_METHOD'] === 'POST') {
    // Validate CSRF Token (Prevents Cross-Site Request Forgery)
    if (!hash_equals($_SESSION['csrf_token'] ?? '', $_POST['csrf_token'] ?? '')) {
        die('Invalid CSRF token.');
    }

    $username = trim($_POST['username'] ?? '');
    $password = $_POST['password'] ?? ''; // Do not trim passwords (spaces can be valid)

    $errors = [];

    // Basic Validation
    if ($username === '') $errors[] = 'Username is required.';
    if ($password === '') $errors[] = 'Password is required.';

    if (empty($errors)) {
        try {
            // 3. Database Lookup (Prepared Statement)
            $sql = "SELECT id, username, password_hash FROM users WHERE username = :username LIMIT 1";
            $stmt = $pdo->prepare($sql);
            $stmt->execute([':username' => $username]);
            $user = $stmt->fetch(PDO::FETCH_ASSOC);

            // 4. Verify Password
            // password_verify handles the hash comparison securely (timing safe)
            if ($user && password_verify($password, $user['password_hash'])) {

                // 5. Regenerate Session ID (Prevents Session Fixation)
                session_regenerate_id(true);

                // 6. Store User Data in Session
                $_SESSION['user_id']    = (int)$user['id'];
                $_SESSION['username']   = $user['username'];
                $_SESSION['logged_in']  = true;
                $_SESSION['last_activity'] = time();

                // 7. Redirect to Dashboard
                header('Location: dashboard.php');
                exit;

            } else {
                // Generic error message to prevent User Enumeration
                $errors[] = 'Invalid username or password.';
            }

        } catch (PDOException $e) {
            // Log the actual error for debugging (do not show to user)
            error_log("Login DB Error: " . $e->getMessage());
            $errors[] = 'A system error occurred. Please try again later.';
        }
    }

    // 8. Failure: Redirect back to self with error
    // We store errors in session to survive the redirect (PRG Pattern)
    $_SESSION['login_errors'] = $errors;
    // Preserve username input for convenience (sanitized for HTML output later)
    $_SESSION['old_username'] = htmlspecialchars($username, ENT_QUOTES, 'UTF-8');

    header('Location: login.php');
    exit;
}

// 9. Handle GET Request (Display Form)
// Retrieve errors/old input from session (flashing)
$errors = $_SESSION['login_errors'] ?? [];
$oldUsername = $_SESSION['old_username'] ?? '';

// Clear flash data immediately after reading
unset($_SESSION['login_errors'], $_SESSION['old_username']);

// Generate CSRF Token for the form
if (empty($_SESSION['csrf_token'])) {
    $_SESSION['csrf_token'] = bin2hex(random_bytes(32));
}
$csrfToken = $_SESSION['csrf_token'];
?>

