class SessionStore:
    def __init__(self, ttl_seconds: int = 86400):
        self._store: dict[str, tuple[str, float]] = {}
        self._ttl = ttl_seconds
        self._lock = Lock()

    def _now(self) -> float:
        return time.time()

    def _is_expired(self, expiry: float) -> bool:
        return self._now() > expiry

    def _cleanup_expired(self) -> None:
        now = self._now()
        expired = [sid for sid, (_, exp) in self._store.items() if exp < now]
        for sid in expired:
            del self._store[sid]

    def create(self, user_id: str) -> str:
        with self._lock:
            self._cleanup_expired()
            session_id = uuid.uuid4().hex
            expiry = self._now() + self._ttl
            self._store[session_id] = (user_id, expiry)
            return session_id

    def get_user(self, session_id: str) -> str | None:
        with self._lock:
            if session_id not in self._store:
                return None
            user_id, expiry = self._store[session_id]
            if self._is_expired(expiry):
                del self._store[session_id]
                return None
            return user_id

    def destroy(self, session_id: str) -> None:
        with self._lock:
            self._store.pop(session_id, None)

