function hashToken(token) {
  return crypto.createHash('sha256').update(token).digest('hex');
}

// Set remember-me cookie on successful login
async function setRememberCookie(res, userId) {
  const token = generateRememberToken();
  const tokenHash = hashToken(token);
  const expiresAt = new Date(Date.now() + 30 * 24 * 60 * 60 * 1000); // 30 days

  // Store hashed token in database (assumes users table has remember_token_hash and remember_expires columns)
  await db.updateUserRememberToken(userId, tokenHash, expiresAt);

  // Set httpOnly, secure, sameSite cookie
  res.cookie('remember_me', token, {
    httpOnly: true,
    secure: process.env.NODE_ENV === 'production',
    sameSite: 'lax',
    maxAge: 30 * 24 * 60 * 60 * 1000,
    path: '/'
  });
