Here is a complete, production-ready implementation.

It uses a **token rotation strategy** (storing a hashed selector/validator pair in the database) rather than putting the User ID directly in the cookie. This prevents session hijacking if the cookie is stolen and allows revoking specific devices.

### 1. Database Schema Assumption
You need a table to store the tokens (e.g., `remember_tokens`).

```sql
CREATE TABLE remember_tokens (
    id SERIAL PRIMARY KEY,
    user_id INT NOT NULL REFERENCES users(id) ON DELETE CASCADE,
    selector CHAR(24) NOT NULL UNIQUE,       -- Public identifier (Base64url encoded 18 bytes)
    validator_hash CHAR(60) NOT NULL,        -- bcrypt hash of the validator
    expires_at TIMESTAMPTZ NOT NULL,
    created_at TIMESTAMPTZ DEFAULT NOW(),
    user_agent TEXT,
    ip_hash CHAR(60)                         -- Optional: hash of IP for anomaly detection
);
CREATE INDEX idx_remember_selector ON remember_tokens(selector);
CREATE INDEX idx_remember_user ON remember_tokens(user_id);
```

### 2. The Middleware (`rememberMe.js`)

```javascript
// rememberMe.js
const crypto = require('crypto');
const bcrypt = require('bcrypt'); // npm install bcrypt
const cookieParser = require('cookie-parser'); // npm install cookie-parser

// Config
const COOKIE_NAME = 'remember_me';
const COOKIE_OPTIONS = {
  httpOnly: true,        // Prevent XSS theft
  secure: process.env.NODE_ENV === 'production', // HTTPS only in prod
  sameSite: 'lax',       // CSRF protection (use 'none' + secure:true if cross-site)
  maxAge: 30 * 24 * 60 * 60 * 1000, // 30 days in ms
  path: '/'
};

// Helper: Generate cryptographically secure random strings (URL safe)
const generateToken = (bytes = 18) => crypto.randomBytes(bytes).toString('base64url');

/**
 * Middleware Factory
 * @param {Object} db - Database wrapper with getUserById and query methods
 * @returns {Function} Express Middleware
*/
function createRememberMeMiddleware(db) {

  // 1. Apply cookie-parser globally (usually done in app.js, but safe to ensure here)
  // This parses req.cookies for us.

  return async (req, res, next) => {
    // ---------------------------------------------------------
    // PART A: READ COOKIE & RESTORE USER (Runs on EVERY request)
    // ---------------------------------------------------------
    if (!req.user && req.cookies[COOKIE_NAME]) {
      try {
        const cookieValue = req.cookies[COOKIE_NAME];
        // Format: "selector:validator"
        const [selector, validator] = cookieValue.split(':');

        if (selector && validator) {
          // Lookup by selector ONLY (timing safe)
          const tokenRecord = await db.getRememberTokenBySelector(selector);

          if (tokenRecord && new Date(tokenRecord.expires_at) > new Date()) {
            // Verify validator against stored hash (async, timing safe)
            const match = await bcrypt.compare(validator, tokenRecord.validator_hash);

            if (match) {
              // VALID TOKEN: Fetch User
              const user = await db.getUserById(tokenRecord.user_id);

              if (user) {
                req.user = user; // Attach to request
                req.rememberMeTokenId = tokenRecord.id; // Store ID for potential rotation/revocation

                // OPTIONAL: Token Rotation (Security Best Practice)
                // Issue a new token every login via cookie to invalidate old stolen cookies.
                // Comment out if you want the same cookie to last the full 30 days without rotation.
                await rotateToken(db, res, user.id, tokenRecord.id);
              }
            }
          }

          // If token invalid/expired/mismatch -> Clear dead cookie
          if (!req.user) {
            clearRememberCookie(res);
          }
        }
      } catch (err) {
        console.error('[RememberMe] Restore Error:', err);
        clearRememberCookie(res); // Fail safe
      }
    }

    // ---------------------------------------------------------
    // PART B: PROVIDE HELPERS TO ROUTE HANDLERS (req.login, req.logout)
    // ---------------------------------------------------------

    /**
     * Call this in your Login Route after verifying password.
     * @param {Object} user - The user object from DB
     * @param {Boolean} remember - True if "Remember Me" checkbox checked
     */
    req.login = async (user, remember = false) => {
      req.user = user; // Set session/user immediately

      if (remember) {
        await issueNewToken(db, res, user.id);
      }
    };

    /**
     * Call this in your Logout Route.
     * @param {Boolean} revokeAll - True to logout all devices (change password flow)
     */
    req.logout = async (revokeAll = false) => {
      if (revokeAll && req.user) {
        await db.revokeAllUserTokens(req.user.id);
      } else if (req.rememberMeTokenId) {
        await db.revokeTokenById(req.rememberMeTokenId);
      }

      req.user = null;
      req.rememberMeTokenId = null;
      clearRememberCookie(res);
    };

    next();
  };
}

/**
 * Issues a brand new token pair, saves hash to DB, sets cookie.
 */
async function issueNewToken(db, res, userId) {
  const selector = generateToken();
  const validator = generateToken(24); // Longer validator = more entropy
  const expiresAt = new Date(Date.now() + COOKIE_OPTIONS.maxAge);

  const validatorHash = await bcrypt.hash(validator, 10); // Cost 10

  await db.createRememberToken({
    user_id: userId,
    selector,
    validator_hash: validatorHash,
    expires_at: expiresAt
    // user_agent, ip_hash optional
  });

  // Set Cookie: "selector:validator"
  res.cookie(COOKIE_NAME, `${selector}:${validator}`, COOKIE_OPTIONS);
}

/**
 * Rotates token: Invalidates old, issues new. 
 * Runs automatically on successful cookie validation (PART A).
 */
async function rotateToken(db, res, userId, oldTokenId) {
  try {
    await db.revokeTokenById(oldTokenId); // Delete old row
    await issueNewToken(db, res, userId); // Create new row + cookie
  } catch (e) {
    console.error('[RememberMe] Rotation failed:', e);
    // Non-blocking: user stays logged in on old token if rotation fails
  }
}

function clearRememberCookie(res) {
  res.clearCookie(COOKIE_NAME, { ...COOKIE_OPTIONS, maxAge: 0 });
}

module.exports = { createRememberMeMiddleware, COOKIE_NAME };
```

### 3. Required Database Methods (`db` object)

Your `db` module must implement these specific methods:

```javascript
// db.js (Conceptual Implementation)
const pool = require('./pool'); // pg, mysql2, etc.

module.exports = {
  // Existing assumption
  getUserById: (id) => pool.query('SELECT * FROM users WHERE id = $1', [id]).then(r => r.rows[0]),

  // New methods required by middleware
  getRememberTokenBySelector: (selector) => 
    pool.query('SELECT * FROM remember_tokens WHERE selector = $1', [selector]).then(r => r.rows[0]),

  createRememberToken: ({ user_id, selector, validator_hash, expires_at }) =>
    pool.query(
      `INSERT INTO remember_tokens (user_id, selector, validator_hash, expires_at) 
       VALUES ($1, $2, $3, $4) RETURNING id`,
      [user_id, selector, validator_hash, expires_at]
    ).then(r => r.rows[0]),

  revokeTokenById: (id) => pool.query('DELETE FROM remember_tokens WHERE id = $1', [id]),

  revokeAllUserTokens: (userId) => pool.query('DELETE FROM remember_tokens WHERE user_id = $1', [userId]),
};
