      // Token format: "userId:hash" - hash prevents tampering
      const [userId, hash] = token.split(':');
      if (!userId || !hash) return next();

      // Verify hash matches expected value for this userId
      const expectedHash = crypto
        .createHmac('sha256', COOKIE_SECRET)
        .update(userId)
        .digest('hex')
        .substring(0, 16);

      if (hash !== expectedHash) {
        // Invalid token - clear cookie
        res.clearCookie(COOKIE_NAME, { signed: true, httpOnly: true, secure: true, sameSite: 'lax' });
        return next();
      }

      // Fetch user from database
      const user = await db.getUserById(userId);
      if (user) {
        req.user = user;
      }
    } catch (err) {
      // Log error but don't block request
      console.error('Remember-me error:', err);
    }
    next();
  };
}

// Call this on successful login to set the remember-me cookie
function setRememberMeCookie(res, userId) {
  const hash = crypto
    .createHmac('sha256', COOKIE_SECRET)
    .update(userId)
    .digest('hex')
    .substring(0, 16);

  const token = `${userId}:${hash}`;

  res.cookie(COOKIE_NAME, token, {
    signed: true,
    httpOnly: true,
    secure: process.env.NODE_ENV === 'production',
    sameSite: 'lax',
    maxAge: COOKIE_MAX_AGE
  });
}

// Call this on logout to clear the cookie
function clearRememberMeCookie(res) {
  res.clearCookie(COOKIE_NAME, {
    signed: true,
    httpOnly: true,
    secure: process.env.NODE_ENV === 'production',
    sameSite: 'lax'
  });
}

module.exports = {
  rememberMeMiddleware,
  setRememberMeCookie,
  clearRememberMeCookie,
  cookieParser: cookieParser(COOKIE_SECRET)
};
