### 2. Middleware Implementation (`middleware/rememberMe.js`)

```javascript
const crypto = require('crypto');
const cookieParser = require('cookie-parser');

// Config
const COOKIE_NAME = 'remember_me';
const COOKIE_OPTIONS = {
  httpOnly: true,      // Prevent XSS theft
  secure: process.env.NODE_ENV === 'production', // HTTPS only in prod
  sameSite: 'lax',     // CSRF protection
  maxAge: 30 * 24 * 60 * 60 * 1000, // 30 days in ms
  path: '/'
};

// --- Helper: Generate Cryptographically Secure Tokens ---
function generateTokenBytes(length = 16) {
  return crypto.randomBytes(length).toString('hex');
}

// Hash validator with SHA-256 (fast, deterministic, sufficient for random input)
function hashValidator(validator) {
  return crypto.createHash('sha256').update(validator).digest('hex');
}

// --- 1. Login Helper: Call this INSIDE your Login Route on Success ---
async function issueRememberToken(userId, res, db) {
  const selector = generateTokenBytes(16); // 16 bytes = 32 hex chars
  const validator = generateTokenBytes(32); // 32 bytes = 64 hex chars
  const validatorHash = hashValidator(validator);
  const expiresAt = new Date(Date.now() + COOKIE_OPTIONS.maxAge);

  // Store hash in DB (async, don't block login response if possible, but await is safer)
  await db.query(
    `INSERT INTO remember_tokens (selector, validator_hash, user_id, expires_at) 
     VALUES ($1, $2, $3, $4)
     ON CONFLICT (selector) DO UPDATE SET validator_hash=$2, user_id=$3, expires_at=$4`,
    [selector, validatorHash, userId, expiresAt]
  );

  // Set Cookie: "selector:validator"
  const cookieValue = `${selector}:${validator}`;
  res.cookie(COOKIE_NAME, cookieValue, COOKIE_OPTIONS);
}

// --- 2. Logout Helper: Call this INSIDE your Logout Route ---
async function clearRememberToken(req, res, db) {
  const cookie = req.cookies[COOKIE_NAME];
  if (cookie) {
    const [selector] = cookie.split(':');
    if (selector) {
      // Delete specific token from DB
      await db.query('DELETE FROM remember_tokens WHERE selector = $1', [selector]);
    }
  }
  res.clearCookie(COOKIE_NAME, COOKIE_OPTIONS);
}

// --- 3. The Actual Express Middleware: Attach to app BEFORE routes ---
function rememberMeMiddleware(db) {
  return async (req, res, next) => {
    // 1. If user already authenticated (via session/passport), skip
    if (req.user) return next();

    // 2. Parse Cookie (requires cookie-parser middleware loaded globally before this)
    const cookie = req.cookies[COOKIE_NAME];
    if (!cookie) return next();

    const [selector, validator] = cookie.split(':');
    if (!selector || !validator) return next(); // Malformed

    try {
      // 3. Lookup by Selector (Public ID)
      const result = await db.query(
        `SELECT user_id, validator_hash, expires_at 
         FROM remember_tokens 
         WHERE selector = $1`,
        [selector]
      );

      const tokenRow = result.rows[0];
      if (!tokenRow) return next(); // Selector not found

      // 4. Check Expiry (DB is source of truth)
      if (new Date(tokenRow.expires_at) < new Date()) {
        await db.query('DELETE FROM remember_tokens WHERE selector = $1', [selector]);
        return next(); // Expired
      }

      // 5. Constant-Time Compare Validator Hash (Prevent Timing Attacks)
      const incomingHash = hashValidator(validator);
      // Use crypto.timingSafeEqual (requires buffers of same length)
      const storedHashBuf = Buffer.from(tokenRow.validator_hash, 'hex');
      const incomingHashBuf = Buffer.from(incomingHash, 'hex');

      if (storedHashBuf.length !== incomingHashBuf.length || 
          !crypto.timingSafeEqual(storedHashBuf, incomingHashBuf)) {
        return next(); // Invalid validator
      }

      // 6. VALID TOKEN: Fetch User
      const user = await db.getUserById(tokenRow.user_id);
      if (!user) {
        // User deleted? Clean up token.
        await db.query('DELETE FROM remember_tokens WHERE selector = $1', [selector]);
        return next();
      }

      // 7. Attach User to Request
      req.user = user;
      req.authViaRememberMe = true; // Flag for logging/auditing

      // 8. OPTIONAL: Token Rotation (Sliding Expiration / Security)
      // Issue new token, invalidate old one. 
      // Comment out if you want static 30-day expiry from login.
      await rotateToken(selector, user.id, res, db);

      next();
    } catch (err) {
      console.error('[RememberMe] Error:', err);
      // Fail closed: do not log in, clear bad cookie just in case
      res.clearCookie(COOKIE_NAME, COOKIE_OPTIONS);
      next();
    }
  };
}

// --- 4. Token Rotation (Sliding Window) ---
async function rotateToken(oldSelector, userId, res, db) {
  const newSelector = generateTokenBytes(16);
  const newValidator = generateTokenBytes(32);
  const newValidatorHash = hashValidator(newValidator);
  const newExpiresAt = new Date(Date.now() + COOKIE_OPTIONS.maxAge);

  // Atomic Swap: Delete old, Insert new
  await db.query('BEGIN');
  try {
    await db.query('DELETE FROM remember_tokens WHERE selector = $1', [oldSelector]);
    await db.query(
      `INSERT INTO remember_tokens (selector, validator_hash, user_id, expires_at) 
       VALUES ($1, $2, $3, $4)`,
      [newSelector, newValidatorHash, userId, newExpiresAt]
    );
    await db.query('COMMIT');

    // Set new cookie
    res.cookie(COOKIE_NAME, `${newSelector}:${newValidator}`, COOKIE_OPTIONS);
  } catch (e) {
    await db.query('ROLLBACK');
    throw e;
  }
}

module.exports = {
  rememberMeMiddleware,
  issueRememberToken,
  clearRememberToken,
  COOKIE_NAME
};
```

