### 2. The Middleware (`rememberMe.js`)

```javascript
// middleware/rememberMe.js
const crypto = require('crypto');
const db = require('../db'); // Adjust path

const COOKIE_NAME = 'remember_me';
const COOKIE_OPTIONS = {
  httpOnly: true,      // Prevents XSS (JS cannot read)
  secure: process.env.NODE_ENV === 'production', // HTTPS only in prod
  sameSite: 'lax',     // CSRF protection (use 'none' + secure:true if cross-site)
  maxAge: 30 * 24 * 60 * 60 * 1000, // 30 Days in ms
  path: '/'
};

// Helper: Generate cryptographically secure random bytes -> Base64 URL Safe
const generateToken = (bytes = 32) => 
  crypto.randomBytes(bytes).toString('base64url');

// Helper: Hash validator (SHA-256 is fast enough for high-entropy random tokens; 
// use bcrypt/scrypt/argon2 if validators were low-entropy passwords)
const hashValidator = (validator) => 
  crypto.createHash('sha256').update(validator).digest('hex');

/**
 * MIDDLEWARE 1: Issue Cookie
 * Call this INSIDE your POST /login route handler AFTER successful credential verification.
 * Usage: await issueRememberMe(req, res, user);
 */
async function issueRememberMe(req, res, user) {
  const selector = generateToken(16);  // 16 bytes = ~22 chars (DB Index friendly)
  const validator = generateToken(32); // 32 bytes = 256 bits entropy
  const validatorHash = hashValidator(validator);
  const expiresAt = Date.now() + COOKIE_OPTIONS.maxAge;

  try {
    await db.createRememberToken(user.id, selector, validatorHash, expiresAt);

    // Cookie format: "selector.validator" (Base64URL safe, no encoding issues)
    const cookieValue = `${selector}.${validator}`;

    res.cookie(COOKIE_NAME, cookieValue, COOKIE_OPTIONS);
    console.log(`[RememberMe] Token issued for user ${user.id}`);
  } catch (err) {
    console.error('[RememberMe] Failed to issue token:', err);
    // Don't crash login if cookie fails, just log it
  }
}

/**
 * MIDDLEWARE 2: Read & Validate Cookie (Global Middleware)
 * Place this EARLY in your middleware stack (before routes), 
 * AFTER cookieParser() and session middleware (if used).
 * 
 * Logic: 
 * 1. If req.user already exists (session login), skip.
 * 2. Parse cookie.
 * 3. Verify against DB.
 * 4. On Success: Attach user, ROTATE token (delete old, issue new).
 * 5. On Fail: Clear invalid cookie.
 */
async function rememberMeAuth(req, res, next) {
  // 1. Skip if already authenticated via Session
  if (req.user) return next();

  const cookie = req.cookies?.[COOKIE_NAME];
  if (!cookie) return next();

  // 2. Parse Selector & Validator
  const [selector, validator] = cookie.split('.');
  if (!selector || !validator) {
    // Malformed cookie -> Clear it
    return clearCookieAndNext(res, next);
  }

  try {
    // 3. Lookup in DB
    const tokenRecord = await db.getRememberToken(selector);

    if (!tokenRecord) {
      // Selector not found or expired
      return clearCookieAndNext(res, next);
    }

    // 4. Constant-time comparison of Hashes
    const incomingHash = hashValidator(validator);
    // Use timingSafeEqual to prevent timing attacks
    const isValid = crypto.timingSafeEqual(
      Buffer.from(tokenRecord.validatorHash),
      Buffer.from(incomingHash)
    );

    if (!isValid) {
      // Invalid validator -> Potential theft? Delete token for safety.
      await db.deleteRememberToken(selector);
      return clearCookieAndNext(res, next);
    }

    // 5. SUCCESS: Load User
    const user = await db.getUserById(tokenRecord.userId);
    if (!user) {
      // User deleted? Clean up token.
      await db.deleteRememberToken(selector);
      return clearCookieAndNext(res, next);
    }

    // Attach user to request
    req.user = user;
    // Flag to distinguish from session login (optional, useful for sensitive actions)
    req.authViaRememberMe = true; 

    // 6. ROTATION: Invalidate old token, Issue new one (Security Best Practice)
    await db.deleteRememberToken(selector);
    await issueRememberMe(req, res, user); // Issues new cookie automatically

    next();
  } catch (err) {
    console.error('[RememberMe] Auth error:', err);
    // Fail closed: clear cookie, continue as guest
    clearCookieAndNext(res, next);
  }
}

function clearCookieAndNext(res, next) {
  res.clearCookie(COOKIE_NAME, { path: COOKIE_OPTIONS.path });
  next();
}

/**
 * MIDDLEWARE 3: Explicit Logout Handler
 * Call this in your POST /logout route.
 */
async function clearRememberMe(req, res) {
  const cookie = req.cookies?.[COOKIE_NAME];
  if (cookie) {
    const [selector] = cookie.split('.');
    if (selector) {
      await db.deleteRememberToken(selector).catch(console.error);
    }
  }
  res.clearCookie(COOKIE_NAME, { path: COOKIE_OPTIONS.path });
}

module.exports = {
  issueRememberMe,
  rememberMeAuth,
  clearRememberMe
};
