  // 2. Parse Cookie
  // cookie-parser puts signed cookies in req.signedCookies, unsigned in req.cookies
  const cookieData = req.cookies?.[COOKIE_NAME] || req.signedCookies?.[COOKIE_NAME];

  if (!cookieData) return next();

  try {
    // Cookie Format: "series:token"
    const [series, presentedToken] = cookieData.split(':');
    if (!series || !presentedToken) return next(); // Malformed cookie

    // 3. Lookup Series in DB
    const record = await db.getRememberToken(series);
    if (!record) return next(); // Series not found (invalid/expired)

    // 4. Check Expiry
    if (new Date(record.expires_at) < new Date()) {
      await db.deleteRememberToken(series); // Clean up
      res.clearCookie(COOKIE_NAME, COOKIE_OPTIONS);
      return next();
    }

    // 5. Verify Token (Constant time comparison via bcrypt)
    const valid = await verifyToken(presentedToken, record.token_hash);
    if (!valid) {
      // **SECURITY CRITICAL**: Token mismatch implies theft.
      // Invalidate ALL tokens for this user immediately.
      await db.deleteAllUserTokens(record.user_id); // Implement this in DB layer
      res.clearCookie(COOKIE_NAME, COOKIE_OPTIONS);
      console.warn(`[SECURITY] Remember-me token theft detected for user ${record.user_id}. All tokens revoked.`);
      return next();
    }

    // 6. TOKEN ROTATION: Issue new token, keep same series
    const newToken = generateToken();
    const newTokenHash = await hashToken(newToken);
    const newExpiresAt = new Date(Date.now() + COOKIE_OPTIONS.maxAge);

    await db.updateRememberToken(series, newTokenHash, newExpiresAt);

    // 7. Set New Cookie (Rotated Token)
    res.cookie(COOKIE_NAME, `${series}:${newToken}`, COOKIE_OPTIONS);

    // 8. Fetch User & Attach to Request
    const user = await db.getUserById(record.user_id);
    if (user) {
      // Remove sensitive fields before attaching
      delete user.password_hash; 
      req.user = user;
      // Optional: Flag to indicate this was auto-login vs explicit login
      req.authViaRememberMe = true; 
    }

  } catch (err) {
    console.error('[RememberMe] Error:', err);
    // Fail open (don't block request), just don't log them in
  } finally {
    next();
  }
}

/**
 * HELPER: Issue Remember Me Cookie on Explicit Login
 * Call this inside your POST /login route AFTER validating username/password.
 */
async function issueRememberMe(res, userId) {
  const series = generateToken(); // Public ID
  const token = generateToken();  // Private Secret
  const tokenHash = await hashToken(token);
  const expiresAt = new Date(Date.now() + COOKIE_OPTIONS.maxAge);

  await db.saveRememberToken(series, tokenHash, userId, expiresAt);

  // Send Cookie: "series:token"
  res.cookie(COOKIE_NAME, `${series}:${token}`, COOKIE_OPTIONS);
}

/**
 * HELPER: Clear Remember Me (Logout)
 * Call this in your POST /logout route.
 */
async function clearRememberMe(req, res) {
  const cookieData = req.cookies?.[COOKIE_NAME] || req.signedCookies?.[COOKIE_NAME];
  if (cookieData) {
    const [series] = cookieData.split(':');
    if (series) {
      await db.deleteRememberToken(series).catch(console.error);
    }
  }
  res.clearCookie(COOKIE_NAME, COOKIE_OPTIONS);
}

module.exports = {
  cookieParserMiddleware,
  rememberMeMiddleware,
  issueRememberMe,
  clearRememberMe,
  COOKIE_NAME
};
```

