### 2. The Middleware (`middleware/rememberMe.js`)

```javascript
// middleware/rememberMe.js
const crypto = require('crypto');
const bcrypt = require('bcrypt'); // npm install bcrypt
// const db = require('../db'); // Your DB module exporting getUserById, etc.

const COOKIE_NAME = 'remember_me';
const COOKIE_OPTIONS = {
  httpOnly: true,    // Prevents XSS theft
  secure: process.env.NODE_ENV === 'production', // HTTPS only in prod
  sameSite: 'lax',   // CSRF protection (use 'none' + secure:true for cross-site)
  maxAge: 30 * 24 * 60 * 60 * 1000, // 30 days in ms
  path: '/'
};

// --- Helper: Generate Token Pair ---
function generateTokenPair() {
  // Selector: 16 bytes (24 chars base64) - Safe to index in DB
  const selector = crypto.randomBytes(16).toString('base64url');
  // Validator: 32 bytes (43 chars base64) - High entropy secret
  const validator = crypto.randomBytes(32).toString('base64url');
  return { selector, validator };
}

// --- Helper: Hash Validator ---
async function hashValidator(validator) {
  // Cost factor 12 is standard for bcrypt (adjust for hardware)
  return bcrypt.hash(validator, 12);
}

/**
 * Express Middleware: Reads cookie, validates token, restores req.user
 * Must be placed AFTER cookieParser() and BEFORE routes needing auth.
 */
async function rememberMeMiddleware(req, res, next) {
  // 1. If user already authenticated (e.g. via session), skip
  if (req.user) return next();

  // 2. Parse Cookie
  const cookieVal = req.cookies?.[COOKIE_NAME];
  if (!cookieVal) return next();

  // 3. Split Selector:Validator
  // Format: "selector.base64:validator.base64"
  const parts = cookieVal.split(':');
  if (parts.length !== 2) return next(); // Malformed cookie

  const [selector, validator] = parts;

  try {
    // 4. Lookup by Selector (Fast, indexed)
    // Assume db.query returns { rows: [...] }
    const result = await db.query(
      'SELECT user_id, validator_hash, expires_at FROM remember_tokens WHERE selector = $1',
      [selector]
    );

    const tokenRecord = result.rows[0];
    if (!tokenRecord) return next(); // Selector not found

    // 5. Check Expiry (DB level safety net)
    if (new Date(tokenRecord.expires_at) < new Date()) {
      // Clean up expired token
      await db.query('DELETE FROM remember_tokens WHERE selector = $1', [selector]);
      return next();
    }

    // 6. Verify Validator (Constant time comparison via bcrypt)
    const match = await bcrypt.compare(validator, tokenRecord.validator_hash);
    if (!match) {
      // SECURITY: Token theft detected? 
      // Best practice: Invalidate ALL tokens for this user (rotation) or just this one.
      // Here we just delete the specific compromised token.
      await db.query('DELETE FROM remember_tokens WHERE selector = $1', [selector]);
      return next();
    }

    // 7. Fetch User
    const user = await db.getUserById(tokenRecord.user_id);
    if (!user) return next(); // User deleted

    // 8. SUCCESS: Attach user to request
    req.user = user;
    // Optional: Flag to distinguish session login vs remember-me login
    req.authViaRememberMe = true; 

    // 9. Token Rotation (Optional but Recommended)
    // Issue new token, invalidate old one -> mitigates long-term theft.
    // Uncomment below to enable rotation on every request.
    /*
    await rotateToken(req, res, user.id, selector);
    */

    next();
  } catch (err) {
    console.error('Remember Me Middleware Error:', err);
    // Fail open (treat as unauthenticated) but log error
    next();
  }
}

/**
 * Optional: Rotate token on use (Security Hardening)
 * Invalidates current cookie, sets new one.
 */
async function rotateToken(req, res, userId, oldSelector) {
  const { selector, validator } = generateTokenPair();
  const validatorHash = await hashValidator(validator);
  const expiresAt = new Date(Date.now() + COOKIE_OPTIONS.maxAge);

  const client = await db.getClient(); // Transaction
  try {
    await client.query('BEGIN');
    await client.query('DELETE FROM remember_tokens WHERE selector = $1', [oldSelector]);
    await client.query(
      'INSERT INTO remember_tokens (user_id, selector, validator_hash, expires_at) VALUES ($1, $2, $3, $4)',
      [userId, selector, validatorHash, expiresAt]
    );
    await client.query('COMMIT');

    // Set new cookie
    res.cookie(COOKIE_NAME, `${selector}:${validator}`, COOKIE_OPTIONS);
  } catch (e) {
    await client.query('ROLLBACK');
    throw e;
  } finally {
    client.release();
  }
}

/**
 * Call this on explicit LOGIN (POST /login) if "Remember Me" checkbox checked.
 */
async function issueRememberToken(res, userId) {
  const { selector, validator } = generateTokenPair();
  const validatorHash = await hashValidator(validator);
  const expiresAt = new Date(Date.now() + COOKIE_OPTIONS.maxAge);

  await db.query(
    'INSERT INTO remember_tokens (user_id, selector, validator_hash, expires_at) VALUES ($1, $2, $3, $4)',
    [userId, selector, validatorHash, expiresAt]
  );

  res.cookie(COOKIE_NAME, `${selector}:${validator}`, COOKIE_OPTIONS);
}

/**
 * Call this on LOGOUT (POST /logout) to clear cookie & DB.
 */
async function clearRememberToken(req, res) {
  const cookieVal = req.cookies?.[COOKIE_NAME];
  if (cookieVal) {
    const selector = cookieVal.split(':')[0];
    if (selector) {
      await db.query('DELETE FROM remember_tokens WHERE selector = $1', [selector]);
    }
  }
  res.clearCookie(COOKIE_NAME, COOKIE_OPTIONS);
}

module.exports = {
  rememberMeMiddleware,
  issueRememberToken,
  clearRememberToken,
  COOKIE_NAME
};
```

