```js
// rememberMe.js
// Express middleware that issues a long‑lived "remember‑me" cookie on login
// and restores req.user from that cookie on subsequent requests.

const cookieParser = require('cookie-parser');
const crypto = require('crypto');

// Secret used to sign the token (keep this out of source control in production)
const TOKEN_SECRET = process.env.REMEMBER_ME_SECRET || 'dev-secret-change-me';

// Cookie options – 30 days, HttpOnly, Secure (HTTPS only), SameSite=Lax
const COOKIE_OPTS = {
  maxAge: 30 * 24 * 60 * 60 * 1000, // 30 days in ms
  httpOnly: true,
  secure: process.env.NODE_ENV === 'production', // true only on HTTPS
  sameSite: 'lax',
  path: '/'
};

/**
 * Middleware factory.
 * @param {Object} db - Database wrapper exposing `getUserById(id)` returning a user object or null.
 * @returns {Function} Express middleware.
 */
function rememberMeMiddleware(db) {
  // Parse cookies first (express will have cookieParser already, but we keep it explicit)
  return [
    cookieParser(TOKEN_SECRET), // signed cookies

    // 1️⃣  Restore user from remember‑me cookie (if no session user already)
    async (req, res, next) => {
      // If a session already populated req.user, skip
      if (req.user) return next();

      const token = req.signedCookies?.remember_me; // signed cookie name
      if (!token) return next();

      try {
        // Token format: "<userId>.<signature>"
        const [userId, signature] = token.split('.');
        if (!userId || !signature) return next();

        // Verify signature (HMAC‑SHA256)
        const expected = crypto
          .createHmac('sha256', TOKEN_SECRET)
          .update(userId)
          .digest('hex');

        if (!crypto.timingSafeEqual(Buffer.from(signature), Buffer.from(expected))) {
          // Invalid signature – discard cookie
          res.clearCookie('remember_me', COOKIE_OPTS);
          return next();
        }

        // Fetch user
        const user = await db.getUserById(userId);
        if (user) {
          req.user = user;               // attach for downstream handlers
          req.rememberMe = true;         // flag that user came from remember‑me
        } else {
          // User no longer exists – clear cookie
          res.clearCookie('remember_me', COOKIE_OPTS);
        }
      } catch (err) {
        // Log but don't block the request
        console.error('rememberMe restore error:', err);
      } finally {
        next();
      }
    },

    // 2️⃣  Helper to set the remember‑me cookie after a successful login
    //    (attach to res so route handlers can call it)
    (req, res, next) => {
      res.setRememberMe = (userId) => {
        const signature = crypto
          .createHmac('sha256', TOKEN_SECRET)
          .update(String(userId))
          .digest('hex');
        const token = `${userId}.${signature}`;
        res.cookie('remember_me', token, { ...COOKIE_OPTS, signed: true });
      };
      next();
    }
  ];
}

module.exports = rememberMeMiddleware;
```

