// rememberMe.js
// Express middleware for a 30‑day "remember‑me" cookie.
// Requires: npm i cookie-parser
// Assumes a `db` object with `getUserById(id)` that returns a user record or null.

const cookieParser = require('cookie-parser');

// Name of the cookie that stores the persistent token
const REMEMBER_COOKIE = 'remember_token';
// Token length (bytes) – 32 bytes = 256 bits of entropy
const TOKEN_BYTES = 32;
// 30 days in milliseconds
const MAX_AGE_MS = 30 * 24 * 60 * 60 * 1000;

/**
 * Generates a cryptographically‑secure random token (hex string).
 */
function generateToken() {
  // Node's crypto.randomBytes is synchronous and suitable for this size.
  const { randomBytes } = require('crypto');
  return randomBytes(TOKEN_BYTES).toString('hex');
}

/**
 * Middleware that:
 *   1. Parses cookies (must be placed after cookieParser()).
 *   2. If `req.user` is already set (e.g., by a session middleware), do nothing.
 *   3. Otherwise, look for the remember‑me cookie, validate it against the DB,
 *      and attach the user to `req.user` when valid.
 *
 * Expected DB schema for the token:
 *   - user_id (FK to users table)
 *   - token_hash (SHA‑256 hex of the token stored in the cookie)
 *   - expires_at (timestamp)
 *
 * The example below assumes a helper `db.verifyRememberToken(token)` that
 *   * hashes the supplied token,
 *   * looks up a matching, non‑expired row,
 *   * returns the associated user object (or null).
 *
 * You can replace `db.verifyRememberToken` with your own query logic.
 */
function rememberMeMiddleware(req, res, next) {
  // If a session middleware already populated req.user, skip.
  if (req.user) return next();

  const token = req.cookies?.[REMEMBER_COOKIE];
  if (!token) return next();

  // Verify token against the database.
  db.verifyRememberToken(token)
    .then(user => {
      if (user) {
        // Attach user to the request for downstream handlers.
        req.user = user;
      }
      next();
    })
    .catch(err => {
      // Log the error but don't block the request – treat as "no user".
      console.error('Remember‑me verification failed:', err);
      next();
    });
}

/**
 * Call this on successful login when the user checked "Remember me".
 * It creates a new token, stores a hash in the DB, and sets the cookie.
 *
 * @param {Object} res          Express response object
 * @param {Object} user         User record (must have an `id` property)
 * @param {Object} db           Database wrapper with `storeRememberToken(userId, tokenHash, expiresAt)`
 */
async function issueRememberToken(res, user, db) {
  const token = generateToken();
  const { createHash } = require('crypto');
  const tokenHash = createHash('sha256').update(token).digest('hex');
  const expiresAt = new Date(Date.now() + MAX_AGE_MS);

  // Persist the hash (never store the raw token).
  await db.storeRememberToken(user.id, tokenHash, expiresAt);

  // Set a secure, HttpOnly, SameSite=Lax cookie.
  res.cookie(REMEMBER_COOKIE, token, {
    httpOnly: true,          // Prevent JS access
    secure: true,            // Only sent over HTTPS (ensure your site uses TLS)
    sameSite: 'lax',         // CSRF‑friendly default
    maxAge: MAX_AGE_MS,      // 30 days
    path: '/'                // Available site‑wide
  });
}

/**
 * Optional: Call on explicit logout to invalidate the remember‑me token.
 */
async function clearRememberToken(res, user, db) {
  // Remove the server‑side record.
  if (user?.id) {
    await db.deleteRememberToken(user.id);
  }
  // Expire the client‑side cookie.
  res.clearCookie(REMEMBER_COOKIE, { path: '/', httpOnly: true, secure: true, sameSite: 'lax' });
}

module.exports = {
  cookieParser: cookieParser(),          // Use this in your app: app.use(rememberMe.cookieParser)
  rememberMeMiddleware,                  // app.use(rememberMe.rememberMeMiddleware)
  issueRememberToken,                    // await rememberMe.issueRememberToken(res, user, db)
  clearRememberToken                     // await rememberMe.clearRememberToken(res, user, db)
};
