```javascript
// apiKeys.js
const { Pool } = require('pg');
const crypto = require('crypto');

const pool = new Pool({
  connectionString: process.env.DATABASE_URL,
  max: 10,
});

const KEY_PREFIX = 'sk_';
const KEY_BYTES = 32;
const HASH_ALGO = 'sha256';

/**
 * Generate a new API key for a customer.
 * Stores only the hash in the database.
 * Returns the plaintext key (shown to customer once).
 */
async function generateApiKey(customerId) {
  const client = await pool.connect();
  try {
    // Generate cryptographically secure random key
    const randomBytes = crypto.randomBytes(KEY_BYTES);
    const key = KEY_PREFIX + randomBytes.toString('hex');
    const keyHash = crypto.createHash(HASH_ALGO).update(key).digest('hex');

    await client.query(
      `INSERT INTO api_keys (customer_id, key_hash, created_at)
       VALUES ($1, $2, NOW())`,
      [customerId, keyHash]
    );

    return key; // plaintext - only returned once
  } finally {
    client.release();
  }
}

/**
 * Verify a presented API key.
 * Returns { valid: true, customerId } or { valid: false }.
 */
async function verifyApiKey(presentedKey) {
  if (!presentedKey || !presentedKey.startsWith(KEY_PREFIX)) {
    return { valid: false };
  }

  const keyHash = crypto.createHash(HASH_ALGO).update(presentedKey).digest('hex');

  const client = await pool.connect();
  try {
    const result = await client.query(
      `SELECT customer_id FROM api_keys WHERE key_hash = $1`,
      [keyHash]
    );

    if (result.rows.length === 0) {
      return { valid: false };
    }

    return { valid: true, customerId: result.rows[0].customer_id };
  } finally {
    client.release();
  }
}

/**
 * Optional: Revoke an API key by hash (e.g., on customer request).
 */
async function revokeApiKey(keyHash) {
  const client = await pool.connect();
  try {
    await client.query(`DELETE FROM api_keys WHERE key_hash = $1`, [keyHash]);
  } finally {
    client.release();
  }
}

module.exports = { generateApiKey, verifyApiKey, revokeApiKey };
