```javascript
const { Pool } = require('pg');
const crypto = require('crypto');

const pool = new Pool({
  connectionString: process.env.DATABASE_URL,
});

// Generate a secure API key, store its hash, return plaintext once
async function generateApiKey(customerId) {
  const plaintextKey = `sk_${crypto.randomBytes(24).toString('base64url')}`;
  const keyHash = crypto.createHash('sha256').update(plaintextKey).digest('hex');
  const keyPrefix = plaintextKey.slice(0, 8); // for identification without exposing full key

  const query = `
    INSERT INTO api_keys (customer_id, key_hash, key_prefix, created_at)
    VALUES ($1, $2, $3, NOW())
    RETURNING id
  `;
  await pool.query(query, [customerId, keyHash, keyPrefix]);

  return plaintextKey; // only returned once
}

// Validate a presented API key against stored hash
async function validateApiKey(presentedKey) {
  if (!presentedKey || !presentedKey.startsWith('sk_')) {
    return { valid: false, reason: 'invalid_format' };
  }

  const keyHash = crypto.createHash('sha256').update(presentedKey).digest('hex');

  const query = `
    SELECT id, customer_id, revoked_at, expires_at
    FROM api_keys
    WHERE key_hash = $1
  `;
  const result = await pool.query(query, [keyHash]);

  if (result.rows.length === 0) {
    return { valid: false, reason: 'not_found' };
  }

  const key = result.rows[0];

  if (key.revoked_at) {
    return { valid: false, reason: 'revoked' };
  }
  if (key.expires_at && new Date(key.expires_at) < new Date()) {
    return { valid: false, reason: 'expired' };
  }

  // Optional: update last_used_at
  await pool.query(
    'UPDATE api_keys SET last_used_at = NOW() WHERE id = $1',
    [key.id]
  );

  return { valid: true, customerId: key.customer_id, keyId: key.id };
}

module.exports = { generateApiKey, validateApiKey, pool };
