### 2. Node.js Implementation (`apiKeyService.js`)

```javascript
// apiKeyService.js
const { Pool } = require('pg');
const crypto = require('crypto');

// --- Configuration ---
const pool = new Pool({
  connectionString: process.env.DATABASE_URL, // e.g., postgres://user:pass@host:5432/db
  // ssl: process.env.NODE_ENV === 'production' ? { rejectUnauthorized: false } : false
});

// Security: A server-side secret (Pepper) added to the hash.
// Rotate this carefully; changing it invalidates ALL existing keys.
// Generate a strong one: `node -e "console.log(require('crypto').randomBytes(32).toString('hex'))"`
const PEPPER = process.env.API_KEY_PEPPER; 

if (!PEPPER) {
  throw new Error('FATAL: API_KEY_PEPPER environment variable is not set.');
}

// Key Format Constants
const KEY_PREFIX = 'sk_live_'; // Secret Key Live
const ENTROPY_BYTES = 32;      // 256 bits of entropy (43 chars base64url)
const HASH_ALGO = 'sha256';

/**
 * Generates a new API Key for a customer.
 * @param {string} customerId - UUID of the customer.
 * @param {object} options - { name?: string, expiresAt?: Date }
 * @returns {Promise<{ key: string, keyId: string }>} The full plaintext key (ONCE) and the DB ID.
 */
async function generateApiKey(customerId, options = {}) {
  const client = await pool.connect();
  try {
    // 1. Generate Cryptographically Secure Random Secret
    const secretBytes = crypto.randomBytes(ENTROPY_BYTES);
    // Use base64url (URL safe, no padding) for the secret part
    const secretPart = secretBytes.toString('base64url'); 

    // 2. Construct Full Key (Prefix + Secret)
    // Format: sk_live_<secret>
    const fullKey = `${KEY_PREFIX}${secretPart}`;

    // 3. Hash the Secret Part + Pepper for Storage
    // We hash ONLY the secret part. The prefix is stored separately for lookup.
    const hashInput = secretPart + PEPPER;
    const keyHash = crypto.createHash(HASH_ALGO).update(hashInput).digest(); // Returns Buffer (BYTEA)

    // 4. Persist to Database
    const query = `
      INSERT INTO api_keys (customer_id, key_hash, key_prefix, name, expires_at)
      VALUES ($1, $2, $3, $4, $5)
      RETURNING id, created_at;
    `;
    const values = [
      customerId,
      keyHash,           // BYTEA
      KEY_PREFIX,        // VARCHAR
      options.name || null,
      options.expiresAt || null
    ];

    const result = await client.query(query, values);
    const newKeyRecord = result.rows[0];

    console.log(`API Key generated for customer ${customerId}: ${newKeyRecord.id}`);

    // 5. Return the FULL KEY (Plaintext) - This is the ONLY time it is visible.
    return {
      key: fullKey,
      keyId: newKeyRecord.id,
      createdAt: newKeyRecord.created_at
    };

  } finally {
    client.release();
  }
}

/**
 * Validates an API Key presented by a client.
 * @param {string} presentedKey - The full key string (e.g., "sk_live_abc123...")
 * @returns {Promise<{ valid: boolean, customerId?: string, keyId?: string, name?: string } | null>}
 */
async function validateApiKey(presentedKey) {
  if (!presentedKey || typeof presentedKey !== 'string') {
    return { valid: false, reason: 'Invalid key format' };
  }

  // 1. Parse Prefix
  if (!presentedKey.startsWith(KEY_PREFIX)) {
    return { valid: false, reason: 'Unknown key prefix' };
  }

  const secretPart = presentedKey.substring(KEY_PREFIX.length);

  // Basic entropy check (prevent timing attacks on obviously short strings)
  if (secretPart.length < 20) { 
     return { valid: false, reason: 'Invalid key length' };
  }

  // 2. Compute Hash of Presented Secret + Pepper
  const hashInput = secretPart + PEPPER;
  const presentedHash = crypto.createHash(HASH_ALGO).update(hashInput).digest(); // Buffer

  const client = await pool.connect();
  try {
    // 3. Lookup Candidate by Prefix (Index Scan)
    // We fetch the hash and metadata. 
    // Note: In high scale systems, you might fetch by a "key_id" prefix embedded in the key,
    // but fetching by static prefix is fine for standard loads.
    const query = `
      SELECT id, customer_id, key_hash, name, revoked_at, expires_at
      FROM api_keys
      WHERE key_prefix = $1
        AND revoked_at IS NULL
        AND (expires_at IS NULL OR expires_at > NOW())
    `;

    const result = await client.query(query, [KEY_PREFIX]);

    // 4. Constant-Time Comparison (Timing Safe)
    // We must compare the presented hash against *all* active hashes for this prefix
    // to avoid leaking *which* key exists via timing (though usually we fetch by ID prefix).
    // Since we don't have a Key ID in the key string, we iterate.

    let matchedRow = null;

    for (const row of result.rows) {
      // row.key_hash is a Buffer (from BYTEA)
      // crypto.timingSafeEqual requires equal length buffers.
      if (row.key_hash.length === presentedHash.length) {
        if (crypto.timingSafeEqual(row.key_hash, presentedHash)) {
          matchedRow = row;
          break; // Found match
        }
      }
    }

    if (!matchedRow) {
      return { valid: false, reason: 'Key not found or invalid' };
    }

    // 5. Update Last Used (Async, fire-and-forget or await)
    // We do this non-blocking to keep validation fast.
    client.query(
      'UPDATE api_keys SET last_used_at = NOW() WHERE id = $1', 
      [matchedRow.id]
    ).catch(err => console.error('Failed to update last_used_at:', err));

    return {
      valid: true,
      customerId: matchedRow.customer_id,
      keyId: matchedRow.id,
      name: matchedRow.name
    };

  } finally {
    client.release();
  }
}

/**
 * Revokes (soft deletes) an API Key.
 */
async function revokeApiKey(keyId, customerId) {
  const query = `
    UPDATE api_keys 
    SET revoked_at = NOW() 
    WHERE id = $1 AND customer_id = $2 AND revoked_at IS NULL
    RETURNING id;
  `;
  const result = await pool.query(query, [keyId, customerId]);
  return result.rowCount > 0;
}

module.exports = {
  generateApiKey,
  validateApiKey,
  revokeApiKey,
  pool // Export pool for graceful shutdown
};
```

