### 2. Node.js Implementation (`apiKeys.js`)

```javascript
// apiKeys.js
const { Pool } = require('pg');
const bcrypt = require('bcrypt');
const crypto = require('crypto');

// --- Configuration ---
const POOL = new Pool({
  connectionString: process.env.DATABASE_URL, // e.g., postgres://user:pass@host:5432/db
  // ssl: { rejectUnauthorized: false } // Uncomment if using managed PG (RDS, Supabase, Neon) requiring SSL
});

const BCRYPT_ROUNDS = 12; // Cost factor (12 is standard as of 2024)
const KEY_PREFIX = 'sk_live_'; // Standard prefix: "Secret Key Live"
const KEY_BYTES = 32; // 32 bytes = 256 bits entropy -> 43 chars base64url

/**
 * Generates a new API Key, stores the hash, returns the plaintext ONCE.
 * @param {string} customerId - UUID of the customer owning this key
 * @param {object} options - { name?: string, scopes?: string[], expiresInDays?: number }
 * @returns {Promise<{ key: string, keyId: string }>} Plaintext key (only time visible) & DB UUID
 */
async function generateApiKey(customerId, options = {}) {
  const client = await POOL.connect();

  try {
    await client.query('BEGIN');

    // 1. Generate Cryptographically Secure Random Key
    // Format: sk_live_<base64url_encoded_random_bytes>
    const randomBytes = crypto.randomBytes(KEY_BYTES);
    // base64url safe (no +, /, =) for easy copying/headers
    const keySuffix = randomBytes.toString('base64url'); 
    const plaintextKey = `${KEY_PREFIX}${keySuffix}`;

    // 2. Derive Prefix for DB Index Lookup (first 12-16 chars usually enough)
    // We use a slightly longer prefix than KEY_PREFIX to ensure uniqueness
    const keyPrefix = plaintextKey.substring(0, 16); 

    // 3. Hash the FULL key using Bcrypt (Async)
    const keyHash = await bcrypt.hash(plaintextKey, BCRYPT_ROUNDS);

    // 4. Calculate Expiry
    let expiresAt = null;
    if (options.expiresInDays && options.expiresInDays > 0) {
      expiresAt = new Date(Date.now() + options.expiresInDays * 24 * 60 * 60 * 1000);
    }

    // 5. Insert into DB
    const insertSql = `
      INSERT INTO api_keys (customer_id, key_hash, key_prefix, name, scopes, expires_at)
      VALUES ($1, $2, $3, $4, $5, $6)
      RETURNING id
    `;

    const values = [
      customerId,
      keyHash,
      keyPrefix,
      options.name || null,
      options.scopes || [],
      expiresAt
    ];

    const result = await client.query(insertSql, values);
    const keyId = result.rows[0].id;

    await client.query('COMMIT');

    // 6. Return Plaintext Key (ONLY TIME IT EXISTS IN MEMORY)
    return { key: plaintextKey, keyId };

  } catch (err) {
    await client.query('ROLLBACK');
    // Handle unique constraint violation on prefix (extremely rare collision)
    if (err.code === '23505') { 
        // Retry logic could go here, but with 256 bits entropy, collision is practically impossible.
        throw new Error('Key collision detected, please retry.');
    }
    throw err;
  } finally {
    client.release();
  }
}

/**
 * Validates a presented API Key against the database.
 * Updates 'last_used_at' on success.
 * @param {string} presentedKey - The key sent by the client (e.g., from Authorization header)
 * @returns {Promise<{ valid: boolean, keyId?: string, customerId?: string, scopes?: string[] }>}
 */
async function validateApiKey(presentedKey) {
  if (!presentedKey || typeof presentedKey !== 'string') {
    return { valid: false, reason: 'Invalid key format' };
  }

  // 1. Basic Format Check (Fail fast before DB hit)
  if (!presentedKey.startsWith(KEY_PREFIX)) {
    return { valid: false, reason: 'Invalid key prefix' };
  }

  // 2. Extract Prefix for Indexed Lookup
  const keyPrefix = presentedKey.substring(0, 16);

  const client = await POOL.connect();

  try {
    // 3. Fetch Candidate Row by Prefix (Indexed Scan)
    // We also check revoked_at and expires_at here to avoid hashing revoked keys.
    const selectSql = `
      SELECT id, customer_id, key_hash, scopes, revoked_at, expires_at
      FROM api_keys
      WHERE key_prefix = $1
        AND revoked_at IS NULL
        AND (expires_at IS NULL OR expires_at > NOW())
      LIMIT 1
    `;

    const result = await client.query(selectSql, [keyPrefix]);

    if (result.rowCount === 0) {
      // Key not found, revoked, or expired
      return { valid: false, reason: 'Key not found or revoked' };
    }

    const row = result.rows[0];

    // 4. Constant-Time Comparison (Bcrypt handles this internally)
    const match = await bcrypt.compare(presentedKey, row.key_hash);

    if (!match) {
      // Hash mismatch (Wrong key for this prefix)
      return { valid: false, reason: 'Invalid key signature' };
    }

    // 5. Success: Update Last Used Timestamp (Async, fire-and-forget or await)
    // We do this non-blocking to keep latency low, but awaiting is safer for consistency.
    await client.query(
      'UPDATE api_keys SET last_used_at = NOW() WHERE id = $1',
      [row.id]
    );

    return {
      valid: true,
      keyId: row.id,
      customerId: row.customer_id,
      scopes: row.scopes || []
    };

  } catch (err) {
    console.error('API Key Validation Error:', err);
    return { valid: false, reason: 'Internal server error' };
  } finally {
    client.release();
  }
}

/**
 * Optional: Revoke a key (Soft Delete)
 */
async function revokeApiKey(keyId, customerId) {
  // Ensure customer owns key before revoking (Authorization)
  const sql = `
    UPDATE api_keys 
    SET revoked_at = NOW() 
    WHERE id = $1 AND customer_id = $2 AND revoked_at IS NULL
    RETURNING id
  `;
  const res = await POOL.query(sql, [keyId, customerId]);
  return res.rowCount > 0;
}

module.exports = {
  generateApiKey,
  validateApiKey,
  revokeApiKey,
  pool: POOL // Export pool for graceful shutdown
};
```

