### 2. Implementation (`apiKeys.js`)

```javascript
// apiKeys.js
const { Pool } = require('pg');
const bcrypt = require('bcrypt');
const crypto = require('node:crypto');

// --- Configuration ---
const POOL = new Pool({
  connectionString: process.env.DATABASE_URL, // e.g., postgresql://user:pass@host:5432/db
  // ssl: { rejectUnauthorized: false } // Enable if using managed PG (RDS, Supabase, Neon)
});

const BCRYPT_ROUNDS = 12; // Cost factor (12 is standard as of 2024)
const KEY_PREFIX = 'sk_live_'; // Prefix to identify your keys (Stripe style)
const KEY_BYTES = 24; // 24 bytes = 32 chars base64url. Total key length ~ 41 chars.

/**
 * Generates a new API key, stores the hash, returns the plaintext key ONCE.
 * @param {string} customerId - Your internal customer identifier
 * @param {string} [name] - Optional label for the key
 * @returns {Promise<{ key: string, prefix: string, id: number }>}
 */
async function generateApiKey(customerId, name = null) {
  const client = await POOL.connect();

  try {
    await client.query('BEGIN');

    // 1. Generate Cryptographically Secure Random Key
    // Format: sk_live_<base64url_entropy>
    const entropy = crypto.randomBytes(KEY_BYTES).toString('base64url');
    const plaintextKey = `${KEY_PREFIX}${entropy}`;
    const prefix = plaintextKey.substring(0, 12); // e.g., "sk_live_abcd" (Used for DB lookup)

    // 2. Hash the FULL key (never store plaintext)
    const keyHash = await bcrypt.hash(plaintextKey, BCRYPT_ROUNDS);

    // 3. Insert into DB
    // ON CONFLICT handles the astronomically rare case of a prefix collision
    const insertSql = `
      INSERT INTO api_keys (customer_id, key_prefix, key_hash, name)
      VALUES ($1, $2, $3, $4)
      ON CONFLICT (key_prefix) DO NOTHING
      RETURNING id;
    `;

    const result = await client.query(insertSql, [customerId, prefix, keyHash, name]);

    // If conflict happened (extremely rare), retry recursively once
    if (result.rowCount === 0) {
      await client.query('ROLLBACK');
      // Safety: limit recursion depth in real apps, but collision is ~1/2^128
      return generateApiKey(customerId, name);
    }

    await client.query('COMMIT');

    const newKeyId = result.rows[0].id;
    console.log(`[API Key Gen] Created key ID ${newKeyId} for customer ${customerId}`);

    return { 
      key: plaintextKey, // RETURN PLAINTEXT ONCE
      prefix: prefix,
      id: newKeyId 
    };

  } catch (e) {
    await client.query('ROLLBACK');
    throw e;
  } finally {
    client.release();
  }
}

/**
 * Validates a presented API key against stored hashes.
 * Updates 'last_used_at' on success.
 * @param {string} presentedKey - The key sent by the client (e.g., from Authorization header)
 * @returns {Promise<{ valid: boolean, customerId?: string, keyId?: number, keyName?: string }>}
 */
async function validateApiKey(presentedKey) {
  if (!presentedKey || typeof presentedKey !== 'string') {
    return { valid: false };
  }

  // 1. Extract Prefix (Must match generation logic length)
  const prefix = presentedKey.substring(0, 12); 

  if (!prefix.startsWith(KEY_PREFIX)) {
    return { valid: false }; // Invalid format, don't hit DB
  }

  const client = await POOL.connect();

  try {
    // 2. Fetch candidate row(s) by prefix (Index Scan - Very Fast)
    // We only check non-revoked keys.
    const selectSql = `
      SELECT id, customer_id, key_hash, name 
      FROM api_keys 
      WHERE key_prefix = $1 AND revoked_at IS NULL
    `;

    const result = await client.query(selectSql, [prefix]);

    if (result.rowCount === 0) {
      return { valid: false }; // Key not found or revoked
    }

    // 3. Compare Hashes (Constant time comparison handled by bcrypt)
    // Usually only 1 row matches prefix, but loop for safety.
    for (const row of result.rows) {
      const match = await bcrypt.compare(presentedKey, row.key_hash);

      if (match) {
        // 4. Update Last Used (Async, non-blocking ideally, but await is fine for low/med traffic)
        // For high traffic: fire-and-forget or use a job queue.
        await client.query(
          'UPDATE api_keys SET last_used_at = NOW() WHERE id = $1', 
          [row.id]
        ).catch(err => console.error('Failed to update last_used_at', err));

        return {
          valid: true,
          customerId: row.customer_id,
          keyId: row.id,
          keyName: row.name
        };
      }
    }

    // Hash mismatch (Wrong key for this prefix)
    return { valid: false };

  } finally {
    client.release();
  }
}

/**
 * Optional: Revoke a key (Soft Delete)
 */
async function revokeApiKey(keyId, customerId) {
  const sql = `UPDATE api_keys SET revoked_at = NOW() WHERE id = $1 AND customer_id = $2`;
  await POOL.query(sql, [keyId, customerId]);
}

module.exports = {
  generateApiKey,
  validateApiKey,
  revokeApiKey,
  pool: POOL // Export pool for graceful shutdown
};
```

