    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    customer_id UUID NOT NULL, -- FK to your customers table
    key_hash TEXT NOT NULL,    -- bcrypt hash (cost 12+)
    key_prefix VARCHAR(8) NOT NULL, -- First 8 chars of raw key for indexing
