### 2. Implementation (`apiKeys.js`)

```javascript
// apiKeys.js
const { Pool } = require('pg');
const bcrypt = require('bcrypt');
const crypto = require('crypto');

// --- Configuration ---
const POOL = new Pool({
  // connectionString: process.env.DATABASE_URL, // Best practice: use env var
  host: 'localhost',
  port: 5432,
  user: 'postgres',
  password: 'postgres',
  database: 'myapp',
  max: 20, // Connection pool size
});

const BCRYPT_COST = 12; // 12 is standard (2024). Increase as hardware improves.
const KEY_BYTES = 32;   // 32 bytes = 256 bits entropy
const PREFIX_LENGTH = 8; // Characters shown in prefix (e.g., "sk_live_abc123")

/**
 * Generates a secure API Key, stores the hash, returns the plaintext ONCE.
 * Format: {prefix}_{randomBase64UrlSafe}
 * Example: sk_live_AbCx9z... (Prefix helps identify key type/env)
 * 
 * @param {Object} params
 * @param {string} params.customerId - UUID of the customer
 * @param {string} [params.name] - Optional label
 * @param {number} [params.ttlDays] - Optional expiry in days
 * @returns {Promise<{ key: string, keyId: string, prefix: string }>}
 */
async function generateApiKey({ customerId, name = null, ttlDays = null }) {
  const client = await POOL.connect();

  try {
    // 1. Generate Cryptographically Secure Random Bytes
    const randomBytes = crypto.randomBytes(KEY_BYTES);
    // Base64URL encoding (no +, /, =) -> URL safe, compact
    const randomPart = randomBytes.toString('base64url'); 

    // 2. Construct Key: "sk_live_" + randomPart
    // Prefix "sk_live_" tells you it's a Secret Key for Live env.
    const prefix = 'sk_live_'; 
    const plainKey = `${prefix}${randomPart}`;

    // 3. Hash the FULL key using bcrypt (async, CPU intensive)
    const keyHash = await bcrypt.hash(plainKey, BCRYPT_COST);

    // 4. Extract DB Prefix (first 8 chars of random part usually enough, 
    //    but we use first 8 of full key for lookup uniqueness)
    //    Note: 'sk_live_' is 8 chars. We want the random part for uniqueness.
    const dbLookupPrefix = plainKey.substring(0, PREFIX_LENGTH + prefix.length); 
    // Actually, better to just use the random part prefix for DB index:
    const dbPrefix = randomPart.substring(0, PREFIX_LENGTH); 

    // 5. Calculate Expiry
    const expiresAt = ttlDays 
      ? new Date(Date.now() + ttlDays * 24 * 60 * 60 * 1000) 
      : null;

    // 6. Insert into DB
    const sql = `
      INSERT INTO api_keys (customer_id, key_hash, key_prefix, name, expires_at)
      VALUES ($1, $2, $3, $4, $5)
      RETURNING id, created_at;
    `;

    const result = await client.query(sql, [
      customerId,
      keyHash,
      dbPrefix,      // Store only random prefix for lookup
      name,
      expiresAt
    ]);

    const keyRecord = result.rows[0];

    // 7. RETURN PLAINTEXT KEY (Only time it exists in memory)
    return {
      key: plainKey,           // <-- SHOW THIS TO CUSTOMER ONCE
      keyId: keyRecord.id,     // Internal UUID for revocation/logs
      prefix: dbPrefix,        // Helpful for UI display (masking)
      createdAt: keyRecord.created_at
    };

  } finally {
    client.release();
  }
}

/**
 * Verifies a presented API Key against the database.
 * Updates 'last_used_at' on success.
 * 
 * @param {string} presentedKey - The full key string sent by client (e.g., in Authorization header)
 * @returns {Promise<{ valid: boolean, keyId?: string, customerId?: string, error?: string }>}
 */
async function verifyApiKey(presentedKey) {
  if (!presentedKey || typeof presentedKey !== 'string') {
    return { valid: false, error: 'Invalid key format' };
  }

  // 1. Basic Format Validation & Prefix Extraction
  // Expected: "sk_live_<random>"
  const expectedPrefix = 'sk_live_';
  if (!presentedKey.startsWith(expectedPrefix)) {
    return { valid: false, error: 'Invalid key prefix' };
  }

  // Extract the random part to calculate DB lookup prefix
  const randomPart = presentedKey.substring(expectedPrefix.length);
  if (randomPart.length < PREFIX_LENGTH) {
    return { valid: false, error: 'Key too short' };
  }

  const dbPrefix = randomPart.substring(0, PREFIX_LENGTH);

  const client = await POOL.connect();

  try {
    // 2. Find Candidate Row(s) by Prefix (Index Scan - Fast)
    // We also filter revoked_at IS NULL and expires_at > NOW() here to save roundtrips
    const sql = `
      SELECT id, customer_id, key_hash, name
      FROM api_keys
      WHERE key_prefix = $1
        AND revoked_at IS NULL
        AND (expires_at IS NULL OR expires_at > NOW())
    `;

    const result = await client.query(sql, [dbPrefix]);

    if (result.rows.length === 0) {
      // Use generic message to prevent key enumeration attacks
      return { valid: false, error: 'Invalid or revoked key' };
    }

    // 3. Verify Hash (bcrypt.compare is constant-time-ish)
    // Usually only 1 row matches prefix, but handle collisions gracefully.
    for (const row of result.rows) {
      const match = await bcrypt.compare(presentedKey, row.key_hash);

      if (match) {
        // 4. SUCCESS: Update last_used_at asynchronously (fire-and-forget)
        // We don't await this to keep verification latency low.
        client.query(
          `UPDATE api_keys SET last_used_at = NOW() WHERE id = $1`,
          [row.id]
        ).catch(err => console.error('Failed to update last_used_at:', err));

        return {
          valid: true,
          keyId: row.id,
          customerId: row.customer_id,
          name: row.name
        };
      }
    }

    // 5. No hash matched (Wrong key, but valid prefix existed)
    return { valid: false, error: 'Invalid key' };

  } finally {
    client.release();
  }
}

/**
 * Revoke (Soft Delete) a key by its Internal UUID.
 */
async function revokeApiKey(keyId, customerId) {
  const sql = `
    UPDATE api_keys 
    SET revoked_at = NOW() 
    WHERE id = $1 AND customer_id = $2 AND revoked_at IS NULL
    RETURNING id;
  `;
  const res = await POOL.query(sql, [keyId, customerId]);
  return res.rowCount > 0;
}

/**
 * List keys for a customer (Returns metadata ONLY, never hashes or plaintext)
 */
async function listApiKeys(customerId) {
  const sql = `
    SELECT id, key_prefix, name, created_at, last_used_at, expires_at, revoked_at
    FROM api_keys
    WHERE customer_id = $1 AND revoked_at IS NULL
    ORDER BY created_at DESC;
  `;
  const res = await POOL.query(sql, [customerId]);
  return res.rows;
}

module.exports = {
  generateApiKey,
  verifyApiKey,
  revokeApiKey,
  listApiKeys,
  pool: POOL // Export pool for graceful shutdown
};
```

