const { Pool } = require('pg');
const bcrypt = require('bcrypt');
const crypto = require('crypto');

// --- Configuration ---
const POOL = new Pool({
  connectionString: process.env.DATABASE_URL, // e.g., postgres://user:pass@host:5432/db
  // ssl: { rejectUnauthorized: false } // Uncomment if using managed PG (RDS, Supabase, Neon) locally
});

const KEY_PREFIX = 'sk_live_';      // Visible prefix (Stripe style)
const KEY_BYTES = 32;               // 32 bytes = 256 bits entropy (43 chars base64url)
const BCRYPT_ROUNDS = 12;           // Cost factor (adjust for CPU load ~100-300ms)

/**
 * Generates a new API Key, stores the hash, returns the plaintext ONCE.
 * @param {string|number} customerId - Your internal customer identifier
 * @param {object} options - { name?: string, scopes?: string[], expiresInDays?: number }
 * @returns {Promise<{ key: string, keyId: string }>} Plaintext key & DB UUID
 */
async function generateApiKey(customerId, options = {}) {
  const client = await POOL.connect();
  try {
    // 1. Generate High Entropy Secret
    const randomPart = crypto.randomBytes(KEY_BYTES).toString('base64url'); // URL safe, no padding
    const plaintextKey = `${KEY_PREFIX}${randomPart}`; // e.g., sk_live_x7Y9z...

    // 2. Derive Prefix for DB Lookup (First 8 chars of random part usually enough)
    // We store a prefix to find the row WITHOUT scanning all rows & bcrypt comparing all.
    const lookupPrefix = `${KEY_PREFIX}${randomPart.substring(0, 8)}`; 

    // 3. Hash the FULL plaintext key (Async bcrypt)
    const keyHash = await bcrypt.hash(plaintextKey, BCRYPT_ROUNDS);

    // 4. Calculate Expiry
    let expiresAt = null;
    if (options.expiresInDays) {
      expiresAt = new Date(Date.now() + options.expiresInDays * 24 * 60 * 60 * 1000);
    }

    // 5. Insert into DB
    const sql = `
      INSERT INTO api_keys (customer_id, key_prefix, key_hash, name, scopes, expires_at)
      VALUES ($1, $2, $3, $4, $5, $6)
      RETURNING id;
    `;
    const params = [
      customerId,
      lookupPrefix,
      keyHash,
      options.name || null,
      options.scopes || [],
      expiresAt
    ];

    const result = await client.query(sql, params);
    const keyId = result.rows[0].id;

    // 6. Return Plaintext Key (ONLY TIME IT EXISTS IN MEMORY)
    return { key: plaintextKey, keyId };

  } finally {
    client.release();
  }
}

/**
 * Validates a presented API Key against the database.
 * Resistant to Timing Attacks (bcrypt constant time comparison).
 * @param {string} presentedKey - The key sent by the client (e.g., in Authorization header)
 * @returns {Promise<object|null>} Key metadata (customer_id, scopes, keyId) or null if invalid
 */
async function validateApiKey(presentedKey) {
  if (!presentedKey || !presentedKey.startsWith(KEY_PREFIX)) {
    return null; // Fail fast on format
  }

  // 1. Extract Lookup Prefix (Must match generation logic exactly)
  // presentedKey = "sk_live_abcdefghijklmnop..."
  // We need first 8 chars of random part: "abcdefgh"
  const randomPart = presentedKey.substring(KEY_PREFIX.length);
  if (randomPart.length < 8) return null; // Invalid format

  const lookupPrefix = `${KEY_PREFIX}${randomPart.substring(0, 8)}`;

  const client = await POOL.connect();
  try {
    // 2. Find Candidate Row(s) by Prefix (Indexed, Fast)
    // We filter revoked_at IS NULL here to avoid checking deleted keys.
    const sql = `
      SELECT id, customer_id, key_hash, scopes, expires_at
      FROM api_keys
      WHERE key_prefix = $1 AND revoked_at IS NULL
    `;
    const result = await client.query(sql, [lookupPrefix]);

    if (result.rows.length === 0) {
      // No key with this prefix exists. 
      // SECURITY NOTE: We return null immediately. 
      // This leaks "prefix exists" vs "prefix not exists" timing, 
      // but prefix is public/low entropy. Bcrypt on non-existent row is slower.
      // For strict constant-time, you'd bcrypt a dummy hash here, but usually overkill for API keys.
      return null;
    }

    // 3. Compare Hashes (Bcrypt handles constant-time comparison internally)
    for (const row of result.rows) {
      // Check Expiry
      if (row.expires_at && new Date(row.expires_at) < new Date()) {
        continue; // Treat expired as invalid
      }

      const match = await bcrypt.compare(presentedKey, row.key_hash);

      if (match) {
        // 4. Optional: Update Last Used Async (Fire & Forget)
        // Don't await this; don't block the auth response.
        POOL.query(
          'UPDATE api_keys SET last_used_at = NOW() WHERE id = $1', 
          [row.id]
        ).catch(err => console.error('Failed to update last_used_at:', err));

        return {
          keyId: row.id,
          customerId: row.customer_id,
          scopes: row.scopes || [],
          // Do NOT return the hash or plaintext key
        };
      }
    }

    return null; // Hash mismatch (Wrong key or Hash collision on prefix)

  } finally {
    client.release();
  }
}

/**
 * Revokes (Soft Deletes) a key by ID.
 * @param {string} keyId 
 * @param {string|number} customerId - Authorization check: ensure customer owns key
 * @returns {Promise<boolean>} True if revoked
 */
async function revokeApiKey(keyId, customerId) {
  const sql = `
    UPDATE api_keys 
    SET revoked_at = NOW() 
    WHERE id = $1 AND customer_id = $2 AND revoked_at IS NULL
  `;
  const result = await POOL.query(sql, [keyId, customerId]);
  return result.rowCount > 0;
}

module.exports = {
  generateApiKey,
  validateApiKey,
  revokeApiKey,
  pool: POOL // Export pool if you need to shutdown gracefully: await pool.end()
};
```

