#### B. Middleware for Express / Fastify / Native Node
```javascript
// authMiddleware.js
const { validateApiKey } = require('./apiKeys');

async function apiKeyAuth(req, res, next) {
  // 1. Extract Key (Header: Authorization: Bearer sk_live_... OR Custom Header)
  const authHeader = req.headers.authorization || '';
  const apiKey = authHeader.replace('Bearer ', '').trim(); 
  // OR: const apiKey = req.headers['x-api-key'];

  if (!apiKey) {
    return res.status(401).json({ error: 'Missing API Key' });
  }

  // 2. Validate
  const keyData = await validateApiKey(apiKey);

  if (!keyData) {
    // Generic message prevents enumeration attacks
    return res.status(401).json({ error: 'Invalid or Expired API Key' });
  }

  // 3. Attach to Request
  req.auth = {
    customerId: keyData.customerId,
    keyId: keyData.keyId,
    scopes: keyData.scopes
  };

  // 4. Optional: Scope Check Helper
  req.requireScope = (scope) => {
    if (!keyData.scopes.includes(scope)) {
      throw new Error(`Forbidden: Requires scope '${scope}'`);
    }
  };

  next();
}

module.exports = apiKeyAuth;
```

