### Critical Security Details Explained

| Feature | Implementation Reason |
| :--- | :--- |
| **`crypto.randomBytes(32)`** | 256 bits entropy. Cryptographically secure. Unpredictable. |
| **`base64url` encoding** | URL safe (no `+`, `/`, `=`). Safe for headers/URLs without extra encoding. |
| **Prefix (`sk_live_`)** | Instantly identifiable in logs/config. Allows DB Index lookup (`key_prefix`) so we only run `bcrypt` on 1 row, not the whole table. |
| **Bcrypt (Cost 12)** | **Slow on purpose.** Defends against offline brute-force if DB leaks. ~100-200ms per check. Handles salting & constant-time comparison automatically. |
| **`revoked_at` Soft Delete** | Allows instant revocation without locking rows or breaking foreign keys. Index `WHERE revoked_at IS NULL` keeps valid-key lookups fast. |
| **`last_used_at` (Async)** | Fire-and-forget update prevents adding 1-2ms latency to every authenticated request. |
| **No Plaintext in DB** | If DB is dumped (SQL injection, backup leak, rogue admin), keys are useless without cracking bcrypt. |
| **Generic 401 Errors** | "Invalid Key" vs "Expired Key" vs "Revoked Key" prevents attackers from enumerating valid prefixes or checking key status. |

### Scaling Note
If you exceed **~10,000 validations/second**, the synchronous Bcrypt CPU cost becomes the bottleneck.
1.  **Vertical Scaling:** Increase CPU cores.
2.  **Horizontal Scaling:** Add more Node instances (stateless).
3.  **Hardware Offload:** Use a dedicated Key Management Service (AWS KMS, HashiCorp Vault) or move validation to an edge worker (Cloudflare Workers / Vercel Edge) where CPU is cheaper.
4.  **Caching:** Cache *valid* key metadata (customerId, scopes) in Redis with short TTL (e.g., 60s) to skip Bcrypt/DB on subsequent requests. **Invalidate cache on Revoke.**

```javascript
// apiKeys.js
const { Pool } = require('pg');
const crypto = require('crypto');
const bcrypt = require('bcrypt');

const pool = new Pool({
  connectionString: process.env.DATABASE_URL,
  max: 10,
});

const KEY_PREFIX = 'sk_';
const KEY_LENGTH = 32;
const HASH_COST = 12;

/**
 * Generate a new API key for a customer.
 * Returns the plaintext key ONCE - store it securely.
 */
async function generateApiKey(customerId) {
  const client = await pool.connect();
  try {
    // Generate cryptographically secure random key
    const randomBytes = crypto.randomBytes(KEY_LENGTH);
    const key = KEY_PREFIX + randomBytes.toString('base64url');

    // Hash for storage (never store plaintext)
    const keyHash = await bcrypt.hash(key, HASH_COST);

    await client.query(
      `INSERT INTO api_keys (customer_id, key_hash, created_at)
       VALUES ($1, $2, NOW())`,
      [customerId, keyHash]
    );

    return key; // Only returned once
  } finally {
    client.release();
  }
}

/**
 * Verify an API key and return customer info if valid.
 * Returns { customerId, keyId } or null if invalid.
 */
async function verifyApiKey(key) {
  if (!key?.startsWith(KEY_PREFIX)) return null;

  const client = await pool.connect();
  try {
    // Fetch candidate hashes (limit to recent keys for performance)
    const result = await client.query(
      `SELECT id, customer_id, key_hash
       FROM api_keys
       WHERE revoked_at IS NULL
       ORDER BY created_at DESC
       LIMIT 100`
    );

    // Constant-time comparison against stored hashes
    for (const row of result.rows) {
      const match = await bcrypt.compare(key, row.key_hash);
      if (match) {
        return { customerId: row.customer_id, keyId: row.id };
      }
    }
    return null;
  } finally {
    client.release();
  }
}

/**
 * Revoke an API key (soft delete).
 */
async function revokeApiKey(keyId) {
  await pool.query(
    `UPDATE api_keys SET revoked_at = NOW() WHERE id = $1`,
    [keyId]
  );
}

module.exports = { generateApiKey, verifyApiKey, revokeApiKey, pool };
```

