const KEY_BYTES = 32;
const BCRYPT_ROUNDS = 12;

/**
 * Generate a new API key for a customer.
 * Returns the plaintext key (only shown once) and the key ID.
 */
async function generateApiKey(customerId, metadata = {}) {
  const plainKey = KEY_PREFIX + crypto.randomBytes(KEY_BYTES).toString('hex');
  const keyHash = await bcrypt.hash(plainKey, BCRYPT_ROUNDS);
  const keyId = crypto.randomUUID();
  const keyPreview = plainKey.slice(0, 8) + '...' + plainKey.slice(-4);

  const query = `
    INSERT INTO api_keys (id, customer_id, key_hash, key_preview, metadata, created_at)
    VALUES ($1, $2, $3, $4, $5, NOW())
    RETURNING id, key_preview, created_at
  `;

  await pool.query(query, [keyId, customerId, keyHash, keyPreview, JSON.stringify(metadata)]);

  return {
    id: keyId,
    key: plainKey,           // only returned once
    preview: keyPreview,
    createdAt: new Date(),
  };
}

/**
 * Validate a presented API key against stored hashes.
 * Returns { valid: true, keyId, customerId, metadata } or { valid: false }.
 */
async function validateApiKey(presentedKey) {
  if (!presentedKey?.startsWith(KEY_PREFIX)) {
    return { valid: false };
  }

  const preview = presentedKey.slice(0, 8) + '...' + presentedKey.slice(-4);

  const query = `
    SELECT id, customer_id, key_hash, metadata, revoked_at
    FROM api_keys
    WHERE key_preview = $1 AND revoked_at IS NULL
  `;

  const result = await pool.query(query, [preview]);

  for (const row of result.rows) {
    const match = await bcrypt.compare(presentedKey, row.key_hash);
    if (match) {
      return {
        valid: true,
        keyId: row.id,
        customerId: row.customer_id,
        metadata: row.metadata,
      };
    }
  }

  return { valid: false };
}

/**
 * Revoke an API key by ID.
 */
async function revokeApiKey(keyId) {
  await pool.query(
    `UPDATE api_keys SET revoked_at = NOW() WHERE id = $1`,
    [keyId]
  );
}

module.exports = {
  generateApiKey,
  validateApiKey,
  revokeApiKey,
  pool,
};
```

