// apiKeys.js
const { Pool } = require('pg');
const crypto = require('crypto');
const bcrypt = require('bcrypt');

const pool = new Pool({
  connectionString: process.env.DATABASE_URL,
  // Or use individual params: host, port, database, user, password
});

const KEY_PREFIX = 'ck_'; // customer key prefix
const KEY_BYTES = 24;     // 24 bytes = 43 chars base64url
const HASH_COST = 12;     // bcrypt cost factor

/**
 * Generate a new API key for a customer, store its hash, return the plain key once.
 * @param {string} customerId - Your internal customer identifier
 * @param {object} [meta={}] - Optional metadata to store with the key
 * @returns {Promise<string>} The plain API key (show to customer once)
 */
async function generateApiKey(customerId, meta = {}) {
  const randomPart = crypto.randomBytes(KEY_BYTES)
    .toString('base64url'); // URL-safe, no padding
  const plainKey = `${KEY_PREFIX}${randomPart}`;

  const hash = await bcrypt.hash(plainKey, HASH_COST);

  const client = await pool.connect();
  try {
    await client.query('BEGIN');
    await client.query(
      `INSERT INTO api_keys (customer_id, key_hash, meta, created_at)
       VALUES ($1, $2, $3, NOW())`,
      [customerId, hash, JSON.stringify(meta)]
    );
    await client.query('COMMIT');
  } catch (e) {
    await client.query('ROLLBACK');
    throw e;
  } finally {
    client.release();
  }

  return plainKey;
}

/**
 * Verify a presented API key against stored hashes.
 * @param {string} presentedKey - The key sent by the client
 * @returns {Promise<{valid: boolean, customerId?: string, meta?: object}>}
 */
async function verifyApiKey(presentedKey) {
  if (!presentedKey?.startsWith(KEY_PREFIX)) {
    return { valid: false };
  }

  const client = await pool.connect();
  try {
    // Fetch candidate rows (prefix match reduces rows scanned if you index key_hash)
    // Since we store bcrypt hashes, we must fetch and compare in JS.
    // For large tables, store a separate lookup column (e.g., key_prefix = first 8 chars of hash).
    const res = await client.query(
      `SELECT customer_id, key_hash, meta FROM api_keys WHERE revoked_at IS NULL`
    );

    for (const row of res.rows) {
      const match = await bcrypt.compare(presentedKey, row.key_hash);
      if (match) {
        return {
          valid: true,
          customerId: row.customer_id,
          meta: row.meta
        };
      }
    }
    return { valid: false };
  } finally {
    client.release();
  }
}

/**
 * Optional: revoke a key by customer_id (or key hash if you track it)
 */
async function revokeApiKey(customerId) {
  await pool.query(
    `UPDATE api_keys SET revoked_at = NOW() WHERE customer_id = $1 AND revoked_at IS NULL`,
    [customerId]
  );
}

module.exports = { generateApiKey, verifyApiKey, revokeApiKey, pool };
