  const keyHash = crypto.createHash('sha256').update(plaintextKey).digest('hex');
  const keyPrefix = plaintextKey.slice(0, 8); // for display/identification

  const result = await pool.query(
    `INSERT INTO api_keys (customer_id, key_hash, key_prefix, metadata)
     VALUES ($1, $2, $3, $4)
     RETURNING id, created_at`,
    [customerId, keyHash, keyPrefix, JSON.stringify(metadata)]
  );

  return {
    key: plaintextKey, // only returned once
    id: result.rows[0].id,
    prefix: keyPrefix,
    createdAt: result.rows[0].created_at,
  };
}

