// Generate a secure API key, store its hash, return plaintext once
async function generateApiKey(customerId, metadata = {}) {
  const plainKey = `mk_${crypto.randomBytes(24).toString('base64url')}`;
  const keyHash = hashKey(plainKey);
  const keyPrefix = plainKey.slice(0, 8); // for identification without exposing full key

  const { rows } = await pool.query(
    `INSERT INTO api_keys (customer_id, key_hash, key_prefix, metadata)
     VALUES ($1, $2, $3, $4)
     RETURNING id, created_at`,
    [customerId, keyHash, keyPrefix, JSON.stringify(metadata)]
  );

  return {
    key: plainKey,           // only returned once
    id: rows[0].id,
    prefix: keyPrefix,
    createdAt: rows[0].created_at,
  };
}

// Verify a presented API key against stored hashes
async function verifyApiKey(presentedKey) {
  if (!presentedKey?.startsWith('mk_')) return null;

  const prefix = presentedKey.slice(0, 8);
  const { rows } = await pool.query(
    `SELECT id, customer_id, key_hash, metadata, last_used_at, revoked_at
     FROM api_keys
     WHERE key_prefix = $1 AND revoked_at IS NULL`,
    [prefix]
  );

  for (const row of rows) {
    if (verifyHash(presentedKey, row.key_hash)) {
      // Update last_used_at (fire-and-forget)
      pool.query(
        `UPDATE api_keys SET last_used_at = NOW() WHERE id = $1`,
        [row.id]
      ).catch(() => {});
      return {
        valid: true,
        keyId: row.id,
        customerId: row.customer_id,
        metadata: row.metadata,
      };
    }
  }
  return { valid: false };
}

// Revoke an API key
async function revokeApiKey(keyId) {
  await pool.query(
    `UPDATE api_keys SET revoked_at = NOW() WHERE id = $1`,
    [keyId]
  );
}

// --- Crypto helpers (PBKDF2 with SHA-256) ---
function hashKey(key) {
  const salt = crypto.randomBytes(16);
  const hash = crypto.pbkdf2Sync(key, salt, 100000, 32, 'sha256');
  return `pbkdf2$100000$${salt.toString('hex')}$${hash.toString('hex')}`;
}

function verifyHash(key, stored) {
  const [, algo, iterations, saltHex, hashHex] = stored.split('$');
  if (algo !== 'pbkdf2') return false;
  const salt = Buffer.from(saltHex, 'hex');
  const hash = crypto.pbkdf2Sync(key, salt, parseInt(iterations, 10), 32, 'sha256');
  return crypto.timingSafeEqual(hash, Buffer.from(hashHex, 'hex'));
}

