const { Pool } = require('pg');
const crypto = require('crypto');

// Postgres connection pool
const pool = new Pool({
  host: process.env.PG_HOST || 'localhost',
  port: process.env.PG_PORT || 5432,
  database: process.env.PG_DATABASE || 'app_db',
  user: process.env.PG_USER || 'app_user',
  password: process.env.PG_PASSWORD || 'app_pass',
  max: 10,
});

// Hash an API key using SHA-256
function hashKey(key) {
  return crypto.createHash('sha256').update(key).digest('hex');
}

// Generate a new API key for a customer
// Returns the plain key (only shown once) and the key prefix for identification
async function generateApiKey(customerId, metadata = {}) {
  const client = await pool.connect();
  try {
    await client.query('BEGIN');

    // Generate cryptographically secure random key: prefix + 32 random bytes
    const prefix = 'ck_'; // customer key prefix
    const randomBytes = crypto.randomBytes(32).toString('base64url');
    const plainKey = `${prefix}${randomBytes}`;
    const keyHash = hashKey(plainKey);
    const keyPrefix = plainKey.slice(0, 12); // first 12 chars for lookup/display

    const result = await client.query(
      `INSERT INTO api_keys (customer_id, key_hash, key_prefix, metadata, created_at)
       VALUES ($1, $2, $3, $4, NOW())
       RETURNING id, created_at`,
      [customerId, keyHash, keyPrefix, JSON.stringify(metadata)]
    );

    await client.query('COMMIT');
    return {
      key: plainKey,           // only returned once
      keyId: result.rows[0].id,
      keyPrefix,
      createdAt: result.rows[0].created_at,
    };
  } catch (err) {
    await client.query('ROLLBACK');
    throw err;
  } finally {
    client.release();
  }
}

// Validate a presented API key against stored hashes
// Returns { valid: true, keyId, customerId, metadata } or { valid: false }
async function validateApiKey(presentedKey) {
  if (!presentedKey || typeof presentedKey !== 'string') {
    return { valid: false, reason: 'invalid_format' };
  }

  // Quick prefix check to avoid hashing garbage
  if (!presentedKey.startsWith('ck_')) {
    return { valid: false, reason: 'invalid_prefix' };
  }

  const keyHash = hashKey(presentedKey);

  const result = await pool.query(
    `SELECT id, customer_id, metadata, last_used_at
     FROM api_keys
     WHERE key_hash = $1 AND revoked_at IS NULL`,
    [keyHash]
  );

  if (result.rows.length === 0) {
    return { valid: false, reason: 'not_found' };
  }

  const row = result.rows[0];

  // Update last_used_at asynchronously (fire-and-forget)
  pool.query(
    `UPDATE api_keys SET last_used_at = NOW() WHERE id = $1`,
    [row.id]
  ).catch(() => {}); // ignore update failures

  return {
    valid: true,
    keyId: row.id,
    customerId: row.customer_id,
    metadata: row.metadata,
    lastUsedAt: row.last_used_at,
  };
}

// Optional: Revoke an API key
async function revokeApiKey(keyId, customerId) {
  const result = await pool.query(
    `UPDATE api_keys SET revoked_at = NOW() WHERE id = $1 AND customer_id = $2`,
    [keyId, customerId]
  );
  return result.rowCount > 0;
}

// Optional: List keys for a customer (without hashes)
async function listCustomerKeys(customerId) {
  const result = await pool.query(
    `SELECT id, key_prefix, metadata, created_at, last_used_at, revoked_at
     FROM api_keys
     WHERE customer_id = $1
     ORDER BY created_at DESC`,
    [customerId]
  );
  return result.rows;
}

module.exports = {
  generateApiKey,
  validateApiKey,
  revokeApiKey,
  listCustomerKeys,
  pool, // export for graceful shutdown
};
