// apiKeys.js
const { Pool } = require('pg');
const crypto = require('crypto');

const pool = new Pool({
  host: process.env.PG_HOST || 'localhost',
  port: process.env.PG_PORT || 5432,
  database: process.env.PG_DATABASE,
  user: process.env.PG_USER,
  password: process.env.PG_PASSWORD,
});

const KEY_PREFIX = 'sk_';
const KEY_BYTES = 32; // 256 bits
const HASH_ALGO = 'sha256';
const SALT_BYTES = 16;

/**
 * Generate a new API key for a customer, store its hash, return plaintext once.
 * @param {string} customerId - Your internal customer identifier
 * @param {string} [name] - Optional label for the key
 * @returns {Promise<string>} Plaintext API key (show to customer once)
 */
async function generateApiKey(customerId, name = '') {
  const client = await pool.connect();
  try {
    await client.query('BEGIN');

    // Generate cryptographically secure random key
    const randomBytes = crypto.randomBytes(KEY_BYTES);
    const key = KEY_PREFIX + randomBytes.toString('base64url');

    // Hash with salt for storage
    const salt = crypto.randomBytes(SALT_BYTES);
    const hash = crypto.createHash(HASH_ALGO).update(salt).update(key).digest();
    const storedHash = salt.toString('hex') + ':' + hash.toString('hex');

    await client.query(
      `INSERT INTO api_keys (customer_id, key_hash, name, created_at)
       VALUES ($1, $2, $3, NOW())`,
      [customerId, storedHash, name]
    );

    await client.query('COMMIT');
    return key; // Return plaintext once
  } catch (e) {
    await client.query('ROLLBACK');
    throw e;
  } finally {
    client.release();
  }
}

/**
 * Verify a presented API key against stored hashes.
 * @param {string} presentedKey - Key sent by client (e.g., in Authorization header)
 * @returns {Promise<{valid: boolean, customerId?: string, keyId?: number}>}
 */
async function verifyApiKey(presentedKey) {
  if (!presentedKey?.startsWith(KEY_PREFIX)) return { valid: false };

  const client = await pool.connect();
  try {
    const { rows } = await client.query(
      `SELECT id, customer_id, key_hash FROM api_keys WHERE revoked_at IS NULL`
    );

    for (const row of rows) {
      const [saltHex, hashHex] = row.key_hash.split(':');
      const salt = Buffer.from(saltHex, 'hex');
      const computedHash = crypto.createHash(HASH_ALGO).update(salt).update(presentedKey).digest();
      if (computedHash.toString('hex') === hashHex) {
        // Optional: update last_used_at
        await client.query(
          `UPDATE api_keys SET last_used_at = NOW() WHERE id = $1`,
          [row.id]
        );
        return { valid: true, customerId: row.customer_id, keyId: row.id };
      }
    }
    return { valid: false };
  } finally {
    client.release();
  }
}

/**
 * Revoke an API key by ID (soft delete).
 */
async function revokeApiKey(keyId, customerId) {
  await pool.query(
    `UPDATE api_keys SET revoked_at = NOW() WHERE id = $1 AND customer_id = $2`,
    [keyId, customerId]
  );
}

module.exports = { generateApiKey, verifyApiKey, revokeApiKey, pool };
