// apiKeys.js
const { Pool } = require('pg');
const crypto = require('crypto');
const bcrypt = require('bcrypt');

const pool = new Pool({
  host: process.env.PG_HOST || 'localhost',
  port: process.env.PG_PORT || 5432,
  database: process.env.PG_DATABASE,
  user: process.env.PG_USER,
  password: process.env.PG_PASSWORD,
  max: 20,
  idleTimeoutMillis: 30000,
});

const KEY_PREFIX = 'sk_';
const KEY_LENGTH = 32;
const HASH_COST = 12;

/**
 * Generate a new API key for a customer.
 * Returns the plain key ONCE - store it securely.
 */
async function generateApiKey(customerId, metadata = {}) {
  const client = await pool.connect();
  try {
    await client.query('BEGIN');

    // Generate cryptographically secure random key
    const randomPart = crypto.randomBytes(KEY_LENGTH).toString('base64url');
    const plainKey = `${KEY_PREFIX}${randomPart}`;

    // Hash for storage (never store plain keys)
    const keyHash = await bcrypt.hash(plainKey, HASH_COST);
    const keyPreview = plainKey.slice(0, 8) + '...' + plainKey.slice(-4);

    const result = await client.query(
      `INSERT INTO api_keys (customer_id, key_hash, key_preview, metadata, created_at)
       VALUES ($1, $2, $3, $4, NOW())
       RETURNING id, created_at`,
      [customerId, keyHash, keyPreview, JSON.stringify(metadata)]
    );

    await client.query('COMMIT');
    return {
      id: result.rows[0].id,
      key: plainKey,              // Only returned once
      preview: keyPreview,
      createdAt: result.rows[0].created_at,
    };
  } catch (err) {
    await client.query('ROLLBACK');
    throw err;
  } finally {
    client.release();
  }
}

/**
 * Validate a presented API key against stored hashes.
 * Returns key record if valid, null if invalid.
 */
async function validateApiKey(presentedKey) {
  if (!presentedKey || !presentedKey.startsWith(KEY_PREFIX)) {
    return null;
  }

  const client = await pool.connect();
  try {
    // Fetch candidates by prefix (first 8 chars after prefix) for efficiency
    const prefix = presentedKey.slice(0, 8 + KEY_PREFIX.length);
    const result = await client.query(
      `SELECT id, customer_id, key_hash, metadata, created_at, last_used_at, revoked_at
       FROM api_keys
       WHERE key_preview LIKE $1
         AND revoked_at IS NULL`,
      [`${prefix}%`]
    );

    for (const row of result.rows) {
      const match = await bcrypt.compare(presentedKey, row.key_hash);
      if (match) {
        // Update last_used_at asynchronously (fire-and-forget)
        client.query(
          `UPDATE api_keys SET last_used_at = NOW() WHERE id = $1`,
          [row.id]
        ).catch(() => {}); // Ignore update errors

        return {
          id: row.id,
          customerId: row.customer_id,
          metadata: row.metadata,
          createdAt: row.created_at,
          lastUsedAt: row.last_used_at,
        };
      }
    }
    return null;
  } finally {
    client.release();
  }
}

/**
 * Revoke an API key by ID.
 */
async function revokeApiKey(keyId) {
  const result = await pool.query(
    `UPDATE api_keys SET revoked_at = NOW() WHERE id = $1 AND revoked_at IS NULL`,
    [keyId]
  );
  return result.rowCount > 0;
}

/**
 * List API keys for a customer (without hashes).
 */
async function listApiKeys(customerId) {
  const result = await pool.query(
    `SELECT id, key_preview, metadata, created_at, last_used_at, revoked_at
     FROM api_keys
     WHERE customer_id = $1
     ORDER BY created_at DESC`,
    [customerId]
  );
  return result.rows;
}

module.exports = {
  generateApiKey,
  validateApiKey,
  revokeApiKey,
  listApiKeys,
  pool, // Export for graceful shutdown
};
