const pool = new Pool({
  host: process.env.PG_HOST || 'localhost',
  port: process.env.PG_PORT || 5432,
  database: process.env.PG_DATABASE,
  user: process.env.PG_USER,
  password: process.env.PG_PASSWORD,
  max: 10,
});

const KEY_PREFIX = 'sk_';
const KEY_BYTES = 32;
const HASH_ALGO = 'sha256';
const HASH_ITERATIONS = 100000;
const SALT_BYTES = 16;

/**
 * Generate a new API key for a customer.
 * Returns the plain key ONCE - store it securely.
 * @param {string} customerId - Your internal customer identifier
 * @param {object} [metadata] - Optional metadata to store
 * @returns {Promise<string>} The plain API key (shown only once)
 */
async function generateApiKey(customerId, metadata = {}) {
  const plainKey = KEY_PREFIX + crypto.randomBytes(KEY_BYTES).toString('hex');
  const salt = crypto.randomBytes(SALT_BYTES);
  const hash = crypto.pbkdf2Sync(plainKey, salt, HASH_ITERATIONS, 32, HASH_ALGO);

  const client = await pool.connect();
  try {
    await client.query('BEGIN');
    await client.query(
      `INSERT INTO api_keys (customer_id, key_hash, salt, metadata, created_at)
       VALUES ($1, $2, $3, $4, NOW())`,
      [customerId, hash, salt, JSON.stringify(metadata)]
    );
    await client.query('COMMIT');
    return plainKey;
  } catch (e) {
    await client.query('ROLLBACK');
    throw e;
  } finally {
    client.release();
  }
}

/**
 * Verify a presented API key against stored hashes.
 * @param {string} presentedKey - The key provided by the client
 * @returns {Promise<{valid: boolean, customerId?: string, metadata?: object}>}
 */
async function verifyApiKey(presentedKey) {
  if (!presentedKey || !presentedKey.startsWith(KEY_PREFIX)) {
    return { valid: false };
  }

  const client = await pool.connect();
  try {
    const result = await client.query(
      `SELECT customer_id, key_hash, salt, metadata
       FROM api_keys
       WHERE revoked_at IS NULL`
    );

    for (const row of result.rows) {
      const computedHash = crypto.pbkdf2Sync(
        presentedKey,
        row.salt,
        HASH_ITERATIONS,
        32,
        HASH_ALGO
      );
      if (crypto.timingSafeEqual(computedHash, row.key_hash)) {
        return {
          valid: true,
          customerId: row.customer_id,
          metadata: row.metadata,
        };
      }
    }
    return { valid: false };
  } finally {
    client.release();
  }
}

/**
 * Revoke an API key by customer ID (optional cleanup).
 */
async function revokeApiKey(customerId) {
  await pool.query(
    `UPDATE api_keys SET revoked_at = NOW() WHERE customer_id = $1`,
    [customerId]
  );
}

module.exports = { generateApiKey, verifyApiKey, revokeApiKey, pool };
