// apiKeys.js
const { Pool } = require('pg');
const crypto = require('crypto');

// PostgreSQL connection pool
const pool = new Pool({
  connectionString: process.env.DATABASE_URL,
  max: 10,
  idleTimeoutMillis: 30000,
});

// Initialize table (run once at startup)
async function initTable() {
  await pool.query(`
    CREATE TABLE IF NOT EXISTS api_keys (
      id SERIAL PRIMARY KEY,
      customer_id VARCHAR(255) NOT NULL,
      key_hash BYTEA NOT NULL,
      key_prefix VARCHAR(8) NOT NULL,
      created_at TIMESTAMPTZ DEFAULT NOW(),
      last_used_at TIMESTAMPTZ,
      revoked_at TIMESTAMPTZ
    );
    CREATE INDEX IF NOT EXISTS idx_api_keys_prefix ON api_keys(key_prefix);
  `);
}

// Generate a secure API key, store its hash, return plain key once
// Format: "sk_live_<24 random chars>"
async function generateApiKey(customerId) {
  const randomBytes = crypto.randomBytes(24);
  const keySuffix = randomBytes.toString('base64url'); // URL-safe, no padding
  const plainKey = `sk_live_${keySuffix}`;
  const keyPrefix = plainKey.slice(0, 12); // "sk_live_xxxx" for fast lookup

  // Hash with SHA-256 (fast, deterministic, no salt needed for high-entropy keys)
  const keyHash = crypto.createHash('sha256').update(plainKey).digest();

  await pool.query(
    `INSERT INTO api_keys (customer_id, key_hash, key_prefix)
     VALUES ($1, $2, $3)`,
    [customerId, keyHash, keyPrefix]
  );

  return plainKey; // Show to customer ONCE
}

// Validate a presented API key, return customerId if valid
async function validateApiKey(presentedKey) {
  if (!presentedKey || typeof presentedKey !== 'string') return null;

  const keyPrefix = presentedKey.slice(0, 12);
  const presentedHash = crypto.createHash('sha256').update(presentedKey).digest();

  const result = await pool.query(
    `SELECT customer_id, key_hash, revoked_at
     FROM api_keys
     WHERE key_prefix = $1`,
    [keyPrefix]
  );

  if (result.rows.length === 0) return null;

  const row = result.rows[0];
  if (row.revoked_at) return null;

  // Constant-time comparison
  const storedHash = row.key_hash;
  if (storedHash.length !== presentedHash.length) return null;
  let match = 0;
  for (let i = 0; i < storedHash.length; i++) {
    match |= storedHash[i] ^ presentedHash[i];
  }
  if (match !== 0) return null;

  // Update last_used_at (fire-and-forget)
  pool.query(
    `UPDATE api_keys SET last_used_at = NOW() WHERE key_prefix = $1`,
    [keyPrefix]
  ).catch(() => {});

  return row.customer_id;
}

// Optional: Revoke a key by prefix (e.g., on customer request)
async function revokeApiKey(keyPrefix) {
  await pool.query(
    `UPDATE api_keys SET revoked_at = NOW() WHERE key_prefix = $1`,
    [keyPrefix]
  );
}

module.exports = { initTable, generateApiKey, validateApiKey, revokeApiKey };
