/**
 * Generate a secure API key, store its hash, return plaintext key once.
 * @param {string} customerId - Unique identifier for the customer
 * @param {string} [name] - Optional customer name/label
 * @returns {Promise<string>} The plaintext API key (shown only once)
 */
async function generateApiKey(customerId, name = '') {
  // Generate 32 bytes (256 bits) of entropy, encode as URL-safe base64
  const plainKey = `uyg_${crypto.randomBytes(32).toString('base64url')}`;

  // Hash with SHA-256 for storage (never store plaintext)
  const keyHash = crypto.createHash('sha256').update(plainKey).digest('hex');

  const query = `
    INSERT INTO api_keys (customer_id, key_hash, name, created_at)
    VALUES ($1, $2, $3, NOW())
    ON CONFLICT (customer_id) DO UPDATE SET
      key_hash = EXCLUDED.key_hash,
      name = EXCLUDED.name,
      created_at = NOW()
    RETURNING id;
  `;

  await pool.query(query, [customerId, keyHash, name]);
  return plainKey; // Return once - caller must show to customer immediately
}

/**
 * Validate a presented API key against stored hashes.
 * @param {string} presentedKey - The key provided by the client
 * @returns {Promise<{valid: boolean, customerId?: string, name?: string}>}
 */
async function validateApiKey(presentedKey) {
  if (!presentedKey || typeof presentedKey !== 'string') {
    return { valid: false };
  }

  // Hash the presented key the same way
  const presentedHash = crypto.createHash('sha256').update(presentedKey).digest('hex');

  const query = `
    SELECT customer_id, name
    FROM api_keys
    WHERE key_hash = $1
    LIMIT 1;
  `;

  const result = await pool.query(query, [presentedHash]);

  if (result.rows.length === 0) {
    return { valid: false };
  }

  return {
    valid: true,
    customerId: result.rows[0].customer_id,
    name: result.rows[0].name,
  };
}

/**
 * Revoke an API key by customer ID.
 * @param {string} customerId
 * @returns {Promise<boolean>} True if a key was deleted
 */
async function revokeApiKey(customerId) {
  const result = await pool.query(
    'DELETE FROM api_keys WHERE customer_id = $1',
    [customerId]
  );
  return result.rowCount > 0;
}

/**
 * Close the connection pool (call on app shutdown).
 */
async function closePool() {
  await pool.end();
}

module.exports = {
  generateApiKey,
  validateApiKey,
  revokeApiKey,
  closePool,
};
