 * @param {string} customerId - Your internal customer identifier
 * @param {string} [label] - Optional description (e.g., "mobile app", "server")
 * @returns {Promise<string>} The plain API key (show to customer once)
 */
async function generateApiKey(customerId, label = '') {
  const client = await pool.connect();
  try {
    await client.query('BEGIN');

    // Generate a secure random key: 32 bytes = 256 bits entropy
    const rawKey = crypto.randomBytes(32).toString('hex');
    const prefix = 'ukc_'; // identifiable prefix for your center
    const apiKey = prefix + rawKey;

    // Hash with SHA-256 + salt for storage
    const salt = crypto.randomBytes(16).toString('hex');
    const hash = crypto.createHash('sha256').update(salt + rawKey).digest('hex');

    await client.query(
      `INSERT INTO api_keys (customer_id, key_hash, salt, label, created_at)
       VALUES ($1, $2, $3, $4, NOW())`,
      [customerId, hash, salt, label]
    );

    await client.query('COMMIT');
    return apiKey; // Return plain key ONCE to show the customer
  } catch (e) {
    await client.query('ROLLBACK');
    throw e;
  } finally {
    client.release();
  }
}

/**
 * Verify a presented API key against stored hashes.
 * @param {string} presentedKey - The key sent by the client (e.g., in Authorization header)
 * @returns {Promise<{valid: boolean, customerId?: string, label?: string}>}
 */
async function verifyApiKey(presentedKey) {
  if (!presentedKey || !presentedKey.startsWith('ukc_')) {
    return { valid: false };
  }

  const rawKey = presentedKey.slice(4); // strip prefix

  const client = await pool.connect();
  try {
    const result = await client.query(
      `SELECT customer_id, key_hash, salt, label, revoked_at
       FROM api_keys
       WHERE key_hash = $1`,
      [crypto.createHash('sha256').update('placeholder').digest('hex')] // dummy, we'll filter in JS
    );

