    // Better: store a key_prefix column (first 8 chars of rawKey) for indexed lookup
    // For simplicity here, we do a small scan (add key_prefix column in production)
    const candidates = await client.query(
      `SELECT customer_id, key_hash, salt, label, revoked_at
       FROM api_keys
       WHERE revoked_at IS NULL`
    );

    for (const row of candidates.rows) {
      const computedHash = crypto.createHash('sha256')
        .update(row.salt + rawKey)
        .digest('hex');
      if (computedHash === row.key_hash) {
        return { valid: true, customerId: row.customer_id, label: row.label };
      }
    }
    return { valid: false };
  } finally {
    client.release();
  }
}

