// apiKeys.js
const { Pool } = require('pg');
const crypto = require('crypto');
const bcrypt = require('bcrypt');

const pool = new Pool({
  connectionString: process.env.DATABASE_URL,
  // Or use individual params: host, port, database, user, password
});

const KEY_PREFIX = 'hkda_';
const KEY_BYTES = 32; // 256 bits
const BCRYPT_ROUNDS = 12;

/**
 * Generate a new API key for a customer.
 * Returns { key, keyId } — the plaintext key is shown ONLY once.
 * Stores only the bcrypt hash in the database.
 */
async function generateApiKey(customerId, metadata = {}) {
  const randomPart = crypto.randomBytes(KEY_BYTES).toString('base64url');
  const key = `${KEY_PREFIX}${randomPart}`;
  const keyHash = await bcrypt.hash(key, BCRYPT_ROUNDS);
  const keyId = crypto.randomUUID();

  const client = await pool.connect();
  try {
    await client.query('BEGIN');
    await client.query(
      `INSERT INTO api_keys (id, customer_id, key_hash, metadata, created_at)
       VALUES ($1, $2, $3, $4, NOW())`,
      [keyId, customerId, keyHash, JSON.stringify(metadata)]
    );
    await client.query('COMMIT');
    return { key, keyId };
  } catch (e) {
    await client.query('ROLLBACK');
    throw e;
  } finally {
    client.release();
  }
}

/**
 * Verify a presented API key.
 * Returns { valid: true, keyId, customerId, metadata } or { valid: false }.
 * Updates last_used_at on success.
 */
async function verifyApiKey(presentedKey) {
  if (!presentedKey?.startsWith(KEY_PREFIX)) return { valid: false };

  const client = await pool.connect();
  try {
    // Fetch candidates — in practice you'd index a key_prefix column for scale
    const { rows } = await client.query(
      `SELECT id, customer_id, key_hash, metadata
       FROM api_keys
       WHERE revoked_at IS NULL`
    );

    for (const row of rows) {
      const match = await bcrypt.compare(presentedKey, row.key_hash);
      if (match) {
        await client.query(
          `UPDATE api_keys SET last_used_at = NOW() WHERE id = $1`,
          [row.id]
        );
        return {
          valid: true,
          keyId: row.id,
          customerId: row.customer_id,
          metadata: row.metadata
        };
      }
    }
    return { valid: false };
  } finally {
    client.release();
  }
}

/**
 * Revoke an API key by its ID.
 */
async function revokeApiKey(keyId) {
  await pool.query(
    `UPDATE api_keys SET revoked_at = NOW() WHERE id = $1`,
    [keyId]
  );
}

module.exports = { generateApiKey, verifyApiKey, revokeApiKey, pool };
