  if (result.rows.length === 0) return null;

  const stored = result.rows[0];
  // Constant-time comparison
  const match = crypto.timingSafeEqual(
    Buffer.from(stored.key_hash),
    Buffer.from(hash)
  );

  return match ? stored.customer_id : null;
