// Assumes: pool is a mysql2/promise pool (pool.execute returns [rows, fields])

async function getUserOrders(userId, status, fromDate) {
  // Base query
  let sql = 'SELECT * FROM orders WHERE user_id = ?';
  const params = [userId];

  // Dynamic WHERE clauses
  if (status) {
    sql += ' AND status = ?';
    params.push(status);
  }

  if (fromDate) {
    // Assumes fromDate is a valid Date object, ISO string, or 'YYYY-MM-DD' format compatible with MySQL
    sql += ' AND created_at >= ?';
    params.push(fromDate);
  }

  // Optional: Add default ordering
  sql += ' ORDER BY created_at DESC';

  try {
    const [rows] = await pool.execute(sql, params);
    return rows;
  } catch (error) {
    console.error('Database error in getUserOrders:', error);
    throw error; // Re-throw to let caller handle HTTP 500 etc.
  }
}

module.exports = { getUserOrders };
