```javascript
/**
 * Retrieves orders for a specific user with optional filtering.
 * 
 * @param {number|string} userId - The ID of the user (required).
 * @param {string} [status] - Optional order status to filter by (e.g., 'pending', 'shipped').
 * @param {string|Date} [fromDate] - Optional start date (inclusive) to filter by created_at. 
 *                                   Accepts ISO string 'YYYY-MM-DD' or Date object.
 * @returns {Promise<Array>} A promise resolving to an array of order objects.
 * @throws {Error} Throws if userId is missing or database query fails.
 */
async function getUserOrders(userId, status, fromDate) {
  // Basic validation
  if (!userId) {
    throw new Error('userId is required');
  }

  // Base query
  let sql = 'SELECT * FROM `orders` WHERE `user_id` = ?';
  const params = [userId];

  // Dynamic WHERE clauses
  if (status) {
    sql += ' AND `status` = ?';
    params.push(status);
  }

  if (fromDate) {
    // Ensure date is formatted correctly for MySQL (YYYY-MM-DD HH:MM:SS)
    // If input is Date object, toISOString() gives UTC. 
    // If input is string, assume it's valid or parse it.
    const dateObj = fromDate instanceof Date ? fromDate : new Date(fromDate);

    if (isNaN(dateObj.getTime())) {
        throw new Error('Invalid fromDate format');
    }

    // Use slice to get 'YYYY-MM-DD' for DATE comparison, 
    // or toISOString().replace('T', ' ').substring(0, 19) for DATETIME comparison.
    // Assuming created_at is DATETIME/TIMESTAMP:
    const formattedDate = dateObj.toISOString().slice(0, 19).replace('T', ' ');

    sql += ' AND `created_at` >= ?';
    params.push(formattedDate);
  }

  // Optional: Add ordering for consistency
  sql += ' ORDER BY `created_at` DESC';

  try {
    // pool.execute uses prepared statements (safe from injection)
    // Returns [rows, fields]
    const [rows] = await pool.execute(sql, params);
    return rows;
  } catch (error) {
    // Log error appropriately in production (e.g., logger.error(error))
    console.error('Database error in getUserOrders:', error);
    throw error; // Re-throw to let caller handle HTTP response etc.
  }
