```php
<?php

/**
 * Fetches a paginated, sortable, searchable list of products.
 *
 * @param mysqli $mysqli An active mysqli connection instance.
 * @param int    $perPage Number of items per page (default 12).
 * @return array Associative array containing 'data', 'pagination', and 'filters'.
 *               Returns ['data' => [], 'pagination' => ..., 'filters' => ...] on error or empty result.
 */
function getProductListing(mysqli $mysqli, int $perPage = 12): array
{
    // ---------------------------------------------------------
    // 1. INPUT HANDLING & VALIDATION
    // ---------------------------------------------------------

    // Page: Default 1, min 1, integer
    $page = max(1, (int)($_GET['page'] ?? 1));

    // Search: Optional, trim whitespace, limit length
    $searchTerm = trim($_GET['search'] ?? '');
    $searchTerm = mb_substr($searchTerm, 0, 100); // Prevent overly long search strings

    // Sort: Whitelist validation (Critical for security)
    // Map user-friendly keys to actual DB columns
    $allowedSortMap = [
        'newest'     => 'created_at DESC',
        'oldest'     => 'created_at ASC',
        'price_asc'  => 'price ASC',
        'price_desc' => 'price DESC',
        'name_asc'   => 'name ASC',
        'name_desc'  => 'name DESC',
        'popular'    => 'sales_count DESC', // Assuming a sales_count column exists
    ];

    $sortKey = $_GET['sort'] ?? 'newest';
    $orderByClause = $allowedSortMap[$sortKey] ?? $allowedSortMap['newest']; // Fallback to default

    // ---------------------------------------------------------
    // 2. BUILD QUERY (Prepared Statements)
    // ---------------------------------------------------------

    // Base WHERE clause
    $whereClauses = ["status = 'active'"]; // Assuming a status column
    $params = [];
    $types = '';

    if ($searchTerm !== '') {
        // Search across name, description, and SKU
        $whereClauses[] = "(name LIKE ? OR description LIKE ? OR sku LIKE ?)";
        $searchParam = "%{$searchTerm}%";
        // Bind the same param 3 times
        $params[] = $searchParam;
        $params[] = $searchParam;
        $params[] = $searchParam;
        $types .= 'sss';
    }

    $whereSql = 'WHERE ' . implode(' AND ', $whereClauses);

    // ---------------------------------------------------------
    // 3. COUNT TOTAL ROWS (For Pagination)
    // ---------------------------------------------------------
    $countSql = "SELECT COUNT(*) as total FROM products {$whereSql}";
    $totalItems = 0;

    if ($stmt = $mysqli->prepare($countSql)) {
        if ($params) {
            $stmt->bind_param($types, ...$params);
        }
        $stmt->execute();
        $result = $stmt->get_result();
        $totalItems = (int)($result->fetch_assoc()['total'] ?? 0);
        $stmt->close();
    } else {
        error_log("Product Count Query Failed: " . $mysqli->error);
        return ['data' => [], 'pagination' => [], 'filters' => []];
    }

    // Calculate Pagination Metadata
    $totalPages = (int)ceil($totalItems / $perPage);
    $page = min($page, max(1, $totalPages)); // Clamp page to valid range
    $offset = ($page - 1) * $perPage;

    // ---------------------------------------------------------
    // 4. FETCH DATA
    // ---------------------------------------------------------
    // Explicitly select columns (avoid SELECT *)
    $columns = "id, name, slug, price, sale_price, thumbnail_url, stock_quantity, created_at";
    $dataSql = "SELECT {$columns} FROM products {$whereSql} ORDER BY {$orderByClause} LIMIT ? OFFSET ?";

    // Add Limit/Offset to params
    $params[] = $perPage;
    $params[] = $offset;
    $types .= 'ii';

    $products = [];

    if ($stmt = $mysqli->prepare($dataSql)) {
        $stmt->bind_param($types, ...$params);
        $stmt->execute();
        $result = $stmt->get_result();

        while ($row = $result->fetch_assoc()) {
            // Optional: Format data for frontend (e.g., format price, check stock status)
            $row['formatted_price'] = number_format($row['price'], 2);
            $row['in_stock'] = (bool)$row['stock_quantity'];
            $products[] = $row;
        }
        $stmt->close();
    } else {
        error_log("Product Data Query Failed: " . $mysqli->error);
    }

    // ---------------------------------------------------------
    // 5. RETURN STRUCTURED RESPONSE
    // ---------------------------------------------------------
    return [
        'data' => $products,
        'pagination' => [
            'current_page' => $page,
            'per_page'     => $perPage,
            'total_items'  => $totalItems,
            'total_pages'  => $totalPages,
            'has_next'     => $page < $totalPages,
            'has_prev'     => $page > 1,
            'next_page'    => $page < $totalPages ? $page + 1 : null,
            'prev_page'    => $page > 1 ? $page - 1 : null,
        ],
        'filters' => [
            'search' => $searchTerm,
            'sort'   => $sortKey,
            'allowed_sorts' => array_keys($allowedSortMap), // Useful for frontend dropdowns
        ]
    ];
}

