<?php

/**
 * Fetches a paginated, sorted, and filtered list of products.
 *
 * @param mysqli $mysqli     Active mysqli connection instance.
 * @param int    $perPage    Number of items per page (default: 12).
 * @return array             ['data' => [], 'total' => 0, 'page' => 1, 'perPage' => 12, 'totalPages' => 1]
 */
function getProductListing(mysqli $mysqli, int $perPage = 12): array
{
    // --- 1. Validate & Sanitize Inputs ---

    // Page: Default 1, min 1
    $page = isset($_GET['page']) ? max(1, (int)$_GET['page']) : 1;
    $offset = ($page - 1) * $perPage;

    // Sort: Whitelist allowed columns to prevent SQL Injection via ORDER BY
    $allowedSortColumns = ['id', 'name', 'price', 'created_at', 'sku'];
    $sort = $_GET['sort'] ?? 'created_at'; // Default sort column
    if (!in_array($sort, $allowedSortColumns, true)) {
        $sort = 'created_at';
    }

    // Direction: Whitelist ASC/DESC
    $dir = strtoupper($_GET['dir'] ?? 'DESC');
    if (!in_array($dir, ['ASC', 'DESC'], true)) {
        $dir = 'DESC';
    }

    // Search: Optional string, trim whitespace
    $searchTerm = isset($_GET['search']) ? trim((string)$_GET['search']) : '';
    $hasSearch = $searchTerm !== '';

    // --- 2. Build Base WHERE Clause ---
    // We build the WHERE clause dynamically but safely.
    $whereClauses = ["is_active = 1"]; // Example: only show active products
    $params = [];
    $types = '';

    if ($hasSearch) {
        // Search across multiple columns (Name, SKU, Description)
        // Using CONCAT or OR logic. OR is usually better for indexes.
        $whereClauses[] = "(name LIKE ? OR sku LIKE ? OR description LIKE ?)";
        $searchParam = "%{$searchTerm}%";
        // Add 3 params for the 3 placeholders
        $params[] = $searchParam;
        $params[] = $searchParam;
        $params[] = $searchParam;
        $types .= 'sss';
    }

    $whereSql = 'WHERE ' . implode(' AND ', $whereClauses);

    // --- 3. Get Total Count (for Pagination) ---
    $countSql = "SELECT COUNT(*) as total FROM products {$whereSql}";
    $stmtCount = $mysqli->prepare($countSql);

    if (!$stmtCount) {
        error_log("Count Query Prepare Failed: " . $mysqli->error);
        return ['data' => [], 'total' => 0, 'page' => $page, 'perPage' => $perPage, 'totalPages' => 0];
    }

    if ($hasSearch) {
        $stmtCount->bind_param($types, ...$params);
    }

    $stmtCount->execute();
    $total = (int)($stmtCount->get_result()->fetch_assoc()['total'] ?? 0);
    $stmtCount->close();

    // Calculate total pages
    $totalPages = $perPage > 0 ? (int)ceil($total / $perPage) : 1;
    // Clamp current page to valid range
    if ($page > $totalPages) $page = max(1, $totalPages);
    $offset = ($page - 1) * $perPage;

    // --- 4. Fetch Data ---
    // Explicitly select columns (avoid SELECT *)
    $columns = "id, sku, name, price, stock_quantity, created_at";
    $dataSql = "SELECT {$columns} FROM products {$whereSql} ORDER BY `{$sort}` {$dir} LIMIT ? OFFSET ?";

    $stmtData = $mysqli->prepare($dataSql);

    if (!$stmtData) {
        error_log("Data Query Prepare Failed: " . $mysqli->error);
        return ['data' => [], 'total' => $total, 'page' => $page, 'perPage' => $perPage, 'totalPages' => $totalPages];
    }

    // Append Limit/Offset params (integers)
    $params[] = $perPage;
    $params[] = $offset;
    $types .= 'ii';

    $stmtData->bind_param($types, ...$params);
    $stmtData->execute();
    $result = $stmtData->get_result();

    $data = $result->fetch_all(MYSQLI_ASSOC);
    $stmtData->close();

    // --- 5. Return Structured Result ---
    return [
        'data'       => $data,
        'total'      => $total,
        'page'       => $page,
        'perPage'    => $perPage,
        'totalPages' => $totalPages,
        'sort'       => $sort,
        'dir'        => $dir,
        'search'     => $searchTerm,
    ];
}

