    $page      = isset($_GET['page'])      ? max(1, (int)$_GET['page'])      : 1;          // 1‑based page number
    $perPage   = 20;                                                                       // items per page (adjust as needed)
    $offset    = ($page - 1) * $perPage;

    // Allowed sort columns – whitelist to avoid SQL injection
    $allowedSort = ['id', 'name', 'price', 'created_at'];
    $sort        = isset($_GET['sort']) && in_array($_GET['sort'], $allowedSort, true)
                    ? $_GET['sort']
                    : 'id';                                                               // default sort column
    $order       = (isset($_GET['order']) && strtoupper($_GET['order']) === 'DESC')
                    ? 'DESC'
                    : 'ASC';                                                              // default ASC

    $search      = isset($_GET['q']) ? trim($_GET['q']) : '';                             // optional search term

    // ---- 2. Build the query with prepared statements ----
    $sql = "SELECT id, name, description, price, created_at
            FROM products";

    $params = [];
    $types  = '';

    if ($search !== '') {
        $sql .= " WHERE name LIKE ? OR description LIKE ?";
        $likeTerm = "%{$search}%";
        $params[] = $likeTerm;
        $params[] = $likeTerm;
        $types   .= 'ss';
    }

    $sql .= " ORDER BY `{$sort}` {$order} LIMIT ? OFFSET ?";
    $params[] = $perPage;
    $params[] = $offset;
    $types   .= 'ii';

    // ---- 3. Execute ----
    $stmt = $mysqli->prepare($sql);
    if (!$stmt) {
        // In production you'd log $mysqli->error and possibly throw an exception
        return [];
    }

    $stmt->bind_param($types, ...$params);
    $stmt->execute();
    $result = $stmt->get_result();

    // ---- 4. Fetch all rows as associative arrays ----
    $rows = $result ? $result->fetch_all(MYSQLI_ASSOC) : [];

