import subprocess
import platform
import re

def ping_host(hostname: str, count: int = 4) -> dict:
    """
    Ping `hostname` using the system ping command.
    Returns a dict with keys:
        reachable (bool) – True if at least one reply received
        avg_rtt_ms (float|None) – average round‑trip time in ms, or None if unreachable
    Works on Linux and macOS.
    """
    system = platform.system().lower()
    # Build command: -c count, -W timeout (Linux) / -t timeout (macOS)
    if system == "linux":
        cmd = ["ping", "-c", str(count), "-W", "2", hostname]
    elif system == "darwin":  # macOS
        cmd = ["ping", "-c", str(count), "-t", "2", hostname]
    else:
        raise OSError(f"Unsupported platform: {system}")

    try:
        result = subprocess.run(cmd, capture_output=True, text=True, timeout=10)
    except subprocess.TimeoutExpired:
        return {"reachable": False, "avg_rtt_ms": None}

    output = result.stdout
    # Look for the summary line containing "rtt min/avg/max/mdev" (Linux) or "round-trip min/avg/max/stddev" (macOS)
    # Example Linux: rtt min/avg/max/mdev = 12.345/15.678/20.123/2.345 ms
    # Example macOS: round-trip min/avg/max/stddev = 12.345/15.678/20.123/2.345 ms
    pattern = r"(?:rtt|round-trip)\s+min/avg/max/(?:mdev|stddev)\s*=\s*[\d.]+/([\d.]+)/"
    match = re.search(pattern, output)
    if match:
        avg = float(match.group(1))
        return {"reachable": True, "avg_rtt_ms": avg}
    # If no summary line, check for any "bytes from" lines (indicates at least one reply)
    if re.search(r"bytes from", output):
        return {"reachable": True, "avg_rtt_ms": None}
    return {"reachable": False, "avg_rtt_ms": None}

