    # Parse average RTT from output (last line typically contains "rtt min/avg/max/mdev = ...")
    output = result.stdout
    # Regex for Linux/macOS ping summary line
    match = re.search(r"rtt min/avg/max/mdev = ([\d.]+)/([\d.]+)/([\d.]+)/([\d.]+) ms", output)
    if not match:
