    if custom_template:
        return render_template_string(custom_template, **user)

    # Otherwise load from templates/emails/{template_name}
    try:
        return current_app.jinja_env.get_template(f"emails/{template_name}").render(**user)
    except TemplateNotFound:
        raise ValueError(f"Email template not found: emails/{template_name}")
