// thumbnail.js
// Uses ImageMagick's `convert` CLI to create a thumbnail of a given width.
// Returns a Promise that resolves when the conversion finishes.

const { spawn } = require('child_process');
const path = require('path');
const fs = require('fs');

/**
 * Create a thumbnail using ImageMagick.
 *
 * @param {string} inputPath  - Absolute or relative path to the source image.
 * @param {string} outputPath - Desired path for the generated thumbnail.
 * @param {number} width      - Target width in pixels (height is scaled proportionally).
 * @returns {Promise<void>}   - Resolves on success, rejects on error.
 */
function createThumbnail(inputPath, outputPath, width) {
  return new Promise((resolve, reject) => {
    // Basic validation
    if (!fs.existsSync(inputPath)) {
      return reject(new Error(`Input file not found: ${inputPath}`));
    }
    if (typeof width !== 'number' || width <= 0) {
      return reject(new Error('Width must be a positive number'));
    }

    // Ensure output directory exists
    const outDir = path.dirname(outputPath);
    if (!fs.existsSync(outDir)) {
      fs.mkdirSync(outDir, { recursive: true });
    }

    // ImageMagick command: convert input -resize WIDTHx output
    const args = [
      inputPath,
      '-resize',
      `${width}x`,   // "WIDTHx" keeps aspect ratio, sets max width
      outputPath
    ];

    const convert = spawn('convert', args);

    let stderr = '';
    convert.stderr.on('data', (data) => {
      stderr += data.toString();
    });

    convert.on('error', (err) => {
      // e.g., `convert` not found in PATH
      reject(new Error(`Failed to start ImageMagick: ${err.message}`));
    });

    convert.on('close', (code) => {
      if (code === 0) {
        resolve();
      } else {
        reject(new Error(`ImageMagick exited with code ${code}: ${stderr.trim()}`));
      }
    });
  });
}

module.exports = { createThumbnail };
