// thumbnail.js
// Simple wrapper around ImageMagick's `convert` CLI to create a thumbnail.
// Returns a Promise that resolves when the conversion finishes or rejects on error.

const { spawn } = require('child_process');
const path = require('path');
const fs = require('fs');

/**
 * Create a thumbnail using ImageMagick's `convert` command.
 *
 * @param {string} inputPath  - Absolute or relative path to the source image.
 * @param {string} outputPath - Desired path for the generated thumbnail.
 * @param {number} width      - Target width in pixels (height is scaled proportionally).
 * @returns {Promise<void>}   - Resolves on success, rejects with an Error on failure.
 */
function createThumbnail(inputPath, outputPath, width) {
  return new Promise((resolve, reject) => {
    // Basic validation
    if (!inputPath || !outputPath || typeof width !== 'number' || width <= 0) {
      return reject(new Error('Invalid arguments: inputPath, outputPath, and a positive width are required.'));
    }

    // Ensure the input file exists before spawning the process
    if (!fs.existsSync(inputPath)) {
      return reject(new Error(`Input file not found: ${inputPath}`));
    }

    // Ensure output directory exists
    const outDir = path.dirname(outputPath);
    if (!fs.existsSync(outDir)) {
      fs.mkdirSync(outDir, { recursive: true });
    }

    // Build the ImageMagick command:
    //   convert input -resize "WIDTHx" output
    // The trailing "x" tells ImageMagick to keep the aspect ratio.
    const args = [
      inputPath,
      '-resize',
      `${width}x`,
      outputPath
    ];

    const convert = spawn('convert', args, { stdio: ['ignore', 'pipe', 'pipe'] });

    let stderr = '';

    convert.stderr.on('data', (chunk) => {
      stderr += chunk.toString();
    });

    convert.on('error', (err) => {
      // Spawn errors (e.g., command not found)
      reject(new Error(`Failed to start ImageMagick convert: ${err.message}`));
    });

    convert.on('close', (code) => {
      if (code === 0) {
        resolve(); // Success
      } else {
        reject(new Error(`ImageMagick convert exited with code ${code}: ${stderr.trim()}`));
      }
    });
  });
}

module.exports = { createThumbnail };
