from cryptography.hazmat.primitives.ciphers.aead import AESGCM
import os

def encrypt(plaintext: bytes, key: bytes) -> bytes:
    """Encrypt plaintext with AES-256-GCM. Returns nonce + ciphertext + tag."""
    if len(key) != 32:
        raise ValueError("Key must be 32 bytes (AES-256)")
    nonce = os.urandom(12)  # 96-bit nonce for GCM
    aesgcm = AESGCM(key)
    ciphertext = aesgcm.encrypt(nonce, plaintext, None)
    return nonce + ciphertext  # nonce (12) + ciphertext+tag (variable)

def decrypt(data: bytes, key: bytes) -> bytes:
    """Decrypt data encrypted by encrypt()."""
    if len(key) != 32:
        raise ValueError("Key must be 32 bytes (AES-256)")
    if len(data) < 12:
        raise ValueError("Data too short to contain nonce")
    nonce = data[:12]
    ciphertext = data[12:]
    aesgcm = AESGCM(key)
    return aesgcm.decrypt(nonce, ciphertext, None)
