    """Generate a 6-digit code and store it for the phone number."""
    code = f"{random.randint(0, 999999):06d}"
    _pending_codes[phone_number] = {
        "code": code,
        "expires_at": time.time() + CODE_TTL_SECONDS
    }
    return code


def verify_code(phone_number: str, user_code: str) -> bool:
    """Check if the user's code matches and hasn't expired."""
    record = _pending_codes.get(phone_number)
    if not record:
        return False

    if time.time() > record["expires_at"]:
        del _pending_codes[phone_number]
        return False

    if record["code"] == user_code:
        del _pending_codes[phone_number]  # consume code
        return True

    return False


def cleanup_expired() -> None:
    """Remove all expired codes from storage."""
    now = time.time()
    expired = [phone for phone, rec in _pending_codes.items() if now > rec["expires_at"]]
    for phone in expired:
        del _pending_codes[phone]

