    """Hash a password using bcrypt. Returns a single string containing salt + hash."""
    # bcrypt.gensalt() generates a random salt; bcrypt.hashpw combines salt + hash
    # Result is a bytes string like b'$2b$12$...' — decode to str for storage
    return bcrypt.hashpw(password.encode('utf-8'), bcrypt.gensalt()).decode('utf-8')

