def generate_code(phone_number: str) -> str:
    """Generate a 6-digit code and store it with expiry."""
    code = f"{random.randint(0, 999999):06d}"
    _pending_codes[phone_number] = {
        "code": code,
        "expires_at": time.time() + VALIDITY_SECONDS
    }
    return code


def verify_code(phone_number: str, user_code: str) -> bool:
    """Check if the provided code matches and hasn't expired."""
    record = _pending_codes.get(phone_number)
    if not record:
        return False

    if time.time() > record["expires_at"]:
        del _pending_codes[phone_number]
        return False

    if record["code"] == user_code:
        del _pending_codes[phone_number]  # one-time use
        return True

    return False


def cleanup_expired() -> None:
    """Remove expired codes from the store."""
    now = time.time()
    expired = [num for num, rec in _pending_codes.items() if now > rec["expires_at"]]
    for num in expired:
        del _pending_codes[num]

