// url-signer.js
const crypto = require('crypto');
const { URLSearchParams } = require('url');

/**
 * URL Signer for secure, expiring download links.
 * Uses HMAC-SHA256 with a secret key.
 */
class UrlSigner {
  /**
   * @param {string | Buffer} secret - The secret key used for signing. Must be kept private.
   * @param {object} [options]
   * @param {string} [options.algorithm='sha256'] - Hash algorithm (e.g., 'sha256', 'sha512').
   * @param {string} [options.pathParam='path'] - Query parameter name for the resource path.
   * @param {string} [options.expiresParam='expires'] - Query parameter name for the expiry timestamp (unix seconds).
   * @param {string} [options.signatureParam='signature'] - Query parameter name for the signature.
   */
  constructor(secret, options = {}) {
    if (!secret || (typeof secret !== 'string' && !Buffer.isBuffer(secret))) {
      throw new Error('A valid secret (string or Buffer) is required.');
    }
    this.secret = secret;
    this.algorithm = options.algorithm || 'sha256';
    this.pathParam = options.pathParam || 'path';
    this.expiresParam = options.expiresParam || 'expires';
    this.signatureParam = options.signatureParam || 'signature';
  }

  /**
   * Generates a signed query string.
   * @param {string} path - The resource path (e.g., '/downloads/file.zip').
   * @param {number | Date} expiresAt - Expiry timestamp (Unix epoch seconds) or Date object.
   * @returns {string} Query string (e.g., 'path=/foo&expires=12345&signature=abc...').
   */
  sign(path, expiresAt) {
    // Normalize expiresAt to Unix seconds (integer)
    const expires = expiresAt instanceof Date 
      ? Math.floor(expiresAt.getTime() / 1000) 
      : Math.floor(Number(expiresAt));

    if (!Number.isInteger(expires) || expires <= 0) {
      throw new Error('expiresAt must be a valid future Unix timestamp (seconds) or Date object.');
    }

    // Create the canonical string to sign: "path:expires"
    // Using a delimiter that cannot appear in the path (colon is safe for standard paths).
    const dataToSign = `${path}:${expires}`;

    // Generate HMAC
    const hmac = crypto.createHmac(this.algorithm, this.secret);
    hmac.update(dataToSign);
    // Use base64url encoding (RFC 4648 §5) for URL safety: no padding, - instead of +, _ instead of /
    const signature = hmac.digest('base64')
      .replace(/\+/g, '-')
      .replace(/\//g, '_')
      .replace(/=/g, '');

    // Build query string using URLSearchParams for proper encoding
    const params = new URLSearchParams();
    params.set(this.pathParam, path);
    params.set(this.expiresParam, expires.toString());
    params.set(this.signatureParam, signature);

    return params.toString();
  }

  /**
   * Verifies a query string.
   * @param {string} query - The query string to verify (e.g., 'path=/foo&expires=12345&signature=abc').
   * @returns {boolean} True if signature is valid and not expired.
   */
  verify(query) {
    try {
      const params = new URLSearchParams(query);

      const path = params.get(this.pathParam);
      const expiresStr = params.get(this.expiresParam);
      const signature = params.get(this.signatureParam);

      // 1. Check presence of all required params
      if (path === null || expiresStr === null || signature === null) {
        return false;
      }

      // 2. Check Expiry
      const expires = parseInt(expiresStr, 10);
      if (Number.isNaN(expires)) {
        return false;
      }

      const now = Math.floor(Date.now() / 1000);
      if (now > expires) {
        return false; // Expired
      }

      // 3. Verify Signature (Constant-time comparison)
      const dataToSign = `${path}:${expires}`;
      const hmac = crypto.createHmac(this.algorithm, this.secret);
      hmac.update(dataToSign);
      const expectedSignature = hmac.digest('base64')
        .replace(/\+/g, '-')
        .replace(/\//g, '_')
        .replace(/=/g, '');

      // timingSafeEqual requires buffers of equal length
      const sigBuffer = Buffer.from(signature);
      const expectedBuffer = Buffer.from(expectedSignature);

      if (sigBuffer.length !== expectedBuffer.length) {
        return false;
      }

      return crypto.timingSafeEqual(sigBuffer, expectedBuffer);

    } catch (e) {
      // Malformed query string or other parsing errors
      return false;
    }
  }
}

module.exports = UrlSigner;
