### Key Implementation Details

1.  **Canonical Signing String**: Signs `path:expires` (e.g., `/foo/bar:1735689600`). This prevents parameter swapping attacks.
2.  **Base64URL Encoding**: Signature uses `base64url` (RFC 4648) — no `+`, `/`, or `=` padding — making it safe to embed directly in URLs without further encoding.
3.  **Timing Safe Comparison**: Uses `crypto.timingSafeEqual` to prevent timing attacks on the signature verification.
4.  **Unix Seconds**: Uses standard Unix timestamps (seconds) for `expires`, compatible with JWT standards and most CDN/Edge logic.
5.  **No External Dependencies**: Uses only Node.js built-ins (`crypto`, `url`).

Here is a complete, production-ready Node.js module (`url-signer.js`) using the built-in `crypto` module.

It uses **HMAC-SHA256** for signing, **Base64URL** encoding (URL-safe, no padding) for the signature, and **timing-safe comparison** to prevent timing attacks.

### `url-signer.js`

```javascript
const crypto = require('crypto');
const querystring = require('querystring');

/**
 * URL Signer Module
 * 
 * Usage:
 *   const signer = require('./url-signer')('my-secret-key');
 *   const query = signer.sign('/downloads/file.zip', Math.floor(Date.now() / 1000) + 3600);
 *   // query => "path=/downloads/file.zip&expires=1735689600&signature=abc123..."
 *   const valid = signer.verify(query);
 */

module.exports = (secret) => {
  if (!secret || typeof secret !== 'string') {
    throw new Error('A secret string is required to initialize the signer.');
  }

  // Ensure secret is a Buffer for crypto operations
  const secretBuffer = Buffer.from(secret, 'utf8');

  /**
   * Generates a Base64URL encoded HMAC-SHA256 signature.
   * @param {string} data - The string to sign (e.g., "path:expires").
   * @returns {string} Base64URL encoded signature (no padding).
   */
  function _sign(data) {
    const hmac = crypto.createHmac('sha256', secretBuffer);
    hmac.update(data);
    // digest('base64url') requires Node.js v14.18.0+ / v15.12.0+
    // For older versions, use .digest('base64') and manually replace +/= -> -_ 
    return hmac.digest('base64url'); 
  }

  /**
   * Verifies a signature using timing-safe comparison.
   * @param {string} data - The original data string.
   * @param {string} signature - The Base64URL signature to verify.
   * @returns {boolean}
   */
  function _verify(data, signature) {
    const expected = _sign(data);

    // timingSafeEqual requires buffers of equal length.
    // Base64URL length is deterministic for SHA256 (43 chars), but we guard anyway.
    if (expected.length !== signature.length) {
      return false;
    }

    return crypto.timingSafeEqual(
      Buffer.from(expected, 'utf8'),
      Buffer.from(signature, 'utf8')
    );
  }

  return {
    /**
     * Signs a path and expiry timestamp.
     * @param {string} path - The resource path (e.g., '/files/report.pdf').
     * @param {number} expiresAt - Unix timestamp (seconds) when the link expires.
     * @returns {string} A query string: "path=...&expires=...&signature=..."
     */
    sign(path, expiresAt) {
      if (typeof path !== 'string') throw new Error('Path must be a string.');
      if (typeof expiresAt !== 'number' || !Number.isInteger(expiresAt)) {
        throw new Error('expiresAt must be an integer Unix timestamp (seconds).');
      }

      // Canonical string format: "path:expires"
      // Using a delimiter that cannot appear in the path (colon is safe for standard paths).
      const payload = `${path}:${expiresAt}`;
      const signature = _sign(payload);

      const params = {
        path,
        expires: expiresAt.toString(),
        signature
      };

      return querystring.stringify(params);
    },

    /**
     * Verifies a query string.
     * @param {string} queryString - The query string (e.g., "path=...&expires=...&signature=...").
     * @returns {boolean} True if valid signature and not expired.
     */
    verify(queryString) {
      if (typeof queryString !== 'string') return false;

      let parsed;
      try {
        parsed = querystring.parse(queryString);
      } catch (e) {
        return false;
      }

      const { path, expires, signature } = parsed;

      // 1. Validate required params exist and are strings
      if (!path || !expires || !signature) return false;
      if (typeof path !== 'string' || typeof expires !== 'string' || typeof signature !== 'string') return false;

      // 2. Check Expiry
      const expiresAt = parseInt(expires, 10);
      if (isNaN(expiresAt)) return false;

      const now = Math.floor(Date.now() / 1000); // Current time in seconds
      if (now > expiresAt) return false; // Expired

      // 3. Verify Signature
      // Reconstruct the exact payload string used during signing
      const payload = `${path}:${expires}`; // Note: use original 'expires' string to match encoding exactly

      return _verify(payload, signature);
    }
  };
};
