const crypto = require('crypto');

/**
 * Creates a URL signer/verifier instance.
 * @param {string|Buffer} secret - The secret key used for HMAC signing. 
 *                                 Should be high entropy (e.g., 32+ bytes).
 * @param {object} [options]
 * @param {string} [options.algorithm='sha256'] - HMAC algorithm.
 * @param {string} [options.pathParam='path'] - Query param name for the path.
 * @param {string} [options.expiresParam='expires'] - Query param name for expiry timestamp (unix seconds).
 * @param {string} [options.signatureParam='signature'] - Query param name for the signature.
 */
function createUrlSigner(secret, options = {}) {
  if (!secret || (typeof secret === 'string' && secret.length === 0)) {
    throw new Error('Secret is required and cannot be empty');
  }

  const algorithm = options.algorithm || 'sha256';
  const pathParam = options.pathParam || 'path';
  const expiresParam = options.expiresParam || 'expires';
  const signatureParam = options.signatureParam || 'signature';

  const secretBuffer = Buffer.isBuffer(secret) ? secret : Buffer.from(secret, 'utf8');

  /**
   * Generates a signed query string.
   * @param {string} path - The resource path (e.g., '/downloads/file.zip').
   * @param {number|Date} expiresAt - Expiration timestamp (unix seconds) or Date object.
   * @returns {string} Query string (e.g., 'path=...&expires=...&signature=...').
   */
  function sign(path, expiresAt) {
    if (!path) throw new Error('Path is required');

    // Normalize expiresAt to unix seconds (integer)
    const expires = expiresAt instanceof Date 
      ? Math.floor(expiresAt.getTime() / 1000) 
      : Math.floor(Number(expiresAt));

    if (!Number.isInteger(expires) || expires <= 0) {
      throw new Error('expiresAt must be a valid future unix timestamp (seconds)');
    }

    // Canonical string to sign: "path=/foo&expires=12345"
    // We sort params alphabetically to ensure consistent verification.
    const canonicalParts = [
      `${pathParam}=${encodeURIComponent(path)}`,
      `${expiresParam}=${expires}`
    ].sort(); // Sort ensures consistent order regardless of param names

    const stringToSign = canonicalParts.join('&');

    // Generate HMAC
    const hmac = crypto.createHmac(algorithm, secretBuffer);
    hmac.update(stringToSign);
    const signature = hmac.digest('hex');

    // Build final query string (order doesn't matter for parsing, but keep readable)
    const queryParts = [
      ...canonicalParts,
      `${signatureParam}=${signature}`
    ];

    return queryParts.join('&');
  }

  /**
   * Verifies a query string.
   * @param {string} query - The query string (without leading '?').
   * @returns {boolean} True if valid and not expired.
   */
  function verify(query) {
    if (!query || typeof query !== 'string') return false;

    try {
      const params = new URLSearchParams(query);

      const path = params.get(pathParam);
      const expiresStr = params.get(expiresParam);
      const providedSignature = params.get(signatureParam);

      // 1. Check presence of required params
      if (!path || !expiresStr || !providedSignature) {
        return false;
      }

      // 2. Check Expiry
      const expires = parseInt(expiresStr, 10);
      if (isNaN(expires)) return false;

      const now = Math.floor(Date.now() / 1000);
      if (now > expires) {
        return false; // Expired
      }

      // 3. Verify Signature (Timing Safe)
      // Reconstruct canonical string exactly as signed
      const canonicalParts = [
        `${pathParam}=${encodeURIComponent(path)}`,
        `${expiresParam}=${expiresStr}` // Use original string to avoid int formatting diffs
      ].sort();

      const stringToSign = canonicalParts.join('&');

      const hmac = crypto.createHmac(algorithm, secretBuffer);
      hmac.update(stringToSign);
      const expectedSignature = hmac.digest('hex');

      // Use timingSafeEqual to prevent timing attacks
      // Buffers must be same length.
      const providedBuf = Buffer.from(providedSignature, 'hex');
      const expectedBuf = Buffer.from(expectedSignature, 'hex');

      if (providedBuf.length !== expectedBuf.length) {
        return false;
      }

      return crypto.timingSafeEqual(providedBuf, expectedBuf);

    } catch (e) {
      // Malformed query string or parsing error
      return false;
    }
  }

  return { sign, verify };
}

module.exports = { createUrlSigner };
