### Key Features
1.  **Timing-Safe Comparison**: Uses `crypto.timingSafeEqual` to prevent timing attacks on the signature.
2.  **Canonical Signing**: Sorts parameters alphabetically before signing. This ensures the signature is independent of the order parameters appear in the final URL query string.
3.  **Standard Encoding**: Uses `encodeURIComponent` for the path during signing and `URLSearchParams` for parsing, handling special characters correctly.
4.  **Unix Seconds**: Uses standard Unix timestamps (seconds) for `expires`, compatible with CDN edge logic (like CloudFront/Cloudflare signed URLs) and JWT standards.
5.  **No Dependencies**: Pure Node.js `crypto` and `URLSearchParams` (global in Node 10+).

```js
const crypto = require('crypto');

const SECRET = process.env.URL_SIGNING_SECRET || 'change-me';

function sign(path, expiresAt) {
  const params = new URLSearchParams();
  params.set('path', path);
  params.set('exp', String(expiresAt));
  const data = params.toString();
  const sig = crypto.createHmac('sha256', SECRET).update(data).digest('hex');
  params.set('sig', sig);
  return params.toString();
}

function verify(query) {
  const params = new URLSearchParams(query);
  const sig = params.get('sig');
  const exp = params.get('exp');
  const path = params.get('path');
  if (!sig || !exp || !path) return false;

  const now = Math.floor(Date.now() / 1000);
  if (Number(exp) < now) return false;

  params.delete('sig');
  const data = params.toString();
  const expected = crypto.createHmac('sha256', SECRET).update(data).digest('hex');
  return crypto.timingSafeEqual(Buffer.from(sig), Buffer.from(expected));
}

module.exports = { sign, verify };
