/**
 * URL Signer Module
 * 
 * Usage:
 *   const signer = require('./url-signer')('my-secret-key');
 *   const query = signer.sign('/downloads/file.zip', Date.now() + 3600000); // 1 hour
 *   // -> "path=/downloads/file.zip&exp=1700000000000&sig=abc123..."
 *   
 *   const isValid = signer.verify(query);
 */

