    // For older versions, use .digest('base64') and manually replace +/= -> -_ 
    return hmac.digest('base64url'); 
  }

  // Internal: Constant-time comparison for security
  function _verifySignature(expectedSig, actualSig) {
    // timingSafeEqual requires Buffers of equal length
    const expectedBuf = Buffer.from(expectedSig);
    const actualBuf = Buffer.from(actualSig);

    if (expectedBuf.length !== actualBuf.length) {
      return false;
    }

    return crypto.timingSafeEqual(expectedBuf, actualBuf);
  }

  /**
   * Signs a path with an expiration timestamp.
   * @param {string} path - The resource path (e.g., '/files/report.pdf')
   * @param {number} expiresAt - Unix timestamp in milliseconds (Date.now() + TTL)
   * @returns {string} Query string: "path=...&exp=...&sig=..."
   */
  function sign(path, expiresAt) {
    if (typeof path !== 'string') throw new Error('Path must be a string.');
    if (typeof expiresAt !== 'number' || !Number.isInteger(expiresAt)) {
      throw new Error('expiresAt must be an integer timestamp (ms).');
    }

    // Payload format: "path|expiresAt"
    // Using a delimiter that cannot appear in the base64url signature.
    const payload = `${path}|${expiresAt}`;
    const signature = _sign(payload);

    // Build query string manually to avoid dependency on querystring/URLSearchParams
    // Base64URL is safe for query values (no +, /, =), but we encode path just in case.
    return `path=${encodeURIComponent(path)}&exp=${expiresAt}&sig=${signature}`;
  }

  /**
   * Verifies a query string.
   * @param {string} query - The query string (e.g., "path=/foo&exp=123&sig=abc")
   * @returns {boolean} True if valid signature and not expired.
   */
  function verify(query) {
    if (typeof query !== 'string') return false;

    // Parse query string manually (lightweight, no URLSearchParams overhead)
    const params = {};
    query.split('&').forEach(pair => {
      const [key, value] = pair.split('=');
      if (key && value) params[key] = decodeURIComponent(value);
    });

    const { path, exp, sig } = params;

    // 1. Check required params exist
    if (!path || !exp || !sig) return false;

    // 2. Check Expiry
    const expiresAt = parseInt(exp, 10);
    if (isNaN(expiresAt)) return false;
    if (Date.now() > expiresAt) return false; // Expired

    // 3. Verify Signature
    // Reconstruct the exact payload used during signing
    const expectedPayload = `${path}|${expiresAt}`;
    const expectedSig = _sign(expectedPayload);

    return _verifySignature(expectedSig, sig);
  }

  return { sign, verify };
};
