   * @param {number} expiresAt - Unix timestamp (milliseconds) when the link expires
   * @returns {string} Query string: "path=...&expires=...&signature=..."
   */
  function sign(path, expiresAt) {
    if (typeof path !== 'string') throw new Error('Path must be a string.');
    if (typeof expiresAt !== 'number' || !Number.isInteger(expiresAt)) {
      throw new Error('expiresAt must be an integer timestamp (ms).');
    }

    // 1. Prepare payload components (sorted for consistency)
    const params = new URLSearchParams();
    params.set('path', path);
    params.set('expires', expiresAt.toString());

    // 2. Create the "Signing String" (canonical representation)
    // We sort keys to ensure the signature is deterministic regardless of param order.
    const signingString = Array.from(params.entries())
      .sort(([a], [b]) => a.localeCompare(b))
      .map(([k, v]) => `${k}=${v}`)
      .join('&');

    // 3. Generate Signature
    const signature = generateSignature(signingString);

    // 4. Append signature and return final query string
    params.set('signature', signature);
    return params.toString();
  }

  /**
   * Verifies a query string.
   * @param {string} query - The query string (e.g., "path=/foo&expires=123&signature=abc")
   * @returns {boolean} True if signature matches and not expired.
   */
  function verify(query) {
    if (typeof query !== 'string') return false;

    try {
      const params = new URLSearchParams(query);

      // Extract required fields
      const path = params.get('path');
      const expiresStr = params.get('expires');
      const providedSignature = params.get('signature');

      if (!path || !expiresStr || !providedSignature) {
        return false; // Missing required parameters
      }

      const expiresAt = parseInt(expiresStr, 10);
      if (isNaN(expiresAt)) return false;

      // 1. Check Expiry
      if (Date.now() > expiresAt) {
        return false; // Expired
      }

      // 2. Reconstruct Signing String (must match sign() logic exactly)
      // Rebuild params *without* signature for verification
      const verificationParams = new URLSearchParams();
      verificationParams.set('path', path);
      verificationParams.set('expires', expiresStr);

      const signingString = Array.from(verificationParams.entries())
        .sort(([a], [b]) => a.localeCompare(b))
        .map(([k, v]) => `${k}=${v}`)
        .join('&');

      // 3. Generate Expected Signature
      const expectedSignature = generateSignature(signingString);

      // 4. Constant-Time Comparison (Prevents Timing Attacks)
      // crypto.timingSafeEqual requires buffers of equal length.
      const providedBuf = Buffer.from(providedSignature, ENCODING);
      const expectedBuf = Buffer.from(expectedSignature, ENCODING);

      if (providedBuf.length !== expectedBuf.length) {
        return false;
      }

      return crypto.timingSafeEqual(providedBuf, expectedBuf);

    } catch (e) {
      // Malformed query string or parsing error
      return false;
    }
  }

  return { sign, verify };
};
