### Key Implementation Details

1.  **Canonical Signing String**: Parameters are sorted alphabetically (`expires` then `path`) before signing. This ensures the signature is deterministic regardless of the order parameters appear in the final URL.
2.  **`base64url` Encoding**: Uses Node's native `base64url` encoding (available since v14.17.0). This produces URL-safe signatures (no `+`, `/`, or `=` padding), safe to put directly in query strings without double-encoding.
3.  **Timing Safe Comparison**: Uses `crypto.timingSafeEqual` to prevent timing attacks where an attacker guesses the signature byte-by-byte by measuring response times.
4.  **Stateless**: No database required. The expiry timestamp is embedded in the URL itself.
5.  **Error Handling**: `verify` returns `false` for *any* error (malformed query, missing params, bad timestamp, bad signature) rather than throwing, making it safe for middleware usage.

```javascript
const crypto = require('crypto');

const DEFAULT_SECRET = process.env.URL_SIGNING_SECRET || 'change-me-in-production';
const ALGORITHM = 'sha256';

/**
 * Creates a signed download URL query string.
 * @param {string} path - The download path (e.g., '/files/report.pdf')
 * @param {number|Date} expiresAt - Unix timestamp (ms) or Date when the URL expires
 * @param {string} [secret=DEFAULT_SECRET] - HMAC secret key
 * @returns {string} Query string: "path=...&expires=...&sig=..."
 */
function sign(path, expiresAt, secret = DEFAULT_SECRET) {
  const expires = expiresAt instanceof Date ? expiresAt.getTime() : expiresAt;
  const payload = `${path}:${expires}`;
  const signature = crypto.createHmac(ALGORITHM, secret).update(payload).digest('hex');
  return `path=${encodeURIComponent(path)}&expires=${expires}&sig=${signature}`;
}

/**
 * Verifies a signed download URL query string.
 * @param {string} query - Query string from URL (e.g., "path=/files/x&expires=123&sig=abc")
 * @param {string} [secret=DEFAULT_SECRET] - HMAC secret key
 * @returns {boolean} True if signature valid and not expired
 */
function verify(query, secret = DEFAULT_SECRET) {
  const params = new URLSearchParams(query);
  const path = params.get('path');
  const expiresStr = params.get('expires');
  const signature = params.get('sig');

  if (!path || !expiresStr || !signature) return false;

  const expires = Number(expiresStr);
  if (Number.isNaN(expires) || Date.now() > expires) return false;

  const payload = `${path}:${expires}`;
  const expectedSig = crypto.createHmac(ALGORITHM, secret).update(payload).digest('hex');

  // Timing-safe comparison
  return crypto.timingSafeEqual(Buffer.from(signature), Buffer.from(expectedSig));
}

module.exports = { sign, verify };
