const DEFAULT_SECRET = process.env.URL_SIGNING_SECRET || 'change-me-in-production';
const ALGORITHM = 'sha256';

/**
 * Creates a signed download URL query string.
 * @param {string} path - The download path (e.g., '/files/document.pdf')
 * @param {number|Date} expiresAt - Unix timestamp (ms) or Date when the URL expires
 * @param {string} [secret=DEFAULT_SECRET] - HMAC secret key
 * @returns {string} Query string: path=<...>&expires=<...>&signature=<...>
 */
function sign(path, expiresAt, secret = DEFAULT_SECRET) {
  const expiry = expiresAt instanceof Date ? expiresAt.getTime() : expiresAt;
  const payload = `${path}:${expiry}`;
  const signature = crypto
    .createHmac(ALGORITHM, secret)
    .update(payload)
    .digest('hex');

  const params = new URLSearchParams({
    path,
    expires: String(expiry),
    signature
  });
  return params.toString();
}

/**
 * Verifies a signed download URL query string.
 * @param {string} query - Query string from sign() (without leading '?')
 * @param {string} [secret=DEFAULT_SECRET] - HMAC secret key
 * @returns {boolean} True if signature is valid and not expired
 */
function verify(query, secret = DEFAULT_SECRET) {
  const params = new URLSearchParams(query);
  const path = params.get('path');
  const expires = params.get('expires');
  const signature = params.get('signature');

  if (!path || !expires || !signature) return false;

  const now = Date.now();
  const expiry = Number(expires);
  if (Number.isNaN(expiry) || now > expiry) return false;

  const payload = `${path}:${expires}`;
  const expected = crypto
    .createHmac(ALGORITHM, secret)
    .update(payload)
    .digest('hex');

  // Timing-safe comparison
  return crypto.timingSafeEqual(Buffer.from(signature), Buffer.from(expected));
}

