const crypto = require('crypto');

/**
 * URL signing module for secure download links
 * @param {string} secret - Secret key for HMAC signing (should be kept secure)
 */
function createUrlSigner(secret) {
  if (!secret || typeof secret !== 'string') {
    throw new Error('Secret must be a non-empty string');
  }

  const algorithm = 'sha256';
  const encoding = 'base64url';

  /**
   * Generate signature for path and expiry
   * @param {string} path - Resource path
   * @param {number} expiresAt - Unix timestamp (seconds) when URL expires
   * @returns {string} Base64URL-encoded HMAC signature
   */
  function signData(path, expiresAt) {
    const data = `${path}:${expiresAt}`;
    return crypto
      .createHmac(algorithm, secret)
      .update(data)
      .digest(encoding);
  }

  /**
   * Create signed query string
   * @param {string} path - Resource path (e.g., '/downloads/file.zip')
   * @param {number|Date} expiresAt - Expiry as Unix timestamp (seconds) or Date
   * @returns {string} Query string: path=...&expires=...&signature=...
   */
  function sign(path, expiresAt) {
    if (!path || typeof path !== 'string') {
      throw new Error('Path must be a non-empty string');
    }

    const expiry = expiresAt instanceof Date
      ? Math.floor(expiresAt.getTime() / 1000)
      : Math.floor(Number(expiresAt));

    if (!Number.isInteger(expiry) || expiry <= 0) {
      throw new Error('expiresAt must be a positive integer timestamp (seconds)');
    }

    const signature = signData(path, expiry);
    const params = new URLSearchParams({
      path,
      expires: String(expiry),
      signature
    });

    return params.toString();
  }

  /**
   * Verify a signed query string
   * @param {string} query - Query string from URL (e.g., 'path=...&expires=...&signature=...')
   * @returns {boolean} True if valid signature and not expired
   */
  function verify(query) {
    if (!query || typeof query !== 'string') {
      return false;
    }

    try {
      const params = new URLSearchParams(query);
      const path = params.get('path');
      const expiresStr = params.get('expires');
      const signature = params.get('signature');

      if (!path || !expiresStr || !signature) {
        return false;
      }

      const expiresAt = parseInt(expiresStr, 10);
      if (!Number.isInteger(expiresAt) || expiresAt <= 0) {
        return false;
      }

      // Check expiry
      const now = Math.floor(Date.now() / 1000);
      if (now > expiresAt) {
        return false;
      }

      // Verify signature (constant-time comparison)
      const expectedSignature = signData(path, expiresAt);
      return crypto.timingSafeEqual(
        Buffer.from(signature, encoding),
        Buffer.from(expectedSignature, encoding)
      );
    } catch (err) {
      return false;
    }
  }

  return { sign, verify };
}

module.exports = { createUrlSigner };

