/**
 * Signs a download path with expiry timestamp.
 * @param {string} path - The download path (e.g., '/files/document.pdf')
 * @param {number} expiresAt - Unix timestamp (seconds) when the URL expires
 * @returns {string} Query string: "?path=...&expires=...&signature=..."
 */
function sign(path, expiresAt) {
  const payload = `${path}:${expiresAt}`;
  const signature = crypto
    .createHmac('sha256', SECRET)
    .update(payload)
    .digest('hex');

  const encodedPath = encodeURIComponent(path);
  return `?path=${encodedPath}&expires=${expiresAt}&signature=${signature}`;
}

