 * Verifies a signed query string.
 * @param {string} query - Query string from URL (e.g., "?path=...&expires=...&signature=...")
 * @returns {boolean} True if signature valid and not expired
 */
function verify(query) {
  try {
    // Parse query string
    const params = new URLSearchParams(query.startsWith('?') ? query.slice(1) : query);
    const path = decodeURIComponent(params.get('path') || '');
    const expiresAt = parseInt(params.get('expires'), 10);
    const signature = params.get('signature');

    if (!path || !expiresAt || !signature) {
      return false;
    }

    // Check expiry
    const now = Math.floor(Date.now() / 1000);
    if (expiresAt <= now) {
      return false;
    }

    // Verify signature
    const payload = `${path}:${expiresAt}`;
    const expectedSignature = crypto
      .createHmac('sha256', SECRET)
      .update(payload)
      .digest('hex');

    // Timing-safe comparison
    return crypto.timingSafeEqual(
      Buffer.from(signature),
      Buffer.from(expectedSignature)
    );
  } catch (e) {
    return false;
