// urlSigner.js
// Simple HMAC‑based signed URL generator / verifier using Node's built‑in crypto.

const crypto = require('crypto');

// Secret key used for HMAC – in production keep this out of source control.
const SECRET = process.env.URL_SIGNING_SECRET || 'change‑this‑secret';

/**
 * Create a signed query string for a download URL.
 *
 * @param {string} path        - The resource path (e.g. "/files/report.pdf").
 * @param {number} expiresAt   - Unix timestamp (seconds) when the link expires.
 * @returns {string}           - Query string like "?path=...&expires=...&sig=..."
 */
function sign(path, expiresAt) {
  // Normalise inputs
  const normalizedPath = encodeURIComponent(path);
  const exp = Number(expiresAt);
  if (!Number.isInteger(exp)) throw new TypeError('expiresAt must be an integer timestamp');

  // Data to be signed: "path|expires"
  const data = `${normalizedPath}|${exp}`;

  // HMAC‑SHA256 signature, base64url‑encoded (no padding)
  const hmac = crypto.createHmac('sha256', SECRET).update(data).digest('base64')
    .replace(/\+/g, '-').replace(/\//g, '_').replace(/=+$/, '');

  // Build query string
  return `path=${normalizedPath}&expires=${exp}&sig=${hmac}`;
}

/**
 * Verify a previously signed query string.
 *
 * @param {string} query - The query string (without leading "?") to verify.
 * @returns {boolean}    - true if signature matches and not expired.
 */
function verify(query) {
  // Parse query string into an object
  const params = new URLSearchParams(query);
  const path = params.get('path');
  const expiresStr = params.get('expires');
  const sig = params.get('sig');

  if (!path || !expiresStr || !sig) return false;

  const expiresAt = Number(expiresStr);
  if (!Number.isInteger(expiresAt)) return false;

  // Check expiry (current time in seconds)
  const now = Math.floor(Date.now() / 1000);
  if (now > expiresAt) return false;

  // Re‑create expected signature
  const data = `${path}|${expiresAt}`;
  const expectedSig = crypto.createHmac('sha256', SECRET).update(data).digest('base64')
    .replace(/\+/g, '-').replace(/\//g, '_').replace(/=+$/, '');

  // Constant‑time comparison to avoid timing attacks
  return crypto.timingSafeEqual(Buffer.from(sig), Buffer.from(expectedSig));
}

module.exports = { sign, verify };
```

import os
from flask import Flask, request, jsonify, send_from_directory
from werkzeug.utils import secure_filename

app = Flask(__name__)

UPLOAD_FOLDER = './uploads'
ALLOWED_EXTENSIONS = {'png', 'jpg', 'jpeg'}

os.makedirs(UPLOAD_FOLDER, exist_ok=True)

def allowed_file(filename):
    return '.' in filename and filename.rsplit('.', 1)[1].lower() in ALLOWED_EXTENSIONS

@app.route('/avatar', methods=['POST'])
def upload_avatar():
    if 'file' not in request.files:
        return jsonify({'error': 'No file provided'}), 400

    file = request.files['file']
    if file.filename == '':
        return jsonify({'error': 'No file selected'}), 400

    if not allowed_file(file.filename):
        return jsonify({'error': 'Invalid file type. Only PNG and JPEG allowed'}), 400

    filename = secure_filename(file.filename)
    filepath = os.path.join(UPLOAD_FOLDER, filename)
    file.save(filepath)

    # Return URL to fetch the uploaded image
    url = request.host_url.rstrip('/') + f'/uploads/{filename}'
    return jsonify({'url': url}), 201

@app.route('/uploads/<filename>')
def serve_upload(filename):
    return send_from_directory(UPLOAD_FOLDER, filename)

if __name__ == '__main__':
    app.run(debug=True)

