const storage = multer.diskStorage({
  destination: (req, file, cb) => {
    cb(null, UPLOAD_DIR);
  },
  filename: (req, file, cb) => {
    // Generate a unique filename to prevent collisions:
    // Format: timestamp-originalname (sanitized)
    const uniqueSuffix = Date.now() + '-' + Math.round(Math.random() * 1e9);
    // Sanitize original name: remove spaces/special chars, keep extension
    const originalName = file.originalname.replace(/\s+/g, '_').replace(/[^a-zA-Z0-9._-]/g, '');
    const extension = path.extname(originalName);
    const baseName = path.basename(originalName, extension);

    cb(null, `${baseName}-${uniqueSuffix}${extension}`);
  }
});

// 3. File Filter: Accept only PDF, DOC, DOCX
const fileFilter = (req, file, cb) => {
  const allowedMimes = [
    'application/pdf',
    'application/msword', // .doc
    'application/vnd.openxmlformats-officedocument.wordprocessingml.document' // .docx
  ];

  const allowedExts = ['.pdf', '.doc', '.docx'];
  const fileExt = path.extname(file.originalname).toLowerCase();

  if (allowedMimes.includes(file.mimetype) && allowedExts.includes(fileExt)) {
    cb(null, true); // Accept file
  } else {
    // Reject file with a custom error
    cb(new Error('Invalid file type. Only PDF, DOC, and DOCX files are allowed.'), false);
  }
};

// 4. Initialize Multer Upload Middleware
// limits: { fileSize: 10 * 1024 * 1024 } -> Optional: Limit to 10MB
const upload = multer({ 
  storage: storage,
  fileFilter: fileFilter,
  limits: { fileSize: 10 * 1024 * 1024 } // 10 MB limit
});

// --- Routes ---

