// 4. Define Route
// ---------------------------------------------------------
// 'document' is the name of the form field (e.g., <input type="file" name="document" />)
app.post('/upload', upload.single('document'), (req, res) => {
  // If multer validation fails, req.file will be undefined
  if (!req.file) {
    return res.status(400).json({ error: 'No file uploaded or file was rejected.' });
  }

  // Success response
  res.status(200).json({
    message: 'File uploaded successfully',
    storedFileName: req.file.filename, // The unique name on disk
    originalName: req.file.originalname,
    mimeType: req.file.mimetype,
    size: req.file.size
  });
});

// ---------------------------------------------------------
// 5. Global Error Handler (Catches Multer Errors)
// ---------------------------------------------------------
app.use((err, req, res, next) => {
  if (err instanceof multer.MulterError) {
    // A Multer error occurred when uploading (e.g., file too large)
    if (err.code === 'LIMIT_FILE_SIZE') {
      return res.status(413).json({ error: 'File size exceeds 10MB limit.' });
    }
    return res.status(400).json({ error: err.message });
  } else if (err) {
    // An unknown error occurred (e.g., our custom fileFilter error)
    return res.status(400).json({ error: err.message });
  }
  next();
});

app.listen(PORT, () => {
  console.log(`Server running on http://localhost:${PORT}`);
  console.log(`Upload directory: ${uploadDir}`);
});
```

