### Key Implementation Details

| Feature | Implementation |
| :--- | :--- |
| **Directory Creation** | `fs.mkdirSync(uploadDir, { recursive: true })` ensures `./uploads` exists on startup. |
| **Unique Filenames** | `Date.now() + random` prefix prevents collisions if two users upload `resume.pdf` simultaneously. |
| **Sanitization** | `replace(/[^a-zA-Z0-9.-]/g, '_')` removes dangerous characters from the original filename before saving to disk. |
| **MIME Validation** | `fileFilter` checks `file.mimetype` against a strict allowlist (PDF, DOC, DOCX). **Note:** This relies on the browser/OS reporting the correct MIME type. For extreme security, add a library like `file-type` to inspect the buffer magic numbers. |
| **Error Handling** | Custom Express error handler distinguishes between Multer errors (size limits) and custom logic errors (file type). |

```javascript
const express = require('express');
const multer = require('multer');
const path = require('path');
const fs = require('fs');

const router = express.Router();

// Ensure uploads directory exists
const uploadDir = path.join(__dirname, 'uploads');
if (!fs.existsSync(uploadDir)) {
  fs.mkdirSync(uploadDir, { recursive: true });
}

// Configure multer storage
const storage = multer.diskStorage({
  destination: (req, file, cb) => cb(null, uploadDir),
  filename: (req, file, cb) => {
    const uniqueSuffix = Date.now() + '-' + Math.round(Math.random() * 1e9);
    const ext = path.extname(file.originalname);
    cb(null, `${file.fieldname}-${uniqueSuffix}${ext}`);
  }
});

// File filter for PDFs and Word documents
const fileFilter = (req, file, cb) => {
  const allowedTypes = [
    'application/pdf',
    'application/msword',
    'application/vnd.openxmlformats-officedocument.wordprocessingml.document'
  ];
  if (allowedTypes.includes(file.mimetype)) {
    cb(null, true);
  } else {
    cb(new Error('Only PDF and Word documents are allowed'), false);
  }
};

const upload = multer({
  storage,
  fileFilter,
  limits: { fileSize: 10 * 1024 * 1024 } // 10MB limit
});

// POST /upload - Accept single document upload
router.post('/upload', upload.single('document'), (req, res) => {
  if (!req.file) {
    return res.status(400).json({ error: 'No file uploaded' });
  }
  res.json({ filename: req.file.filename });
});

// Error handling middleware for multer errors
router.use((err, req, res, next) => {
  if (err instanceof multer.MulterError) {
    return res.status(400).json({ error: err.message });
  }
  if (err) {
    return res.status(400).json({ error: err.message });
  }
  next();
});

module.exports = router;
```

