from flask import Flask, request, jsonify, send_from_directory
import os
from werkzeug.utils import secure_filename
from pathlib import Path

app = Flask(__name__)

UPLOAD_DIR = Path("./uploads")
UPLOAD_DIR.mkdir(exist_ok=True)

ALLOWED_EXTENSIONS = {"png", "jpg", "jpeg"}
MAX_FILE_SIZE = 5 * 1024 * 1024  # 5MB


def allowed_file(filename: str) -> bool:
    return "." in filename and filename.rsplit(".", 1)[1].lower() in ALLOWED_EXTENSIONS


@app.route("/avatar", methods=["POST"])
def upload_avatar():
    if "file" not in request.files:
        return jsonify({"error": "No file provided"}), 400

    file = request.files["file"]
    if file.filename == "":
        return jsonify({"error": "No file selected"}), 400

    if not allowed_file(file.filename):
        return jsonify({"error": "Invalid file type. Only PNG and JPEG allowed"}), 400

    # Check file size
    file.seek(0, os.SEEK_END)
    size = file.tell()
    file.seek(0)
    if size > MAX_FILE_SIZE:
        return jsonify({"error": "File too large. Max 5MB"}), 400

    # Secure filename with original extension
    ext = file.filename.rsplit(".", 1)[1].lower()
    filename = f"avatar_{secure_filename(file.filename.rsplit('.', 1)[0])}.{ext}"
    filepath = UPLOAD_DIR / filename

    # Avoid overwriting
    counter = 1
    while filepath.exists():
        filename = f"avatar_{secure_filename(file.filename.rsplit('.', 1)[0])}_{counter}.{ext}"
        filepath = UPLOAD_DIR / filename
        counter += 1

    file.save(filepath)

    return jsonify({
        "url": f"/uploads/{filename}",
        "filename": filename
    }), 201


@app.route("/uploads/<filename>")
def serve_upload(filename):
    return send_from_directory(UPLOAD_DIR, filename)


if __name__ == "__main__":
    app.run(debug=True)
