```php
<?php
// upload.php
// Configuration
$uploadDir = __DIR__ . '/uploads/';
$maxFileSize = 5 * 1024 * 1024; // 5 MB
$allowedMimeTypes = ['image/jpeg', 'image/png', 'image/gif', 'image/webp'];
$allowedExtensions = ['jpg', 'jpeg', 'png', 'gif', 'webp'];

// Ensure upload directory exists
if (!is_dir($uploadDir)) {
    if (!mkdir($uploadDir, 0755, true)) {
        http_response_code(500);
        exit('Failed to create upload directory.');
    }
}

// Only accept POST requests
if ($_SERVER['REQUEST_METHOD'] !== 'POST') {
    http_response_code(405);
    exit('Method not allowed. Use POST.');
}

// Check if file was uploaded without errors
if (!isset($_FILES['avatar']) || $_FILES['avatar']['error'] !== UPLOAD_ERR_OK) {
    $errorMessages = [
        UPLOAD_ERR_INI_SIZE   => 'File exceeds upload_max_filesize.',
        UPLOAD_ERR_FORM_SIZE  => 'File exceeds MAX_FILE_SIZE.',
        UPLOAD_ERR_PARTIAL    => 'File was only partially uploaded.',
        UPLOAD_ERR_NO_FILE    => 'No file was uploaded.',
        UPLOAD_ERR_NO_TMP_DIR => 'Missing temporary folder.',
        UPLOAD_ERR_CANT_WRITE => 'Failed to write file to disk.',
        UPLOAD_ERR_EXTENSION  => 'A PHP extension stopped the upload.',
    ];
    $code = $_FILES['avatar']['error'] ?? UPLOAD_ERR_NO_FILE;
    http_response_code(400);
    exit($errorMessages[$code] ?? 'Unknown upload error.');
}

$file = $_FILES['avatar'];

// Validate file size
if ($file['size'] > $maxFileSize) {
    http_response_code(400);
    exit('File too large. Maximum size is ' . ($maxFileSize / 1024 / 1024) . ' MB.');
}

// Validate MIME type (use finfo for reliable detection)
$finfo = new finfo(FILEINFO_MIME_TYPE);
$mimeType = $finfo->file($file['tmp_name']);
if (!in_array($mimeType, $allowedMimeTypes, true)) {
    http_response_code(400);
    exit('Invalid file type. Allowed: JPEG, PNG, GIF, WebP.');
}

// Validate extension matches MIME type
$extension = strtolower(pathinfo($file['name'], PATHINFO_EXTENSION));
$expectedExtensions = [
    'image/jpeg' => ['jpg', 'jpeg'],
    'image/png'  => ['png'],
    'image/gif'  => ['gif'],
    'image/webp' => ['webp'],
];
if (!in_array($extension, $expectedExtensions[$mimeType] ?? [], true)) {
    http_response_code(400);
    exit('File extension does not match content type.');
}

// Generate a safe, unique filename
$basename = bin2hex(random_bytes(12)) . '.' . $extension;
$destination = $uploadDir . $basename;

// Move the uploaded file
if (!move_uploaded_file($file['tmp_name'], $destination)) {
    http_response_code(500);
    exit('Failed to move uploaded file.');
}

// Set restrictive permissions (readable by web server, not executable)
chmod($destination, 0644);

// Build the public URL
$scriptUrl = (isset($_SERVER['HTTPS']) && $_SERVER['HTTPS'] !== 'off' ? 'https' : 'http')
           . '://' . $_SERVER['HTTP_HOST']
           . rtrim(dirname($_SERVER['SCRIPT_NAME']), '/\\');
$publicUrl = $scriptUrl . '/uploads/' . $basename;

// Output the URL (plain text; adjust if you need JSON)
header('Content-Type: text/plain; charset=utf-8');
echo $publicUrl;
```

