from flask import Flask, request, jsonify, abort

app = Flask(__name__)

stripe.api_key = os.getenv("STRIPE_SECRET_KEY")
WEBHOOK_SECRET = os.getenv("STRIPE_WEBHOOK_SECRET")

# Example Order model (replace with your actual ORM model)
class Order:
    def __init__(self, id, paid=False):
        self.id = id
        self.paid = paid

# In-memory store for demo; replace with your DB session
orders_db = {
    "order_123": Order("order_123"),
    "order_456": Order("order_456"),
}

def get_order(order_id):
    return orders_db.get(order_id)

def save_order(order):
    orders_db[order.id] = order

@app.route("/webhooks/stripe", methods=["POST"])
def stripe_webhook():
    payload = request.get_data(as_text=True)
    sig_header = request.headers.get("Stripe-Signature")

    try:
        event = stripe.Webhook.construct_event(payload, sig_header, WEBHOOK_SECRET)
    except ValueError:
        # Invalid payload
        abort(400)
    except stripe.error.SignatureVerificationError:
        # Invalid signature
        abort(400)

    if event["type"] == "checkout.session.completed":
        session = event["data"]["object"]
        order_id = session.get("metadata", {}).get("order_id")

        if not order_id:
            app.logger.warning("checkout.session.completed missing order_id in metadata")
            return "", 200

        order = get_order(order_id)
        if not order:
            app.logger.warning(f"Order {order_id} not found")
            return "", 200

        if not order.paid:
            order.paid = True
            save_order(order)
            app.logger.info(f"Order {order_id} marked as paid")
        else:
            app.logger.info(f"Order {order_id} already paid")

    return "", 200

if __name__ == "__main__":
    app.run(port=5000)
```

**Key points:**

- **Signature verification** uses `stripe.Webhook.construct_event` with your webhook secret (set in Stripe Dashboard → Webhooks → Signing secret).
- **Metadata extraction**: `session["metadata"]["order_id"]` — ensure your Checkout Session creation includes `metadata={"order_id": "order_123"}`.
- **Idempotency**: Checks `order.paid` before updating to handle duplicate webhook deliveries.
- **Always returns 200** for acknowledged events; Stripe will retry non-2xx responses.
- Replace `orders_db` / `Order` with your actual database layer (SQLAlchemy, Django ORM, etc.).

