const express = require('express');
const multer = require('multer');
const path = require('path');
const fs = require('fs');

const app = express();
const PORT = 3000;

// ---------------------------------------------------------
// 1. Ensure Upload Directory Exists
// ---------------------------------------------------------
const UPLOAD_DIR = path.join(__dirname, 'uploads');
if (!fs.existsSync(UPLOAD_DIR)) {
    fs.mkdirSync(UPLOAD_DIR, { recursive: true });
}

// ---------------------------------------------------------
// 2. Configure Multer Storage & File Filtering
// ---------------------------------------------------------

// Allowed MIME Types: PDF, .doc, .docx
const ALLOWED_MIME_TYPES = [
    'application/pdf',
    'application/msword', // .doc
    'application/vnd.openxmlformats-officedocument.wordprocessingml.document' // .docx
];

const storage = multer.diskStorage({
    destination: (req, file, cb) => {
        cb(null, UPLOAD_DIR);
    },
    filename: (req, file, cb) => {
        // Generate a unique filename to prevent collisions: timestamp-originalname
        const uniqueSuffix = Date.now() + '-' + Math.round(Math.random() * 1E9);
        // Sanitize original name to remove potentially dangerous characters
        const sanitizedName = file.originalname.replace(/[^a-zA-Z0-9.\-_]/g, '_');
        cb(null, `${uniqueSuffix}-${sanitizedName}`);
    }
});

const fileFilter = (req, file, cb) => {
    if (ALLOWED_MIME_TYPES.includes(file.mimetype)) {
        cb(null, true); // Accept file
    } else {
        // Reject file with a custom error
        cb(new Error('Invalid file type. Only PDF, DOC, and DOCX are allowed.'), false);
    }
};

const upload = multer({ 
    storage: storage,
    fileFilter: fileFilter,
    limits: { fileSize: 10 * 1024 * 1024 } // Optional: 10MB limit
});

// ---------------------------------------------------------
// 3. Define Routes
// ---------------------------------------------------------

// Health check
app.get('/', (req, res) => res.send('Server running. POST to /upload'));

// Upload Route
// 'document' is the expected field name in the form-data (e.g., formData.append('document', file))
app.post('/upload', upload.single('document'), (req, res) => {
    // If multer validation fails, req.file will be undefined
    if (!req.file) {
        // This block is technically reached only if fileFilter calls cb(null, false) 
        // without an error, but good practice to check.
        return res.status(400).json({ error: 'No file uploaded or file rejected.' });
    }

    // Success: Return the stored filename
    res.json({
        message: 'File uploaded successfully',
        storedFileName: req.file.filename,
        originalName: req.file.originalname,
        mimeType: req.file.mimetype,
        size: req.file.size
    });
});

// ---------------------------------------------------------
// 4. Global Error Handler (Catches Multer Errors)
// ---------------------------------------------------------
app.use((err, req, res, next) => {
    if (err instanceof multer.MulterError) {
        // Multer specific errors (e.g., file too large, unexpected field)
        return res.status(400).json({ error: `Multer Error: ${err.message}` });
    } else if (err) {
        // Custom errors (e.g., fileFilter rejection)
        return res.status(400).json({ error: err.message });
    }
    next();
});

app.listen(PORT, () => {
    console.log(`Server listening on http://localhost:${PORT}`);
    console.log(`Upload directory: ${UPLOAD_DIR}`);
});
```

