import subprocess
import hmac
import hashlib
from fastapi import FastAPI, Request, Header, HTTPException
from pydantic import BaseModel
from typing import Optional

app = FastAPI()

# GitHub webhook secret (set via env var in production)
WEBHOOK_SECRET = "your-webhook-secret"


class PushEvent(BaseModel):
    ref: str  # e.g., "refs/heads/main"
    repository: dict
    head_commit: Optional[dict] = None


def verify_signature(payload: bytes, signature: str) -> bool:
    """Verify GitHub webhook signature."""
    if not WEBHOOK_SECRET:
        return True  # Skip verification if no secret configured
    expected = "sha256=" + hmac.new(
        WEBHOOK_SECRET.encode(), payload, hashlib.sha256
    ).hexdigest()
    return hmac.compare_digest(expected, signature)


@app.post("/github/webhook")
async def github_webhook(
    request: Request,
    x_hub_signature_256: Optional[str] = Header(None),
    x_github_event: Optional[str] = Header(None),
):
    # Only handle push events
    if x_github_event != "push":
        return {"status": "ignored", "reason": "not a push event"}

    payload = await request.body()

    # Verify webhook signature
    if not verify_signature(payload, x_hub_signature_256 or ""):
        raise HTTPException(status_code=401, detail="Invalid signature")

    # Parse push event
    try:
        event = PushEvent.model_validate_json(payload)
    except Exception as e:
        raise HTTPException(status_code=400, detail=f"Invalid payload: {e}")

    # Extract branch name from ref (refs/heads/main -> main)
    branch = event.ref.split("/")[-1] if event.ref.startswith("refs/heads/") else event.ref

    # Only deploy on main branch
    if branch != "main":
        return {"status": "ignored", "reason": f"branch '{branch}' is not main"}

    # Trigger deployment
    try:
        result = subprocess.run(
            ["./deploy.sh", branch],
            capture_output=True,
            text=True,
            timeout=300,  # 5 min timeout
        )
        if result.returncode != 0:
            raise HTTPException(
                status_code=500,
                detail=f"Deploy failed: {result.stderr}"
            )
        return {"status": "deployed", "branch": branch, "output": result.stdout}
    except subprocess.TimeoutExpired:
        raise HTTPException(status_code=500, detail="Deploy timed out")
    except FileNotFoundError:
        raise HTTPException(status_code=500, detail="deploy.sh not found")
