    branch = event.ref.replace("refs/heads/", "")

    if branch != "main":
        return {"status": "ignored", "reason": f"branch '{branch}' is not main"}

    background_tasks.add_task(run_deploy, branch)
    return {"status": "deploy triggered", "branch": branch}
