    if not WEBHOOK_SECRET:
        return True  # Skip verification if no secret configured
    expected = "sha256=" + hmac.new(
        WEBHOOK_SECRET.encode(), payload, hashlib.sha256
    ).hexdigest()
    return hmac.compare_digest(expected, signature)

@app.post("/github/webhook")
async def github_webhook(
    request: Request,
    x_hub_signature_256: str = Header(None),
    x_github_event: str = Header(None)
):
    # Verify GitHub event type
    if x_github_event != "push":
        return JSONResponse({"status": "ignored", "reason": "not a push event"})

    payload = await request.body()

    # Verify webhook signature
    if not verify_signature(payload, x_hub_signature_256 or ""):
        raise HTTPException(status_code=401, detail="Invalid signature")

    try:
        data = json.loads(payload)
    except json.JSONDecodeError:
        raise HTTPException(status_code=400, detail="Invalid JSON")

    # Extract branch name from ref (e.g., "refs/heads/main" -> "main")
    ref = data.get("ref", "")
    if not ref.startswith("refs/heads/"):
        return JSONResponse({"status": "ignored", "reason": "not a branch push"})

    branch = ref.split("refs/heads/")[-1]

    # Only deploy for main branch
    if branch != "main":
        return JSONResponse({"status": "ignored", "reason": f"branch '{branch}' not main"})

    # Trigger deployment script
    try:
        result = subprocess.run(
            ["./deploy.sh", branch],
            capture_output=True,
            text=True,
            timeout=300,
            cwd=os.getcwd()
        )
        if result.returncode != 0:
            return JSONResponse(
                {"status": "error", "output": result.stdout, "error": result.stderr},
                status_code=500
            )
        return JSONResponse({"status": "deployed", "branch": branch, "output": result.stdout})
    except subprocess.TimeoutExpired:
        return JSONResponse({"status": "error", "reason": "deployment timeout"}, status_code=500)
    except FileNotFoundError:
        return JSONResponse({"status": "error", "reason": "deploy.sh not found"}, status_code=500)
    except Exception as e:
        return JSONResponse({"status": "error", "reason": str(e)}, status_code=500)
