from fastapi import FastAPI, Request, HTTPException, Header
from fastapi.responses import JSONResponse
import subprocess
import hmac
import hashlib
import os
import json

app = FastAPI()

# GitHub webhook secret (set via environment variable for security)
WEBHOOK_SECRET = os.getenv("GITHUB_WEBHOOK_SECRET", "")


def verify_signature(payload: bytes, signature: str) -> bool:
    """Verify GitHub webhook signature using HMAC-SHA256."""
    if not WEBHOOK_SECRET:
        return True  # Skip verification if secret not configured
    expected = "sha256=" + hmac.new(
        WEBHOOK_SECRET.encode(), payload, hashlib.sha256
    ).hexdigest()
    return hmac.compare_digest(expected, signature)


@app.post("/github/webhook")
async def github_webhook(
    request: Request,
    x_github_event: str = Header(None),
    x_hub_signature_256: str = Header(None),
):
    # Only handle push events
    if x_github_event != "push":
        return JSONResponse({"message": "Event ignored"}, status_code=200)

    # Read and verify payload
    payload = await request.body()
    if not verify_signature(payload, x_hub_signature_256 or ""):
        raise HTTPException(status_code=401, detail="Invalid signature")

    try:
        data = json.loads(payload)
    except json.JSONDecodeError:
        raise HTTPException(status_code=400, detail="Invalid JSON")

    # Extract branch name from ref (e.g., "refs/heads/main" -> "main")
    ref = data.get("ref", "")
    branch = ref.split("/")[-1] if ref.startswith("refs/heads/") else ""

    # Only deploy on pushes to main branch
    if branch != "main":
        return JSONResponse({"message": f"Branch '{branch}' ignored"}, status_code=200)

    # Trigger deployment script with branch name
    try:
        result = subprocess.run(
            ["./deploy.sh", branch],
            capture_output=True,
            text=True,
            timeout=300,  # 5-minute timeout
            cwd=os.getcwd(),
        )
        if result.returncode != 0:
            return JSONResponse(
                {"error": "Deployment failed", "output": result.stderr},
                status_code=500,
            )
        return JSONResponse(
            {"message": "Deployment triggered", "output": result.stdout}, status_code=200
        )
    except subprocess.TimeoutExpired:
        raise HTTPException(status_code=500, detail="Deployment timed out")
    except FileNotFoundError:
        raise HTTPException(status_code=500, detail="deploy.sh not found")
    except Exception as e:
        raise HTTPException(status_code=500, detail=str(e))
