// server.js (or wherever you define your routes)
const express = require('express');
const multer = require('multer');
const path = require('path');
const fs = require('fs');

const app = express();

// ---------- Multer configuration ----------
const uploadDir = path.join(__dirname, 'uploads');

// Ensure the upload directory exists
if (!fs.existsSync(uploadDir)) {
  fs.mkdirSync(uploadDir, { recursive: true });
}

// Allow only PDF and Word documents
const allowedMimeTypes = [
  'application/pdf',
  'application/msword',                                 // .doc
  'application/vnd.openxmlformats-officedocument.wordprocessingml.document' // .docx
];

const storage = multer.diskStorage({
  destination: (req, file, cb) => cb(null, uploadDir),
  filename: (req, file, cb) => {
    // Sanitize the original name: keep only alphanumerics, dots, dashes, underscores
    const safeName = file.originalname.replace(/[^a-zA-Z0-9._-]/g, '_');
    // Append a timestamp to avoid collisions
    const uniqueName = `${Date.now()}-${safeName}`;
    cb(null, uniqueName);
  }
});

const fileFilter = (req, file, cb) => {
  if (allowedMimeTypes.includes(file.mimetype)) {
    cb(null, true);
  } else {
    cb(new Error('Only PDF and Word documents are allowed'), false);
  }
};

const upload = multer({
  storage,
  fileFilter,
  limits: { fileSize: 10 * 1024 * 1024 } // 10 MB max (adjust as needed)
});

// ---------- Route ----------
/**
 * POST /upload
 * Accepts a single file field named "document".
 * Returns JSON { "filename": "<stored‑filename>" } on success.
 */
app.post('/upload', upload.single('document'), (req, res) => {
  if (!req.file) {
    return res.status(400).json({ error: 'No file uploaded' });
  }
  // Respond with the stored filename
  res.json({ filename: req.file.filename });
});

// ---------- Error handling for multer ----------
app.use((err, req, res, next) => {
  if (err instanceof multer.MulterError) {
    // Multer‑specific errors (e.g., file too large)
    return res.status(400).json({ error: err.message });
  } else if (err) {
    // Our custom file‑type error or any other error
    return res.status(400).json({ error: err.message });
  }
  next();
});

// Start the server (example)
const PORT = process.env.PORT || 3000;
app.listen(PORT, () => console.log(`Server listening on port ${PORT}`));
