// app.js (or wherever you set up your Express routes)
const express = require('express');
const multer  = require('multer');
const path    = require('path');
const fs      = require('fs');

const app = express();

// ------------------------------------------------------------------
// Multer configuration
// ------------------------------------------------------------------
// 1. Destination folder – create it if it doesn't exist
const uploadDir = path.join(__dirname, 'uploads');
if (!fs.existsSync(uploadDir)) {
  fs.mkdirSync(uploadDir, { recursive: true });
}

// 2. Allowed MIME types (PDF, DOC, DOCX)
const allowedMimeTypes = [
  'application/pdf',
  'application/msword',                         // .doc
  'application/vnd.openxmlformats-officedocument.wordprocessingml.document' // .docx
];

// 3. Storage engine – keep original extension, avoid name clashes
const storage = multer.diskStorage({
  destination: (req, file, cb) => cb(null, uploadDir),
  filename: (req, file, cb) => {
    const ext = path.extname(file.originalname).toLowerCase();
    const uniqueName = `${Date.now()}-${Math.round(Math.random() * 1e9)}${ext}`;
    cb(null, uniqueName);
  }
});

// 4. File filter – reject anything not in the whitelist
const fileFilter = (req, file, cb) => {
  if (allowedMimeTypes.includes(file.mimetype)) {
    cb(null, true);
  } else {
    cb(new Error('Only PDF and Word documents are allowed'), false);
  }
};

// 5. Limits – e.g., 10 MB max per file
const limits = { fileSize: 10 * 1024 * 1024 };

const upload = multer({ storage, fileFilter, limits });

// ------------------------------------------------------------------
// Route: POST /upload
// ------------------------------------------------------------------
// Accepts a single file under the field name "document"
app.post('/upload', upload.single('document'), (req, res) => {
  // multer puts file info on req.file
  if (!req.file) {
    return res.status(400).json({ error: 'No file uploaded' });
  }

  // Respond with the stored filename (relative to ./uploads)
  res.json({ filename: req.file.filename });
});

// ------------------------------------------------------------------
// Error‑handling middleware for multer errors
// ------------------------------------------------------------------
app.use((err, req, res, next) => {
  if (err instanceof multer.MulterError) {
    // Multer‑specific errors (e.g., file too large)
    return res.status(400).json({ error: err.message });
  } else if (err) {
    // Our custom file‑filter error or any other error
    return res.status(400).json({ error: err.message });
  }
  next();
});

// Start server (example)
const PORT = process.env.PORT || 3000;
app.listen(PORT, () => console.log(`Server listening on port ${PORT}`));
