```php
<?php
/**
 * IPN Handler for Payment Gateway
 * 
 * Expects POST: order_id, amount, status, sig
 * Verifies signature using GATEWAY_SECRET env var.
 * On status=completed & valid sig -> UPDATE orders SET paid=1 WHERE id=order_id
 */

// 1. Load Configuration & Secrets
$secret = getenv('GATEWAY_SECRET');
if ($secret === false || $secret === '') {
    error_log('IPN Error: GATEWAY_SECRET environment variable not set.');
    http_response_code(500);
    exit('Server configuration error');
}

// Database Configuration (Ideally from env vars in production)
$dbHost = getenv('DB_HOST') ?: '127.0.0.1';
$dbName = getenv('DB_NAME') ?: 'payments';
$dbUser = getenv('DB_USER') ?: 'root';
$dbPass = getenv('DB_PASS') ?: '';
$dbCharset = 'utf8mb4';

$dsn = "mysql:host={$dbHost};dbname={$dbName};charset={$dbCharset}";
$pdoOptions = [
    PDO::ATTR_ERRMODE            => PDO::ERRMODE_EXCEPTION,
    PDO::ATTR_DEFAULT_FETCH_MODE => PDO::FETCH_ASSOC,
    PDO::ATTR_EMULATE_PREPARES   => false,
];

// 2. Validate Request Method
if ($_SERVER['REQUEST_METHOD'] !== 'POST') {
    http_response_code(405);
    exit('Method Not Allowed');
}

// 3. Retrieve & Validate Input
$orderId = filter_input(INPUT_POST, 'order_id', FILTER_VALIDATE_INT);
$amount  = filter_input(INPUT_POST, 'amount', FILTER_VALIDATE_FLOAT);
$status  = filter_input(INPUT_POST, 'status', FILTER_SANITIZE_STRING);
$sig     = filter_input(INPUT_POST, 'sig', FILTER_SANITIZE_STRING);

if ($orderId === false || $orderId === null || $amount === false || $status === null || $sig === null) {
    error_log('IPN Error: Missing or invalid parameters.');
    http_response_code(400);
    exit('Invalid parameters');
}

// 4. Verify Signature
// Assumption: Gateway signs "order_id:amount:status" with HMAC-SHA256 using secret.
// Adjust the $data string format to match your specific gateway's documentation.
$dataToSign = "{$orderId}:{$amount}:{$status}";
$expectedSig = hash_hmac('sha256', $dataToSign, $secret);

// Use hash_equals for timing-attack safe comparison
if (!hash_equals($expectedSig, $sig)) {
    error_log("IPN Error: Invalid signature for Order ID {$orderId}.");
    http_response_code(400);
    exit('Invalid signature');
}

// 5. Process Logic
// Only act on 'completed' status. Ignore others (pending, failed, refunded) silently but return 200 OK.
if (strtolower($status) !== 'completed') {
    error_log("IPN Info: Order {$orderId} status is '{$status}', no action taken.");
    http_response_code(200);
    exit('OK');
}

try {
    $pdo = new PDO($dsn, $dbUser, $dbPass, $pdoOptions);

    // Use transaction to ensure atomicity if multiple updates were needed
    $pdo->beginTransaction();

    // Check current state to prevent idempotency issues (double processing)
    $stmtCheck = $pdo->prepare('SELECT paid FROM orders WHERE id = ? FOR UPDATE');
    $stmtCheck->execute([$orderId]);
    $order = $stmtCheck->fetch();

    if (!$order) {
        error_log("IPN Error: Order {$orderId} not found in database.");
        $pdo->rollBack();
        // Return 404 or 200 depending on gateway retry policy. 
        // 404 might stop retries; 200 acknowledges receipt but logs error.
        http_response_code(404);
        exit('Order not found');
    }

    if ((int)$order['paid'] === 1) {
        error_log("IPN Info: Order {$orderId} already marked as paid. Idempotent request ignored.");
        $pdo->commit(); // Commit the read lock
        http_response_code(200);
        exit('Already processed');
    }

    // Update Order
    $stmtUpdate = $pdo->prepare('UPDATE orders SET paid = 1, paid_at = NOW() WHERE id = ?');
    $stmtUpdate->execute([$orderId]);

    if ($stmtUpdate->rowCount() === 0) {
        // Should not happen due to SELECT FOR UPDATE, but safety check
        throw new Exception("Update failed for Order {$orderId} (0 rows affected).");
    }

    $pdo->commit();
    error_log("IPN Success: Order {$orderId} marked as paid.");
    http_response_code(200);
    exit('OK');

} catch (PDOException $e) {
    if ($pdo->inTransaction()) {
        $pdo->rollBack();
    }
    error_log('IPN Database Error: ' . $e->getMessage());
    http_response_code(500);
    exit('Database error');
} catch (Exception $e) {
    if (isset($pdo) && $pdo->inTransaction()) {
        $pdo->rollBack();
    }
    error_log('IPN General Error: ' . $e->getMessage());
    http_response_code(500);
    exit('Internal error');
}
```

### Key Implementation Details

1.  **Signature Verification (`hash_equals`)**:
    *   Prevents timing attacks.
    *   Assumes the gateway signs the string `order_id:amount:status` using **HMAC-SHA256**. **You must verify the exact string format and algorithm in your gateway's documentation** (e.g., some gateways sort params alphabetically, use `|` as delimiter, or include a nonce).

2.  **Idempotency Handling**:
    *   Uses `SELECT ... FOR UPDATE` inside a transaction to lock the row.
    *   Checks `if ($order['paid'] === 1)` before updating. This safely handles duplicate notifications (retries) from the gateway without double-processing.

3.  **Environment Variables**:
    *   `GATEWAY_SECRET`: **Critical**. Never hardcode this.
    *   DB Credentials: Also pulled from `getenv()` with fallbacks for local dev only.

4.  **Response Codes**:
    *   **200 OK**: Returned for valid signatures (even if status != completed or already paid). This tells the gateway "Stop retrying, I got it."
    *   **400 Bad Request**: Invalid signature or malformed data.
    *   **500 Internal Server Error**: DB connection failure or server misconfiguration (triggers gateway retry).

5.  **Security**:
    *   **PDO Prepared Statements**: Prevents SQL Injection.
    *   **Input Validation**: `filter_input` ensures `order_id` is integer, `amount` is float.
    *   **Error Logging**: Logs details to PHP error log (syslog/docker stdout) but returns generic messages to the gateway.

### Deployment Checklist
1.  Set `GATEWAY_SECRET` in your web server / PHP-FPM / Docker environment.
2.  Ensure the DB user has `UPDATE` permissions on `orders` table.
3.  Verify the `$dataToSign` construction matches the gateway spec **exactly** (whitespace, delimiter, parameter order, encoding).
4.  Configure your Gateway Dashboard to point the IPN/Callback URL to `https://yourdomain.com/ipn.php`.
5.  Test with the gateway's sandbox/test mode *before* going live.

