import os
import stripe
from flask import Flask, request, jsonify, abort

app = Flask(__name__)

stripe.api_key = os.getenv("STRIPE_SECRET_KEY")
WEBHOOK_SECRET = os.getenv("STRIPE_WEBHOOK_SECRET")

# Example Order model (replace with your actual ORM/model)
class Order:
    @staticmethod
    def mark_paid(order_id: str) -> bool:
        # Implement your DB update logic here
        # e.g., Order.query.filter_by(id=order_id).update({"status": "paid"})
        print(f"Marking order {order_id} as paid")
        return True

@app.route("/webhooks/stripe", methods=["POST"])
def stripe_webhook():
    payload = request.get_data(as_text=True)
    sig_header = request.headers.get("Stripe-Signature")

    if not sig_header:
        abort(400, "Missing Stripe-Signature header")

    try:
        event = stripe.Webhook.construct_event(
            payload, sig_header, WEBHOOK_SECRET
        )
    except ValueError:
        abort(400, "Invalid payload")
    except stripe.error.SignatureVerificationError:
        abort(400, "Invalid signature")

    if event["type"] == "checkout.session.completed":
        session = event["data"]["object"]
        order_id = session.get("metadata", {}).get("order_id")

        if not order_id:
            app.logger.warning("checkout.session.completed missing order_id in metadata")
            return "", 200

        try:
            Order.mark_paid(order_id)
        except Exception as e:
            app.logger.exception(f"Failed to mark order {order_id} as paid: {e}")
            abort(500, "Database error")

    return "", 200

if __name__ == "__main__":
    app.run(port=5000)
```

**Key points:**

- **Signature verification** using `stripe.Webhook.construct_event` with your webhook secret (set in Stripe Dashboard → Webhooks → Signing secret).
- **Metadata extraction**: `session["metadata"]["order_id"]` — ensure you pass `metadata: {order_id: "..."}` when creating the Checkout Session.
- **Idempotency**: Stripe may retry; `mark_paid` should be idempotent (e.g., `UPDATE orders SET status='paid' WHERE id=? AND status!='paid'`).
- **Always return 200** for acknowledged events; otherwise Stripe will retry.
- **Configure the webhook URL** in Stripe Dashboard: `https://yourdomain.com/webhooks/stripe` with `checkout.session.completed` selected.

