$orderId = isset($_POST['order_id']) ? trim($_POST['order_id']) : '';
$amount  = isset($_POST['amount'])   ? trim($_POST['amount'])   : '';
$status  = isset($_POST['status'])   ? trim($_POST['status'])   : '';
$sig     = isset($_POST['sig'])      ? trim($_POST['sig'])      : '';

if ($orderId === '' || $amount === '' || $status === '' || $sig === '') {
    http_response_code(400);
    error_log('IPN: Missing required parameters');
    exit('Bad Request: Missing parameters');
}

// 3. Verify Signature
$secret = getenv('GATEWAY_SECRET');
if ($secret === false || $secret === '') {
    error_log('IPN: GATEWAY_SECRET environment variable not set');
    http_response_code(500);
    exit('Server Configuration Error');
}

// Construct the string to sign (adjust format if gateway docs differ)
$dataToSign = "$orderId:$amount:$status";
$expectedSig = hash_hmac('sha256', $dataToSign, $secret);

// Timing-safe comparison
if (!hash_equals($expectedSig, $sig)) {
    error_log("IPN: Invalid signature for order $orderId");
    http_response_code(400);
    exit('Invalid Signature');
}

// 4. Process only 'completed' status (case-insensitive check usually safer)
if (strtolower($status) !== 'completed') {
    // Not a success notification, acknowledge receipt but do nothing
    exit('OK: Status not completed');
}

// 5. Database Update via PDO
try {
    // Assuming config.php creates $pdo or provides DSN/credentials
    // Example DSN: 'mysql:host=localhost;dbname=shop;charset=utf8mb4'
    $dsn = DB_DSN; // Define in config.php
    $user = DB_USER;
    $pass = DB_PASS;

    $pdo = new PDO($dsn, $user, $pass, [
        PDO::ATTR_ERRMODE            => PDO::ERRMODE_EXCEPTION,
        PDO::ATTR_DEFAULT_FETCH_MODE => PDO::FETCH_ASSOC,
        PDO::ATTR_EMULATE_PREPARES   => false,
    ]);

    // Start transaction to ensure atomicity
    $pdo->beginTransaction();

    // Check current state (Idempotency: prevent double processing)
    $stmtCheck = $pdo->prepare('SELECT paid, amount FROM orders WHERE id = ? FOR UPDATE');
    $stmtCheck->execute([$orderId]);
    $order = $stmtCheck->fetch();

    if (!$order) {
        $pdo->rollBack();
        error_log("IPN: Order $orderId not found");
        http_response_code(404);
        exit('Order Not Found');
    }

    // Optional: Verify amount matches (prevent amount tampering)
    // Assuming DB amount is stored in cents or same format as gateway
    if ((float)$order['amount'] !== (float)$amount) {
        $pdo->rollBack();
        error_log("IPN: Amount mismatch for order $orderId (DB: {$order['amount']}, Gateway: $amount)");
        http_response_code(400);
        exit('Amount Mismatch');
    }

    if ((int)$order['paid'] === 1) {
        // Already paid, idempotent success
        $pdo->rollBack(); // No changes needed
        exit('OK: Already Paid');
    }

    // Update order
    $stmtUpdate = $pdo->prepare('UPDATE orders SET paid = 1, paid_at = NOW() WHERE id = ?');
    $stmtUpdate->execute([$orderId]);

    $pdo->commit();

    error_log("IPN: Order $orderId marked as paid");
    exit('OK');

} catch (PDOException $e) {
    if ($pdo->inTransaction()) {
        $pdo->rollBack();
    }
    error_log('IPN Database Error: ' . $e->getMessage());
    http_response_code(500);
