import subprocess
import json
from fastapi import FastAPI, Request, HTTPException, Header
from fastapi.responses import JSONResponse
from pydantic import BaseModel
from typing import Optional

app = FastAPI()

class GitHubPushEvent(BaseModel):
    ref: str
    repository: dict
    head_commit: Optional[dict] = None
    commits: list = []

@app.post("/github/webhook")
async def github_webhook(
    request: Request,
    x_github_event: Optional[str] = Header(None),
    x_hub_signature_256: Optional[str] = Header(None),
):
    # Verify it's a push event
    if x_github_event != "push":
        return JSONResponse(
            status_code=200,
            content={"message": f"Ignored event type: {x_github_event}"}
        )

    try:
        payload = await request.json()
    except json.JSONDecodeError:
        raise HTTPException(status_code=400, detail="Invalid JSON payload")

    # Validate payload structure
    if "ref" not in payload:
        raise HTTPException(status_code=400, detail="Missing 'ref' in payload")

    ref = payload["ref"]

    # Only deploy on pushes to main branch
    if ref != "refs/heads/main":
        return JSONResponse(
            status_code=200,
            content={"message": f"Ignored push to {ref}, only main branch triggers deploy"}
        )

    branch_name = ref.replace("refs/heads/", "")

    try:
        # Run deploy script with branch name as argument
        result = subprocess.run(
            ["./deploy.sh", branch_name],
            capture_output=True,
            text=True,
            timeout=300,  # 5 minute timeout
            cwd="."  # Run from current directory
        )

        if result.returncode == 0:
            return JSONResponse(
                status_code=200,
                content={
                    "message": "Deployment triggered successfully",
                    "branch": branch_name,
                    "output": result.stdout
                }
            )
        else:
            return JSONResponse(
                status_code=500,
                content={
                    "message": "Deployment script failed",
                    "branch": branch_name,
                    "error": result.stderr,
                    "output": result.stdout,
                    "return_code": result.returncode
                }
            )

    except subprocess.TimeoutExpired:
        raise HTTPException(status_code=500, detail="Deployment timed out after 5 minutes")
    except FileNotFoundError:
        raise HTTPException(status_code=500, detail="deploy.sh not found")
    except Exception as e:
        raise HTTPException(status_code=500, detail=f"Deployment error: {str(e)}")

# Health check endpoint
@app.get("/health")
async def health_check():
    return {"status": "ok"}
```

