```python
import os
import re
from typing import Any, Dict, List, Optional
from urllib.parse import urlparse

def get_diagnostics_config(
    settings: Optional[object] = None,
    env_allowlist: Optional[List[str]] = None,
    sensitive_patterns: Optional[List[str]] = None,
) -> Dict[str, Any]:
    """
    Collects runtime configuration for admin diagnostics, masking sensitive values.

    Args:
        settings: An object/module holding app settings (e.g., `app.config`, `settings`).
                  Attributes are inspected for DB/API config.
        env_allowlist: List of environment variable names to include (default: all).
        sensitive_patterns: Regex patterns for keys that should be masked (default: common secrets).

    Returns:
        A JSON-serializable dict with sections: environment, database, third_party_apis.
    """
    # Default patterns for sensitive keys (case-insensitive)
    default_sensitive_patterns = [
        r".*password.*", r".*secret.*", r".*api[_-]?key.*", r".*token.*",
        r".*auth.*", r".*private.*", r".*credential.*", r".*dsn.*",
        r".*connection[_-]?string.*", r".*access[_-]?key.*", r".*client[_-]?secret.*"
    ]
    sensitive_patterns = sensitive_patterns or default_sensitive_patterns
    compiled_patterns = [re.compile(p, re.IGNORECASE) for p in sensitive_patterns]

    def is_sensitive(key: str) -> bool:
        return any(p.match(key) for p in compiled_patterns)

    def mask_value(value: Any, key: str = "") -> Any:
        """Mask sensitive values; show first/last 4 chars for strings, else <REDACTED>."""
        if is_sensitive(key):
            if isinstance(value, str) and len(value) > 8:
                return f"{value[:4]}...{value[-4:]}"
            return "<REDACTED>"
        return value

    def safe_getattr(obj: object, attr: str, default: Any = None) -> Any:
        try:
            return getattr(obj, attr, default)
        except Exception:
            return default

    # 1. Environment variables
    env_vars = {}
    source_env = os.environ if env_allowlist is None else {k: os.environ[k] for k in env_allowlist if k in os.environ}
    for k, v in sorted(source_env.items()):
        env_vars[k] = mask_value(v, k)

    # 2. Database settings (from settings object or common env vars)
    db_config = {}
    db_attrs = [
        "DATABASE_URL", "SQLALCHEMY_DATABASE_URI", "DB_HOST", "DB_PORT",
        "DB_NAME", "DB_USER", "DB_PASSWORD", "DB_SSL_MODE", "DB_POOL_SIZE"
    ]
    for attr in db_attrs:
        val = safe_getattr(settings, attr) or os.environ.get(attr)
        if val is not None:
            # Parse URL to avoid logging full DSN
            if attr in ("DATABASE_URL", "SQLALCHEMY_DATABASE_URI") and isinstance(val, str):
                try:
                    parsed = urlparse(val)
                    db_config[attr] = {
                        "scheme": parsed.scheme,
                        "host": parsed.hostname,
                        "port": parsed.port,
                        "database": parsed.path.lstrip("/"),
                        "user": mask_value(parsed.username, attr),
                        "password": mask_value(parsed.password, attr),
                    }
                except Exception:
                    db_config[attr] = mask_value(val, attr)
            else:
                db_config[attr] = mask_value(val, attr)

    # 3. Third-party API settings
    api_config = {}
    # Common patterns for API config attributes
    api_attr_patterns = [
        r".*_API[_-]?(KEY|SECRET|URL|ENDPOINT|BASE[_-]?URL|HOST|TIMEOUT|VERSION).*",
        r".*(STRIPE|SENDGRID|TWILIO|AWS|GOOGLE|AZURE|SLACK|GITHUB|OPENAI|ANTHROPIC).*",
        r".*WEBHOOK.*",
    ]
    api_attr_regex = [re.compile(p, re.IGNORECASE) for p in api_attr_patterns]

    def looks_like_api_attr(name: str) -> bool:
        return any(r.match(name) for r in api_attr_regex)

    # Inspect settings object for API-like attributes
    if settings:
        for attr in dir(settings):
            if not attr.startswith("_") and looks_like_api_attr(attr):
                val = safe_getattr(settings, attr)
                if val is not None:
                    api_config[attr] = mask_value(val, attr)

    # Also check environment for API-like vars
    for k, v in os.environ.items():
        if looks_like_api_attr(k) and k not in api_config:
            api_config[k] = mask_value(v, k)

    return {
        "environment": env_vars,
        "database": db_config,
        "third_party_apis": api_config,
    }


