from urllib.parse import urlparse
from typing import Dict, Any, Optional

def get_runtime_config() -> Dict[str, Any]:
    """
    Returns a sanitized runtime configuration dictionary for admin diagnostics.

    Security: All sensitive values (passwords, secrets, tokens, keys) are masked.
    Only known configuration keys are included to avoid leaking unintended env vars.

    Returns:
        dict: Structured configuration with sections:
            - environment: filtered and masked environment variables
            - database: parsed database connection settings (without credentials)
            - third_party_apis: known external service configurations
    """
    def mask_value(key: str, value: Optional[str]) -> str:
        """Mask sensitive values based on key name."""
        if value is None:
            return "NOT_SET"
        sensitive_keywords = ['SECRET', 'KEY', 'PASSWORD', 'TOKEN', 'PRIVATE', 'CREDENTIAL']
        if any(kw in key.upper() for kw in sensitive_keywords):
            return "***" if value else "EMPTY"
        return value

    # 1. Environment Variables (filtered by known prefixes)
    env_prefixes = ('APP_', 'DB_', 'API_', 'LOG_', 'CACHE_', 'QUEUE_', 'STORAGE_')
    environment = {}
    for key, value in os.environ.items():
        if key.startswith(env_prefixes):
            environment[key] = mask_value(key, value)

    # 2. Database Settings (parse DATABASE_URL if present)
    database = {}
    db_url = os.environ.get('DATABASE_URL') or os.environ.get('DB_URL')
    if db_url:
        try:
            parsed = urlparse(db_url)
            database = {
                'scheme': parsed.scheme,
                'host': parsed.hostname,
                'port': parsed.port,
                'database': parsed.path.lstrip('/') if parsed.path else None,
                'username': parsed.username,
                'password': mask_value('PASSWORD', parsed.password),
                'query_params': dict(q.split('=') for q in parsed.query.split('&') if '=' in q) if parsed.query else {}
            }
        except Exception:
            database = {'error': 'Failed to parse DATABASE_URL', 'raw': mask_value('DATABASE_URL', db_url)}
    else:
        # Fallback to discrete DB_* env vars
        db_keys = ['DB_HOST', 'DB_PORT', 'DB_NAME', 'DB_USER', 'DB_PASSWORD', 'DB_SSLMODE']
        for k in db_keys:
            if k in os.environ:
                database[k] = mask_value(k, os.environ[k])

    # 3. Third-Party API Settings (known services)
    third_party_apis = {}
    known_services = {
        'stripe': ['STRIPE_SECRET_KEY', 'STRIPE_PUBLISHABLE_KEY', 'STRIPE_WEBHOOK_SECRET', 'STRIPE_API_VERSION'],
        'sendgrid': ['SENDGRID_API_KEY', 'SENDGRID_FROM_EMAIL'],
        'aws': ['AWS_ACCESS_KEY_ID', 'AWS_SECRET_ACCESS_KEY', 'AWS_REGION', 'AWS_S3_BUCKET'],
        'github': ['GITHUB_CLIENT_ID', 'GITHUB_CLIENT_SECRET', 'GITHUB_WEBHOOK_SECRET'],
        'slack': ['SLACK_BOT_TOKEN', 'SLACK_SIGNING_SECRET', 'SLACK_APP_TOKEN'],
        'datadog': ['DD_API_KEY', 'DD_APP_KEY', 'DD_SITE'],
        'sentry': ['SENTRY_DSN', 'SENTRY_ENVIRONMENT'],
        'redis': ['REDIS_URL', 'REDIS_HOST', 'REDIS_PORT', 'REDIS_PASSWORD'],
    }

    for service, keys in known_services.items():
        config = {}
        for key in keys:
            if key in os.environ:
                config[key] = mask_value(key, os.environ[key])
        if config:
            third_party_apis[service] = config

    return {
        'environment': environment,
        'database': database,
        'third_party_apis': third_party_apis
    }

