from typing import Dict, Any

def redact_sensitive(data: Dict[str, Any], sensitive_keywords: tuple = None) -> Dict[str, Any]:
    """Return a copy of data with values redacted for keys containing sensitive keywords."""
    if sensitive_keywords is None:
        sensitive_keywords = (
            'password', 'secret', 'key', 'token', 'api_key', 'apikey',
            'access_token', 'secret_key', 'private_key', 'credential'
        )
    redacted = {}
    for k, v in data.items():
        if any(keyword in k.lower() for keyword in sensitive_keywords):
            redacted[k] = '***REDACTED***'
        elif isinstance(v, dict):
            redacted[k] = redact_sensitive(v, sensitive_keywords)
        else:
            redacted[k] = v
    return redacted

def get_runtime_config() -> Dict[str, Any]:
    """
    Collect runtime configuration for admin diagnostics.
    Returns a dictionary safe to serialize as JSON.
    """
    # Environment variables (redact sensitive)
    env_vars = dict(os.environ)
    safe_env = redact_sensitive(env_vars)

    # Database settings - replace with actual config loading in your app
    # Example: from your_config import DATABASE_CONFIG
    DATABASE_CONFIG = {
