import os
import re
from typing import Any, Dict, List, Optional
from dataclasses import dataclass, asdict

@dataclass
class ConfigSection:
    """Represents a configuration section with metadata."""
    name: str
    description: str
    settings: Dict[str, Any]
    warnings: List[str]

class ConfigSanitizer:
    """Handles sanitization of sensitive configuration values."""

    # Patterns for sensitive keys (case-insensitive)
    SENSITIVE_PATTERNS = [
        r'.*password.*', r'.*secret.*', r'.*key.*', r'.*token.*',
        r'.*api[_-]?key.*', r'.*access[_-]?key.*', r'.*private[_-]?key.*',
        r'.*credential.*', r'.*auth.*', r'.*cert.*', r'.*ssl.*',
        r'.*database[_-]?url.*', r'.*dsn.*', r'.*connection[_-]?string.*'
    ]

    # Keys that should always be masked regardless of pattern
    ALWAYS_MASK = {
        'database_password', 'db_password', 'secret_key', 'api_key',
        'access_token', 'refresh_token', 'private_key', 'client_secret'
    }

    # Keys that are safe to show fully
    SAFE_KEYS = {
        'database_host', 'db_host', 'database_port', 'db_port',
        'database_name', 'db_name', 'database_user', 'db_user',
        'environment', 'debug', 'log_level', 'app_name', 'version'
    }

    def __init__(self, mask_char: str = "•", reveal_chars: int = 4):
        self.mask_char = mask_char
        self.reveal_chars = reveal_chars
        self._compiled_patterns = [re.compile(p, re.IGNORECASE) for p in self.SENSITIVE_PATTERNS]

    def is_sensitive(self, key: str) -> bool:
        """Check if a key should be masked."""
        key_lower = key.lower()
        if key_lower in self.SAFE_KEYS:
            return False
        if key_lower in self.ALWAYS_MASK:
            return True
        return any(pattern.match(key) for pattern in self._compiled_patterns)

    def sanitize_value(self, key: str, value: Any) -> Any:
        """Sanitize a single value based on its key."""
        if not isinstance(value, str) or not value:
            return value

        if self.is_sensitive(key):
            if len(value) <= self.reveal_chars * 2:
                return self.mask_char * len(value)
            return value[:self.reveal_chars] + self.mask_char * (len(value) - self.reveal_chars * 2) + value[-self.reveal_chars:]
        return value

    def sanitize_dict(self, data: Dict[str, Any], prefix: str = "") -> Dict[str, Any]:
        """Recursively sanitize a dictionary."""
        result = {}
        for key, value in data.items():
            full_key = f"{prefix}.{key}" if prefix else key
            if isinstance(value, dict):
                result[key] = self.sanitize_dict(value, full_key)
            elif isinstance(value, list):
                result[key] = [
                    self.sanitize_dict(item, f"{full_key}[{i}]") if isinstance(item, dict)
                    else self.sanitize_value(full_key, item)
                    for i, item in enumerate(value)
                ]
            else:
                result[key] = self.sanitize_value(full_key, value)
        return result

def get_runtime_config(
    include_env: bool = True,
    include_database: bool = True,
    include_third_party: bool = True,
    custom_sections: Optional[Dict[str, Dict[str, Any]]] = None,
    sanitizer: Optional[ConfigSanitizer] = None
) -> Dict[str, Any]:
    """
    Collect and return runtime configuration for admin diagnostics.

    Args:
        include_env: Include environment variables
        include_database: Include database configuration
        include_third_party: Include third-party API configuration
        custom_sections: Additional custom configuration sections
        sanitizer: Custom sanitizer instance (uses default if None)

    Returns:
        Dictionary with configuration sections, ready for JSON serialization
    """
    sanitizer = sanitizer or ConfigSanitizer()
    sections = []
    warnings = []

    # Environment Variables
    if include_env:
        env_vars = dict(os.environ)
        sanitized_env = sanitizer.sanitize_dict(env_vars)

        # Check for common misconfigurations
        env_warnings = []
        if not os.getenv('SECRET_KEY') and not os.getenv('APP_SECRET'):
            env_warnings.append("No SECRET_KEY or APP_SECRET found in environment")
        if os.getenv('DEBUG', '').lower() in ('true', '1', 'yes'):
            env_warnings.append("DEBUG mode is enabled in production environment")

        sections.append(ConfigSection(
            name="environment_variables",
            description="Application environment variables (sensitive values masked)",
            settings=sanitized_env,
            warnings=env_warnings
        ))
        warnings.extend(env_warnings)

    # Database Configuration
    if include_database:
        db_config = _get_database_config()
        sanitized_db = sanitizer.sanitize_dict(db_config)

        db_warnings = []
        if not db_config.get('host'):
            db_warnings.append("Database host not configured")
        if db_config.get('port') in (None, '', 0):
            db_warnings.append("Database port not configured")
        if 'sqlite' in str(db_config.get('engine', '')).lower():
            db_warnings.append("Using SQLite - not recommended for production")

        sections.append(ConfigSection(
            name="database",
            description="Database connection settings (credentials masked)",
            settings=sanitized_db,
            warnings=db_warnings
        ))
        warnings.extend(db_warnings)

    # Third-party API Configuration
    if include_third_party:
        api_config = _get_third_party_config()
        sanitized_api = sanitizer.sanitize_dict(api_config)

        api_warnings = []
        for service, config in api_config.items():
            if isinstance(config, dict):
                if not config.get('enabled', True):
                    api_warnings.append(f"{service}: Service is disabled")
                if not config.get('api_key') and not config.get('access_token'):
                    api_warnings.append(f"{service}: No authentication configured")

        sections.append(ConfigSection(
            name="third_party_apis",
            description="Third-party service configurations (keys/tokens masked)",
            settings=sanitized_api,
            warnings=api_warnings
        ))
        warnings.extend(api_warnings)

    # Custom Sections
    if custom_sections:
        for name, config in custom_sections.items():
            sanitized = sanitizer.sanitize_dict(config)
            sections.append(ConfigSection(
                name=name,
                description=f"Custom configuration section: {name}",
                settings=sanitized,
                warnings=[]
            ))

    # Build final response
    return {
        "timestamp": _get_timestamp(),
        "version": _get_app_version(),
        "environment": os.getenv('ENVIRONMENT', os.getenv('APP_ENV', 'unknown')),
        "warnings": warnings,
        "sections": [asdict(section) for section in sections]
    }

def _get_database_config() -> Dict[str, Any]:
    """Extract database configuration from common sources."""
    # Try Django-style DATABASES setting
    try:
        from django.conf import settings
        if hasattr(settings, 'DATABASES'):
            db = settings.DATABASES.get('default', {})
            return {
                'engine': db.get('ENGINE', ''),
                'host': db.get('HOST', ''),
                'port': db.get('PORT', ''),
                'name': db.get('NAME', ''),
                'user': db.get('USER', ''),
                'password': db.get('PASSWORD', ''),
                'options': db.get('OPTIONS', {}),
            }
    except ImportError:
        pass

    # Try SQLAlchemy-style URL
    db_url = os.getenv('DATABASE_URL') or os.getenv('DB_URL') or os.getenv('SQLALCHEMY_DATABASE_URI')
    if db_url:
        return {'url': db_url}

    # Fallback to individual env vars
    return {
        'engine': os.getenv('DB_ENGINE', os.getenv('DATABASE_ENGINE', '')),
        'host': os.getenv('DB_HOST', os.getenv('DATABASE_HOST', '')),
        'port': os.getenv('DB_PORT', os.getenv('DATABASE_PORT', '')),
        'name': os.getenv('DB_NAME', os.getenv('DATABASE_NAME', '')),
        'user': os.getenv('DB_USER', os.getenv('DATABASE_USER', '')),
        'password': os.getenv('DB_PASSWORD', os.getenv('DATABASE_PASSWORD', '')),
    }

def _get_third_party_config() -> Dict[str, Any]:
    """Extract third-party API configuration from environment."""
    # Common third-party services - extend as needed
    services = {
        'aws': {
            'enabled': True,
            'region': os.getenv('AWS_REGION', os.getenv('AWS_DEFAULT_REGION', '')),
            'access_key_id': os.getenv('AWS_ACCESS_KEY_ID', ''),
            'secret_access_key': os.getenv('AWS_SECRET_ACCESS_KEY', ''),
            'session_token': os.getenv('AWS_SESSION_TOKEN', ''),
