        'stripe': {
            'enabled': bool(os.getenv('STRIPE_SECRET_KEY')),
            'publishable_key': os.getenv('STRIPE_PUBLISHABLE_KEY', ''),
            'secret_key': os.getenv('STRIPE_SECRET_KEY', ''),
            'webhook_secret': os.getenv('STRIPE_WEBHOOK_SECRET', ''),
        },
        'sendgrid': {
            'enabled': bool(os.getenv('SENDGRID_API_KEY')),
            'api_key': os.getenv('SENDGRID_API_KEY', ''),
            'from_email': os.getenv('SENDGRID_FROM_EMAIL', ''),
        },
        'twilio': {
            'enabled': bool(os.getenv('TWILIO_ACCOUNT_SID')),
            'account_sid': os.getenv('TWILIO_ACCOUNT_SID', ''),
            'auth_token': os.getenv('TWILIO_AUTH_TOKEN', ''),
            'phone_number': os.getenv('TWILIO_PHONE_NUMBER', ''),
        },
        'github': {
            'enabled': bool(os.getenv('GITHUB_CLIENT_ID')),
            'client_id': os.getenv('GITHUB_CLIENT_ID', ''),
            'client_secret': os.getenv('GITHUB_CLIENT_SECRET', ''),
        },
        'slack': {
            'enabled': bool(os.getenv('SLACK_BOT_TOKEN')),
            'bot_token': os.getenv('SLACK_BOT_TOKEN', ''),
            'signing_secret': os.getenv('SLACK_SIGNING_SECRET', ''),
            'app_token': os.getenv('SLACK_APP_TOKEN', ''),
        },
        'sentry': {
            'enabled': bool(os.getenv('SENTRY_DSN')),
            'dsn': os.getenv('SENTRY_DSN', ''),
            'environment': os.getenv('SENTRY_ENVIRONMENT', ''),
        },
        'redis': {
            'enabled': bool(os.getenv('REDIS_URL')),
