import os
import re
from typing import Any, Dict, List, Optional, Union
from urllib.parse import urlparse

def get_runtime_config(
    app_config: Optional[Dict[str, Any]] = None,
    sensitive_patterns: Optional[List[str]] = None,
    include_env: bool = True,
    include_db: bool = True,
    include_third_party: bool = True,
) -> Dict[str, Any]:
    """
    Collects the current runtime configuration for admin diagnostics.

    Args:
        app_config: A dictionary-like object containing the application's configuration
                    (e.g., Flask's `app.config`, Django's `settings`, or a custom dict).
                    If None, only environment variables are used.
        sensitive_patterns: List of regex patterns (case-insensitive) that identify
                            sensitive keys. Values matching these patterns will be redacted.
                            Defaults to common secret-like patterns.
        include_env: Whether to include environment variables.
        include_db: Whether to include database connection settings.
        include_third_party: Whether to include third‑party API settings.

    Returns:
        A dictionary ready to be serialized as JSON for the diagnostics page.
    """
    # Default patterns for sensitive data (passwords, tokens, keys, secrets, etc.)
    if sensitive_patterns is None:
        sensitive_patterns = [
            r'password',
            r'secret',
            r'api[_-]?key',
            r'token',
            r'private[_-]?key',
            r'access[_-]?key',
            r'auth',
            r'credential',
        ]

    compiled_patterns = [re.compile(p, re.IGNORECASE) for p in sensitive_patterns]

    def _is_sensitive(key: str) -> bool:
        """Check if a key matches any sensitive pattern."""
        return any(p.search(key) for p in compiled_patterns)

    def _redact(value: Any) -> Any:
        """Redact sensitive values (strings, URLs, dicts, lists)."""
        if isinstance(value, str):
            # If it looks like a URL, keep the scheme and host but redact userinfo/password
            parsed = urlparse(value)
            if parsed.scheme and parsed.netloc:
                # Reconstruct URL without password
                netloc = parsed.netloc
                if '@' in netloc:
                    userinfo, host = netloc.split('@', 1)
                    if ':' in userinfo:
                        user, _ = userinfo.split(':', 1)
                        netloc = f"{user}:****@{host}"
                return parsed._replace(netloc=netloc).geturl()
            # Otherwise, if the key is sensitive, show only last 4 chars (or **** if too short)
            return value[-4:] if len(value) > 4 else '****'
        elif isinstance(value, dict):
            return {k: _redact(v) if _is_sensitive(k) else v for k, v in value.items()}
        elif isinstance(value, (list, tuple)):
            return [_redact(v) for v in value]
        return value

    config_snapshot: Dict[str, Any] = {}

    # 1. Environment Variables
    if include_env:
        env_vars = {}
        for k, v in os.environ.items():
            env_vars[k] = _redact(v) if _is_sensitive(k) else v
        config_snapshot["environment_variables"] = env_vars

    # 2. Application Configuration (database, third‑party, etc.)
    if app_config:
        # Helper to extract a subsection from app_config using a prefix
        def _extract_section(prefix: str) -> Dict[str, Any]:
            section = {}
            for k, v in app_config.items():
                if k.startswith(prefix):
                    # Remove prefix for cleaner keys
                    short_key = k[len(prefix):]
                    section[short_key] = _redact(v) if _is_sensitive(k) else v
            return section

        if include_db:
            # Common prefixes for database settings
            db_prefixes = ["DATABASE_", "SQLALCHEMY_", "DB_", "POSTGRES_", "MYSQL_", "MONGO_"]
            db_settings = {}
            for prefix in db_prefixes:
                db_settings.update(_extract_section(prefix))
            config_snapshot["database_settings"] = db_settings

        if include_third_party:
            # Common prefixes for third‑party APIs
            api_prefixes = ["AWS_", "GOOGLE_", "AZURE_", "STRIPE_", "TWILIO_", "SENDGRID_", "SLACK_", "GITHUB_"]
            api_settings = {}
            for prefix in api_prefixes:
                api_settings.update(_extract_section(prefix))
            config_snapshot["third_party_api_settings"] = api_settings

        # Include any other top‑level config that isn't already captured
        # (optional – you can decide to expose the whole config minus sensitive keys)
        other_config = {}
        captured_keys = set()
        for prefix in db_prefixes + api_prefixes:
            captured_keys.update(k for k in app_config if k.startswith(prefix))
        for k, v in app_config.items():
            if k not in captured_keys:
                other_config[k] = _redact(v) if _is_sensitive(k) else v
        if other_config:
            config_snapshot["other_settings"] = other_config

    return config_snapshot


