import os
import json
from typing import Dict, Any, Optional

def get_runtime_config(config: Optional[object] = None) -> Dict[str, Any]:
    """
    Collects runtime configuration for admin diagnostics.
    Masks sensitive values (passwords, secrets, keys, tokens).
    Args:
        config: Optional application config object with attributes:
            - DATABASE_* or database dict
            - Third-party API settings (e.g., STRIPE_API_KEY, SENTRY_DSN)
    Returns:
        Dict ready for JSON serialization.
    """
    def mask_value(key: str, value: Any) -> Any:
        """Mask sensitive values based on key name."""
        if not isinstance(value, str):
            return value
        sensitive_keywords = [
            'password', 'secret', 'key', 'token', 'api_key', 'apikey',
            'access_token', 'private_key', 'credential', 'auth'
        ]
        key_lower = key.lower()
        if any(kw in key_lower for kw in sensitive_keywords):
            return '***MASKED***'
        return value

    # Environment variables (masked)
    env_vars = {
        k: mask_value(k, v)
        for k, v in os.environ.items()
    }

    # Database settings (from config object or env)
    db_settings = {}
    if config:
        # Common patterns: config.DATABASE_URL, config.DATABASES, config.db
        for attr in ['DATABASE_URL', 'DATABASES', 'db', 'database']:
            if hasattr(config, attr):
                val = getattr(config, attr)
                if isinstance(val, dict):
                    db_settings = {k: mask_value(k, v) for k, v in val.items()}
                else:
                    db_settings = {'url': mask_value(attr, val)}
                break
    # Fallback to environment
    if not db_settings:
        for k, v in os.environ.items():
            if k.startswith(('DATABASE_', 'DB_', 'POSTGRES_', 'MYSQL_', 'MONGO_')):
                db_settings[k] = mask_value(k, v)

    # Third-party API settings (from config object or env)
    api_settings = {}
    if config:
        # Collect attributes that look like API configs
        for attr in dir(config):
            if attr.isupper() and any(kw in attr for kw in ['API', 'KEY', 'SECRET', 'TOKEN', 'DSN', 'URL']):
                val = getattr(config, attr)
                if not callable(val) and not attr.startswith('_'):
                    api_settings[attr] = mask_value(attr, val)
    # Fallback to environment
    if not api_settings:
        for k, v in os.environ.items():
            if any(kw in k for kw in ['API', 'KEY', 'SECRET', 'TOKEN', 'DSN', 'WEBHOOK']):
                api_settings[k] = mask_value(k, v)

    return {
        "environment": env_vars,
        "database": db_settings,
        "third_party_apis": api_settings
    }

