import os
import re
from urllib.parse import urlparse
from typing import Dict, Any


def get_runtime_config() -> Dict[str, Any]:
    """Return sanitized runtime configuration for admin diagnostics."""

    def mask_value(key: str, value: str) -> str:
        """Mask sensitive values based on key name."""
        sensitive_patterns = [
            r'PASSWORD', r'SECRET', r'KEY', r'TOKEN', 
            r'PRIVATE', r'CREDENTIAL', r'AUTH'
        ]
        if any(re.search(p, key, re.IGNORECASE) for p in sensitive_patterns):
            if value:
                return f"{value[:4]}{'*' * (len(value) - 8)}{value[-4:]}" if len(value) > 8 else "********"
        return value

    def parse_database_url(url: str) -> Dict[str, Any]:
        """Parse DATABASE_URL into components without credentials."""
        try:
            parsed = urlparse(url)
            return {
                "scheme": parsed.scheme,
                "host": parsed.hostname,
                "port": parsed.port,
                "database": parsed.path.lstrip('/') if parsed.path else None,
                "username": parsed.username,
                "password": "********" if parsed.password else None,
                "query": dict(q.split('=') for q in parsed.query.split('&') if q) if parsed.query else {}
            }
        except Exception:
            return {"raw": mask_value("DATABASE_URL", url)}

    # Collect environment variables
    env_vars = {}
    for key, value in os.environ.items():
        env_vars[key] = mask_value(key, value)

    # Database settings
    db_config = {}
    database_url = os.environ.get('DATABASE_URL')
    if database_url:
        db_config['url_parsed'] = parse_database_url(database_url)
    else:
        # Fallback to individual components
        db_config['host'] = os.environ.get('DB_HOST')
        db_config['port'] = os.environ.get('DB_PORT')
        db_config['name'] = os.environ.get('DB_NAME')
        db_config['user'] = os.environ.get('DB_USER')
        db_config['password'] = mask_value('DB_PASSWORD', os.environ.get('DB_PASSWORD', ''))

    # Third-party API settings (common prefixes)
    api_prefixes = ['STRIPE_', 'AWS_', 'GOOGLE_', 'GITHUB_', 'SLACK_', 'TWILIO_', 
                    'SENDGRID_', 'MAILGUN_', 'REDIS_', 'ELASTIC_', 'OPENAI_']
    api_settings = {}
    for key, value in os.environ.items():
        if any(key.startswith(prefix) for prefix in api_prefixes):
            api_settings[key] = mask_value(key, value)

    # Application settings
    app_settings = {
        'ENV': os.environ.get('ENV', 'development'),
        'DEBUG': os.environ.get('DEBUG', 'false').lower() == 'true',
        'LOG_LEVEL': os.environ.get('LOG_LEVEL', 'INFO'),
        'ALLOWED_HOSTS': os.environ.get('ALLOWED_HOSTS', '').split(',') if os.environ.get('ALLOWED_HOSTS') else [],
        'CORS_ORIGINS': os.environ.get('CORS_ORIGINS', '').split(',') if os.environ.get('CORS_ORIGINS') else [],
    }

    return {
        "environment_variables": env_vars,
        "database": db_config,
        "third_party_apis": api_settings,
        "application": app_settings,
        "python_version": f"{__import__('sys').version_info.major}.{__import__('sys').version_info.minor}.{__import__('sys').version_info.micro}",
        "platform": __import__('platform').platform()
    }

import os
import re
from typing import Dict, Any, Optional

def mask_sensitive(value: Optional[str], visible_chars: int = 4) -> str:
    """Mask sensitive string, showing only first and last `visible_chars` characters."""
    if not value:
        return "***"
    if len(value) <= visible_chars * 2:
        return "*" * len(value)
    return value[:visible_chars] + "*" * (len(value) - visible_chars * 2) + value[-visible_chars:]

def get_runtime_config(app_config: Optional[Dict[str, Any]] = None) -> Dict[str, Any]:
    """
    Collect runtime configuration for admin diagnostics.
    Args:
        app_config: Optional application config dict (e.g., Flask app.config).
    Returns:
        Dict safe for JSON serialization with sensitive values masked.
    """
    config = {}

    # 1. Environment variables (filter for relevant prefixes)
    env_prefixes = ("APP_", "DB_", "DATABASE_", "API_", "THIRD_PARTY_", "SECRET_", "KEY_", "TOKEN_")
    env_vars = {
        k: mask_sensitive(v) if any(k.startswith(p) for p in ("SECRET_", "KEY_", "TOKEN_", "PASSWORD", "PASSWD")) else v
        for k, v in os.environ.items()
        if k.startswith(env_prefixes)
    }
    config["environment_variables"] = env_vars

    # 2. Database settings (from app_config or env)
    db_config = {}
    if app_config:
        # Common keys
        for key in ["DATABASE_URL", "SQLALCHEMY_DATABASE_URI", "DB_HOST", "DB_PORT", "DB_NAME", "DB_USER", "DB_PASSWORD"]:
            if key in app_config:
                val = app_config[key]
                if "PASSWORD" in key or "PASSWD" in key:
                    db_config[key] = mask_sensitive(val)
                else:
                    db_config[key] = val
    # Fallback to environment
    for key in ["DB_HOST", "DB_PORT", "DB_NAME", "DB_USER", "DB_PASSWORD", "DATABASE_URL"]:
        if key in os.environ and key not in db_config:
            val = os.environ[key]
            db_config[key] = mask_sensitive(val) if "PASSWORD" in key else val
    config["database"] = db_config

    # 3. Third-party API settings
    api_config = {}
    # From app_config
    if app_config:
        for key, val in app_config.items():
            if key.startswith(("API_", "THIRD_PARTY_")) and not key.endswith(("_KEY", "_SECRET", "_TOKEN")):
                api_config[key] = val
            elif key.endswith(("_KEY", "_SECRET", "_TOKEN")):
                api_config[key] = mask_sensitive(val)
    # From environment
    for key, val in os.environ.items():
        if key.startswith(("API_", "THIRD_PARTY_")) and key not in api_config:
            if key.endswith(("_KEY", "_SECRET", "_TOKEN")):
                api_config[key] = mask_sensitive(val)
            else:
                api_config[key] = val
    config["third_party_apis"] = api_config

    # 4. General app settings (non-sensitive)
    general = {}
    if app_config:
        for key in ["DEBUG", "TESTING", "ENV", "SECRET_KEY", "JWT_SECRET_KEY"]:
            if key in app_config:
                general[key] = mask_sensitive(app_config[key]) if "SECRET" in key or "KEY" in key else app_config[key]
    config["general"] = general

    return config

