import os
import json
from typing import Dict, Any, Set

# Keys that should be redacted in output
SENSITIVE_KEYS: Set[str] = {
    "password", "secret", "key", "token", "api_key", "apikey",
    "access_key", "secret_key", "private_key", "cert", "credential",
    "auth", "passwd", "pwd", "dsn", "connection_string"
}

def _is_sensitive(key: str) -> bool:
    """Check if a config key contains sensitive information."""
    key_lower = key.lower()
    return any(sensitive in key_lower for sensitive in SENSITIVE_KEYS)

def _redact_value(key: str, value: Any) -> Any:
    """Redact sensitive values, keep non-sensitive as-is."""
    if _is_sensitive(key):
        return "***REDACTED***" if value else None
    return value

def _sanitize_dict(data: Dict[str, Any], prefix: str = "") -> Dict[str, Any]:
    """Recursively sanitize a dictionary, redacting sensitive keys."""
    result = {}
    for key, value in data.items():
        full_key = f"{prefix}.{key}" if prefix else key
        if isinstance(value, dict):
            result[key] = _sanitize_dict(value, full_key)
        elif isinstance(value, (list, tuple)):
            result[key] = [
                _sanitize_dict(item, f"{full_key}[{i}]") if isinstance(item, dict)
                else _redact_value(full_key, item)
                for i, item in enumerate(value)
            ]
        else:
            result[key] = _redact_value(full_key, value)
    return result

def get_runtime_config() -> Dict[str, Any]:
    """
    Collect and return current runtime configuration for admin diagnostics.
    Redacts sensitive values (passwords, secrets, keys, tokens).
    """
    config = {
        "environment": _sanitize_dict(dict(os.environ)),
        "database": _get_database_config(),
        "third_party_apis": _get_third_party_api_config(),
        "application": _get_application_config(),
    }
    return config

def _get_database_config() -> Dict[str, Any]:
    """Extract database configuration from common sources."""
    db_config = {}

    # Common environment variable patterns
    for key, value in os.environ.items():
        if any(prefix in key.upper() for prefix in ["DATABASE", "DB_", "SQLALCHEMY", "DJANGO_DB"]):
            db_config[key] = value

    # Flask/Django app config if available
    try:
        from flask import current_app
        if current_app:
            for key, value in current_app.config.items():
                if "DATABASE" in key.upper() or "SQLALCHEMY" in key.upper():
                    db_config[key] = value
    except (ImportError, RuntimeError):
        pass

    try:
        from django.conf import settings
        if hasattr(settings, "DATABASES"):
            db_config["DATABASES"] = settings.DATABASES
    except (ImportError, AttributeError):
        pass

    return _sanitize_dict(db_config)

def _get_third_party_api_config() -> Dict[str, Any]:
    """Extract third-party API configuration."""
    api_config = {}

    # Common environment variable patterns
    for key, value in os.environ.items():
        if any(prefix in key.upper() for prefix in [
            "API_", "AWS_", "GOOGLE_", "AZURE_", "STRIPE_", "SENDGRID_",
            "TWILIO_", "SLACK_", "GITHUB_", "OPENAI_", "ANTHROPIC_"
        ]):
            api_config[key] = value

    return _sanitize_dict(api_config)

def _get_application_config() -> Dict[str, Any]:
    """Extract general application configuration."""
    app_config = {}

    # Framework-specific config
    try:
        from flask import current_app
        if current_app:
            app_config["flask"] = dict(current_app.config)
    except (ImportError, RuntimeError):
        pass

    try:
        from django.conf import settings
        if settings.configured:
            # Only include non-sensitive Django settings
            django_settings = {}
            for key in dir(settings):
                if not key.startswith("_") and key.isupper():
                    value = getattr(settings, key)
                    if not callable(value):
                        django_settings[key] = value
            app_config["django"] = django_settings
    except (ImportError, AttributeError):
        pass

    # Generic app config from environment
    for key, value in os.environ.items():
        if any(prefix in key.upper() for prefix in ["APP_", "SERVICE_", "CONFIG_"]):
            app_config[key] = value

    return _sanitize_dict(app_config)

