def _mask_key(key: Optional[str], visible_chars: int = 4) -> str:
    """Masks a key, showing only first/last few characters for identification."""
    if not key:
        return ""
    if len(key) <= visible_chars * 2:
        return "*" * len(key)
    return key[:visible_chars] + "*" * (len(key) - visible_chars * 2) + key[-visible_chars:]

