# Keys considered sensitive — values will be masked in output
SENSITIVE_KEY_PATTERNS: List[re.Pattern] = [
    re.compile(r'(?i)^.*(password|secret|key|token|auth|credential|api[_-]?key|access[_-]?token|private[_-]?key).*$'),
    re.compile(r'(?i)^(database[_-]?url|db[_-]?uri|sqlalchemy[_-]?database[_-]?uri)$'),
]

# Known third-party service prefixes to include explicitly
THIRD_PARTY_PREFIXES: Set[str] = {
    'AWS_', 'AZURE_', 'GOOGLE_', 'STRIPE_', 'SENDGRID_', 'TWILIO_',
    'GITHUB_', 'GITLAB_', 'SLACK_', 'DATADOG_', 'NEW_RELIC_', 'SENTRY_'
}

def mask_value(key: str, value: Any) -> Any:
    """Mask sensitive values; return original for non-sensitive."""
    if not isinstance(value, str):
        return value
    for pattern in SENSITIVE_KEY_PATTERNS:
        if pattern.match(key):
            return '***MASKED***'
    return value

