        if any(kw in key.upper() for kw in ['DATABASE', 'DB_', 'SQLALCHEMY']):
            config['database_settings'][key] = masked

        # Extract third-party API settings by known prefixes
        for prefix in THIRD_PARTY_PREFIXES:
            if key.startswith(prefix):
                config['third_party_api_settings'][key] = masked
                break

    return config

