    sensitive_keys: tuple = ("PASSWORD", "SECRET", "KEY", "TOKEN", "CREDENTIAL")
) -> Dict[str, Any]:
    """
    Collects runtime configuration for admin diagnostics.
    Masks sensitive values (shows only last 4 chars if length > 4).
    Args:
        config: Application config dict (e.g., Flask app.config). If None, uses os.environ.
        env_prefixes: Prefixes to filter environment variables.
        sensitive_keys: Keywords that indicate a value should be masked.
    Returns:
        JSON-serializable dict with configuration sections.
    """
    def mask_value(key: str, value: Any) -> Any:
        """Mask sensitive string values."""
        if isinstance(value, str) and any(sk in key.upper() for sk in sensitive_keys):
            if len(value) > 4:
                return f"****{value[-4:]}"
            return "****"
        return value

    def filter_env(prefixes: tuple) -> Dict[str, Any]:
        """Extract env vars matching prefixes."""
        result = {}
        for k, v in os.environ.items():
            if any(k.startswith(p) for p in prefixes):
                result[k] = mask_value(k, v)
        return result

    # Use provided config or fall back to environment
    source = config if config is not None else os.environ

    # Environment variables (filtered)
    env_vars = filter_env(env_prefixes)

    # Database settings (common keys)
    db_keys = ("DB_HOST", "DB_PORT", "DB_NAME", "DB_USER", "DB_PASSWORD", "DATABASE_URL")
    database = {}
    for k in db_keys:
        if k in source:
            database[k] = mask_value(k, source[k])

    # Third-party API settings (common keys)
    api_keys = ("API_BASE_URL", "API_TIMEOUT", "API_KEY", "API_SECRET", "THIRD_PARTY_API_URL", "THIRD_PARTY_API_KEY")
    third_party = {}
    for k in api_keys:
        if k in source:
            third_party[k] = mask_value(k, source[k])

    return {
        "environment_variables": env_vars,
        "database": database,
        "third_party_apis": third_party,
        "runtime": {
            "python_version": os.sys.version.split()[0],
            "platform": os.sys.platform,
            "pid": os.getpid()
        }
    }

