from urllib.parse import urlparse

def get_runtime_config() -> Dict[str, Any]:
    """
    Returns sanitized runtime configuration for admin diagnostics.
    Masks sensitive values (passwords, keys, tokens) while showing structure.
    """
    def mask_value(key: str, value: str) -> str:
        """Mask sensitive configuration values."""
        sensitive_keywords = [
            'password', 'secret', 'key', 'token', 'api_key', 'apikey',
            'access_key', 'secret_key', 'private_key', 'auth', 'credential'
        ]
        key_lower = key.lower()
        if any(kw in key_lower for kw in sensitive_keywords):
            if len(value) > 8:
                return value[:4] + '*' * (len(value) - 8) + value[-4:]
            return '*' * len(value)
        return value

    def parse_database_url(url: str) -> Dict[str, Any]:
        """Parse database URL into components without exposing credentials."""
        try:
            parsed = urlparse(url)
            return {
                'scheme': parsed.scheme,
                'host': parsed.hostname,
                'port': parsed.port,
                'database': parsed.path.lstrip('/') if parsed.path else None,
                'username': parsed.username,
                'password': '***' if parsed.password else None
            }
        except Exception:
            return {'raw': 'invalid_url'}

    config = {
        'environment': os.getenv('ENVIRONMENT', 'development'),
        'debug_mode': os.getenv('DEBUG', 'false').lower() == 'true',
        'python_version': os.sys.version.split()[0],
        'environment_variables': {},
        'database': {},
        'third_party_apis': {}
    }

    # Environment variables (sanitized)
    for key, value in os.environ.items():
        # Skip internal/system vars
        if key.startswith(('_', 'PYTHON', 'PATH', 'HOME', 'USER', 'SHELL', 'TERM')):
            continue
        config['environment_variables'][key] = mask_value(key, value)

    # Database settings
    db_url = os.getenv('DATABASE_URL') or os.getenv('SQLALCHEMY_DATABASE_URI')
    if db_url:
        config['database']['connection'] = parse_database_url(db_url)
    else:
        # Fallback to individual settings
        db_config = {}
        for key in ['DB_HOST', 'DB_PORT', 'DB_NAME', 'DB_USER', 'DB_PASSWORD', 'DB_SSL_MODE']:
            val = os.getenv(key)
            if val is not None:
                db_config[key.lower()] = mask_value(key, val)
        if db_config:
            config['database']['settings'] = db_config

    # Third-party API settings (common patterns)
    api_prefixes = ['AWS_', 'GOOGLE_', 'AZURE_', 'STRIPE_', 'TWILIO_', 'SENDGRID_', 'SLACK_', 'GITHUB_', 'OPENAI_']
    for key, value in os.environ.items():
        if any(key.startswith(prefix) for prefix in api_prefixes):
            if 'third_party_apis' not in config:
                config['third_party_apis'] = {}
            # Group by service prefix
            service = next((p.rstrip('_') for p in api_prefixes if key.startswith(p)), 'OTHER')
            if service not in config['third_party_apis']:
                config['third_party_apis'][service] = {}
            config['third_party_apis'][service][key] = mask_value(key, value)

    return config

