    """
    # Default sensitive patterns (case-insensitive)
    default_sensitive = {
        "password", "secret", "key", "token", "api_key", "apikey",
        "access_key", "secret_key", "private_key", "cert", "credential",
        "auth", "passwd", "pwd", "dsn", "connection_string", "uri"
    }
    sensitive = default_sensitive | {k.lower() for k in (sensitive_keys or set())}

    # Default env prefixes to include
    prefixes = {p.upper() for p in (env_prefixes or {"APP_", "DB_", "API_", "THIRD_PARTY_"})}

    def is_sensitive(key: str) -> bool:
        kl = key.lower()
        return any(s in kl for s in sensitive)

    def mask_value(key: str, value: Any) -> Any:
        if value is None:
            return None
        if is_sensitive(key):
            s = str(value)
            if len(s) <= 8:
                return "***"
            return f"{s[:4]}***{s[-4:]}"
        return value

    def sanitize_dict(d: Dict[str, Any], prefix: str = "") -> Dict[str, Any]:
        result = {}
        for k, v in d.items():
            full_key = f"{prefix}{k}" if prefix else k
            if isinstance(v, dict):
                result[k] = sanitize_dict(v, f"{full_key}.")
            elif isinstance(v, (list, tuple)):
                result[k] = [
                    sanitize_dict(item, f"{full_key}[{i}].") if isinstance(item, dict)
                    else mask_value(full_key, item)
                    for i, item in enumerate(v)
                ]
            else:
                result[k] = mask_value(full_key, v)
        return result

    diagnostics = {
        "environment": {},
        "database": {},
        "third_party_apis": {},
        "application": {},
    }

    # 1. Environment variables (filtered by prefix)
    for key, value in os.environ.items():
        if any(key.upper().startswith(p) for p in prefixes):
            diagnostics["environment"][key] = mask_value(key, value)

    # 2. Application config (if provided)
    if app_config:
        diagnostics["application"] = sanitize_dict(app_config)

    # 3. Extract database settings from common config keys
    db_keys = [
        "DATABASE_URL", "DATABASE_URI", "SQLALCHEMY_DATABASE_URI",
        "DB_HOST", "DB_PORT", "DB_NAME", "DB_USER", "DB_PASSWORD",
