        "MYSQL_HOST", "MYSQL_PORT", "MYSQL_DATABASE", "MYSQL_USER",
    ]
    for key in db_keys:
        # Check env first
        if key in os.environ:
            diagnostics["database"][key] = mask_value(key, os.environ[key])
        # Then app config
        elif app_config and key in app_config:
            diagnostics["database"][key] = mask_value(key, app_config[key])

    # Parse DATABASE_URL if present for structured info
    db_url = diagnostics["database"].get("DATABASE_URL") or diagnostics["database"].get("DATABASE_URI") or diagnostics["database"].get("SQLALCHEMY_DATABASE_URI")
    if db_url and not is_sensitive("DATABASE_URL"):
        try:
