                "database": parsed.path.lstrip("/") if parsed.path else None,
                "username": parsed.username,
                "password": "***" if parsed.password else None,
            }
        except Exception:
            pass

    # 4. Third-party API settings (common patterns)
    api_patterns = [
        "API_", "THIRD_PARTY_", "EXTERNAL_", "SERVICE_",
        "STRIPE_", "SENDGRID_", "TWILIO_", "AWS_", "GOOGLE_",
        "GITHUB_", "SLACK_", "DISCORD_", "OPENAI_", "ANTHROPIC_",
    ]
    for key, value in os.environ.items():
        if any(key.upper().startswith(p) for p in api_patterns):
            diagnostics["third_party_apis"][key] = mask_value(key, value)

    if app_config:
        for key, value in app_config.items():
            if any(key.upper().startswith(p) for p in api_patterns):
                diagnostics["third_party_apis"][key] = mask_value(key, value)

    # 5. Runtime info
    diagnostics["runtime"] = {
        "python_version": os.sys.version.split()[0],
        "platform": os.sys.platform,
        "pid": os.getpid(),
        "cwd": os.getcwd(),
    }

    return diagnostics


