    key_lower = key.lower()
    if any(s in key_lower for s in SENSITIVE_KEYS):
        return True
    if any(key.upper().startswith(p) for p in SENSITIVE_PREFIXES):
        return True
    return False


def _mask_value(value: Any) -> str:
    """Mask a sensitive value for display."""
    if value is None:
        return "<not set>"
    s = str(value)
    if len(s) <= 8:
        return "********"
    return f"{s[:4]}****{s[-4:]}"


def _sanitize_dict(data: Dict[str, Any], prefix: str = "") -> Dict[str, Any]:
    """Recursively sanitize a dictionary, masking sensitive values."""
    result = {}
    for k, v in data.items():
        full_key = f"{prefix}.{k}" if prefix else k
        if _is_sensitive(full_key):
            result[k] = _mask_value(v)
        elif isinstance(v, dict):
            result[k] = _sanitize_dict(v, full_key)
        elif isinstance(v, (list, tuple)):
            result[k] = [
                _sanitize_dict(item, f"{full_key}[{i}]") if isinstance(item, dict)
                else _mask_value(item) if _is_sensitive(f"{full_key}[{i}]")
                else item
                for i, item in enumerate(v)
            ]
        else:
            result[k] = v
    return result


def _parse_db_url(url: str) -> Dict[str, Any]:
    """Parse a database URL into components, masking password."""
    try:
