import os
import json
from typing import Any, Dict, Set
from urllib.parse import urlparse


SENSITIVE_KEYS: Set[str] = {
    "password", "secret", "key", "token", "api_key", "apikey",
    "access_token", "refresh_token", "private_key", "cert",
    "dsn", "connection_string", "uri", "url"
}

SENSITIVE_PATTERNS = ("password", "secret", "key", "token", "auth")


def _is_sensitive(key: str) -> bool:
    key_lower = key.lower()
    return any(pattern in key_lower for pattern in SENSITIVE_PATTERNS)


def _mask_value(value: Any) -> Any:
    if isinstance(value, str) and value:
        return "***MASKED***"
    if isinstance(value, dict):
        return {k: _mask_value(v) for k, v in value.items()}
    if isinstance(value, (list, tuple)):
        return [_mask_value(v) for v in value]
    return value


def _sanitize_dict(data: Dict[str, Any], prefix: str = "") -> Dict[str, Any]:
    result = {}
    for k, v in data.items():
        full_key = f"{prefix}.{k}" if prefix else k
        if _is_sensitive(full_key):
            result[k] = _mask_value(v)
        elif isinstance(v, dict):
            result[k] = _sanitize_dict(v, full_key)
        else:
            result[k] = v
    return result


def _parse_database_url(url: str) -> Dict[str, Any]:
    try:
        parsed = urlparse(url)
        return {
            "scheme": parsed.scheme,
            "host": parsed.hostname,
            "port": parsed.port,
            "database": parsed.path.lstrip("/") if parsed.path else None,
            "username": parsed.username,
            "password": "***MASKED***" if parsed.password else None,
        }
    except Exception:
        return {"raw": "***MASKED***"}


def get_runtime_config() -> Dict[str, Any]:
    config = {
        "environment": _sanitize_dict(dict(os.environ)),
        "database": {},
        "third_party_apis": {},
    }

    db_url = os.getenv("DATABASE_URL") or os.getenv("DB_URL")
    if db_url:
        config["database"]["url_parsed"] = _parse_database_url(db_url)

    for key in ("DB_HOST", "DB_PORT", "DB_NAME", "DB_USER", "DB_SSL_MODE"):
        if val := os.getenv(key):
            config["database"][key.lower()] = val if not _is_sensitive(key) else "***MASKED***"

    api_prefixes = ("API_", "AWS_", "GOOGLE_", "AZURE_", "STRIPE_", "SENDGRID_", "TWILIO_")
    for key, val in os.environ.items():
        if key.startswith(api_prefixes):
            section = "third_party_apis"
            config[section][key] = "***MASKED***" if _is_sensitive(key) else val

    return config


def runtime_config_json() -> str:
    return json.dumps(get_runtime_config(), indent=2, default=str)
