```js
import express from 'express';
import mongoose from 'mongoose';

// ---------- Config with sensible defaults ----------
const config = {
  port: Number(process.env.PORT) || 3000,
  env: process.env.NODE_ENV || 'development',
  mongo: {
    uri: process.env.MONGODB_URI || 'mongodb://localhost:27017/health_app',
    maxPoolSize: Number(process.env.MONGO_MAX_POOL_SIZE) || 10,
    serverSelectionTimeoutMS: Number(process.env.MONGO_SERVER_SELECTION_TIMEOUT_MS) || 5000,
  },
};

// ---------- Structured logger (JSON, no extra deps) ----------
const logger = {
  info: (msg, meta = {}) => console.log(JSON.stringify({ level: 'info', time: new Date().toISOString(), msg, ...meta })),
  error: (msg, meta = {}) => console.error(JSON.stringify({ level: 'error', time: new Date().toISOString(), msg, ...meta })),
  warn: (msg, meta = {}) => console.warn(JSON.stringify({ level: 'warn', time: new Date().toISOString(), msg, ...meta })),
};

// ---------- MongoDB connection with retry/backoff ----------
async function connectWithRetry(uri, options, retries = 5, delayMs = 2000) {
  for (let attempt = 1; attempt <= retries; attempt++) {
    try {
      await mongoose.connect(uri, options);
      logger.info('MongoDB connected', { uri: maskUri(uri), ...options });
      return;
    } catch (err) {
      logger.warn(`MongoDB connection attempt ${attempt}/${retries} failed`, { error: err.message });
      if (attempt === retries) throw err;
      await new Promise(r => setTimeout(r, delayMs * attempt)); // exponential-ish backoff
    }
  }
}

function maskUri(uri) {
  // Hide credentials in logs
  return uri.replace(/\/\/([^:]+):([^@]+)@/, '//***:***@');
}

// ---------- Express app ----------
const app = express();
app.disable('x-powered-by');
app.use(express.json({ limit: '100kb' }));

// Request logging (dev-friendly)
if (config.env !== 'test') {
  app.use((req, res, next) => {
    const start = process.hrtime.bigint();
    res.on('finish', () => {
      const ms = Number(process.hrtime.bigint() - start) / 1e6;
      logger.info('HTTP', { method: req.method, path: req.path, status: res.statusCode, duration_ms: ms.toFixed(2) });
    });
    next();
  });
}

// ---------- Health endpoint (liveness + readiness) ----------
app.get('/health', async (req, res) => {
  const checks = {
    server: 'ok',
    database: mongoose.connection.readyState === 1 ? 'ok' : 'down',
  };
  const healthy = Object.values(checks).every(v => v === 'ok');
  res.status(healthy ? 200 : 503).json({
    status: healthy ? 'healthy' : 'degraded',
    timestamp: new Date().toISOString(),
    uptime_seconds: Math.floor(process.uptime()),
    checks,
    env: config.env,
  });
});

// ---------- 404 & error handlers ----------
app.use((req, res) => res.status(404).json({ error: 'Not Found' }));
app.use((err, req, res, next) => {
  logger.error('Unhandled error', { error: err.message, stack: err.stack });
  res.status(500).json({ error: 'Internal Server Error' });
});

// ---------- Graceful shutdown ----------
let server;
async function start() {
  try {
    await connectWithRetry(config.mongo.uri, {
      maxPoolSize: config.mongo.maxPoolSize,
      serverSelectionTimeoutMS: config.mongo.serverSelectionTimeoutMS,
      autoIndex: config.env !== 'production', // dev convenience
    });

    server = app.listen(config.port, () => {
      logger.info('Server started', {
        port: config.port,
        env: config.env,
        pid: process.pid,
        node: process.version,
        mongo: maskUri(config.mongo.uri),
      });
    });
  } catch (err) {
    logger.error('Failed to start', { error: err.message });
    process.exit(1);
  }
}

async function shutdown(signal) {
  logger.info(`${signal} received, shutting down gracefully`);
  if (server) {
    await new Promise((resolve, reject) => {
      server.close(err => (err ? reject(err) : resolve()));
    });
    logger.info('HTTP server closed');
  }
  await mongoose.connection.close(false);
  logger.info('MongoDB connection closed');
  process.exit(0);
}

process.on('SIGTERM', () => shutdown('SIGTERM'));
process.on('SIGINT', () => shutdown('SIGINT'));
process.on('unhandledRejection', (reason) => {
  logger.error('Unhandled rejection', { reason: String(reason) });
  shutdown('unhandledRejection');
});
process.on('uncaughtException', (err) => {
  logger.error('Uncaught exception', { error: err.message, stack: err.stack });
  shutdown('uncaughtException');
});

start();
