### 2. The Entry Point (`src/index.js`)

```javascript
// src/index.js
import express from 'express';
import mongoose from 'mongoose';
import pino from 'pino';
import { fileURLToPath } from 'url';
import { dirname, join } from 'path';
import { config } from 'dotenv';

// --- 1. Bootstrap & Configuration ---
// Load .env file (non-fatal if missing)
config();

// Resolve __dirname for ES Modules
const __filename = fileURLToPath(import.meta.url);
const __dirname = dirname(__filename);

// Sensible Defaults via Environment Variables
const CFG = {
  port: Number(process.env.PORT) || 3000,
  mongoUri: process.env.MONGODB_URI || 'mongodb://localhost:27017/dev_db',
  // Allow disabling pretty logs in CI/Prod
  logPretty: process.env.NODE_ENV !== 'production',
  // Mongoose options
  mongoose: {
    maxPoolSize: 10,
    serverSelectionTimeoutMS: 5000, // Fail fast if DB down
    socketTimeoutMS: 45000,
  },
};

// --- 2. Logger Setup ---
// Pino is extremely fast; pino-pretty makes it human-readable locally
const logger = pino({
  level: process.env.LOG_LEVEL || 'info',
  transport: CFG.logPretty
    ? { target: 'pino-pretty', options: { colorize: true, translateTime: 'SYS:standard', ignore: 'pid,hostname' } }
    : undefined,
  base: { service: 'health-api' }, // Base fields on every log line
});

// --- 3. Express App Setup ---
const app = express();
app.use(express.json());

// Request logging middleware (tiny footprint)
app.use((req, res, next) => {
  const start = Date.now();
  res.on('finish', () => {
    logger.info({ req: { method: req.method, url: req.url }, res: { statusCode: res.statusCode }, latencyMs: Date.now() - start }, 'request completed');
  });
  next();
});

// --- 4. Routes ---
/**
 * @route GET /health
 * @description Liveness/Readiness probe.
 * Returns 200 if process is up AND MongoDB connection is 'open'.
 * Returns 503 if DB is disconnected.
 */
app.get('/health', (req, res) => {
  const dbState = mongoose.connection.readyState; // 0=disconnected, 1=connected, 2=connecting, 3=disconnecting
  const isHealthy = dbState === 1;

  const payload = {
    status: isHealthy ? 'ok' : 'degraded',
    timestamp: new Date().toISOString(),
    uptime: process.uptime(),
    memory: process.memoryUsage(),
    checks: {
      database: {
        status: isHealthy ? 'up' : 'down',
        state: ['disconnected', 'connected', 'connecting', 'disconnecting'][dbState],
        host: mongoose.connection.host,
        name: mongoose.connection.name,
      },
    },
  };

  res.status(isHealthy ? 200 : 503).json(payload);
});

// Simple root route for browser verification
app.get('/', (req, res) => {
  res.json({ message: 'Service running. See /health for status.' });
});

// 404 Handler
app.use((req, res) => res.status(404).json({ error: 'Not Found' }));

// Global Error Handler
app.use((err, req, res, next) => {
  logger.error({ err }, 'Unhandled error');
  res.status(500).json({ error: 'Internal Server Error' });
});

// --- 5. Database Connection Logic ---
async function connectDB() {
  logger.info({ uri: maskMongoUri(CFG.mongoUri) }, 'Attempting MongoDB connection...');

  try {
    await mongoose.connect(CFG.mongoUri, CFG.mongoose);
    // Connection events for observability
    mongoose.connection.on('connected', () => logger.info({ host: mongoose.connection.host }, 'MongoDB connected'));
    mongoose.connection.on('error', (err) => logger.error({ err }, 'MongoDB connection error'));
    mongoose.connection.on('disconnected', () => logger.warn('MongoDB disconnected'));

    return true;
  } catch (err) {
    logger.fatal({ err, uri: maskMongoUri(CFG.mongoUri) }, 'Failed initial MongoDB connection');
    throw err;
  }
}

// Helper: Mask password in URI for logs
function maskMongoUri(uri) {
  return uri.replace(/:([^:@]+)@/, ':****@');
}

// --- 6. Graceful Shutdown ---
let server;
const shutdown = (signal) => {
  logger.warn({ signal }, 'Shutdown signal received. Closing HTTP server...');
  server.close(async () => {
    logger.info('HTTP server closed. Closing MongoDB connection...');
    await mongoose.connection.close(false); // false = force close, don't wait for ops
    logger.info('MongoDB connection closed. Exiting process.');
    process.exit(0);
  });

  // Force exit if graceful shutdown takes too long
  setTimeout(() => {
    logger.error('Forced shutdown timeout reached.');
    process.exit(1);
  }, 10_000).unref(); // .unref() prevents timer from keeping process alive
};

process.on('SIGTERM', () => shutdown('SIGTERM'));
process.on('SIGINT', () => shutdown('SIGINT'));

// --- 7. Main Entrypoint ---
async function main() {
  try {
    await connectDB();

    server = app.listen(CFG.port, () => {
      const lines = [
        '╔═══════════════════════════════════════════════════╗',
        `║  Service Started Successfully                     ║`,
        `║  Environment: ${process.env.NODE_ENV || 'development'.padEnd(17)} ║`,
        `║  Port: ${String(CFG.port).padEnd(46)} ║`,
        `║  MongoDB: ${maskMongoUri(CFG.mongoUri).padEnd(41)} ║`,
        `║  Health Check: http://localhost:${CFG.port}/health`.padEnd(51) + '║',
        '╚═══════════════════════════════════════════════════╝',
      ];
      // Use logger.info for structured logs, console.log for the pretty box
      console.log(lines.join('\n')); 
    });

    server.on('error', (err) => {
      if (err.code === 'EADDRINUSE') {
        logger.fatal({ port: CFG.port }, 'Port already in use');
      } else {
        logger.fatal({ err }, 'Server error');
      }
      process.exit(1);
    });

  } catch (err) {
    logger.fatal({ err }, 'Failed to start application');
    process.exit(1);
  }
}

main();
```

