### 3. `src/index.js` (The Entry Point)
```javascript
import express from 'express';
import mongoose from 'mongoose';
import 'dotenv/config';

// ---------------------------------------------------------
// Configuration with Sensible Defaults
// ---------------------------------------------------------
const PORT = Number(process.env.PORT) || 3000;
const NODE_ENV = process.env.NODE_ENV || 'development';

// Build MongoDB URI: Priority 1: Full URI, Priority 2: Discrete parts
function buildMongoUri() {
  if (process.env.MONGODB_URI) {
    return process.env.MONGODB_URI;
  }

  const host = process.env.MONGODB_HOST || 'localhost';
  const port = process.env.MONGODB_PORT || '27017';
  const db = process.env.MONGODB_DATABASE || 'test';
  const user = process.env.MONGODB_USERNAME;
  const pass = process.env.MONGODB_PASSWORD;
  const authSource = process.env.MONGODB_AUTH_SOURCE || 'admin';

  let uri = `mongodb://`;
  if (user && pass) {
    uri += `${encodeURIComponent(user)}:${encodeURIComponent(pass)}@`;
  }
  uri += `${host}:${port}/${db}?authSource=${authSource}`;

  return uri;
}

const MONGODB_URI = buildMongoUri();

// Helper to log connection info safely (redacts credentials)
function getSafeConnectionInfo(uri) {
  try {
    // Remove credentials from mongodb://user:pass@host:port/db
    const sanitized = uri.replace(/\/\/([^:]+):([^@]+)@/, '//****:****@');
    const url = new URL(sanitized);
    return {
      host: url.hostname,
      port: url.port || '27017 (default)',
      database: url.pathname.replace('/', '') || 'unknown',
      authSource: url.searchParams.get('authSource') || 'admin'
    };
  } catch (e) {
    return { raw: 'Invalid URI format' };
  }
}

// ---------------------------------------------------------
// App & Middleware
// ---------------------------------------------------------
const app = express();
app.disable('x-powered-by'); // Security hygiene

// JSON body parser (built-in since Express 4.16)
app.use(express.json());

// Request logging (tiny, dependency-free)
app.use((req, res, next) => {
  const start = Date.now();
  res.on('finish', () => {
    const duration = Date.now() - start;
    // Only log non-health checks in dev to reduce noise, or log all in prod
    if (NODE_ENV === 'development' || req.path !== '/health') {
      console.log(`[${new Date().toISOString()}] ${req.method} ${req.path} ${res.statusCode} ${duration}ms`);
    }
  });
  next();
});

// ---------------------------------------------------------
// Routes
// ---------------------------------------------------------

// Liveness Probe (Infrastructure health - process is up)
app.get('/health/live', (req, res) => {
  res.status(200).json({ status: 'alive', timestamp: new Date().toISOString() });
});

// Readiness Probe (Application health - DB connected)
app.get('/health/ready', (req, res) => {
  const state = mongoose.connection.readyState; // 1 = connected
  if (state === 1) {
    return res.status(200).json({ 
      status: 'ready', 
      database: 'connected',
      timestamp: new Date().toISOString() 
    });
  }

  // 0 = disconnected, 2 = connecting, 3 = disconnecting
  const states = ['disconnected', 'connected', 'connecting', 'disconnecting'];
  return res.status(503).json({ 
    status: 'not ready', 
    database: states[state] || 'unknown',
    timestamp: new Date().toISOString() 
  });
});

// Legacy / Combined Health (often required by older load balancers)
app.get('/health', (req, res) => {
  const dbState = mongoose.connection.readyState === 1 ? 'connected' : 'disconnected';
  const httpStatus = dbState === 'connected' ? 200 : 503;

  res.status(httpStatus).json({
    status: dbState === 'connected' ? 'healthy' : 'degraded',
    checks: {
      database: dbState,
      uptime: process.uptime(),
      memory: process.memoryUsage(),
      env: NODE_ENV
    },
    timestamp: new Date().toISOString()
  });
});

// ---------------------------------------------------------
// Database Connection & Server Boot
// ---------------------------------------------------------
async function start() {
  // 1. Mongoose Setup
  mongoose.set('strictQuery', true); // Prepare for Mongoose 8 default

  // Connection Event Logging (Great for debugging replica sets/failover)
  mongoose.connection.on('connecting', () => console.log('🔄 [MongoDB] Connecting...'));
  mongoose.connection.on('connected', () => console.log('✅ [MongoDB] Connected'));
  mongoose.connection.on('disconnected', () => console.warn('⚠️ [MongoDB] Disconnected'));
  mongoose.connection.on('error', (err) => console.error('❌ [MongoDB] Error:', err.message));

  try {
    const safeInfo = getSafeConnectionInfo(MONGODB_URI);

    console.log('🚀 Starting Application...');
    console.log(`   Env:          ${NODE_ENV}`);
    console.log(`   Port:         ${PORT}`);
    console.log(`   Mongo Host:   ${safeInfo.host}`);
    console.log(`   Mongo Port:   ${safeInfo.port}`);
    console.log(`   Database:     ${safeInfo.database}`);
    console.log(`   Auth Source:  ${safeInfo.authSource}`);

    // Connect with modern options (Mongoose 8+ defaults are good, explicit for clarity)
    await mongoose.connect(MONGODB_URI, {
      serverSelectionTimeoutMS: 5000, // Fail fast if DB unavailable
      maxPoolSize: 10,                // Connection pool size
    });

    // 2. Start HTTP Server
    const server = app.listen(PORT, () => {
      console.log(`🌐 HTTP Server listening on http://localhost:${PORT}`);
      console.log(`   Health:       GET http://localhost:${PORT}/health`);
      console.log(`   Ready:        GET http://localhost:${PORT}/health/ready`);
      console.log(`   Live:         GET http://localhost:${PORT}/health/live`);
    });

    // 3. Graceful Shutdown Handling
    const shutdown = async (signal) => {
      console.log(`\n🛑 Received ${signal}. Shutting down gracefully...`);
      server.close(() => {
        console.log('🔌 HTTP Server closed.');
      });

      try {
        await mongoose.connection.close(false); // false = don't force close immediately
        console.log('🍃 MongoDB connection closed.');
        process.exit(0);
      } catch (err) {
        console.error('❌ Error during shutdown:', err);
        process.exit(1);
      }

      // Force exit if cleanup takes too long
      setTimeout(() => {
        console.error('⏰ Forced shutdown timeout.');
        process.exit(1);
      }, 10000).unref();
    };

    process.on('SIGTERM', () => shutdown('SIGTERM'));
    process.on('SIGINT', () => shutdown('SIGINT'));

  } catch (err) {
    console.error('💥 Failed to start application:', err.message);
    // Log specific MongoDB auth errors nicely
    if (err.name === 'MongoServerSelectionError') {
      console.error('   -> Could not reach MongoDB. Check host/port/firewall.');
    } else if (err.name === 'MongoAuthenticationError') {
      console.error('   -> Authentication failed. Check username/password/authSource.');
    }
    process.exit(1);
  }
}

start();
```

