### Key Features Included
| Feature | Implementation |
| :--- | :--- |
| **Sensible Defaults** | Falls back to `localhost:27017`, port `3000`, `NODE_ENV=development`. |
| **Flexible Config** | Accepts full `MONGODB_URI` **OR** discrete `HOST/PORT/DB/USER/PASS` vars. |
| **Secure Logging** | `getSafeConnectionInfo` redacts passwords in startup logs. |
| **K8s Ready Probes** | `/health/live` (liveness), `/health/ready` (readiness), `/health` (legacy). |
| **Graceful Shutdown** | Handles `SIGTERM`/`SIGINT`, closes HTTP server & Mongo pool before exit. |
| **Connection Resilience** | `serverSelectionTimeoutMS: 5000` prevents hanging indefinitely on bad URI. |
| **Structured Logs** | ISO timestamps, emoji prefixes for visual scanning, request duration logging. |

```javascript
// src/index.js
require('dotenv').config();
const express = require('express');
const { MongoClient } = require('mongodb');

const app = express();
const PORT = process.env.PORT || 3000;
const MONGODB_URI = process.env.MONGODB_URI || 'mongodb://localhost:27017';
const DB_NAME = process.env.DB_NAME || 'app';

let db;

async function connectToMongo() {
  const client = new MongoClient(MONGODB_URI, {
    serverSelectionTimeoutMS: 5000,
  });

  await client.connect();
  db = client.db(DB_NAME);

  // Verify connection with a ping
  await db.admin().ping();

  console.log(`✅ Connected to MongoDB`);
  console.log(`   URI: ${MONGODB_URI.replace(/\/\/([^:]+):([^@]+)@/, '//***:***@')}`);
  console.log(`   Database: ${DB_NAME}`);

  return client;
}

app.get('/health', async (req, res) => {
  try {
    await db.admin().ping();
    res.json({ 
      status: 'ok', 
      mongodb: 'connected',
      database: DB_NAME,
      timestamp: new Date().toISOString()
    });
  } catch (err) {
    res.status(503).json({ 
      status: 'degraded', 
      mongodb: 'disconnected',
      error: err.message,
      timestamp: new Date().toISOString()
    });
  }
});

async function start() {
  try {
    await connectToMongo();

    app.listen(PORT, () => {
      console.log(`🚀 Server running on http://localhost:${PORT}`);
      console.log(`   Health check: http://localhost:${PORT}/health`);
    });
  } catch (err) {
    console.error('❌ Failed to start:', err.message);
    process.exit(1);
  }
}

// Graceful shutdown
process.on('SIGINT', async () => {
  console.log('\n🛑 Shutting down...');
  process.exit(0);
});

start();
```

