### 3. `src/index.js` (The Entry Point)
```javascript
// src/index.js
import express from 'express';
import mongoose from 'mongoose';
import pino from 'pino';
import { fileURLToPath } from 'url';
import { dirname, resolve } from 'path';

// --- Configuration & Constants ---
const __filename = fileURLToPath(import.meta.url);
const __dirname = dirname(__filename);

// Sensible Defaults
const PORT = Number(process.env.PORT) || 3000;
const MONGO_URI = process.env.MONGODB_URI || 'mongodb://localhost:27017/myapp_dev';
const NODE_ENV = process.env.NODE_ENV || 'development';

// --- Logger Setup ---
// Pretty print in dev, JSON in prod (for log aggregators)
const logger = pino({
  level: NODE_ENV === 'production' ? 'info' : 'debug',
  transport: NODE_ENV !== 'production' 
    ? { target: 'pino-pretty', options: { colorize: true, translateTime: 'SYS:standard', ignore: 'pid,hostname' } } 
    : undefined,
  base: { service: 'express-mongo-health' }
});

// --- Express App ---
const app = express();
app.use(express.json());

// Request logging middleware (optional but recommended)
app.use((req, res, next) => {
  const start = Date.now();
  res.on('finish', () => {
    logger.info({ 
      method: req.method, 
      url: req.url, 
      status: res.statusCode, 
      durationMs: Date.now() - start 
    }, 'HTTP Request');
  });
  next();
});

// --- Routes ---
app.get('/health', (req, res) => {
  // Check DB connection state: 0=disconnected, 1=connected, 2=connecting, 3=disconnecting
  const dbState = mongoose.connection.readyState;
  const isHealthy = dbState === 1;

  const payload = {
    status: isHealthy ? 'ok' : 'degraded',
    timestamp: new Date().toISOString(),
    uptime: process.uptime(),
    environment: NODE_ENV,
    database: {
      state: ['disconnected', 'connected', 'connecting', 'disconnecting'][dbState],
      host: mongoose.connection.host || 'unknown',
      name: mongoose.connection.name || 'unknown'
    }
  };

  // Kubernetes/Load Balancers expect 200 for OK, 503 for not ready
  res.status(isHealthy ? 200 : 503).json(payload);
});

// Example API route to verify DB writes work
app.get('/api/ping', async (req, res) => {
  try {
    // Lightweight command to verify primary connectivity
    await mongoose.connection.db.admin().ping();
    res.json({ message: 'pong', db: 'reachable' });
  } catch (err) {
    logger.error(err, 'DB Ping failed');
    res.status(500).json({ message: 'pong', db: 'unreachable', error: err.message });
  }
});

// 404 Handler
app.use((req, res) => res.status(404).json({ error: 'Not Found' }));

// Global Error Handler
app.use((err, req, res, next) => {
  logger.error(err, 'Unhandled Error');
  res.status(500).json({ error: 'Internal Server Error' });
});

// --- MongoDB Connection Logic ---
async function connectMongo() {
  // Mongoose 8+ defaults: strictQuery: false, bufferCommands: false (good for serverless)
  mongoose.set('strictQuery', false);

  // Connection Event Listeners (Great for debugging startup/issues)
  mongoose.connection.on('connecting', () => logger.info('MongoDB: Connecting...'));
  mongoose.connection.on('connected', () => logger.info({ host: mongoose.connection.host, name: mongoose.connection.name }, 'MongoDB: Connected'));
  mongoose.connection.on('disconnected', () => logger.warn('MongoDB: Disconnected'));
  mongoose.connection.on('reconnected', () => logger.info('MongoDB: Reconnected'));
  mongoose.connection.on('error', (err) => logger.error(err, 'MongoDB: Connection Error'));

  try {
    // `serverSelectionTimeoutMS`: Fail fast if DB isn't reachable (default 30s)
    // `maxPoolSize`: Limit connections (default 100)
    await mongoose.connect(MONGO_URI, {
      serverSelectionTimeoutMS: 5000,
      maxPoolSize: 10,
      // autoIndex: NODE_ENV !== 'production', // Build indexes on startup in dev
    });
  } catch (err) {
    logger.fatal(err, 'MongoDB: Initial connection failed. Exiting.');
    process.exit(1);
  }
}

// --- Graceful Shutdown ---
async function shutdown(signal) {
  logger.info({ signal }, 'Shutdown signal received. Closing connections...');

  // Stop accepting new requests immediately
  server.close(() => {
    logger.info('HTTP Server closed.');
  });

  // Force close after 10s timeout
  const forceClose = setTimeout(() => {
    logger.error('Forced shutdown timeout reached.');
    process.exit(1);
  }, 10000);
  forceClose.unref(); // Don't keep process alive just for this timer

  try {
    await mongoose.connection.close(false); // false = don't force close immediately, let ops finish
    logger.info('MongoDB connection closed.');
    clearTimeout(forceClose);
    process.exit(0);
  } catch (err) {
    logger.error(err, 'Error during MongoDB disconnect');
    clearTimeout(forceClose);
    process.exit(1);
  }
}

process.on('SIGTERM', () => shutdown('SIGTERM'));
process.on('SIGINT', () => shutdown('SIGINT'));

// --- Bootstrap ---
let server;

async function main() {
  logger.info({ nodeVersion: process.version, pid: process.pid, cwd: process.cwd() }, 'Starting Application');

  // 1. Connect DB
  await connectMongo();

  // 2. Start HTTP Server
  server = app.listen(PORT, () => {
    logger.info({ 
      port: PORT, 
      env: NODE_ENV,
      mongoUri: MONGO_URI.replace(/:\/\/([^:]+):([^@]+)@/, '://***:***@'), // Mask credentials in logs
      healthEndpoint: `http://localhost:${PORT}/health`
    }, 'Server Ready');
  });
}

main().catch((err) => {
  logger.fatal(err, 'Failed to start application');
  process.exit(1);
});
```

