### Key Features Included
1.  **Masked Credentials**: Logs `mongodb://***:***@host/db` so you can share logs safely.
2.  **Structured Logging**: Pino outputs JSON in prod (Datadog/Splunk ready) and pretty colors in dev.
3.  **Graceful Shutdown**: Handles `SIGTERM`/`SIGINT` (Kubernetes/Docker stop), drains HTTP server, closes Mongo pool.
4.  **Connection Resilience**: Mongoose handles auto-reconnection; event listeners log every state change.
5.  **Fast Failure**: `serverSelectionTimeoutMS: 5000` prevents the app hanging 30s on startup if DB is down.
6.  **Kubernetes Ready**: `/health` returns **503** if DB disconnected (so K8s `readinessProbe` kills pod) and **200** if connected.

Here is a complete, production-ready `index.js` entry point. It uses **native Node.js modules only** (no external config libraries like `dotenv` required—though it supports a `.env` file if present via `--env-file` flag in Node 20.6+), includes structured logging, graceful shutdown, and a comprehensive health check that verifies the DB connection.

### `index.js`

```javascript
// index.js
// Entry point for Express + MongoDB app
// Run locally: node --env-file=.env index.js (Node 20.6+)
// Or: node index.js (relies on shell env vars / defaults)

import express from 'express';
import { MongoClient, ServerApiVersion } from 'mongodb';

// ---------------------------------------------------------
// Configuration with Sensible Defaults
// ---------------------------------------------------------
const config = {
  port: Number(process.env.PORT) || 3000,
  mongo: {
    uri: process.env.MONGODB_URI || 'mongodb://localhost:27017',
    dbName: process.env.MONGODB_DB || 'dev_app',
    // Options to avoid deprecation warnings and ensure modern behavior
    options: {
      serverApi: {
        version: ServerApiVersion.v1,
        strict: true,
        deprecationErrors: true,
      },
      // Local dev often doesn't need TLS/Replica sets, but Atlas requires them.
      // The driver handles this automatically based on the URI scheme.
    },
  },
  // How long to wait for existing requests to finish on shutdown
  gracefulShutdownTimeout: 10000, 
};

// ---------------------------------------------------------
// Structured Logger (JSON friendly for prod, readable for dev)
// ---------------------------------------------------------
const logger = {
  info: (msg, meta = {}) => console.log(JSON.stringify({ level: 'info', time: new Date().toISOString(), msg, ...meta })),
  warn: (msg, meta = {}) => console.warn(JSON.stringify({ level: 'warn', time: new Date().toISOString(), msg, ...meta })),
  error: (msg, meta = {}) => console.error(JSON.stringify({ level: 'error', time: new Date().toISOString(), msg, ...meta })),
  // Helper for pretty startup logs
  startup: (msg, meta = {}) => console.log(`\x1b[36m[STARTUP]\x1b[0m ${msg}`, Object.keys(meta).length ? meta : ''),
};

// ---------------------------------------------------------
// MongoDB Connection Singleton
// ---------------------------------------------------------
let mongoClient = null;
let db = null;

async function connectToMongo() {
  if (mongoClient) return db; // Already connected

  const { uri, dbName, options } = config.mongo;

  logger.startup('Initiating MongoDB connection...', { uri: sanitizeUri(uri), dbName });

  try {
    mongoClient = new MongoClient(uri, options);
    // connect() establishes the connection pool
    await mongoClient.connect();

    // Explicitly ping to verify authentication/connectivity before marking "ready"
    await mongoClient.db(dbName).command({ ping: 1 });

    db = mongoClient.db(dbName);

    // Log topology details for debugging replica sets / sharding
    const topology = mongoClient.topology;
    const servers = topology ? topology.servers : [];
    const serverDescriptions = Array.from(servers.values()).map(s => ({
      address: s.description.address,
      type: s.description.type,
      state: s.description.state,
    }));

    logger.startup('MongoDB connected successfully', {
      database: dbName,
      servers: serverDescriptions,
    });

    // Handle unexpected disconnections
    mongoClient.on('close', () => logger.warn('MongoDB connection closed unexpectedly'));
    mongoClient.on('error', (err) => logger.error('MongoDB client error', { error: err.message }));

    return db;
  } catch (err) {
    logger.error('FATAL: Failed to connect to MongoDB', { error: err.message, stack: err.stack });
    throw err; // Crash the process if DB unavailable at startup
  }
}

function sanitizeUri(uri) {
  // Hide credentials in logs: mongodb://user:pass@host -> mongodb://user:***@host
  return uri.replace(/:([^:@]+)@/, ':***@');
}

// ---------------------------------------------------------
// Express App Setup
// ---------------------------------------------------------
const app = express();

// Basic middleware
app.use(express.json({ limit: '100kb' }));
app.disable('x-powered-by'); // Security hygiene

// Request logging (dev friendly)
app.use((req, res, next) => {
  const start = Date.now();
  res.on('finish', () => {
    const duration = Date.now() - start;
    // Only log non-health checks to reduce noise, or log all if DEBUG=true
    if (req.path !== '/health' || process.env.DEBUG) {
      logger.info('HTTP Request', {
        method: req.method,
        path: req.path,
        status: res.statusCode,
        durationMs: duration,
        ip: req.ip,
      });
    }
  });
  next();
});

// ---------------------------------------------------------
// Routes
// ---------------------------------------------------------

// 1. Liveness Probe (K8s/Orchestrator): Process is up
app.get('/health/live', (req, res) => {
  res.status(200).json({ status: 'alive', timestamp: new Date().toISOString() });
});

// 2. Readiness Probe: Process is up AND dependencies (DB) are reachable
app.get('/health', async (req, res) => {
  const checks = {
    database: 'unknown',
    timestamp: new Date().toISOString(),
  };
  let httpStatus = 200;

  try {
    if (!mongoClient || !mongoClient.topology || !mongoClient.topology.isConnected()) {
      checks.database = 'disconnected';
      httpStatus = 503;
    } else {
      // Lightweight ping (no auth overhead usually)
      await mongoClient.db(config.mongo.dbName).command({ ping: 1 });
      checks.database = 'connected';
    }
  } catch (err) {
    checks.database = 'error';
    checks.dbError = err.message;
    httpStatus = 503;
  }

  // Add version info if available (e.g. from package.json)
  if (process.env.APP_VERSION) checks.version = process.env.APP_VERSION;

  res.status(httpStatus).json({
    status: httpStatus === 200 ? 'ready' : 'degraded',
    checks,
  });
});

// Example API Route (Proof of life)
app.get('/api/ping', (req, res) => {
  res.json({ message: 'pong', db: config.mongo.dbName });
});

// 404 Handler
app.use((req, res) => {
  res.status(404).json({ error: 'Not Found', path: req.originalUrl });
});

// Global Error Handler
app.use((err, req, res, next) => {
  logger.error('Unhandled Request Error', { path: req.path, error: err.message, stack: err.stack });
  res.status(500).json({ error: 'Internal Server Error' });
});

// ---------------------------------------------------------
// Server Lifecycle
// ---------------------------------------------------------
let server = null;

async function start() {
  try {
    // 1. Connect DB
    await connectToMongo();

    // 2. Start HTTP Server
    server = app.listen(config.port, () => {
      logger.startup(`HTTP Server listening`, {
        port: config.port,
        env: process.env.NODE_ENV || 'development',
        pid: process.pid,
        nodeVersion: process.version,
      });
    });

    // Handle Server Errors (e.g. EADDRINUSE)
    server.on('error', (err) => {
      if (err.code === 'EADDRINUSE') {
        logger.error(`Port ${config.port} already in use.`, { error: err.message });
      } else {
        logger.error('Server error', { error: err.message });
      }
      process.exit(1);
    });

  } catch (err) {
    // connectToMongo throws on failure, caught here
    logger.error('Startup failed', { error: err.message });
    process.exit(1);
  }
}

// Graceful Shutdown
async function shutdown(signal) {
  logger.startup(`${signal} received. Starting graceful shutdown...`);

  const shutdownTimer = setTimeout(() => {
    logger.error('Graceful shutdown timed out. Forcing exit.');
    process.exit(1);
  }, config.gracefulShutdownTimeout);

  try {
    // 1. Stop accepting new connections
    if (server) {
      await new Promise((resolve, reject) => {
        server.close((err) => (err ? reject(err) : resolve()));
      });
      logger.startup('HTTP Server closed');
    }

    // 2. Close DB Connection Pool
    if (mongoClient) {
      await mongoClient.close(true); // force: true closes sockets immediately
      logger.startup('MongoDB connection pool closed');
    }

    clearTimeout(shutdownTimer);
    logger.startup('Graceful shutdown complete.');
    process.exit(0);
  } catch (err) {
    clearTimeout(shutdownTimer);
    logger.error('Error during shutdown', { error: err.message });
    process.exit(1);
  }
}

// Signal Handlers
process.on('SIGTERM', () => shutdown('SIGTERM'));
process.on('SIGINT', () => shutdown('SIGINT'));

// Uncaught Exception / Rejection Safety Net
process.on('uncaughtException', (err) => {
  logger.error('Uncaught Exception', { error: err.message, stack: err.stack });
  shutdown('uncaughtException'); // Attempt graceful shutdown even on crash
});

process.on('unhandledRejection', (reason) => {
  logger.error('Unhandled Rejection', { reason: String(reason) });
});

// ---------------------------------------------------------
// Bootstrap
// ---------------------------------------------------------
start();
```

