### Key Features Included
1.  **No `dotenv` dependency**: Uses Node `--env-file` flag (standard since v20.6).
2.  **Structured JSON Logging**: Easy to ingest into Datadog, CloudWatch, Loki, etc.
3.  **Sanitized URI Logging**: Passwords stripped from startup logs automatically.
4.  **Topology Logging**: Shows Replica Set/Standalone status and server addresses at startup.
5.  **Dual Health Endpoints**: `/health/live` (process alive) vs `/health` (dependencies ready) — Kubernetes best practice.
6.  **Graceful Shutdown**: Drains HTTP connections (`server.close`) and closes Mongo pool cleanly on `SIGTERM`/`SIGINT` (critical for zero-downtime deploys).
7.  **Strict Mongo Driver Config**: `ServerApiVersion.v1` + `strict: true` prevents deprecated API usage.

```javascript
// src/app.js
require('dotenv').config();
const express = require('express');
const mongoose = require('mongoose');

const app = express();
app.use(express.json());

// Config with sensible defaults
const config = {
  port: process.env.PORT || 3000,
  mongoUri: process.env.MONGODB_URI || 'mongodb://localhost:27017/myapp',
  nodeEnv: process.env.NODE_ENV || 'development'
};

// Health check endpoint
app.get('/health', (req, res) => {
  const dbState = mongoose.connection.readyState;
  const states = ['disconnected', 'connected', 'connecting', 'disconnecting'];
  res.json({
    status: 'ok',
    timestamp: new Date().toISOString(),
    uptime: process.uptime(),
    database: states[dbState] || 'unknown',
    environment: config.nodeEnv
  });
});

// Connect to MongoDB with clear logging
async function connectDB() {
  mongoose.set('strictQuery', true);

  try {
    await mongoose.connect(config.mongoUri);
    console.log(`📦 MongoDB connected: ${maskUri(config.mongoUri)}`);
  } catch (err) {
    console.error('❌ MongoDB connection failed:', err.message);
    process.exit(1);
  }
}

// Mask credentials in URI for logging
function maskUri(uri) {
  return uri.replace(/\/\/([^:]+):([^@]+)@/, '//***:***@');
}

// Start server
async function start() {
  await connectDB();

  app.listen(config.port, () => {
    console.log(`🚀 Server running on http://localhost:${config.port}`);
    console.log(`🌍 Environment: ${config.nodeEnv}`);
    console.log(`🏥 Health check: http://localhost:${config.port}/health`);
  });
}

// Graceful shutdown
process.on('SIGTERM', async () => {
  console.log('🛑 SIGTERM received, shutting down...');
  await mongoose.connection.close();
  process.exit(0);
});

start();

module.exports = app;
