// server.js
require('dotenv').config();
const express = require('express');
const { MongoClient } = require('mongodb');

const {
  PORT = 3000,
  MONGODB_URI = 'mongodb://localhost:27017',
  MONGODB_DB = 'app',
  NODE_ENV = 'development'
} = process.env;

const app = express();
app.use(express.json());

let db;
let client;

async function connectMongo() {
  client = new MongoClient(MONGODB_URI, {
    serverSelectionTimeoutMS: 5000,
    maxPoolSize: 10
  });

  await client.connect();
  db = client.db(MONGODB_DB);

  // Verify connection
  await db.command({ ping: 1 });

  const host = new URL(MONGODB_URI).host;
  console.log(`[startup] MongoDB connected: ${host}/${MONGODB_DB}`);
  console.log(`[startup] Environment: ${NODE_ENV}`);
}

app.get('/health', async (req, res) => {
  try {
    await db.command({ ping: 1 });
    res.json({
      status: 'ok',
      mongodb: 'connected',
      database: MONGODB_DB,
      timestamp: new Date().toISOString()
    });
  } catch (err) {
    res.status(503).json({
      status: 'degraded',
      mongodb: 'disconnected',
      error: err.message,
      timestamp: new Date().toISOString()
    });
  }
});

async function start() {
  try {
    await connectMongo();

    const server = app.listen(PORT, () => {
      console.log(`[startup] HTTP server listening on http://localhost:${PORT}`);
      console.log(`[startup] Health check: http://localhost:${PORT}/health`);
    });

    // Graceful shutdown
    const shutdown = async (signal) => {
      console.log(`\n[shutdown] Received ${signal}, closing...`);
      server.close(async () => {
        await client?.close();
        console.log('[shutdown] Connections closed');
        process.exit(0);
      });

      // Force exit after 10s
      setTimeout(() => {
        console.error('[shutdown] Forced exit');
        process.exit(1);
      }, 10000);
    };

    process.on('SIGTERM', () => shutdown('SIGTERM'));
    process.on('SIGINT', () => shutdown('SIGINT'));

  } catch (err) {
    console.error('[startup] Failed to start:', err.message);
    process.exit(1);
  }
}

start();
