const express = require('express');
const { MongoClient } = require('mongodb');

const app = express();
const PORT = process.env.PORT || 3000;
const MONGODB_URI = process.env.MONGODB_URI || 'mongodb://localhost:27017';
const DB_NAME = process.env.DB_NAME || 'app';

let db;

async function connectToMongo() {
  const client = new MongoClient(MONGODB_URI);
  await client.connect();
  db = client.db(DB_NAME);

  // Log connection details (mask credentials if present)
  const sanitizedUri = MONGODB_URI.replace(/\/\/([^:]+):([^@]+)@/, '//***:***@');
  console.log(`[startup] Connected to MongoDB: ${sanitizedUri}`);
  console.log(`[startup] Using database: ${DB_NAME}`);

  // Verify connection with a ping
  await db.command({ ping: 1 });
  console.log('[startup] MongoDB ping successful');

  return client;
}

app.get('/health', async (req, res) => {
  try {
    if (!db) {
      return res.status(503).json({ status: 'down', reason: 'database not connected' });
    }
    await db.command({ ping: 1 });
    res.json({ status: 'ok', database: 'connected' });
  } catch (err) {
    res.status(503).json({ status: 'down', reason: err.message });
  }
});

async function start() {
  try {
    const client = await connectToMongo();

    const server = app.listen(PORT, () => {
      console.log(`[startup] Server listening on http://localhost:${PORT}`);
      console.log(`[startup] Health endpoint: http://localhost:${PORT}/health`);
    });

    // Graceful shutdown
    const shutdown = async (signal) => {
      console.log(`[shutdown] Received ${signal}, closing...`);
      server.close(async () => {
        await client.close();
        console.log('[shutdown] MongoDB connection closed');
        process.exit(0);
      });

      // Force exit after 10s
      setTimeout(() => {
        console.error('[shutdown] Forced exit after timeout');
        process.exit(1);
      }, 10000);
    };

    process.on('SIGTERM', () => shutdown('SIGTERM'));
    process.on('SIGINT', () => shutdown('SIGINT'));

  } catch (err) {
    console.error('[startup] Failed to start:', err);
    process.exit(1);
  }
}

start();

