    process.on('SIGINT', () => shutdown('SIGINT'));

    return server;
  } catch (err) {
    console.error('[Startup] Failed:', err.message);
    process.exit(1);
  }
}

// Only start if run directly (not imported)
if (require.main === module) {
  start();
}

module.exports = { app, start };
