// src/index.js
require('dotenv').config();

const express = require('express');
const mongoose = require('mongoose');

const {
  PORT = 3000,
  MONGODB_URI = 'mongodb://localhost:27017/dev',
  NODE_ENV = 'development'
} = process.env;

const app = express();
app.use(express.json());

// Health check endpoint
app.get('/health', async (req, res) => {
  const dbState = mongoose.connection.readyState;
  const states = ['disconnected', 'connected', 'connecting', 'disconnecting'];

  res.json({
    status: 'ok',
    timestamp: new Date().toISOString(),
    environment: NODE_ENV,
    mongodb: {
      state: states[dbState] || 'unknown',
      host: mongoose.connection.host || 'n/a',
      name: mongoose.connection.name || 'n/a'
    }
  });
});

// 404 handler
app.use((req, res) => {
  res.status(404).json({ error: 'Not found' });
});

// Error handler
app.use((err, req, res, next) => {
  console.error('Unhandled error:', err);
  res.status(500).json({ error: 'Internal server error' });
});

async function connectMongo() {
  mongoose.set('strictQuery', true);

  await mongoose.connect(MONGODB_URI, {
    maxPoolSize: 10,
    serverSelectionTimeoutMS: 5000,
    socketTimeoutMS: 45000
  });

  console.log(`[mongodb] connected to ${mongoose.connection.host}:${mongoose.connection.port}/${mongoose.connection.name}`);
}

async function start() {
  try {
    await connectMongo();

    const server = app.listen(PORT, () => {
      console.log(`[server] listening on http://localhost:${PORT}`);
      console.log(`[env] NODE_ENV=${NODE_ENV}`);
      console.log(`[health] GET http://localhost:${PORT}/health`);
    });

    // Graceful shutdown
    const shutdown = async (signal) => {
      console.log(`\n[shutdown] ${signal} received, closing...`);
      server.close(async () => {
        await mongoose.connection.close(false);
        console.log('[shutdown] connections closed');
        process.exit(0);
      });

      // Force exit after 10s
      setTimeout(() => {
        console.error('[shutdown] forced exit');
        process.exit(1);
      }, 10000);
    };

    process.on('SIGTERM', () => shutdown('SIGTERM'));
    process.on('SIGINT', () => shutdown('SIGINT'));

  } catch (err) {
    console.error('[startup] failed:', err.message);
    process.exit(1);
  }
}

start();
