// server.js - Express app entry point with MongoDB connection
require('dotenv').config();
const express = require('express');
const { MongoClient } = require('mongodb');

const app = express();
const PORT = process.env.PORT || 3000;
const MONGODB_URI = process.env.MONGODB_URI || 'mongodb://localhost:27017';
const DB_NAME = process.env.DB_NAME || 'community_center';

let db;
let client;

// Health check endpoint
app.get('/health', async (req, res) => {
  const dbStatus = db ? 'connected' : 'disconnected';
  const details = {
    status: 'ok',
    database: dbStatus,
    timestamp: new Date().toISOString()
  };

  // Verify DB is actually responsive
  if (db) {
    try {
      await db.command({ ping: 1 });
      details.database = 'healthy';
    } catch (err) {
      details.database = 'unhealthy';
      details.error = err.message;
      return res.status(503).json(details);
    }
  } else {
    return res.status(503).json(details);
  }

  res.json(details);
});

// Connect to MongoDB
async function connectToMongo() {
  try {
    client = new MongoClient(MONGODB_URI, {
      serverSelectionTimeoutMS: 5000,
      maxPoolSize: 10
    });

    await client.connect();
    db = client.db(DB_NAME);

    // Verify connection
    await db.command({ ping: 1 });

    console.log('✓ MongoDB connected');
    console.log(`  URI: ${MONGODB_URI.replace(/\/\/.*:.*@/, '//***:***@')}`);
    console.log(`  Database: ${DB_NAME}`);
    console.log(`  Collections: ${(await db.listCollections().toArray()).map(c => c.name).join(', ') || 'none'}`);
  } catch (err) {
    console.error('✗ MongoDB connection failed:', err.message);
    process.exit(1);
  }
}

// Graceful shutdown
async function shutdown() {
  console.log('\nShutting down...');
  if (client) {
    await client.close();
    console.log('✓ MongoDB connection closed');
  }
  process.exit(0);
}

process.on('SIGTERM', shutdown);
process.on('SIGINT', shutdown);

// Start server
async function start() {
  await connectToMongo();

  app.listen(PORT, () => {
    console.log(`✓ Server running on http://localhost:${PORT}`);
    console.log(`  Health check: http://localhost:${PORT}/health`);
  });
}

start();
