// server.js
// Minimal Express + MongoDB starter with a /health endpoint.
// Run locally:  npm install express mongoose && node server.js
//   (expects a MongoDB instance at mongodb://localhost:27017 by default)

require('dotenv').config();               // load .env if present
const express = require('express');
const mongoose = require('mongoose');

// ---------- Configuration ----------
const PORT = process.env.PORT || 3000;
const MONGODB_URI = process.env.MONGODB_URI || 'mongodb://localhost:27017/devdb';

// ---------- Express app ----------
const app = express();
app.use(express.json());

// ---------- Health check ----------
app.get('/health', (req, res) => {
  // Simple liveness probe – could be expanded to check DB connectivity
  res.json({ status: 'ok', uptime: process.uptime() });
});

// ---------- MongoDB connection ----------
mongoose.set('strictQuery', true); // avoid deprecation warning

async function connectDB() {
  try {
    await mongoose.connect(MONGODB_URI, {
      // Options are mostly defaults in Mongoose 7+, but kept for clarity
      autoIndex: true,
    });
    console.log(`✅ Connected to MongoDB at ${MONGODB_URI}`);
  } catch (err) {
    console.error('❌ MongoDB connection error:', err);
    process.exit(1); // fail fast on startup
  }
}

// ---------- Start server ----------
async function start() {
  await connectDB();

  app.listen(PORT, () => {
    console.log(`🚀 Server listening on http://localhost:${PORT}`);
    console.log(`🩺 Health endpoint: http://localhost:${PORT}/health`);
  });
}

start();

// Graceful shutdown
process.on('SIGINT', async () => {
  console.log('\n🛑 Shutting down...');
  await mongoose.connection.close();
  process.exit(0);
});
