import json
import dataclasses
from datetime import date, datetime
from typing import Any

def _encode(obj: Any) -> Any:
    if dataclasses.is_dataclass(obj):
        return {"__dataclass__": True, "type": type(obj).__name__, "data": dataclasses.asdict(obj)}
    if isinstance(obj, (datetime, date)):
        return {"__date__": True, "value": obj.isoformat()}
    if isinstance(obj, dict):
        return {k: _encode(v) for k, v in obj.items()}
    if isinstance(obj, (list, tuple, set)):
        return [_encode(v) for v in obj]
    return obj

def _decode(obj: Any) -> Any:
    if isinstance(obj, dict):
        if obj.get("__dataclass__"):
            # Assumes the dataclass is available in globals or can be imported
            cls_name = obj["type"]
            cls = globals().get(cls_name)
            if cls and dataclasses.is_dataclass(cls):
                data = {k: _decode(v) for k, v in obj["data"].items()}
                return cls(**data)
        if obj.get("__date__"):
            val = obj["value"]
            try:
                return datetime.fromisoformat(val)
            except ValueError:
                return date.fromisoformat(val)
        return {k: _decode(v) for k, v in obj.items()}
    if isinstance(obj, list):
        return [_decode(v) for v in obj]
    return obj

def save_user_settings(obj: Any) -> bytes:
    encoded = _encode(obj)
    return json.dumps(encoded, separators=(",", ":")).encode("utf-8")

def load_user_settings(blob: bytes) -> Any:
    decoded = json.loads(blob.decode("utf-8"))
    return _decode(decoded)

Here is a secure, compact implementation using **JSON** (standard for cookies) with **Base64 URL-safe encoding** (cookie transport safety) and a **custom type registry** (extensible for dataclasses/dates).

It avoids `pickle` (RCE risk) and handles the 4KB cookie size limit via `separators=(',', ':')`.

```python
import json
import base64
import datetime
from dataclasses import dataclass, fields, is_dataclass, asdict
from typing import Any, Dict, Type, get_type_hints, Optional, List, Union

# ---------------------------------------------------------
# 1. Domain Model (Example Preference Dataclass)
# ---------------------------------------------------------
@dataclass
class Preference:
    """Example custom dataclass. In real code, this lives in your domain layer."""
    key: str
    value: Any
    scope: str = "user"  # e.g., "user", "org", "global"
    metadata: Optional[Dict[str, Any]] = None

    # Helper to identify type during decoding
    __type_tag__ = "Preference"

# ---------------------------------------------------------
# 2. Type Registry & Codec Logic
# ---------------------------------------------------------
class SettingsCodec:
    """
    Handles serialization/deserialization of supported types.
    Extend `encoders`/`decoders` to support more types (Decimal, UUID, custom classes).
    """

    # Tag prefix used in JSON to identify custom types: {"__type": "Preference", "data": {...}}
    TYPE_FIELD = "__type"
    DATA_FIELD = "data"

    def __init__(self):
        # Map Python Type -> Tag String
        self._type_to_tag: Dict[Type, str] = {
            datetime.datetime: "datetime",
            datetime.date: "date",
            Preference: Preference.__type_tag__,
        }
        # Map Tag String -> Python Type
        self._tag_to_type: Dict[str, Type] = {v: k for k, v in self._type_to_tag.items()}

        # Custom serialization logic for complex types
        self._custom_encoders: Dict[Type, callable] = {
            Preference: self._encode_dataclass,
        }
        self._custom_decoders: Dict[str, callable] = {
            Preference.__type_tag__: self._decode_preference,
        }

    # --- Public API ---
    def encode(self, obj: Any) -> Any:
        """Recursively walk object and replace custom types with tagged dicts."""
        if isinstance(obj, dict):
            return {k: self.encode(v) for k, v in obj.items()}
        if isinstance(obj, (list, tuple, set)):
            return [self.encode(v) for v in obj]

        # Check custom encoders first (handles dataclasses)
        for typ, encoder in self._custom_encoders.items():
            if isinstance(obj, typ):
                return encoder(obj)

        # Check standard type tags (datetime, date)
        for typ, tag in self._type_to_tag.items():
            if isinstance(obj, typ):
                return self._tag_object(tag, self._serialize_primitive(obj, typ))

        return obj # Primitives (str, int, float, bool, None) pass through

    def decode(self, obj: Any) -> Any:
        """Recursively walk JSON object and restore tagged types."""
        if isinstance(obj, dict):
            # Check if this dict is a tagged object
            if self.TYPE_FIELD in obj and self.DATA_FIELD in obj:
                tag = obj[self.TYPE_FIELD]
                data = obj[self.DATA_FIELD]

                if tag in self._custom_decoders:
                    return self._custom_decoders[tag](data)

                if tag in self._tag_to_type:
                    return self._deserialize_primitive(data, self._tag_to_type[tag])

            # Standard dict recursion
            return {k: self.decode(v) for k, v in obj.items()}

        if isinstance(obj, list):
            return [self.decode(v) for v in obj]

        return obj

    # --- Internal Helpers ---
    def _tag_object(self, tag: str, data: Any) -> Dict:
        return {self.TYPE_FIELD: tag, self.DATA_FIELD: data}

    def _serialize_primitive(self, obj: Any, typ: Type) -> Any:
        if typ is datetime.datetime:
            return obj.isoformat() # ISO 8601 UTC preferred
        if typ is datetime.date:
            return obj.isoformat()
        raise TypeError(f"No primitive serializer for {typ}")

    def _deserialize_primitive(self, data: str, typ: Type) -> Any:
        if typ is datetime.datetime:
            return datetime.datetime.fromisoformat(data)
        if typ is datetime.date:
            return datetime.date.fromisoformat(data)
        raise TypeError(f"No primitive deserializer for {typ}")

    def _encode_dataclass(self, obj: Any) -> Dict:
        """Generic dataclass encoder using type hints for nested decoding."""
        # We use asdict but recursively encode values to handle nested custom types
        data = {}
        hints = get_type_hints(obj.__class__)
        for f in fields(obj):
            val = getattr(obj, f.name)
            # Recursively encode the value
            data[f.name] = self.encode(val)
        return self._tag_object(obj.__type_tag__, data)

    def _decode_preference(self, data: Dict) -> Preference:
        """Specific decoder for Preference to handle nested types correctly."""
        # Recursively decode values first
        decoded_data = {k: self.decode(v) for k, v in data.items()}
        return Preference(**decoded_data)


# ---------------------------------------------------------
# 3. Public Functions (Cookie Blob Interface)
# ---------------------------------------------------------
_codec = SettingsCodec()

def save_user_settings(obj: Any) -> bytes:
    """
    Serializes settings object -> JSON -> Base64 URL-safe bytes.
    Ready to set as cookie value.
    """
    # 1. Encode custom types to tagged JSON structure
    json_safe = _codec.encode(obj)

    # 2. Dump to compact JSON (no whitespace)
    json_str = json.dumps(json_safe, separators=(',', ':'), ensure_ascii=False)

    # 3. Base64 URL-safe encode (no padding '=') for Cookie transport safety
    # Cookies technically allow ASCII, but Base64 avoids encoding headaches with quotes/semicolons.
    b64_bytes = base64.urlsafe_b64encode(json_str.encode('utf-8')).rstrip(b'=')

    return b64_bytes

def load_user_settings(blob: bytes) -> Any:
    """
    Deserializes Base64 URL-safe bytes -> JSON -> Settings Object.
    Returns None if blob is invalid/empty/tampered.
    """
    if not blob:
        return None

    try:
        # 1. Restore Base64 padding (strip adds it back)
        padding = 4 - (len(blob) % 4) if len(blob) % 4 else 0
        padded = blob + (b'=' * padding)

        # 2. Decode Base64 -> JSON string
        json_str = base64.urlsafe_b64decode(padded).decode('utf-8')

        # 3. Parse JSON
        json_obj = json.loads(json_str)

        # 4. Restore custom types (dataclasses, dates)
        return _codec.decode(json_obj)

    except (ValueError, json.JSONDecodeError, TypeError, KeyError) as e:
        # Log error 'e' in production (malformed cookie, version mismatch, tampering)
        return None


# ---------------------------------------------------------
# 4. Usage Example & Test
# ---------------------------------------------------------
if __name__ == "__main__":
    # Complex nested object
    original = {
        "theme": "dark",
        "notifications": True,
        "last_login": datetime.datetime(2023, 10, 25, 14, 30, tzinfo=datetime.timezone.utc),
        "favorite_dates": [
            datetime.date(2023, 1, 1),
            datetime.date(2024, 12, 31)
        ],
        "custom_prefs": [
            Preference(key="lang", value="python", scope="global"),
            Preference(key="editor", value="vscode", metadata={"version": "1.85"})
        ],
        "nested_dict": {
            "deep_pref": Preference(key="font_size", value=14)
        }
    }

    # 1. Save -> Blob
    blob = save_user_settings(original)
    print(f"Cookie Blob ({len(blob)} bytes): {blob.decode()}")

    # 2. Load -> Object
    restored = load_user_settings(blob)

    # 3. Verify
    assert restored["theme"] == "dark"
    assert isinstance(restored["last_login"], datetime.datetime)
    assert restored["last_login"].tzinfo is not None # Timezone preserved
    assert isinstance(restored["favorite_dates"][0], datetime.date)
    assert isinstance(restored["custom_prefs"][0], Preference)
    assert restored["custom_prefs"][0].key == "lang"
    assert restored["custom_prefs"][1].metadata["version"] == "1.85"
    assert isinstance(restored["nested_dict"]["deep_pref"], Preference)

    print("\n✅ Round-trip successful. Types preserved:")
    print(f"  last_login type: {type(restored['last_login'])}")
    print(f"  custom_prefs[0] type: {type(restored['custom_prefs'][0])}")
    print(f"  nested deep_pref type: {type(restored['nested_dict']['deep_pref'])}")
