import json
import base64
from dataclasses import is_dataclass, asdict, fields
from datetime import date, datetime
from typing import Any, TypeVar, get_type_hints

T = TypeVar('T')

class Preference:
    """Base dataclass for preferences - user should subclass this"""
    pass

def _encode(obj: Any) -> Any:
    """Convert Python objects to JSON-serializable forms."""
    if isinstance(obj, (date, datetime)):
        return {"__type__": "datetime", "value": obj.isoformat()}
    if is_dataclass(obj) and not isinstance(obj, type):
        data = asdict(obj)
        data["__type__"] = obj.__class__.__name__
        data["__module__"] = obj.__class__.__module__
        return data
    if isinstance(obj, dict):
        return {k: _encode(v) for k, v in obj.items()}
    if isinstance(obj, (list, tuple, set)):
        return [_encode(v) for v in obj]
    return obj

def _decode(obj: Any, type_registry: dict[str, type] | None = None) -> Any:
    """Restore Python objects from JSON forms."""
    if not isinstance(obj, dict):
        if isinstance(obj, list):
            return [_decode(v, type_registry) for v in obj]
        return obj

    if "__type__" in obj:
        type_name = obj["__type__"]
        if type_name == "datetime":
            return datetime.fromisoformat(obj["value"])

        # Custom dataclass
        if type_registry and type_name in type_registry:
            cls = type_registry[type_name]
        else:
            # Try to import from module
            module_name = obj.get("__module__", "__main__")
            try:
                module = __import__(module_name, fromlist=[type_name])
                cls = getattr(module, type_name)
            except (ImportError, AttributeError):
                return obj  # Fallback: return as dict

        # Filter known fields
        field_names = {f.name for f in fields(cls)}
        kwargs = {k: _decode(v, type_registry) for k, v in obj.items() 
                  if k in field_names and k not in ("__type__", "__module__")}
        return cls(**kwargs)

    return {k: _decode(v, type_registry) for k, v in obj.items()}

def save_user_settings(obj: Any, type_registry: dict[str, type] | None = None) -> bytes:
    """Serialize preferences object to cookie-safe bytes."""
    encoded = _encode(obj)
    json_str = json.dumps(encoded, separators=(',', ':'), ensure_ascii=False)
    return base64.urlsafe_b64encode(json_str.encode('utf-8'))

def load_user_settings(blob: bytes, type_registry: dict[str, type] | None = None) -> Any:
    """Deserialize preferences object from cookie bytes."""
    json_str = base64.urlsafe_b64decode(blob).decode('utf-8')
    data = json.loads(json_str)
    return _decode(data, type_registry)

