Here is a robust, standard-library-only implementation using **JSON with a typed envelope strategy**.

It handles `dataclass` instances (like your `Preference` class), `datetime`/`date`/`time`, `UUID`, `bytes`, `set`, and `Enum` automatically. It includes a **security allowlist** to prevent arbitrary code execution (RCE) during deserialization—a critical requirement for cookie data.

```python
import json
import dataclasses
import datetime
import base64
import uuid
import enum
from typing import Any, Dict, Type, Set, Optional, Callable, List

# ─── Configuration & Security ────────────────────────────────────────

# MARKER KEYS (unlikely to clash with user data keys)
_TYPE_KEY = "__type__"
_VALUE_KEY = "__value__"
_CLASS_KEY = "__class__"  # Fully qualified name: "module.ClassName"

# GLOBAL ALLOWLIST: Map "module.ClassName" -> Actual Class
# Populate this with your specific Preference class and any other dataclasses.
# This PREVENTS Remote Code Execution (RCE) via malicious cookie payloads.
ALLOWED_CLASSES: Dict[str, Type] = {}

def register_class(cls: Type) -> Type:
    """Decorator to register a dataclass/class for safe (de)serialization."""
    key = f"{cls.__module__}.{cls.__qualname__}"
    ALLOWED_CLASSES[key] = cls
    return cls

# ─── Custom JSON Encoder ─────────────────────────────────────────────

class SettingsEncoder(json.JSONEncoder):
    """
    Encodes non-JSON-native types into a typed envelope:
    { "__type__": "datetime", "__value__": "2023-10-27T10:00:00" }
    { "__type__": "dataclass", "__class__": "myapp.models.Preference", "__value__": { ... } }
    """
    def default(self, obj: Any) -> Any:
        # 1. Dataclasses (including custom Preference classes)
        if dataclasses.is_dataclass(obj) and not isinstance(obj, type):
            class_key = f"{obj.__class__.__module__}.{obj.__class__.__qualname__}"
            return {
                _TYPE_KEY: "dataclass",
                _CLASS_KEY: class_key,
                _VALUE_KEY: dataclasses.asdict(obj) # Recursively encoded
            }

        # 2. Datetime family
        if isinstance(obj, datetime.datetime):
            return {_TYPE_KEY: "datetime", _VALUE_KEY: obj.isoformat()}
        if isinstance(obj, datetime.date):
            return {_TYPE_KEY: "date", _VALUE_KEY: obj.isoformat()}
        if isinstance(obj, datetime.time):
            return {_TYPE_KEY: "time", _VALUE_KEY: obj.isoformat()}

        # 3. UUID
        if isinstance(obj, uuid.UUID):
            return {_TYPE_KEY: "uuid", _VALUE_KEY: str(obj)}

        # 4. Bytes (Base64 encoded)
        if isinstance(obj, (bytes, bytearray)):
            return {_TYPE_KEY: "bytes", _VALUE_KEY: base64.b64encode(obj).decode('ascii')}

        # 5. Set -> List
        if isinstance(obj, set):
            return {_TYPE_KEY: "set", _VALUE_KEY: list(obj)}

        # 6. Enum -> Value
        if isinstance(obj, enum.Enum):
            return {_TYPE_KEY: "enum", _CLASS_KEY: f"{obj.__class__.__module__}.{obj.__class__.__qualname__}", _VALUE_KEY: obj.value}

        # Fallback to default (raises TypeError if not serializable)
        return super().default(obj)

# ─── Custom Decoder Hook ─────────────────────────────────────────────

def _object_hook(dct: Dict[str, Any]) -> Any:
    """Decodes typed envelopes back into Python objects."""
    if _TYPE_KEY not in dct:
        return dct

    type_val = dct[_TYPE_KEY]
    value = dct[_VALUE_KEY]

    # --- Primitives & Containers ---
    if type_val == "datetime":
        return datetime.datetime.fromisoformat(value)
    if type_val == "date":
        return datetime.date.fromisoformat(value)
    if type_val == "time":
        return datetime.time.fromisoformat(value)
    if type_val == "uuid":
        return uuid.UUID(value)
    if type_val == "bytes":
        return base64.b64decode(value.encode('ascii'))
    if type_val == "set":
        return set(value)

    # --- Enum ---
    if type_val == "enum":
        class_key = dct[_CLASS_KEY]
        cls = ALLOWED_CLASSES.get(class_key)
        if not cls:
            raise ValueError(f"Enum class '{class_key}' not in allowlist.")
        return cls(value)

    # --- Dataclasses (The critical security boundary) ---
    if type_val == "dataclass":
        class_key = dct[_CLASS_KEY]
        cls = ALLOWED_CLASSES.get(class_key)

        if not cls:
            # SECURITY: Fail closed. Do not instantiate arbitrary classes.
            raise ValueError(f"Dataclass '{class_key}' not in allowlist. Possible tampering.")

        # 'value' is already a dict because json.loads runs object_hook recursively on nested dicts first.
        # We just need to instantiate the class.
        try:
            return cls(**value)
        except TypeError as e:
            raise ValueError(f"Failed to instantiate {class_key}: {e}") from e

    # Unknown type marker -> return raw dict (or raise)
    return dct

# ─── Public API ──────────────────────────────────────────────────────

def save_user_settings(obj: Any) -> bytes:
    """
    Serializes the preferences object to a compact UTF-8 JSON byte blob.
    Ready to be set as a cookie value (consider Base64 encoding for cookie transport safety).
    """
    # separators=(',', ':') removes whitespace for minimal cookie size
    json_str = json.dumps(obj, cls=SettingsEncoder, separators=(',', ':'), ensure_ascii=False)
    return json_str.encode('utf-8')

def load_user_settings(blob: bytes) -> Any:
    """
    Deserializes the byte blob back into the preferences object hierarchy.
    Raises json.JSONDecodeError if blob is corrupt.
    Raises ValueError if blob contains unregistered types (tampering).
    """
    if not blob:
        raise ValueError("Empty settings blob")

    json_str = blob.decode('utf-8')
    return json.loads(json_str, object_hook=_object_hook)

# ─── Example Usage & Registration ────────────────────────────────────

# 1. Define your custom types
