        "version": 4,
        "profile": UserProfile(
            user_id=uuid.uuid4(),
            name="Alice",
            prefs=Preference(theme="light", volume=0.5),
            last_login=datetime.datetime(2023, 11, 15, 14, 30, tzinfo=datetime.timezone.utc),
            tags={"beta", "premium"}
        ),
        "metadata": {
            "created": datetime.date(2023, 1, 1),
            "flags": {"a", "b", "c"} # set at top level too
        }
    }

    # Save
    blob = save_user_settings(original_obj)
    print(f"Cookie Size: {len(blob)} bytes")
    # Output: ~350 bytes (compact JSON)

    # Load
    restored_obj = load_user_settings(blob)

    # Verify
    assert isinstance(restored_obj["profile"], UserProfile)
    assert isinstance(restored_obj["profile"].prefs, Preference)
    assert isinstance(restored_obj["profile"].last_login, datetime.datetime)
    assert isinstance(restored_obj["profile"].tags, set)
    assert restored_obj["profile"].prefs.theme == "light"
    print("✅ Round-trip successful. Types preserved.")
