import json
import hmac
import hashlib
import base64
from datetime import date, datetime
from dataclasses import is_dataclass, asdict, fields
from typing import Any, TypeVar, get_type_hints

# Secret for HMAC signing (in production, load from env/config)
SECRET_KEY = b"your-secret-key-change-in-production"

T = TypeVar("T")


def _serialize(obj: Any) -> Any:
    """Convert Python objects to JSON-serializable forms."""
    if isinstance(obj, (datetime, date)):
        return {"__type__": "datetime", "value": obj.isoformat()}
    if is_dataclass(obj) and not isinstance(obj, type):
        data = asdict(obj)
        data["__dataclass__"] = obj.__class__.__name__
        data["__module__"] = obj.__class__.__module__
        return data
    if isinstance(obj, dict):
        return {k: _serialize(v) for k, v in obj.items()}
    if isinstance(obj, (list, tuple, set)):
        return [_serialize(v) for v in obj]
    return obj


def _deserialize(obj: Any, type_hints: dict | None = None) -> Any:
    """Restore Python objects from JSON forms."""
    if isinstance(obj, dict):
        # datetime
        if obj.get("__type__") == "datetime":
            return datetime.fromisoformat(obj["value"])
        # dataclass
        if "__dataclass__" in obj and "__module__" in obj:
            cls_name = obj.pop("__dataclass__")
            mod_name = obj.pop("__module__")
            module = __import__(mod_name, fromlist=[cls_name])
            cls = getattr(module, cls_name)
            hints = get_type_hints(cls)
            restored = {k: _deserialize(v, hints) for k, v in obj.items()}
            return cls(**restored)
        return {k: _deserialize(v, type_hints) for k, v in obj.items()}
    if isinstance(obj, list):
        return [_deserialize(v, type_hints) for v in obj]
    return obj


def _sign(data: bytes) -> bytes:
    """HMAC-SHA256 signature."""
    return hmac.new(SECRET_KEY, data, hashlib.sha256).digest()


def _verify(data: bytes, sig: bytes) -> bool:
    """Constant-time signature verification."""
    return hmac.compare_digest(_sign(data), sig)


def save_user_settings(obj: Any) -> bytes:
    """
    Serialize preferences object to a signed, base64-encoded blob for cookie storage.
    """
    serialized = _serialize(obj)
    json_bytes = json.dumps(serialized, separators=(",", ":"), ensure_ascii=False).encode()
    signature = _sign(json_bytes)
    payload = base64.urlsafe_b64encode(json_bytes + b"." + signature)
    return payload


def load_user_settings(blob: bytes) -> Any:
    """
    Verify and deserialize blob from cookie back to preferences object.
    Raises ValueError if signature invalid or data corrupted.
    """
    try:
        decoded = base64.urlsafe_b64decode(blob)
        json_bytes, signature = decoded.rsplit(b".", 1)
    except (ValueError, IndexError):
        raise ValueError("Invalid blob format")

    if not _verify(json_bytes, signature):
        raise ValueError("Invalid signature")

    try:
        data = json.loads(json_bytes)
    except json.JSONDecodeError:
        raise ValueError("Invalid JSON")

    return _deserialize(data)
