import xml.etree.ElementTree as ET
from typing import Dict, List, Union, IO

def parse_invoice_xml(source: Union[str, IO[bytes]]) -> Dict:
    """
    Parse an XML invoice file and return a dict with total amount, customer name, and line items.

    Args:
        source: File path (str) or file-like object (bytes mode).

    Returns:
        dict: {
            'total_amount': float,
            'customer_name': str,
            'line_items': List[dict]  # each with description, quantity, unit_price, amount
        }
    """
    # Parse XML
    if isinstance(source, str):
        tree = ET.parse(source)
    else:
        tree = ET.parse(source)
    root = tree.getroot()

    # Helper to safely get text
    def get_text(element, tag: str, default: str = '') -> str:
        child = element.find(tag)
        return child.text.strip() if child is not None and child.text else default

    # Extract customer name
    customer_name = get_text(root, 'customer')

    # Extract total amount
    total_str = get_text(root, 'total')
    try:
        total_amount = float(total_str)
    except ValueError:
        total_amount = 0.0

    # Extract line items
    line_items = []
    line_items_elem = root.find('lineItems')
    if line_items_elem is not None:
        for item_elem in line_items_elem.findall('item'):
            description = get_text(item_elem, 'description')
            quantity_str = get_text(item_elem, 'quantity')
            unit_price_str = get_text(item_elem, 'unitPrice')
            amount_str = get_text(item_elem, 'amount')

            try:
                quantity = float(quantity_str)
            except ValueError:
                quantity = 0.0
            try:
                unit_price = float(unit_price_str)
            except ValueError:
                unit_price = 0.0
            try:
                amount = float(amount_str)
            except ValueError:
                amount = 0.0

            line_items.append({
                'description': description,
                'quantity': quantity,
                'unit_price': unit_price,
                'amount': amount
            })

    return {
        'total_amount': total_amount,
        'customer_name': customer_name,
        'line_items': line_items
    }

import xml.etree.ElementTree as ET
from typing import Dict, List, Any, Optional

def parse_invoice_xml(file_path: str) -> Dict[str, Any]:
    """
    Parse an XML invoice file and extract total amount, customer name, and line items.
    Assumes common invoice XML structure; tries multiple tag names for flexibility.
    Returns a dict with keys: 'total_amount' (float), 'customer_name' (str), 'line_items' (list of dicts).
    """
    tree = ET.parse(file_path)
    root = tree.getroot()

    # Helper to find text of first matching tag (ignoring namespace)
    def find_text(parent: ET.Element, *tag_names: str) -> Optional[str]:
        for tag in tag_names:
            # Search recursively for tag without namespace
            for elem in parent.iter():
                if elem.tag.split('}')[-1] == tag:
                    return elem.text.strip() if elem.text else None
        return None

    # Helper to find all line item elements
    def find_line_items(parent: ET.Element) -> List[ET.Element]:
        items = []
        # Common container tags
        container_tags = ['LineItems', 'Items', 'InvoiceLines', 'Details']
        for container_tag in container_tags:
            for container in parent.iter():
                if container.tag.split('}')[-1] == container_tag:
                    # Common item tags
                    item_tags = ['LineItem', 'Item', 'InvoiceLine', 'Detail']
                    for item_tag in item_tags:
                        for item in container.iter():
                            if item.tag.split('}')[-1] == item_tag:
                                items.append(item)
                    if items:
                        return items
        # Fallback: direct children with item-like tags
        item_tags = ['LineItem', 'Item', 'InvoiceLine', 'Detail']
        for item_tag in item_tags:
            for item in parent.iter():
                if item.tag.split('}')[-1] == item_tag:
                    items.append(item)
        return items

    # Extract customer name
    customer_name = find_text(root,
                              'CustomerName', 'BuyerName', 'ClientName',
                              'Customer', 'Buyer', 'Client')  # may be parent element
    if customer_name is None:
        # Try nested <Name> under Customer/Buyer
        for parent_tag in ['Customer', 'Buyer', 'Client']:
            for parent in root.iter():
                if parent.tag.split('}')[-1] == parent_tag:
                    name_elem = parent.find('.//Name') or parent.find('.//name')
                    if name_elem is not None and name_elem.text:
                        customer_name = name_elem.text.strip()
                        break
            if customer_name:
                break

    # Extract total amount
    total_str = find_text(root,
                          'TotalAmount', 'InvoiceTotal', 'Total',
                          'GrandTotal', 'AmountDue')
    total_amount = float(total_str) if total_str else 0.0

    # Extract line items
    line_items = []
    for item_elem in find_line_items(root):
        # Try to get description, quantity, unit price, amount
        desc = find_text(item_elem, 'Description', 'ProductName', 'ItemName', 'Name')
        qty_str = find_text(item_elem, 'Quantity', 'Qty', 'Amount')
        unit_price_str = find_text(item_elem, 'UnitPrice', 'Price', 'UnitCost')
        amount_str = find_text(item_elem, 'Amount', 'LineTotal', 'Total')
        line_items.append({
            'description': desc or '',
            'quantity': float(qty_str) if qty_str else 0.0,
            'unit_price': float(unit_price_str) if unit_price_str else 0.0,
            'amount': float(amount_str) if amount_str else 0.0
        })

    return {
        'total_amount': total_amount,
        'customer_name': customer_name or '',
        'line_items': line_items
    }

