            - 'line_items': List[Dict] each with keys like 'description', 'quantity', 'unit_price', 'total'
    """
    tree = ET.parse(file_path)
    root = tree.getroot()

    # Helper to find text from element, handling namespaces
    def find_text(element, tag):
        # Search for tag ignoring namespace
        for child in element.iter():
            if child.tag.endswith(tag):
                return child.text
        return None

    # Extract customer name (common tags: CustomerName, BuyerName, Customer, etc.)
    customer_name = None
    for tag in ['CustomerName', 'BuyerName', 'Customer', 'ClientName']:
        customer_name = find_text(root, tag)
        if customer_name:
            break

    # Extract total amount (common tags: TotalAmount, InvoiceTotal, GrandTotal, Amount)
    total_amount = None
    for tag in ['TotalAmount', 'InvoiceTotal', 'GrandTotal', 'Amount']:
        text = find_text(root, tag)
        if text:
            try:
                total_amount = float(text)
                break
            except ValueError:
                pass

    # Extract line items (common parent tags: LineItems, Items, InvoiceLines, etc.)
    line_items = []
    # Find the container for line items
    items_container = None
    for tag in ['LineItems', 'Items', 'InvoiceLines', 'LineItemList']:
        items_container = root.find(f'.//*[local-name()="{tag}"]')
        if items_container is not None:
            break

    if items_container is not None:
        # Iterate over each line item element (common child tags: LineItem, Item, InvoiceLine)
        for item_elem in items_container:
            if item_elem.tag.endswith(('LineItem', 'Item', 'InvoiceLine')):
                item = {}
                # Extract common fields
                for field in ['Description', 'ProductName', 'Name', 'ItemDescription']:
                    item['description'] = find_text(item_elem, field)
                    if item.get('description'):
                        break
                for field in ['Quantity', 'Qty', 'Amount']:
                    qty_text = find_text(item_elem, field)
                    if qty_text:
                        try:
                            item['quantity'] = float(qty_text)
                            break
                        except ValueError:
                            pass
                for field in ['UnitPrice', 'Price', 'UnitCost']:
                    price_text = find_text(item_elem, field)
                    if price_text:
                        try:
                            item['unit_price'] = float(price_text)
                            break
                        except ValueError:
                            pass
                for field in ['Total', 'LineTotal', 'ExtendedPrice']:
                    total_text = find_text(item_elem, field)
                    if total_text:
                        try:
                            item['total'] = float(total_text)
                            break
                        except ValueError:
                            pass
                # If total missing, compute from quantity * unit_price
                if 'total' not in item and 'quantity' in item and 'unit_price' in item:
                    item['total'] = item['quantity'] * item['unit_price']
                line_items.append(item)

    return {
        'total_amount': total_amount,
        'customer_name': customer_name,
        'line_items': line_items
    }

