import shlex
from dataclasses import dataclass
from typing import Dict, List, Optional


@dataclass
class Job:
    name: str
    schedule: str
    command: List[str]  # stored as list for safe subprocess execution
    env: Dict[str, str]


def load_job_from_yaml(yaml_str: str) -> Job:
    """Parse YAML string and return a Job object with validated fields."""
    data = yaml.safe_load(yaml_str)

    if not isinstance(data, dict):
        raise ValueError("YAML must be a mapping")

    # Required fields
    name = data.get("name")
    schedule = data.get("schedule")
    command = data.get("command")

    if not name or not isinstance(name, str):
        raise ValueError("Field 'name' is required and must be a string")
    if not schedule or not isinstance(schedule, str):
        raise ValueError("Field 'schedule' is required and must be a string")
    if not command:
        raise ValueError("Field 'command' is required")

    # Convert command to list for safe subprocess.run(command, shell=False)
    if isinstance(command, str):
        command_list = shlex.split(command)
    elif isinstance(command, list):
        command_list = [str(c) for c in command]
    else:
        raise ValueError("Field 'command' must be a string or list")

    if not command_list:
        raise ValueError("Field 'command' cannot be empty")

    # Optional env, default to empty dict
    env = data.get("env", {})
    if not isinstance(env, dict):
        raise ValueError("Field 'env' must be a mapping")
    env = {str(k): str(v) for k, v in env.items()}

    return Job(
        name=name,
        schedule=schedule,
        command=command_list,
        env=env
    )
