// deep-merge.js
/**
 * Recursively merge `source` into `target`.
 *
 * - If a key exists in both objects **and both values are plain objects**,
 *   they are merged recursively.
 * - Otherwise the value from `source` overwrites the one in `target`
 *   (including `null`, `undefined`, arrays, primitives, Dates, etc.).
 *
 * @param {Object} target   The object that will receive the merged properties.
 * @param {Object} source   The object whose properties will be merged in.
 * @returns {Object}        The mutated `target` (convenient for chaining).
 */
function deepMerge(target, source) {
  if (!isPlainObject(target) || !isPlainObject(source)) {
    throw new TypeError('Both target and source must be plain objects');
  }

  for (const key of Object.keys(source)) {
    const srcVal = source[key];
    const tgtVal = target[key];

    // Both values are plain objects → recurse
    if (isPlainObject(srcVal) && isPlainObject(tgtVal)) {
      deepMerge(tgtVal, srcVal);
    } else {
      // Overwrite (or create) the property
      target[key] = srcVal;
    }
  }
  return target;
}

/**
 * Parse a JSON string supplied by the user and merge it into a *copy* of
 * the default settings.
 *
 * @param {Object} defaults   Default configuration (will NOT be mutated).
 * @param {string} userJson   JSON string from the API client.
 * @returns {Object}          A new settings object with user overrides applied.
 * @throws {SyntaxError}      If `userJson` is not valid JSON.
 * @throws {TypeError}        If the parsed JSON is not a plain object.
 */
function applyUserSettings(defaults, userJson) {
  // 1️⃣ Parse the incoming JSON
  let userSettings;
  try {
    userSettings = JSON.parse(userJson);
  } catch (err) {
    // Re‑throw with a clearer message
    throw new SyntaxError(`Invalid user JSON: ${err.message}`);
  }

  // 2️⃣ Guard against non‑object payloads (e.g. `"foo"` or `123`)
  if (!isPlainObject(userSettings)) {
    throw new TypeError('Parsed user JSON must be an object');
  }

  // 3️⃣ Clone defaults so the original stays pristine
  const merged = cloneDeep(defaults);

  // 4️⃣ Deep‑merge the user supplied settings
  deepMerge(merged, userSettings);

  return merged;
}

/* ------------------------------------------------------------------ */
/* Helper utilities                                                    */
/* ------------------------------------------------------------------ */

/**
 * Checks whether `value` is a plain object (created by `{}` or `new Object`).
 * Returns `false` for `null`, arrays, Dates, RegExp, class instances, etc.
 */
function isPlainObject(value) {
  return (
    typeof value === 'object' &&
    value !== null &&
    Object.prototype.toString.call(value) === '[object Object]'
  );
}

/**
 * Very small deep‑clone that only understands plain objects, arrays,
 * and primitive values. Good enough for typical configuration objects.
 */
function cloneDeep(value) {
  if (Array.isArray(value)) {
    return value.map(cloneDeep);
  }
  if (isPlainObject(value)) {
    const cloned = {};
    for (const k of Object.keys(value)) {
      cloned[k] = cloneDeep(value[k]);
    }
    return cloned;
  }
  // Primitives (string, number, boolean, null, undefined, Symbol, BigInt)
  // and non‑plain objects (Date, RegExp, etc.) are returned as‑is.
  return value;
}

/* ------------------------------------------------------------------ */
/* Export                                                             */
/* ------------------------------------------------------------------ */
module.exports = {
  deepMerge,
  applyUserSettings,
};
