/**
 * Recursively merges `source` into `target`.
 * Both arguments must be plain objects (or null/undefined).
 * Returns the mutated `target`.
 */
function deepMerge(target, source) {
  if (!source || typeof source !== 'object') return target;
  if (!target || typeof target !== 'object') target = {};

  for (const key of Object.keys(source)) {
    const srcVal = source[key];
    const tgtVal = target[key];

    // Recurse when both values are plain objects (not arrays, dates, etc.)
    if (
      srcVal &&
      typeof srcVal === 'object' &&
      !Array.isArray(srcVal) &&
      tgtVal &&
      typeof tgtVal === 'object' &&
      !Array.isArray(tgtVal)
    ) {
      target[key] = deepMerge(tgtVal, srcVal);
    } else {
      // Overwrite (or assign) for primitives, arrays, dates, etc.
      target[key] = srcVal;
    }
  }
  return target;
}

/**
 * Parses a JSON string (`userJson`) and merges the resulting object
 * into `defaults` using deepMerge.
 * Returns the merged settings object (mutates `defaults`).
 */
function applyUserSettings(defaults, userJson) {
  let userObj;
  try {
    userObj = JSON.parse(userJson);
  } catch (err) {
    throw new Error(`Invalid JSON in user settings: ${err.message}`);
  }

  if (userObj && typeof userObj === 'object' && !Array.isArray(userObj)) {
    return deepMerge(defaults, userObj);
  }
  // If the parsed JSON isn't an object, just return defaults unchanged.
  return defaults;
}

// Example usage:
// const defaults = { theme: 'dark', notifications: { email: true, sms: false } };
// const userJson = '{"notifications": {"sms": true}, "language": "en"}';
// const settings = applyUserSettings(defaults, userJson);
// console.log(settings);
// → { theme: 'dark', notifications: { email: true, sms: true }, language: 'en' }

module.exports = { deepMerge, applyUserSettings };
