### Alternative: Zero-Dependency Implementation (Not Recommended for Prod)
*Only use this if you absolutely cannot install `cors` (e.g., edge runtime constraints, extreme bundle size limits). You lose `Vary` header automation, preflight caching headers, and battle-tested parsing.*

```javascript
// middleware/cors-no-deps.js
const ALLOWED_ORIGINS = new Set([
  'https://my-web-app.com',
  'https://partner-a.com',
  // ... load from config
]);

const ALLOWED_METHODS = 'GET,HEAD,PUT,PATCH,POST,DELETE,OPTIONS';
const ALLOWED_HEADERS = 'Content-Type,Authorization,X-Requested-With,X-Partner-Key';
const EXPOSED_HEADERS = 'X-Total-Count';
const MAX_AGE = '86400';

const corsHeaders = (origin) => ({
  'Access-Control-Allow-Origin': origin,
  'Access-Control-Allow-Credentials': 'true',
  'Access-Control-Allow-Methods': ALLOWED_METHODS,
  'Access-Control-Allow-Headers': ALLOWED_HEADERS,
  'Access-Control-Expose-Headers': EXPOSED_HEADERS,
  'Access-Control-Max-Age': MAX_AGE,
  'Vary': 'Origin', // Critical for caching
});

module.exports = (req, res, next) => {
  const origin = req.headers.origin;

  // 1. No Origin header (non-browser or same-origin) -> Pass through
  if (!origin) return next();

  // 2. Check Allowlist
  if (!ALLOWED_ORIGINS.has(origin)) {
    return res.status(403).json({ error: 'CORS: Origin not allowed' });
  }

  // 3. Set Headers for ALL responses (Simple & Preflight & Actual)
  Object.entries(corsHeaders(origin)).forEach(([k, v]) => res.setHeader(k, v));

  // 4. Handle Preflight (OPTIONS)
  if (req.method === 'OPTIONS') {
    // Check requested method/headers validity (simplified)
    const reqMethod = req.headers['access-control-request-method'];
    const reqHeaders = req.headers['access-control-request-headers'];

    // Optional: Strict validation of requested method/headers here

    return res.status(204).end(); // 204 No Content
  }

  // 5. Actual Request
  next();
};
```

### Summary Checklist for Your Requirements
| Requirement | Solution |
| :--- | :--- |
| **Web App + Partners** | Dynamic `origin` callback checking a `Set`/DB. |
| **Credentials (Cookies/Auth)** | `credentials: true` + Specific Origin Reflection (No `*`). |
| **Easy Partner Config** | Abstract `getAllowedOrigins()` function (DB, Redis, ENV, File). |
| **OPTIONS Preflight** | Handled automatically by `cors` package (`preflightContinue: false`). |
| **Security** | `Vary: Origin` header set automatically; Strict allowlist; No wildcard with creds. |

```javascript
const cors = require('cors');

function createCorsMiddleware(config) {
  const {
    allowedOrigins = [],
    allowedMethods = ['GET', 'POST', 'PUT', 'PATCH', 'DELETE', 'OPTIONS'],
    allowedHeaders = ['Content-Type', 'Authorization', 'X-Requested-With'],
    exposedHeaders = [],
    credentials = true,
    maxAge = 86400
  } = config;

  const originSet = new Set(allowedOrigins);

  function isOriginAllowed(origin) {
    if (!origin) return false;
    return originSet.has(origin);
  }

  function addOrigin(origin) {
    originSet.add(origin);
  }

  function removeOrigin(origin) {
    originSet.delete(origin);
  }

  const corsOptions = {
    origin: (origin, callback) => {
      if (!origin || isOriginAllowed(origin)) {
        callback(null, true);
      } else {
        callback(new Error('Not allowed by CORS'));
      }
    },
    methods: allowedMethods,
    allowedHeaders,
    exposedHeaders,
    credentials,
    maxAge,
    optionsSuccessStatus: 204
  };

  const middleware = cors(corsOptions);

  return {
    middleware,
    addOrigin,
    removeOrigin,
    getAllowedOrigins: () => Array.from(originSet)
  };
}

module.exports = createCorsMiddleware;
```

