Here is a robust, production-ready Express.js CORS middleware.

It uses a **dynamic origin validation function** (the only way to properly support `credentials: true` with a dynamic list of partners) and includes a **startup validation** step to catch configuration errors early.

### 1. The Middleware (`middleware/cors.js`)

```javascript
// middleware/cors.js
const cors = require('cors');

/**
 * Builds the CORS middleware configuration.
 * 
 * @param {Object} options
 * @param {string} options.primaryOrigin - Your main web app origin (e.g., 'https://app.example.com')
 * @param {string[]} options.partnerOrigins - Array of partner origins (e.g., ['https://partner-a.com'])
 * @param {boolean} options.allowLocalhost - Allow localhost with any port (dev only)
 * @returns {import('express').RequestHandler}
 */
function createCorsMiddleware({ primaryOrigin, partnerOrigins = [], allowLocalhost = false }) {

  // 1. Normalize and Validate Origins at Startup
  const allowedOrigins = new Set();

  const normalize = (origin) => {
    if (!origin) return null;
    try {
      // Remove trailing slash, enforce lowercase hostname
      const url = new URL(origin);
      url.pathname = '/';
      url.hash = '';
      url.search = '';
      return url.toString().replace(/\/$/, '');
    } catch (e) {
      console.error(`[CORS Config Error] Invalid origin format: "${origin}"`);
      return null;
    }
  };

  // Add Primary
  const normPrimary = normalize(primaryOrigin);
  if (!normPrimary) throw new Error('[CORS] Primary Origin is required and must be a valid URL.');
  allowedOrigins.add(normPrimary);

  // Add Partners
  partnerOrigins.forEach((o, i) => {
    const norm = normalize(o);
    if (norm) allowedOrigins.add(norm);
    else console.warn(`[CORS Config Warning] Skipping invalid partner origin at index ${i}: "${o}"`);
  });

  // Dev Helper: Allow localhost:* (http/https, any port)
  // In production, you should explicitly list your preview/staging URLs instead.
  const localhostRegex = allowLocalhost 
    /^https?:\/\/localhost(:\d+)?$/ 
    : null;

  // 2. The Dynamic Origin Verification Function
  // This is required because 'origin: true' reflects the request origin blindly,
  // and 'origin: ["a", "b"]' does not support regex/patterns for localhost.
  const originValidator = (requestOrigin, callback) => {
    // 1. Allow non-browser clients (curl, Postman, server-to-server) with no Origin header
    if (!requestOrigin) {
      return callback(null, true); 
    }

    const normalizedRequestOrigin = normalize(requestOrigin);

    // 2. Check Exact Matches (Primary + Partners)
    if (allowedOrigins.has(normalizedRequestOrigin)) {
      return callback(null, true);
    }

    // 3. Check Localhost Regex (Dev Only)
    if (localhostRegex && localhostRegex.test(normalizedRequestOrigin)) {
      return callback(null, true);
    }

    // 4. Reject
    console.warn(`[CORS Blocked] Origin not in allowlist: "${requestOrigin}"`);
    callback(new Error('Not allowed by CORS'), false);
  };

  // 3. Configure CORS Options
  // credentials: true REQUIRES origin to be a function (or specific string), not "*" or true.
  const corsOptions = {
    origin: originValidator,
    credentials: true, // Allow cookies/auth headers
    methods: ['GET', 'POST', 'PUT', 'PATCH', 'DELETE', 'OPTIONS'],
    allowedHeaders: [
      'Content-Type', 
      'Authorization', 
      'X-Requested-With',
      'Accept',
      'Origin',
      'X-CSRF-Token' // If you use CSRF tokens
    ],
    exposedHeaders: ['X-Total-Count', 'X-Request-Id'], // Headers JS can read
    maxAge: 86400, // Cache preflight for 24 hours (reduces OPTIONS traffic)
    optionsSuccessStatus: 204 // Some legacy browsers choke on 200
  };

  return cors(corsOptions);
}

module.exports = { createCorsMiddleware };
```

