### 3. Application Entry Point (`app.js` or `server.js`)

Apply the middleware **early**, before your routes.

```javascript
// app.js
const express = require('express');
const { createCorsMiddleware } = require('./middleware/cors');
const { cors: corsConfig } = require('./config/cors');

const app = express();

// 1. Trust Proxy (Required if behind Nginx/AWS ALB/Cloudflare)
// Ensures req.protocol / req.secure / req.ip are correct for CORS logic
app.set('trust proxy', 1); 

// 2. Apply CORS Middleware Globally
// This handles OPTIONS preflight automatically for ALL routes.
app.use(createCorsMiddleware(corsConfig));

// 3. Body Parsers (Must come AFTER CORS if CORS needs to read body? No, CORS doesn't read body. 
// But standard practice: CORS -> Body Parser -> Routes)
app.use(express.json());
app.use(express.urlencoded({ extended: true }));

// 4. Your Routes
app.get('/api/health', (req, res) => res.json({ status: 'ok' }));
app.post('/api/data', (req, res) => res.json({ received: true }));

// 5. Global Error Handler (Catches CORS errors from the middleware)
app.use((err, req, res, next) => {
  // The cors middleware passes an Error object when origin is rejected
  if (err.message === 'Not allowed by CORS') {
    return res.status(403).json({ 
      error: 'Forbidden', 
      message: 'CORS policy violation: Origin not allowed.' 
    });
  }
  console.error(err);
  res.status(500).json({ error: 'Internal Server Error' });
});

module.exports = app;
```

