### Approach 1: Custom Middleware (Zero Dependencies, Max Control)
Use this if you need to fetch allowed origins from a Database/Redis at runtime, or have complex validation logic (e.g., wildcard subdomains `*.partner.com`).

**`middleware/cors.js`**
```javascript
/**
 * Dynamic CORS Middleware
 * - Reads allowed origins from a configurable source (Array, Function, Async Function).
 * - Handles credentials (cookies/auth headers) correctly.
 * - Responds to OPTIONS preflight requests immediately.
 */

const DEFAULT_HEADERS = [
  'Content-Type',
  'Authorization',
  'X-Requested-With',
  'Accept',
  'Origin',
  'X-CSRF-Token', // Common for partnered integrations
];

const DEFAULT_METHODS = ['GET', 'POST', 'PUT', 'PATCH', 'DELETE', 'OPTIONS'];

/**
 * @param {Object} options
 * @param {string|string[]|Function|Promise} options.allowedOrigins 
 *   - String: Single origin (e.g., "https://app.example.com")
 *   - Array: Static list ["https://app.com", "https://partner1.com"]
 *   - Function(req): Sync function returning string|string[]|boolean
 *   - Async Function(req): Async function (e.g., DB lookup) returning string|string[]|boolean
 * @param {string[]} [options.allowedHeaders=DEFAULT_HEADERS]
 * @param {string[]} [options.allowedMethods=DEFAULT_METHODS]
 * @param {number} [options.maxAge=86400] Preflight cache duration (seconds)
 * @param {boolean} [options.credentials=true] Allow cookies/auth headers
 */
export function corsMiddleware(options = {}) {
  const {
    allowedOrigins = [],
    allowedHeaders = DEFAULT_HEADERS,
    allowedMethods = DEFAULT_METHODS,
    maxAge = 86400, // 24 hours
    credentials = true,
  } = options;

  // Normalize headers/methods to strings once
  const headersString = allowedHeaders.join(', ');
  const methodsString = allowedMethods.join(', ');

  return async (req, res, next) => {
    const requestOrigin = req.headers.origin;

    // 1. No Origin header? (e.g. curl, Postman, server-to-server non-browser)
    // We technically don't need CORS headers, but adding them doesn't hurt.
    // If you strictly only want browser traffic, you could return 403 here.
    if (!requestOrigin) {
      return next();
    }

    // 2. Resolve Allowed Origins (Supports static, dynamic, async)
    let resolvedOrigins;
    try {
      if (typeof allowedOrigins === 'function') {
        resolvedOrigins = await allowedOrigins(req);
      } else {
        resolvedOrigins = allowedOrigins;
      }
    } catch (err) {
      console.error('[CORS] Error resolving origins:', err);
      return res.status(500).send('CORS Configuration Error');
    }

    // Normalize to Array
    const originList = Array.isArray(resolvedOrigins) 
      ? resolvedOrigins 
      : [resolvedOrigins].filter(Boolean); // Handle single string or false/null

    // 3. Check if Origin is Allowed
    // Supports exact match. Add logic here for wildcard/subdomain matching if needed.
    const isAllowed = originList.some(allowed => allowed === requestOrigin);

    if (!isAllowed) {
      // Security: Do not leak which origins are allowed in error message
      console.warn(`[CORS] Blocked origin: ${requestOrigin}`);
      return res.status(403).send('Forbidden: CORS Origin Not Allowed');
    }

    // 4. Set Response Headers (Actual Response & Preflight)
    // Vary: Origin is critical for CDN/Proxy caching correctness
    res.setHeader('Vary', 'Origin');
    res.setHeader('Access-Control-Allow-Origin', requestOrigin); // MUST be specific origin, not *, when credentials=true

    if (credentials) {
      res.setHeader('Access-Control-Allow-Credentials', 'true');
    }

    // 5. Handle Preflight (OPTIONS)
    if (req.method === 'OPTIONS') {
      res.setHeader('Access-Control-Allow-Methods', methodsString);
      res.setHeader('Access-Control-Allow-Headers', headersString);
      res.setHeader('Access-Control-Max-Age', maxAge.toString());

      // Preflight succeeds with 204 No Content
      return res.status(204).end();
    }

    // 6. Expose headers needed by the client (e.g., for file downloads, pagination)
    res.setHeader('Access-Control-Expose-Headers', 'Content-Disposition, X-Total-Count, X-Rate-Limit-Remaining');

    next();
  };
}
```

