### Approach 2: `cors` Package Wrapper (Standard, Battle-Tested)
Use this for 95% of apps. It handles edge cases (legacy browsers, header parsing quirks) better than custom code. We wrap it to enable the **dynamic origin function** pattern.

**`middleware/corsWrapper.js`**
```javascript
import cors from 'cors';

/**
 * Wrapper around 'cors' package to support async origin validation.
 * The 'cors' package supports a function for `origin` option: `function(origin, callback)`
 * but it does NOT natively support async/await. This wrapper bridges that gap.
 */
export function createCorsMiddleware(options = {}) {
  const {
    allowedOrigins = [], // String, Array, Sync Fn, or Async Fn(req) -> String|Array|Boolean
    allowedHeaders = [
      'Content-Type', 'Authorization', 'X-Requested-With', 'Accept', 'Origin', 'X-CSRF-Token'
    ],
    allowedMethods = ['GET', 'POST', 'PUT', 'PATCH', 'DELETE', 'OPTIONS'],
    maxAge = 86400,
    credentials = true,
    // ... other cors options (exposedHeaders, preflightContinue, etc.)
  } = options;

  // Standard cors config (static parts)
  const corsOptions = {
    allowedHeaders,
    methods: allowedMethods,
    maxAge,
    credentials,
    exposedHeaders: ['Content-Disposition', 'X-Total-Count', 'X-Rate-Limit-Remaining'],
    // We handle 'origin' dynamically below via the wrapper logic
  };

  return async (req, res, next) => {
    const requestOrigin = req.headers.origin;

    // 1. Resolve Allowed Origins (Same logic as Approach 1)
    let resolvedOrigins;
    try {
      if (typeof allowedOrigins === 'function') {
        resolvedOrigins = await allowedOrigins(req);
      } else {
        resolvedOrigins = allowedOrigins;
      }
    } catch (err) {
      return next(err); // Pass to Express error handler
    }

    const originList = Array.isArray(resolvedOrigins) 
      ? resolvedOrigins 
      : [resolvedOrigins].filter(Boolean);

    // 2. Determine if allowed
    // cors package expects `origin` option to be: true (reflect), false (disable), string, array, or function.
    // We calculate the specific value to pass to the underlying cors middleware for *this* request.
    let originOption = false; // Default: Disable CORS

    if (!requestOrigin) {
      // No origin header (non-browser). Enable CORS loosely or disable.
      // Setting origin: true reflects the request origin (which is undefined), effectively doing nothing.
      originOption = false; 
    } else if (originList.includes(requestOrigin)) {
      // EXACT MATCH REQUIRED for credentials
      originOption = requestOrigin; 
    } else {
      // Not allowed
      originOption = false;
    }

    // 3. Delegate to actual `cors` middleware instance for this specific request config
    // We create a transient middleware instance with the resolved origin.
    // This is slightly less performant than a single instance but necessary for dynamic async origins.
    // For HIGH TRAFFIC, memoize the cors instance per unique origin list hash.
    const dynamicCors = cors({ ...corsOptions, origin: originOption });

    return dynamicCors(req, res, next);
  };
}
```

**Usage (Approach 2)** is identical to Approach 1, just import `createCorsMiddleware` instead.

