### `middleware/cors.js`

```javascript
/**
 * Configurable CORS Middleware for Credentialed Requests
 * 
 * Features:
 * - Dynamic allowlist (Set based for performance)
 * - Reflects specific Origin (required for credentials)
 * - Handles OPTIONS preflight automatically
 * - Sets Vary: Origin for caching safety
 * - Exposes API to add origins at runtime
 */

const DEFAULT_ALLOWED_METHODS = 'GET,HEAD,PUT,PATCH,POST,DELETE,OPTIONS';
const DEFAULT_ALLOWED_HEADERS = 'Content-Type,Authorization,X-Requested-With,Accept,Origin';
const DEFAULT_EXPOSED_HEADERS = 'Content-Length,X-Request-Id';
const DEFAULT_MAX_AGE = 86400; // 24 hours

function createCorsMiddleware(options = {}) {
  // 1. Configuration with sensible defaults
  const config = {
    // Core allowlist: Use a Set for O(1) lookups
    allowedOrigins: new Set(options.allowedOrigins || []),

    // Optional: Allow regex patterns for complex subdomain logic (e.g. *.partner.com)
    // Note: Exact matches in Set are checked first for performance.
    allowedOriginPatterns: options.allowedOriginPatterns || [],

    // Credentials support (cookies, auth headers)
    credentials: options.credentials !== false, // Default true

    // Preflight cache duration
    maxAge: options.maxAge ?? DEFAULT_MAX_AGE,

    // Custom headers
    allowedMethods: options.allowedMethods ?? DEFAULT_ALLOWED_METHODS,
    allowedHeaders: options.allowedHeaders ?? DEFAULT_ALLOWED_HEADERS,
    exposedHeaders: options.exposedHeaders ?? DEFAULT_EXPOSED_HEADERS,

    // Optional: Custom logic for complex validation (e.g. check DB)
    customOriginValidator: options.customOriginValidator || null,
  };

  /**
   * Public API: Add an origin to the allowlist at runtime.
   * Usage: corsMiddleware.addOrigin('https://new-partner.com')
   */
  function addOrigin(origin) {
    if (typeof origin === 'string' && origin) {
      config.allowedOrigins.add(origin);
    }
  }

  /**
   * Public API: Add multiple origins at once (e.g. on app startup from DB).
   */
  function addOrigins(origins) {
    if (Array.isArray(origins)) {
      origins.forEach(addOrigin);
    }
  }

  /**
   * Core Validation Logic
   */
  function isOriginAllowed(origin) {
    if (!origin) return false; // No origin header (non-browser or same-origin)

    // 1. Fast Path: Exact Match in Set
    if (config.allowedOrigins.has(origin)) {
      return true;
    }

    // 2. Pattern Matching (Regex)
    // Escape dots, convert * to .* for wildcard subdomains if desired
    // Example pattern: 'https://*.partner.com'
    for (const pattern of config.allowedOriginPatterns) {
      // Simple glob-to-regex conversion for convenience
      const regexStr = pattern
        .replace(/\./g, '\\.')
        .replace(/\*/g, '.*');

      try {
        if (new RegExp(`^${regexStr}$`, 'i').test(origin)) {
          return true;
        }
      } catch (e) {
        console.error(`[CORS] Invalid regex pattern: ${pattern}`, e);
      }
    }

    // 3. Custom Async/Sync Validator (e.g. check database)
    // Note: Middleware is sync. If you need async DB checks, 
    // you must load origins into the Set at startup/interval, 
    // or implement a custom async middleware wrapper.
    if (config.customOriginValidator) {
      return config.customOriginValidator(origin);
    }

    return false;
  }

  // 4. The Actual Middleware Function
  const middleware = (req, res, next) => {
    const requestOrigin = req.headers.origin;

    // --- PREFLIGHT HANDLING (OPTIONS) ---
    if (req.method === 'OPTIONS') {
      // If origin is allowed, respond with 204 and headers
      if (isOriginAllowed(requestOrigin)) {
        setCorsHeaders(res, requestOrigin);
        // Preflight requests should end here with 204
        return res.status(204).end();
      }

      // Origin not allowed: Do NOT set CORS headers. 
      // Browser will block the request automatically.
      return res.status(403).send('CORS: Origin not allowed');
    }

    // --- ACTUAL REQUEST HANDLING ---

    // Only apply CORS headers if the request has an Origin header (Cross-Origin)
    // Same-origin requests don't need CORS headers.
    if (requestOrigin) {
      if (isOriginAllowed(requestOrigin)) {
        setCorsHeaders(res, requestOrigin);
      } else {
        // Optional: Log blocked attempts for security auditing
        // console.warn(`[CORS Blocked] Origin: ${requestOrigin} | Path: ${req.path}`);
        // We do NOT set CORS headers here. The browser will handle the error.
        // However, we still call next() so your 404/401 handlers run normally 
        // for non-browser clients or same-origin requests.
      }
    }

    next();
  };

  // Attach public API to middleware function
  middleware.addOrigin = addOrigin;
  middleware.addOrigins = addOrigins;
  middleware.getAllowedOrigins = () => [...config.allowedOrigins];

  return middleware;
}

/**
 * Helper: Sets the actual response headers
 */
function setCorsHeaders(res, origin) {
  // CRITICAL: Reflect the specific origin, NOT '*'
  res.setHeader('Access-Control-Allow-Origin', origin);

  // CRITICAL: Prevent caching issues where Partner A gets Partner B's response
  res.setHeader('Vary', 'Origin');

  if (res.locals.corsCredentials !== false) { // Allow override per route if needed
    res.setHeader('Access-Control-Allow-Credentials', 'true');
  }

  // Preflight specific headers (safe to send on actual responses too)
  res.setHeader('Access-Control-Allow-Methods', res.locals.corsMethods || DEFAULT_ALLOWED_METHODS);
  res.setHeader('Access-Control-Allow-Headers', res.locals.corsAllowedHeaders || DEFAULT_ALLOWED_HEADERS);
  res.setHeader('Access-Control-Expose-Headers', res.locals.corsExposedHeaders || DEFAULT_EXPOSED_HEADERS);
  res.setHeader('Access-Control-Max-Age', res.locals.corsMaxAge || DEFAULT_MAX_AGE);
}

module.exports = { createCorsMiddleware };
```

