### Critical "Gotchas" This Solves

| Issue | Standard `cors()` Package Default | This Implementation |
| :--- | :--- | :--- |
| **Credentials + Wildcard** | Fails silently in browser (CORS error) | **Reflects specific Origin** (Required by Spec) |
| **CDN Caching** | Often misses `Vary: Origin` | **Sets `Vary: Origin`** automatically |
| **Preflight (OPTIONS)** | Sometimes returns 200 with body | **Returns 204 No Content** (Standard) |
| **Dynamic Partners** | Requires app restart / config reload | **`addOrigin()` / `addOrigins()` API** |
| **Security** | `origin: true` reflects *any* origin | **Strict Allowlist + Optional Regex** |

### Testing Checklist
1.  **Credentials**: `fetch('/api', { credentials: 'include' })` works from allowed origins.
2.  **Blocked**: Request from `https://evil.com` returns **no CORS headers** (browser blocks).
3.  **Preflight**: `OPTIONS /api` returns `204` + `Access-Control-Allow-Methods`.
4.  **Caching**: Hit endpoint from Origin A, then Origin B. Verify Origin B doesn't get Origin A's `Access-Control-Allow-Origin` value (check `Vary: Origin`).
5.  **Dynamic Add**: Call `addOrigin`, immediately test new origin works without restart.

```javascript
// corsMiddleware.js
const DEFAULT_ALLOWED_METHODS = ['GET', 'POST', 'PUT', 'PATCH', 'DELETE', 'OPTIONS'];
const DEFAULT_ALLOWED_HEADERS = ['Content-Type', 'Authorization', 'X-Requested-With', 'Accept', 'Origin'];
const DEFAULT_EXPOSED_HEADERS = ['X-Total-Count', 'X-Page-Count'];
const DEFAULT_MAX_AGE = 86400; // 24 hours

/**
 * Creates a CORS middleware with configurable origin allowlist.
 * @param {Object} options
 * @param {string[]} options.allowedOrigins - List of allowed origins (exact match or regex patterns)
 * @param {string} options.appOrigin - Your web app's origin (always allowed)
 * @param {boolean} options.credentials - Allow credentials (cookies, auth headers)
 * @param {string[]} options.allowedMethods - HTTP methods to allow
 * @param {string[]} options.allowedHeaders - Request headers to allow
 * @param {string[]} options.exposedHeaders - Response headers to expose to client
 * @param {number} options.maxAge - Preflight cache duration in seconds
 * @param {Function} options.customOriginCheck - Optional: custom function(origin) => boolean
 */
function createCorsMiddleware({
  allowedOrigins = [],
  appOrigin,
  credentials = true,
  allowedMethods = DEFAULT_ALLOWED_METHODS,
  allowedHeaders = DEFAULT_ALLOWED_HEADERS,
  exposedHeaders = DEFAULT_EXPOSED_HEADERS,
  maxAge = DEFAULT_MAX_AGE,
  customOriginCheck
} = {}) {
  // Normalize origins: ensure protocol, no trailing slash
  const normalizeOrigin = (origin) => origin.replace(/\/+$/, '');

  const origins = new Set([
    ...(appOrigin ? [normalizeOrigin(appOrigin)] : []),
    ...allowedOrigins.map(normalizeOrigin)
  ]);

  // Compile regex patterns for wildcard/subdomain matching
  const originPatterns = Array.from(origins).map(origin => {
    if (origin.includes('*')) {
      const escaped = origin.replace(/\./g, '\\.').replace(/\*/g, '.*');
      return new RegExp(`^${escaped}$`);
    }
    return null;
  }).filter(Boolean);

  const isOriginAllowed = (origin) => {
    if (!origin) return false;
    const normalized = normalizeOrigin(origin);

    // Exact match
    if (origins.has(normalized)) return true;

    // Pattern match (wildcards)
    if (originPatterns.some(pattern => pattern.test(normalized))) return true;

    // Custom check
    if (customOriginCheck && customOriginCheck(normalized)) return true;

    return false;
  };

  const corsHeaders = (origin) => ({
    'Access-Control-Allow-Origin': origin,
    'Access-Control-Allow-Credentials': credentials ? 'true' : 'false',
    'Access-Control-Allow-Methods': allowedMethods.join(', '),
    'Access-Control-Allow-Headers': allowedHeaders.join(', '),
    'Access-Control-Expose-Headers': exposedHeaders.join(', '),
    'Access-Control-Max-Age': String(maxAge),
    'Vary': 'Origin'
  });

  return (req, res, next) => {
    const requestOrigin = req.headers.origin;
    const isPreflight = req.method === 'OPTIONS';

    // No origin header = not a CORS request (same-origin or non-browser)
    if (!requestOrigin) {
      return next();
    }

    const allowed = isOriginAllowed(requestOrigin);

    if (!allowed) {
      // Origin not allowed - don't set CORS headers, let browser block
      if (isPreflight) {
        return res.status(403).send('CORS: Origin not allowed');
      }
      return next();
    }

    // Set CORS headers for allowed origin
    Object.entries(corsHeaders(requestOrigin)).forEach(([key, value]) => {
      res.setHeader(key, value);
    });

    // Handle preflight
    if (isPreflight) {
      // Respond to preflight without hitting route handlers
      return res.status(204).end();
    }

    next();
  };
}

/**
 * Helper to add partner origins at runtime (e.g., from config/database)
 */
function createDynamicCorsMiddleware(getAllowedOrigins, options = {}) {
  let cachedMiddleware = null;
  let cachedOrigins = null;

  return (req, res, next) => {
    const currentOrigins = getAllowedOrigins();
    const originsKey = JSON.stringify(currentOrigins.sort());

    if (originsKey !== cachedOrigins) {
      cachedOrigins = originsKey;
      cachedMiddleware = createCorsMiddleware({
        ...options,
        allowedOrigins: currentOrigins
      });
    }

    return cachedMiddleware(req, res, next);
  };
}

module.exports = { createCorsMiddleware, createDynamicCorsMiddleware };
```

