**Key features:**
- **Easy partner management**: Add origins to array or use `createDynamicCorsMiddleware` for runtime updates
- **Wildcard support**: `https://*.partner.com` matches subdomains
- **Credentials handling**: `Access-Control-Allow-Credentials: true` with specific origin (not `*`)
- **Preflight caching**: `Access-Control-Max-Age` reduces OPTIONS requests
- **Vary: Origin**: Ensures CDN/proxy caches separate responses per origin
- **Security**: Rejects non-allowed origins silently (browser blocks) or with 403 on preflight

Here are two production-ready approaches. **Approach 1 (Recommended)** uses the standard `cors` package with a dynamic origin validator. **Approach 2** is a zero-dependency custom implementation if you want to avoid the package or need highly specific logic.

---

### Approach 1: Using `cors` package (Recommended)
This is the standard, battle-tested way. The key is passing a **function** to `origin` instead of a string/array. This function runs per-request, allowing you to check a database, cache, or config file dynamically.

#### 1. Install
```bash
npm install cors
```

#### 2. Configuration Strategy (`config/cors.js`)
Keep your allowed origins in a centralized, easy-to-update place (JSON file, DB, Redis, Env Var).

```javascript
// config/cors.js
// In production, load this from a DB, Redis, or a JSON file watched by a file-watcher (e.g., nodemon/pm2 reload)
const ALLOWED_ORIGINS = new Set([
  // Your main web app
  'https://app.yourdomain.com',
  'https://www.yourdomain.com',

  // Localhost for dev (add ports as needed)
  'http://localhost:3000',
  'http://localhost:5173', // Vite default
  'http://127.0.0.1:5500', // VS Code Live Server

  // Partner sites (add/remove over time)
  'https://partner-a.com',
  'https://partner-b.io',
  'https://subdomain.partner-c.org'
]);

/**
 * Checks if an origin is allowed.
 * @param {string} origin - The request Origin header.
 * @returns {boolean}
 */
function isOriginAllowed(origin) {
  if (!origin) return false; // Non-browser requests (curl, Postman) often have no origin

  // 1. Exact match (Fastest)
  if (ALLOWED_ORIGINS.has(origin)) return true;

  // 2. Optional: Wildcard subdomain matching for partners
  // e.g., allow *.partner-c.org
  // Be careful with this; validate the TLD properly in real apps.
  try {
    const url = new URL(origin);
    // Example logic: allow any subdomain of 'trusted-partner.com'
    if (url.hostname.endsWith('.trusted-partner.com')) return true;
  } catch (e) {
    return false; // Invalid URL format
  }

  return false;
}

module.exports = { isOriginAllowed, ALLOWED_ORIGINS };
```

#### 3. The Middleware (`middleware/cors.js`)

```javascript
// middleware/cors.js
const cors = require('cors');
const { isOriginAllowed } = require('../config/cors');

const corsMiddleware = cors({
  // 1. Dynamic Origin Validation
  // This function is called for EVERY request.
  // Return the origin string if allowed, or false/Error if denied.
  origin: (origin, callback) => {
    // Allow requests with no origin (mobile apps, curl, server-to-server)
    // ONLY if you have a separate auth mechanism (API Keys/JWT) for them.
    // If this is a public API strictly for browsers, return callback(new Error('No origin'), false);
    if (!origin) return callback(null, true); 

    if (isOriginAllowed(origin)) {
      // Reflect the specific origin back (REQUIRED for credentials)
      callback(null, origin);
    } else {
      // Log denied attempts for security auditing
      console.warn(`[CORS Blocked] Origin: ${origin}`);
      callback(new Error(`CORS policy: Origin ${origin} not allowed`), false);
    }
  },

  // 2. Credentials Support (Cookies, Authorization headers, TLS client certs)
  // REQUIRES: origin above MUST return a specific string (not "*")
  credentials: true,

  // 3. Methods allowed
  methods: ['GET', 'POST', 'PUT', 'PATCH', 'DELETE', 'OPTIONS'],

  // 4. Headers allowed in actual request (from client)
  allowedHeaders: [
    'Content-Type', 
    'Authorization', 
    'X-Requested-With',
    'Accept',
    'X-Api-Key',           // Custom headers partners might use
    'Idempotency-Key'      // Common for payment APIs
  ],

  // 5. Headers exposed to the client (browser JS can read these)
  exposedHeaders: [
    'X-Request-Id', 
    'X-RateLimit-Limit', 
    'X-RateLimit-Remaining',
    'Link'                // For pagination
  ],

  // 6. Preflight Cache Duration (seconds)
  // Browsers cache the OPTIONS response. 86400 = 1 day. Reduce during dev.
  maxAge: process.env.NODE_ENV === 'production' ? 86400 : 10,

  // 7. Handle Preflight (OPTIONS) explicitly
  // The package handles this automatically if optionsSuccessStatus is set.
  // 204 No Content is standard; 200 OK works for legacy browsers (IE11, SmartTVs).
  optionsSuccessStatus: 204
});

module.exports = corsMiddleware;
```

#### 4. Usage in `app.js` / `server.js`
**Critical:** Place this **before** your routes and body parsers.

```javascript
// app.js
