### Approach 2: Zero-Dependency Custom Middleware
Use this if you cannot use `npm install cors` or need absolute control over the header logic (e.g., complex regex matching per partner).

```javascript
// middleware/customCors.js
const { isOriginAllowed, ALLOWED_ORIGINS } = require('../config/cors');

const customCors = (req, res, next) => {
  const origin = req.headers.origin;
  const requestMethod = req.method;

  // 1. Determine Allowed Origin
  let allowedOrigin = null;
  if (origin && isOriginAllowed(origin)) {
    allowedOrigin = origin;
  }

  // 2. Set Headers (Only if allowed or no origin)
  // Note: We do NOT set headers if origin is present but NOT allowed.
  if (allowedOrigin || !origin) {
    // Vary header tells caches (CDN/Browser) response varies by Origin
    res.setHeader('Vary', 'Origin');

    if (allowedOrigin) {
      // MUST echo specific origin for credentials (cannot use *)
      res.setHeader('Access-Control-Allow-Origin', allowedOrigin);
      res.setHeader('Access-Control-Allow-Credentials', 'true');
    }
    // If no origin (curl/server), we typically don't set ACAO unless it's a public API.
  }

  // 3. Handle Preflight (OPTIONS)
  if (requestMethod === 'OPTIONS') {
    // If origin not allowed, deny preflight immediately (403)
    if (origin && !allowedOrigin) {
      return res.status(403).end('CORS: Origin not allowed');
    }

    // Set Preflight specific headers
    res.setHeader('Access-Control-Allow-Methods', 'GET,HEAD,PUT,PATCH,POST,DELETE,OPTIONS');
    res.setHeader('Access-Control-Allow-Headers', 'Content-Type, Authorization, X-Requested-With, Accept, X-Api-Key, Idempotency-Key');
    res.setHeader('Access-Control-Max-Age', '86400'); // 1 day cache

    // Expose headers for actual response
    res.setHeader('Access-Control-Expose-Headers', 'X-Request-Id, X-RateLimit-Limit, X-RateLimit-Remaining, Link');

    // Respond 204 No Content (Standard for preflight)
    return res.status(204).end();
  }

  // 4. Continue to actual route handler
  next();
};

module.exports = customCors;
```

