```javascript
// corsMiddleware.js
const cors = require('cors');

/**
 * Build CORS options from a configurable allowlist.
 * Allowlist can be an array of origins or a function(origin, callback).
 * Supports credentials for partner sites.
 */
function createCorsMiddleware({ allowlist = [], credentials = true } = {}) {
  const normalized = Array.isArray(allowlist) ? allowlist.map(o => o.toLowerCase()) : [];

  const corsOptions = {
    origin: (origin, callback) => {
      // Allow non-browser requests (no origin) or origins in allowlist
      if (!origin || normalized.includes(origin.toLowerCase())) {
        return callback(null, true);
      }
      callback(new Error(`CORS: Origin ${origin} not allowed`));
    },
    credentials,
    methods: ['GET', 'POST', 'PUT', 'PATCH', 'DELETE', 'OPTIONS'],
    allowedHeaders: ['Content-Type', 'Authorization', 'X-Requested-With'],
    exposedHeaders: ['X-Total-Count', 'X-Request-Id'],
    maxAge: 86400, // 24h preflight cache
    optionsSuccessStatus: 204
  };

  return cors(corsOptions);
}

module.exports = { createCorsMiddleware };
