```javascript
// corsMiddleware.js
const cors = require('cors');

/**
 * Creates CORS middleware with configurable origin allowlist.
 * Supports credentials and handles OPTIONS preflight automatically.
 * 
 * @param {Object} options
 * @param {string[]} options.allowedOrigins - List of allowed origins (exact match or regex strings)
 * @param {boolean} [options.allowCredentials=true] - Allow cookies/auth headers
 * @param {string[]} [options.allowedMethods] - HTTP methods to allow
 * @param {string[]} [options.allowedHeaders] - Headers to allow in requests
 * @param {number} [options.maxAge=86400] - Preflight cache duration (seconds)
 */
function createCorsMiddleware({
  allowedOrigins = [],
  allowCredentials = true,
  allowedMethods = ['GET', 'POST', 'PUT', 'PATCH', 'DELETE', 'OPTIONS'],
  allowedHeaders = ['Content-Type', 'Authorization', 'X-Requested-With', 'Accept', 'Origin'],
  maxAge = 86400
} = {}) {
  // Normalize origins: support exact strings and regex patterns
  const originPatterns = allowedOrigins.map(origin => {
    if (origin instanceof RegExp) return origin;
    if (typeof origin === 'string' && origin.startsWith('/') && origin.endsWith('/')) {
      return new RegExp(origin.slice(1, -1));
    }
    return origin; // exact string match
  });

  const corsOptions = {
    origin: (origin, callback) => {
      // Allow non-browser requests (no origin header) - e.g., curl, server-to-server
      if (!origin) return callback(null, true);

      const isAllowed = originPatterns.some(pattern => {
        if (pattern instanceof RegExp) return pattern.test(origin);
        return pattern === origin;
      });

      if (isAllowed) {
        callback(null, true);
      } else {
        callback(new Error(`CORS: Origin ${origin} not allowed`), false);
      }
    },
    credentials: allowCredentials,
    methods: allowedMethods,
    allowedHeaders: allowedHeaders,
    optionsSuccessStatus: 200, // Some legacy browsers choke on 204
    maxAge: maxAge
  };

  return cors(corsOptions);
}

module.exports = { createCorsMiddleware };
