```javascript
const corsMiddleware = (options = {}) => {
  const {
    // Static allowlist of origins
    allowlist = [],
    // Dynamic origin validator: function(origin, callback) -> callback(err, allowed)
    validateOrigin = null,
    // Allow all origins if true (ignored if allowlist/validateOrigin provided)
    allowAll = false,
    // Credentials support
    credentials = true,
    // Allowed methods
    methods = ['GET', 'POST', 'PUT', 'PATCH', 'DELETE', 'OPTIONS'],
    // Allowed headers
    allowedHeaders = ['Content-Type', 'Authorization', 'X-Requested-With'],
    // Exposed headers
    exposedHeaders = [],
    // Max age for preflight cache (seconds)
    maxAge = 86400,
  } = options;

  const isOriginAllowed = (origin, callback) => {
    // No origin (same-origin, curl, etc.) - allow
    if (!origin) return callback(null, true);

    // Allow all mode
    if (allowAll) return callback(null, true);

    // Check static allowlist
    if (allowlist.includes(origin)) return callback(null, true);

    // Check dynamic validator
    if (validateOrigin) {
      return validateOrigin(origin, (err, allowed) => {
        if (err) return callback(err);
        callback(null, allowed === true);
      });
    }

    callback(null, false);
  };

  return (req, res, next) => {
    const origin = req.headers.origin;

    // Handle preflight OPTIONS request
    if (req.method === 'OPTIONS') {
      isOriginAllowed(origin, (err, allowed) => {
        if (err) return next(err);
        if (!allowed) return res.sendStatus(403);

        res.set({
          'Access-Control-Allow-Origin': origin,
          'Access-Control-Allow-Methods': methods.join(', '),
          'Access-Control-Allow-Headers': allowedHeaders.join(', '),
          'Access-Control-Allow-Credentials': credentials.toString(),
          'Access-Control-Max-Age': maxAge.toString(),
        });
        return res.sendStatus(204);
      });
      return;
    }

    // Handle actual request
    isOriginAllowed(origin, (err, allowed) => {
      if (err) return next(err);

      if (allowed && origin) {
        res.set({
          'Access-Control-Allow-Origin': origin,
          'Access-Control-Allow-Credentials': credentials.toString(),
        });
        if (exposedHeaders.length) {
          res.set('Access-Control-Expose-Headers', exposedHeaders.join(', '));
        }
      }

      // Vary header for caching proxies
      res.set('Vary', 'Origin');
      next();
    });
  };
};

module.exports = corsMiddleware;
