// cors-middleware.js
const cors = require('cors');

/**
 * Build CORS configuration from environment or config object.
 * Expects ALLOWED_ORIGINS as comma-separated string or array.
 * Example: "https://app.example.com,https://partner1.com,https://partner2.com"
 */
function buildCorsOptions(config = {}) {
  const origins = config.allowedOrigins 
    ? (Array.isArray(config.allowedOrigins) 
        ? config.allowedOrigins 
        : config.allowedOrigins.split(',').map(o => o.trim()))
    : (process.env.ALLOWED_ORIGINS 
        ? process.env.ALLOWED_ORIGINS.split(',').map(o => o.trim())
        : ['http://localhost:3000']); // dev default

  return {
    origin: function (origin, callback) {
      // Allow non-browser requests (curl, Postman, server-to-server)
      if (!origin) return callback(null, true);

      if (origins.includes(origin)) {
        callback(null, true);
      } else {
        callback(new Error(`CORS: Origin ${origin} not allowed`));
      }
    },
    credentials: true, // Required for cookies/auth headers
    methods: ['GET', 'POST', 'PUT', 'PATCH', 'DELETE', 'OPTIONS'],
    allowedHeaders: [
      'Content-Type',
      'Authorization',
      'X-Requested-With',
      'Accept',
      'Origin',
      'X-Partner-ID' // Custom header for partner identification
    ],
    exposedHeaders: ['X-Request-ID', 'X-RateLimit-Remaining'],
    maxAge: 86400, // Cache preflight for 24 hours
    optionsSuccessStatus: 204 // Some legacy browsers choke on 200
  };
}

/**
 * Express middleware factory.
 * Usage: app.use(corsMiddleware({ allowedOrigins: [...] }))
 */
function corsMiddleware(config = {}) {
  const options = buildCorsOptions(config);
  const corsHandler = cors(options);

  // Explicit OPTIONS handler for preflight (cors package handles this,
  // but this ensures it runs before other middleware)
  return (req, res, next) => {
    if (req.method === 'OPTIONS') {
      return corsHandler(req, res, () => res.sendStatus(204));
    }
    corsHandler(req, res, next);
  };
}

module.exports = { corsMiddleware, buildCorsOptions };
