  const rawOrigins = config.allowedOrigins || process.env.CORS_ALLOWED_ORIGINS || '';
  const allowedOrigins = Array.isArray(rawOrigins)
    ? rawOrigins
    : rawOrigins.split(',').map(o => o.trim()).filter(Boolean);

  // Compile wildcard patterns to RegExp for flexible matching
  const originPatterns = allowedOrigins.map(origin => {
    if (origin.includes('*')) {
      const escaped = origin.replace(/[.+?^${}()|[\]\\]/g, '\\$&').replace('\\*', '.*');
      return new RegExp(`^${escaped}$`);
    }
    return origin;
  });

  const corsOptions = {
    origin: (requestOrigin, callback) => {
      // Allow non-browser requests (e.g., server-to-server) with no Origin header
      if (!requestOrigin) return callback(null, true);

      const isAllowed = originPatterns.some(pattern =>
        pattern instanceof RegExp ? pattern.test(requestOrigin) : pattern === requestOrigin
      );

      if (isAllowed) {
        callback(null, requestOrigin); // echo back the requesting origin
      } else {
        callback(new Error(`CORS: Origin ${requestOrigin} not allowed`), false);
      }
    },
    credentials: true, // allow cookies, authorization headers
    methods: ['GET', 'POST', 'PUT', 'PATCH', 'DELETE', 'OPTIONS'],
    allowedHeaders: [
      'Content-Type',
      'Authorization',
      'X-Requested-With',
      'Accept',
      'Origin',
      'X-CSRF-Token'
    ],
    exposedHeaders: ['X-Request-Id', 'X-RateLimit-Remaining'],
    maxAge: 86400, // cache preflight for 24h
    optionsSuccessStatus: 204 // some legacy browsers choke on 200
  };

  return cors(corsOptions);
}

module.exports = { createCorsMiddleware };
