// cors-middleware.js
const fs = require('fs');
const path = require('path');

/**
 * CORS middleware with dynamic allowlist loaded from config file
 * Supports credentials and handles OPTIONS preflight requests
 */
function createCorsMiddleware(options = {}) {
  const {
    allowlistPath = path.join(__dirname, 'cors-allowlist.json'),
    defaultOrigins = ['http://localhost:3000', 'https://app.example.com'],
    credentials = true,
    maxAge = 86400, // 24 hours
    methods = ['GET', 'POST', 'PUT', 'PATCH', 'DELETE', 'OPTIONS'],
    allowedHeaders = ['Content-Type', 'Authorization', 'X-Requested-With', 'Accept', 'Origin'],
    exposedHeaders = ['X-Total-Count', 'X-Request-ID']
  } = options;

  let allowlist = [...defaultOrigins];

  // Load allowlist from JSON file (watched for changes in production)
  function loadAllowlist() {
    try {
      if (fs.existsSync(allowlistPath)) {
        const fileContent = fs.readFileSync(allowlistPath, 'utf8');
        const parsed = JSON.parse(fileContent);
        if (Array.isArray(parsed.origins)) {
          allowlist = [...new Set([...defaultOrigins, ...parsed.origins])];
        }
      }
    } catch (err) {
      console.error('[CORS] Failed to load allowlist:', err.message);
    }
  }

  // Initial load
  loadAllowlist();

  // Optional: watch for changes (disable in serverless environments)
  let watcher = null;
  if (process.env.NODE_ENV !== 'production' || process.env.CORS_WATCH === 'true') {
    try {
      watcher = fs.watch(allowlistPath, (eventType) => {
        if (eventType === 'change') {
          console.log('[CORS] Allowlist changed, reloading...');
          loadAllowlist();
        }
      });
    } catch (err) {
      // Watching not supported (e.g., serverless)
    }
  }

  function isOriginAllowed(origin) {
    if (!origin) return false;
    return allowlist.some(allowed => {
      if (allowed instanceof RegExp) return allowed.test(origin);
      return allowed === origin;
    });
  }

  function getCorsHeaders(origin) {
    const headers = {
      'Access-Control-Allow-Methods': methods.join(', '),
      'Access-Control-Allow-Headers': allowedHeaders.join(', '),
      'Access-Control-Expose-Headers': exposedHeaders.join(', '),
      'Access-Control-Max-Age': maxAge.toString()
    };

    if (credentials) {
      headers['Access-Control-Allow-Credentials'] = 'true';
      // With credentials, cannot use wildcard - must echo origin
      headers['Access-Control-Allow-Origin'] = origin;
    } else {
      headers['Access-Control-Allow-Origin'] = origin || '*';
    }

    return headers;
  }

  return function corsMiddleware(req, res, next) {
    const origin = req.headers.origin;

    // Handle preflight OPTIONS request
    if (req.method === 'OPTIONS') {
      if (origin && isOriginAllowed(origin)) {
        const headers = getCorsHeaders(origin);
        Object.entries(headers).forEach(([key, value]) => res.setHeader(key, value));
        return res.sendStatus(204);
      }
      // Origin not allowed - still respond but without CORS headers
      return res.sendStatus(204);
    }

    // Actual request - add CORS headers if origin allowed
    if (origin && isOriginAllowed(origin)) {
      const headers = getCorsHeaders(origin);
      Object.entries(headers).forEach(([key, value]) => res.setHeader(key, value));
    }

    // Vary header ensures caches distinguish by origin
    res.setHeader('Vary', 'Origin');

    next();
  };
}

module.exports = { createCorsMiddleware };
