```javascript
// corsMiddleware.js
const cors = require('cors');

/**
 * Creates CORS middleware with configurable allowlist.
 * @param {Object} options
 * @param {string[]|Function} options.allowlist - Array of allowed origins or async function(origin) => boolean
 * @param {string} options.appOrigin - Primary web app origin (always allowed)
 * @param {boolean} options.credentials - Allow credentials (default: true)
 */
function createCorsMiddleware({ allowlist = [], appOrigin, credentials = true }) {
  const origins = new Set([appOrigin, ...allowlist].filter(Boolean));

  const isAllowed = async (origin) => {
    if (!origin) return false; // non-browser requests
    if (origins.has(origin)) return true;
    if (typeof allowlist === 'function') return await allowlist(origin);
    return false;
  };

  return cors({
    origin: async (origin, callback) => {
      try {
        const allowed = await isAllowed(origin);
        callback(null, allowed);
      } catch (err) {
        callback(err);
      }
    },
    credentials,
    methods: ['GET', 'HEAD', 'PUT', 'PATCH', 'POST', 'DELETE', 'OPTIONS'],
    allowedHeaders: ['Content-Type', 'Authorization', 'X-Requested-With', 'Accept', 'Origin'],
    exposedHeaders: ['X-Total-Count', 'X-Request-Id'],
    maxAge: 86400, // 24h preflight cache
    preflightContinue: false,
    optionsSuccessStatus: 204
  });
}

module.exports = { createCorsMiddleware };
