// corsMiddleware.js
const DEFAULT_ALLOWED_HEADERS = [
  'Content-Type',
  'Authorization',
  'X-Requested-With',
  'Accept',
  'Origin',
  'Cache-Control',
  'X-CSRF-Token'
];

const DEFAULT_ALLOWED_METHODS = [
  'GET', 'POST', 'PUT', 'PATCH', 'DELETE', 'OPTIONS'
];

/**
 * Creates a CORS middleware with configurable allowlist.
 * @param {Object} options
 * @param {string[]|Function} options.allowlist - Array of allowed origins or async function(origin) => boolean
 * @param {string} options.appOrigin - Your web app's origin (always allowed)
 * @param {boolean} options.credentials - Allow credentials (cookies, auth headers)
 * @param {string[]} options.allowedHeaders - Additional allowed headers
 * @param {string[]} options.allowedMethods - Additional allowed methods
 * @param {number} options.maxAge - Preflight cache duration in seconds
 */
function createCorsMiddleware({
  allowlist = [],
  appOrigin,
  credentials = true,
  allowedHeaders = [],
  allowedMethods = [],
  maxAge = 86400 // 24 hours
}) {
  const allAllowedHeaders = [...DEFAULT_ALLOWED_HEADERS, ...allowedHeaders];
  const allAllowedMethods = [...DEFAULT_ALLOWED_METHODS, ...allowedMethods];

  // Normalize allowlist to a Set for O(1) lookups
  const staticAllowlist = new Set(
    Array.isArray(allowlist) ? allowlist : []
  );
  if (appOrigin) staticAllowlist.add(appOrigin);

  const dynamicCheck = typeof allowlist === 'function' ? allowlist : null;

  async function isOriginAllowed(origin) {
    if (!origin) return false;
    if (staticAllowlist.has(origin)) return true;
    if (dynamicCheck) return await dynamicCheck(origin);
    return false;
  }

  return async function corsMiddleware(req, res, next) {
    const origin = req.headers.origin;
    const isAllowed = await isOriginAllowed(origin);

    // Set Vary header for proper caching
    res.setHeader('Vary', 'Origin');

    if (isAllowed) {
      res.setHeader('Access-Control-Allow-Origin', origin);
      if (credentials) {
        res.setHeader('Access-Control-Allow-Credentials', 'true');
      }
    }

    // Handle preflight OPTIONS request
    if (req.method === 'OPTIONS') {
      if (!isAllowed) {
        return res.status(403).end();
      }

      res.setHeader('Access-Control-Allow-Methods', allAllowedMethods.join(', '));
      res.setHeader('Access-Control-Allow-Headers', allAllowedHeaders.join(', '));
      res.setHeader('Access-Control-Max-Age', maxAge.toString());
      return res.status(204).end();
    }

    // Expose headers for actual requests
    if (isAllowed) {
      res.setHeader('Access-Control-Expose-Headers', 'Content-Length, X-Request-Id');
    }

    next();
  };
}

module.exports = { createCorsMiddleware };
