// corsMiddleware.js
const cors = require('cors');

/**
 * Build CORS options from configuration
 * @param {Object} config - Configuration object
 * @param {string[]} config.allowedOrigins - List of allowed origins (exact match)
 * @param {string[]} [config.allowedOriginPatterns=[]] - Regex patterns for dynamic origins
 * @param {string[]} [config.allowedMethods=['GET','POST','PUT','PATCH','DELETE','OPTIONS']]
 * @param {string[]} [config.allowedHeaders=['Content-Type','Authorization','X-Requested-With']]
 * @param {boolean} [config.credentials=true] - Allow cookies/auth headers
 * @param {number} [config.maxAge=86400] - Preflight cache duration (seconds)
 * @returns {Function} Express middleware
 */
function createCorsMiddleware(config) {
  const {
    allowedOrigins = [],
    allowedOriginPatterns = [],
    allowedMethods = ['GET', 'POST', 'PUT', 'PATCH', 'DELETE', 'OPTIONS'],
    allowedHeaders = ['Content-Type', 'Authorization', 'X-Requested-With'],
    credentials = true,
    maxAge = 86400
  } = config;

  // Normalize origins to lowercase for case-insensitive matching
  const normalizedOrigins = new Set(allowedOrigins.map(o => o.toLowerCase()));
  const compiledPatterns = allowedOriginPatterns.map(p => new RegExp(p, 'i'));

  const corsOptions = {
    origin: (origin, callback) => {
      // Allow non-browser requests (no origin header) - e.g., server-to-server
      if (!origin) return callback(null, true);

      const lowerOrigin = origin.toLowerCase();

      // Exact match
      if (normalizedOrigins.has(lowerOrigin)) {
        return callback(null, true);
      }

      // Pattern match
      for (const pattern of compiledPatterns) {
        if (pattern.test(lowerOrigin)) {
          return callback(null, true);
        }
      }

      // Origin not allowed
      callback(new Error(`CORS: Origin ${origin} not allowed`), false);
    },
    methods: allowedMethods,
    allowedHeaders,
    credentials,
    maxAge,
    optionsSuccessStatus: 204 // No content for preflight
  };

  return cors(corsOptions);
}

module.exports = { createCorsMiddleware };
