const cors = require('cors');

/**
 * Build CORS options from configuration
 * @param {Object} config - Configuration object
 * @param {string[]} config.allowedOrigins - List of allowed origins (exact matches)
 * @param {string[]} config.allowedOriginPatterns - Regex patterns for dynamic origins (e.g., partner subdomains)
 * @param {string[]} config.allowedMethods - HTTP methods to allow
 * @param {string[]} config.allowedHeaders - Headers to allow
 * @param {string[]} config.exposedHeaders - Headers to expose to client
 * @param {number} config.maxAge - Preflight cache duration in seconds
 * @returns {Object} CORS options for express cors middleware
 */
function buildCorsOptions(config = {}) {
  const {
    allowedOrigins = [],
    allowedOriginPatterns = [],
    allowedMethods = ['GET', 'POST', 'PUT', 'PATCH', 'DELETE', 'OPTIONS'],
    allowedHeaders = ['Content-Type', 'Authorization', 'X-Requested-With', 'Accept', 'Origin'],
    exposedHeaders = ['X-Total-Count', 'X-Page-Count'],
    maxAge = 86400 // 24 hours
  } = config;

  // Combine static origins with pattern-based matching
  const originWhitelist = [...allowedOrigins];

  return {
    origin: (origin, callback) => {
      // Allow non-browser requests (no origin header) - e.g., mobile apps, curl
      if (!origin) return callback(null, true);

      // Check exact match
      if (originWhitelist.includes(origin)) {
        return callback(null, true);
      }

      // Check regex patterns (for partner subdomains like *.partner.com)
      const matched = allowedOriginPatterns.some(pattern => {
        const regex = typeof pattern === 'string' ? new RegExp(pattern) : pattern;
        return regex.test(origin);
      });

      if (matched) return callback(null, true);

      callback(new Error(`CORS: Origin ${origin} not allowed`));
    },
    credentials: true,
    methods: allowedMethods,
    allowedHeaders: allowedHeaders,
    exposedHeaders: exposedHeaders,
    maxAge: maxAge,
