// corsMiddleware.js
const DEFAULT_ALLOWED_ORIGINS = [
  'https://your-web-app.com',
  'https://app.your-web-app.com'
];

const DEFAULT_ALLOWED_METHODS = ['GET', 'POST', 'PUT', 'PATCH', 'DELETE', 'OPTIONS'];
const DEFAULT_ALLOWED_HEADERS = ['Content-Type', 'Authorization', 'X-Requested-With', 'Accept', 'Origin'];
const DEFAULT_EXPOSED_HEADERS = ['X-Total-Count', 'X-Page-Count'];
const DEFAULT_MAX_AGE = 86400; // 24 hours

/**
 * Creates a CORS middleware with configurable options
 * @param {Object} options
 * @param {string[]} options.allowedOrigins - List of allowed origins (supports wildcards)
 * @param {boolean} options.allowCredentials - Allow cookies/credentials
 * @param {string[]} options.allowedMethods - Allowed HTTP methods
 * @param {string[]} options.allowedHeaders - Allowed request headers
 * @param {string[]} options.exposedHeaders - Headers exposed to client
 * @param {number} options.maxAge - Preflight cache duration in seconds
 * @param {Function} options.originValidator - Custom origin validation function
 */
function createCorsMiddleware(options = {}) {
  const {
    allowedOrigins = DEFAULT_ALLOWED_ORIGINS,
    allowCredentials = true,
    allowedMethods = DEFAULT_ALLOWED_METHODS,
    allowedHeaders = DEFAULT_ALLOWED_HEADERS,
    exposedHeaders = DEFAULT_EXPOSED_HEADERS,
    maxAge = DEFAULT_MAX_AGE,
    originValidator
  } = options;

  const normalizedOrigins = allowedOrigins.map(o => o.toLowerCase());

  function isOriginAllowed(origin) {
    if (!origin) return false;
    const lowerOrigin = origin.toLowerCase();

    if (originValidator && originValidator(origin)) return true;

    return normalizedOrigins.some(allowed => {
      if (allowed === '*') return true;
      if (allowed.includes('*')) {
        const regex = new RegExp('^' + allowed.replace(/\*/g, '.*') + '$');
        return regex.test(lowerOrigin);
      }
      return allowed === lowerOrigin;
    });
  }

  function setCorsHeaders(res, origin) {
    res.setHeader('Access-Control-Allow-Origin', origin);
    if (allowCredentials) {
      res.setHeader('Access-Control-Allow-Credentials', 'true');
    }
    if (exposedHeaders.length) {
      res.setHeader('Access-Control-Expose-Headers', exposedHeaders.join(', '));
    }
  }

  return function corsMiddleware(req, res, next) {
    const origin = req.headers.origin;

    if (req.method === 'OPTIONS') {
      if (!origin || !isOriginAllowed(origin)) {
        return res.status(403).end();
      }

      setCorsHeaders(res, origin);
      res.setHeader('Access-Control-Allow-Methods', allowedMethods.join(', '));
      res.setHeader('Access-Control-Allow-Headers', allowedHeaders.join(', '));
      res.setHeader('Access-Control-Max-Age', maxAge.toString());
      return res.status(204).end();
    }

    if (origin && isOriginAllowed(origin)) {
      setCorsHeaders(res, origin);
      res.setHeader('Vary', 'Origin');
    } else if (!origin) {
      // No origin header (non-browser requests) - allow but don't set CORS headers
    } else {
      // Origin not allowed - don't set CORS headers, browser will block
    }

    next();
  };
}

module.exports = { createCorsMiddleware, DEFAULT_ALLOWED_ORIGINS };
