// corsMiddleware.js
const cors = require('cors');

/**
 * Creates CORS middleware with dynamic origin allowlist.
 * @param {Object} options
 * @param {string[]|Function} options.allowlist - Static array or async function(origin) => boolean
 * @param {string} options.webAppOrigin - Primary web app origin (always allowed)
 * @param {boolean} options.credentials - Allow credentials (default: true)
 */
function createCorsMiddleware({ allowlist = [], webAppOrigin, credentials = true }) {
  const origins = new Set([webAppOrigin].filter(Boolean));

  // Normalize allowlist to array
  const staticOrigins = Array.isArray(allowlist) ? allowlist : [];
  staticOrigins.forEach(o => origins.add(o));

  const isDynamic = typeof allowlist === 'function';

  const corsOptions = {
    credentials,
    methods: ['GET', 'POST', 'PUT', 'PATCH', 'DELETE', 'OPTIONS'],
    allowedHeaders: ['Content-Type', 'Authorization', 'X-Requested-With', 'Accept', 'Origin'],
    exposedHeaders: ['X-Total-Count', 'X-Request-Id'],
    maxAge: 86400, // 24h preflight cache
    origin: (origin, callback) => {
      // Allow non-browser requests (no origin header)
      if (!origin) return callback(null, true);

      // Check static allowlist
      if (origins.has(origin)) return callback(null, true);

      // Check dynamic allowlist (async)
      if (isDynamic) {
        return Promise.resolve(allowlist(origin))
          .then(allowed => callback(null, allowed))
          .catch(err => callback(err));
      }

      callback(new Error('CORS: Origin not allowed'), false);
    }
  };

  const middleware = cors(corsOptions);

  // Explicit OPTIONS handler for preflight (cors handles this, but explicit is clearer)
  return (req, res, next) => {
    if (req.method === 'OPTIONS') {
      return middleware(req, res, () => res.sendStatus(204));
    }
    middleware(req, res, next);
  };
}

module.exports = { createCorsMiddleware };
