// cors-middleware.js
const cors = require('cors');

/**
 * Create configurable CORS middleware
 * @param {Object} options
 * @param {string[]} options.allowedOrigins - List of allowed origins (exact match)
 * @param {RegExp[]} [options.allowedOriginPatterns] - Regex patterns for dynamic origins
 * @param {boolean} [options.credentials=true] - Allow credentials (cookies, auth headers)
 * @param {string[]} [options.allowedMethods] - HTTP methods allowed
 * @param {string[]} [options.allowedHeaders] - Headers allowed in requests
 * @param {number} [options.maxAge=86400] - Preflight cache duration (seconds)
 */
function createCorsMiddleware({
  allowedOrigins = [],
  allowedOriginPatterns = [],
  credentials = true,
  allowedMethods = ['GET', 'POST', 'PUT', 'PATCH', 'DELETE', 'OPTIONS'],
  allowedHeaders = ['Content-Type', 'Authorization', 'X-Requested-With', 'Accept', 'Origin'],
  maxAge = 86400
} = {}) {
  const originWhitelist = new Set(allowedOrigins);

  const corsOptions = {
    origin: (origin, callback) => {
      // Allow non-browser requests (no origin header) or same-origin
      if (!origin) return callback(null, true);

      // Exact match
      if (originWhitelist.has(origin)) return callback(null, true);

      // Pattern match
      for (const pattern of allowedOriginPatterns) {
        if (pattern.test(origin)) return callback(null, true);
      }

      callback(new Error(`CORS: Origin ${origin} not allowed`), false);
    },
    credentials,
    methods: allowedMethods,
    allowedHeaders,
    exposedHeaders: ['X-Request-Id'],
    maxAge,
    optionsSuccessStatus: 204
  };

  return cors(corsOptions);
}

module.exports = { createCorsMiddleware };
