/**
 * CORS middleware with dynamic origin validation.
 * Allowed origins are loaded from config (env, DB, file) at startup.
 * Supports credentials and handles preflight OPTIONS automatically.
 */
function createCorsMiddleware(getAllowedOrigins) {
