// corsMiddleware.js
const cors = require('cors');

/**
 * Load allowed origins from environment variable.
 * Format: comma-separated list, e.g. "https://app.example.com,https://partner1.com"
 * Supports wildcards for subdomains: "https://*.partner.com"
 */
function loadAllowedOrigins() {
  const raw = process.env.CORS_ALLOWED_ORIGINS || '';
  return raw
    .split(',')
    .map(s => s.trim())
    .filter(Boolean);
}

/**
 * Convert wildcard patterns to RegExp for matching.
 * "https://*.partner.com" -> /^https:\/\/[^.]+\.partner\.com$/
 */
function patternToRegex(pattern) {
  const escaped = pattern
    .replace(/[.+?^${}()|[\]\\]/g, '\\$&')  // escape regex special chars
    .replace(/\\\*/g, '[^.]+');              // * -> any subdomain
  return new RegExp(`^${escaped}$`);
}

/**
 * Check if origin is allowed.
 * Returns true for exact matches or wildcard pattern matches.
 */
function isOriginAllowed(origin, allowedPatterns) {
  if (!origin) return false; // non-browser requests may lack origin

  for (const pattern of allowedPatterns) {
    if (pattern.includes('*')) {
      if (patternToRegex(pattern).test(origin)) return true;
    } else if (pattern === origin) {
      return true;
    }
  }
  return false;
}

/**
 * CORS middleware factory.
 * Reads allowed origins on each request to support dynamic updates without restart.
 */
function corsMiddleware() {
  const allowedPatterns = loadAllowedOrigins();

  return (req, res, next) => {
    const origin = req.headers.origin;

    // Handle preflight OPTIONS request
    if (req.method === 'OPTIONS') {
      // Always respond to preflight, but only set CORS headers if origin allowed
      if (isOriginAllowed(origin, allowedPatterns)) {
        res.setHeader('Access-Control-Allow-Origin', origin);
        res.setHeader('Access-Control-Allow-Credentials', 'true');
        res.setHeader('Access-Control-Allow-Methods', 'GET,HEAD,PUT,PATCH,POST,DELETE,OPTIONS');
        res.setHeader('Access-Control-Allow-Headers', 'Content-Type,Authorization,X-Requested-With');
        res.setHeader('Access-Control-Max-Age', '86400'); // 24 hours
      }
      return res.sendStatus(204);
    }

    // Actual request - set CORS headers if origin allowed
    if (isOriginAllowed(origin, allowedPatterns)) {
      res.setHeader('Access-Control-Allow-Origin', origin);
      res.setHeader('Access-Control-Allow-Credentials', 'true');
      // Expose custom headers to client if needed
      res.setHeader('Access-Control-Expose-Headers', 'X-Request-Id');
    }

    // Vary header tells caches that response varies by Origin
    res.setHeader('Vary', 'Origin');

    next();
  };
}

module.exports = { corsMiddleware, loadAllowedOrigins, isOriginAllowed };
