CORS_ALLOWED_ORIGINS=https://app.example.com,https://admin.example.com,https://*.partner.com,https://partner2.com
```

**Key features:**
- **Dynamic config** - reads `CORS_ALLOWED_ORIGINS` on each request; update env var without restart
- **Wildcard support** - `https://*.partner.com` matches any subdomain
- **Credentials enabled** - `Access-Control-Allow-Credentials: true` for cookies/auth headers
- **Preflight handled** - responds to `OPTIONS` with proper headers and `204 No Content`
- **Security** - only reflects allowed origins, never `*` when credentials are used
- **Cache-friendly** - includes `Vary: Origin` header

```javascript
// cors-middleware.js
const cors = require('cors');

/**
 * CORS configuration - add partner origins here as they're onboarded
 * Supports exact matches, regex patterns, or functions for dynamic validation
 */
const corsConfig = {
  // Your web app origin(s)
  webApp: [
    'https://app.yourcompany.com',
    'https://staging.yourcompany.com',
    'http://localhost:3000',  // dev
  ],

  // Partner origins - add new partners here
  partners: [
    'https://partner1.com',
    'https://partner2.com',
    // Regex example for subdomains: /^https:\/\/.*\.partner3\.com$/
  ],

  // Allowed HTTP methods
  methods: ['GET', 'POST', 'PUT', 'PATCH', 'DELETE', 'OPTIONS'],

  // Allowed headers
  allowedHeaders: [
    'Content-Type',
    'Authorization',
    'X-Requested-With',
    'Accept',
    'Origin',
    'X-Partner-ID',  // custom header for partner identification
  ],

  // Headers exposed to the client
  exposedHeaders: ['X-Request-ID', 'X-RateLimit-Remaining'],

  // Cache preflight response for 24 hours
  maxAge: 86400,

  // Allow credentials (cookies, auth headers)
  credentials: true,
};

/**
 * Build the complete origin list from config
 */
function getAllowedOrigins() {
  return [...corsConfig.webApp, ...corsConfig.partners];
}

/**
 * Custom origin validator - supports exact, regex, and function matchers
 */
function originValidator(origin, callback) {
  // Allow non-browser requests (no origin header) - e.g., server-to-server
  if (!origin) return callback(null, true);

  const allowedOrigins = getAllowedOrigins();

  const isAllowed = allowedOrigins.some(allowed => {
    if (typeof allowed === 'string') {
      return allowed === origin;
    }
    if (allowed instanceof RegExp) {
      return allowed.test(origin);
    }
    if (typeof allowed === 'function') {
      return allowed(origin);
    }
    return false;
  });

  if (isAllowed) {
    callback(null, true);
  } else {
    callback(new Error(`CORS: Origin ${origin} not allowed`), false);
  }
}

/**
 * Create the CORS middleware
 */
function createCorsMiddleware(customOptions = {}) {
  const options = {
    origin: originValidator,
    methods: corsConfig.methods,
    allowedHeaders: corsConfig.allowedHeaders,
    exposedHeaders: corsConfig.exposedHeaders,
    credentials: corsConfig.credentials,
    maxAge: corsConfig.maxAge,
    optionsSuccessStatus: 204,  // Some legacy browsers choke on 200
    ...customOptions,
  };

  return cors(options);
}

/**
 * Helper to add a partner origin at runtime (e.g., from admin panel)
 */
function addPartnerOrigin(origin) {
  if (!corsConfig.partners.includes(origin)) {
    corsConfig.partners.push(origin);
  }
}

/**
 * Helper to remove a partner origin
 */
function removePartnerOrigin(origin) {
  const idx = corsConfig.partners.indexOf(origin);
  if (idx > -1) corsConfig.partners.splice(idx, 1);
}

module.exports = {
  createCorsMiddleware,
  addPartnerOrigin,
  removePartnerOrigin,
  getAllowedOrigins,
  corsConfig,  // exposed for inspection/debugging
};
