const cors = require('cors');

/**
 * Creates CORS middleware with configurable allowed origins.
 * Supports credentials and handles OPTIONS preflight automatically.
 * 
 * @param {Object} options
 * @param {string[]} options.allowedOrigins - List of allowed origins (exact match or regex patterns)
 * @param {string} options.ourWebAppOrigin - Our web app origin (always allowed)
 * @returns {Function} Express middleware
 */
function createCorsMiddleware({ allowedOrigins = [], ourWebAppOrigin }) {
  const allOrigins = [ourWebAppOrigin, ...allowedOrigins].filter(Boolean);

  const corsOptions = {
    origin: (origin, callback) => {
      // Allow non-browser requests (no origin header)
      if (!origin) return callback(null, true);

      const isAllowed = allOrigins.some(allowed => {
        if (allowed instanceof RegExp) return allowed.test(origin);
        return allowed === origin;
      });

      if (isAllowed) {
        callback(null, true);
      } else {
        callback(new Error(`CORS: Origin ${origin} not allowed`));
      }
    },
    credentials: true,                    // Allow cookies/auth headers
    methods: ['GET', 'POST', 'PUT', 'PATCH', 'DELETE', 'OPTIONS'],
    allowedHeaders: ['Content-Type', 'Authorization', 'X-Requested-With'],
    exposedHeaders: ['X-Total-Count'],    // Headers client can read
    maxAge: 86400,                        // Cache preflight for 24h
    optionsSuccessStatus: 204             // No content for preflight
  };

  return cors(corsOptions);
}

module.exports = { createCorsMiddleware };
