// corsMiddleware.js
const cors = require('cors');

/**
 * CORS middleware with configurable allowlist and credentials support.
 * Allowlist can be loaded from environment variable or config file.
 * Format: comma-separated origins (e.g., "https://app.example.com,https://partner1.com")
 */
function createCorsMiddleware(options = {}) {
  const {
    allowlist = process.env.CORS_ALLOWLIST?.split(',').map(s => s.trim()) || [],
    allowlistFile = process.env.CORS_ALLOWLIST_FILE,
    credentials = true,
    methods = ['GET', 'POST', 'PUT', 'PATCH', 'DELETE', 'OPTIONS'],
    allowedHeaders = ['Content-Type', 'Authorization', 'X-Requested-With'],
    exposedHeaders = ['X-Total-Count', 'X-Request-Id'],
    maxAge = 86400 // 24 hours
  } = options;

  // Load allowlist from file if specified (one origin per line)
  let dynamicAllowlist = [...allowlist];
  if (allowlistFile) {
    try {
      const fs = require('fs');
      const fileOrigins = fs.readFileSync(allowlistFile, 'utf-8')
        .split('\n')
        .map(line => line.trim())
        .filter(line => line && !line.startsWith('#'));
      dynamicAllowlist = [...dynamicAllowlist, ...fileOrigins];
    } catch (err) {
      console.warn(`[CORS] Failed to load allowlist from ${allowlistFile}:`, err.message);
    }
  }

  const allowlistSet = new Set(dynamicAllowlist);

  const corsOptions = {
    origin: (origin, callback) => {
      // Allow non-browser requests (no origin header) and same-origin
      if (!origin) return callback(null, true);

      if (allowlistSet.has(origin)) {
        return callback(null, true);
      }

      // Allow subdomains of configured origins (optional: enable via env)
      if (process.env.CORS_ALLOW_SUBDOMAINS === 'true') {
        const matched = dynamicAllowlist.some(allowed => {
          try {
            const allowedHost = new URL(allowed).hostname;
            const originHost = new URL(origin).hostname;
            return originHost === allowedHost || originHost.endsWith(`.${allowedHost}`);
          } catch {
            return false;
          }
        });
        if (matched) return callback(null, true);
      }

      callback(new Error(`CORS: Origin ${origin} not allowed`), false);
    },
    credentials,
    methods,
    allowedHeaders,
    exposedHeaders,
    maxAge,
    optionsSuccessStatus: 204
  };

  const corsMiddleware = cors(corsOptions);

  // Explicit OPTIONS handler for preflight (cors handles this, but explicit is clearer)
  return (req, res, next) => {
    if (req.method === 'OPTIONS') {
      return corsMiddleware(req, res, () => {
        res.status(204).end();
      });
    }
    corsMiddleware(req, res, next);
  };
}

module.exports = { createCorsMiddleware };
