// corsMiddleware.js
const cors = require('cors');

/**
 * Creates CORS middleware with configurable allowed origins.
 * Supports credentials and handles OPTIONS preflight automatically.
 * 
 * @param {Object} options
 * @param {string[]} options.allowedOrigins - List of allowed origins (exact match)
 * @param {string[]} [options.allowedOriginPatterns] - Regex patterns for dynamic origins
 * @param {string[]} [options.allowedMethods] - HTTP methods to allow
 * @param {string[]} [options.allowedHeaders] - Headers to allow in requests
 * @param {number} [options.maxAge] - Preflight cache duration in seconds
 */
function createCorsMiddleware({
  allowedOrigins = [],
  allowedOriginPatterns = [],
  allowedMethods = ['GET', 'POST', 'PUT', 'PATCH', 'DELETE', 'OPTIONS'],
  allowedHeaders = ['Content-Type', 'Authorization', 'X-Requested-With'],
  maxAge = 86400 // 24 hours
} = {}) {
  // Build origin validator: exact matches + regex patterns
  const originValidator = (origin, callback) => {
    // Allow non-browser requests (no origin header) - e.g., mobile apps, curl
    if (!origin) return callback(null, true);

    // Check exact matches
    if (allowedOrigins.includes(origin)) return callback(null, true);

    // Check regex patterns
    const matched = allowedOriginPatterns.some(pattern => pattern.test(origin));
    if (matched) return callback(null, true);

    callback(new Error(`CORS: Origin ${origin} not allowed`), false);
  };

  return cors({
    origin: originValidator,
    credentials: true,                    // Allow cookies/auth headers
    methods: allowedMethods,
    allowedHeaders: allowedHeaders,
    exposedHeaders: ['X-Total-Count'],    // Headers client can read
    maxAge: maxAge,                       // Cache preflight response
    preflightContinue: false,             // Let cors handle OPTIONS
    optionsSuccessStatus: 204             // No content for preflight
  });
}

module.exports = { createCorsMiddleware };
