const corsMiddleware = (allowedOrigins = []) => {
  // Normalize origins to lowercase for case-insensitive matching
  const originSet = new Set(allowedOrigins.map(o => o.toLowerCase()));

  // Check if origin is allowed (supports exact match and subdomain wildcards)
  const isOriginAllowed = (origin) => {
    if (!origin) return false;
    const lowerOrigin = origin.toLowerCase();
    if (originSet.has(lowerOrigin)) return true;
    // Support wildcard subdomains: *.example.com
    for (const allowed of originSet) {
      if (allowed.startsWith('*.')) {
        const domain = allowed.slice(2);
        if (lowerOrigin.endsWith('.' + domain) || lowerOrigin === domain) {
          return true;
        }
      }
    }
    return false;
  };

  return (req, res, next) => {
    const origin = req.headers.origin;

    // Handle preflight OPTIONS request
    if (req.method === 'OPTIONS') {
      // Only set CORS headers if origin is allowed
      if (origin && isOriginAllowed(origin)) {
        res.setHeader('Access-Control-Allow-Origin', origin);
        res.setHeader('Access-Control-Allow-Credentials', 'true');
        res.setHeader('Access-Control-Allow-Methods', 'GET,HEAD,PUT,PATCH,POST,DELETE,OPTIONS');
        res.setHeader('Access-Control-Allow-Headers', 'Content-Type,Authorization,X-Requested-With,Accept,Origin');
        res.setHeader('Access-Control-Max-Age', '86400'); // 24 hours
      }
      // Respond to preflight with 204 No Content
      return res.sendStatus(204);
    }

    // Actual request - set CORS headers if origin allowed
    if (origin && isOriginAllowed(origin)) {
      res.setHeader('Access-Control-Allow-Origin', origin);
      res.setHeader('Access-Control-Allow-Credentials', 'true');
      // Expose headers your frontend might need
      res.setHeader('Access-Control-Expose-Headers', 'X-Total-Count,X-Page-Count');
    }

    // Vary header tells caches to vary by Origin
    res.setHeader('Vary', 'Origin');

    next();
  };
};

module.exports = corsMiddleware;
