// corsMiddleware.js
const cors = require('cors');

/**
 * Creates CORS middleware with configurable allowed origins.
 * Supports credentials and handles OPTIONS preflight automatically.
 * 
 * @param {Object} options
 * @param {string[]} options.allowedOrigins - List of allowed origins (exact match)
 * @param {string[]} [options.allowedOriginPatterns] - Optional regex patterns for dynamic matching
 * @param {string[]} [options.allowedMethods] - HTTP methods to allow
 * @param {string[]} [options.allowedHeaders] - Headers to allow in requests
 * @param {number} [options.maxAge] - Preflight cache duration in seconds
 */
function createCorsMiddleware({
  allowedOrigins = [],
  allowedOriginPatterns = [],
  allowedMethods = ['GET', 'POST', 'PUT', 'PATCH', 'DELETE', 'OPTIONS'],
  allowedHeaders = ['Content-Type', 'Authorization', 'X-Requested-With', 'Accept', 'Origin'],
  maxAge = 86400 // 24 hours
} = {}) {
  // Normalize origins to lowercase for case-insensitive matching
  const normalizedOrigins = new Set(allowedOrigins.map(o => o.toLowerCase()));
  const compiledPatterns = allowedOriginPatterns.map(p => new RegExp(p));

  const corsOptions = {
    // Dynamic origin validation
    origin: (origin, callback) => {
      // Allow non-browser requests (no origin header) like curl, Postman, server-to-server
      if (!origin) return callback(null, true);

      const lowerOrigin = origin.toLowerCase();

      // Exact match
      if (normalizedOrigins.has(lowerOrigin)) {
        return callback(null, true);
      }

      // Pattern match
      for (const pattern of compiledPatterns) {
        if (pattern.test(lowerOrigin)) {
          return callback(null, true);
        }
      }

      // Origin not allowed
      callback(new Error(`CORS: Origin ${origin} not allowed`), false);
    },

    // Required for cookies, Authorization headers, etc.
    credentials: true,

    // Expose headers the frontend may need to read
    exposedHeaders: ['X-Total-Count', 'X-Request-Id'],

    // Preflight configuration
    methods: allowedMethods,
    allowedHeaders: allowedHeaders,
    maxAge: maxAge,

    // Handle preflight OPTIONS requests automatically
    preflightContinue: false,
    optionsSuccessStatus: 204
  };

  return cors(corsOptions);
}

module.exports = { createCorsMiddleware };
