      const isAllowedSubdomain = allowedOrigins.some(allowed => {
        if (!allowed.includes('*')) return false;
        const pattern = allowed.replace(/\./g, '\\.').replace('*', '.*');
        return new RegExp(`^${pattern}$`).test(origin);
