// corsMiddleware.js
const cors = require('cors');

/**
 * Build CORS options from configuration.
 * ALLOWED_ORIGINS: comma-separated list, e.g. "https://app.example.com,https://partner1.com"
 * Supports wildcard subdomains: "https://*.partner.com"
 */
function buildCorsOptions() {
  const raw = process.env.ALLOWED_ORIGINS || '';
  const origins = raw
    .split(',')
    .map(s => s.trim())
    .filter(Boolean);

  // Convert wildcard patterns to regex
  const originPatterns = origins.map(origin => {
    if (origin.includes('*')) {
      const escaped = origin
        .replace(/[.+?^${}()|[\]\\]/g, '\\$&')  // escape regex special chars
        .replace(/\\\*/g, '.*');                 // * -> .*
      return new RegExp(`^${escaped}$`);
    }
    return origin;
  });

  return {
    origin: (requestOrigin, callback) => {
      // Allow non-browser requests (no Origin header) — e.g., server-to-server
      if (!requestOrigin) return callback(null, true);

      const allowed = originPatterns.some(pattern =>
        pattern instanceof RegExp ? pattern.test(requestOrigin) : pattern === requestOrigin
      );

      if (allowed) {
        callback(null, true);
      } else {
        callback(new Error(`CORS: Origin ${requestOrigin} not allowed`));
      }
    },
    credentials: true,                    // allow cookies, Authorization header
    methods: ['GET', 'POST', 'PUT', 'PATCH', 'DELETE', 'OPTIONS'],
    allowedHeaders: [
      'Content-Type',
      'Authorization',
      'X-Requested-With',
      'Accept',
      'Origin',
      'X-CSRF-Token'
    ],
    exposedHeaders: ['X-Request-Id'],     // headers the frontend may read
    maxAge: 86400,                        // cache preflight for 24h
    optionsSuccessStatus: 204             // some legacy browsers choke on 200
  };
}

const corsMiddleware = cors(buildCorsOptions());

module.exports = corsMiddleware;
