// corsMiddleware.js
const DEFAULT_ALLOWED_ORIGINS = [
  'https://your-web-app.com',
  'https://www.your-web-app.com'
];

/**
 * Creates a CORS middleware with configurable allowed origins.
 * @param {Object} options
 * @param {string[]} options.allowedOrigins - Additional origins to allow (partners)
 * @param {boolean} options.allowCredentials - Allow cookies/auth headers (default: true)
 * @param {string[]} options.allowedMethods - HTTP methods to allow
 * @param {string[]} options.allowedHeaders - Headers to allow in requests
 * @param {number} options.maxAge - Preflight cache duration in seconds
 */
function createCorsMiddleware({
  allowedOrigins = [],
  allowCredentials = true,
  allowedMethods = ['GET', 'POST', 'PUT', 'PATCH', 'DELETE', 'OPTIONS'],
  allowedHeaders = ['Content-Type', 'Authorization', 'X-Requested-With', 'Accept', 'Origin'],
  maxAge = 86400 // 24 hours
} = {}) {
  const allAllowedOrigins = [...DEFAULT_ALLOWED_ORIGINS, ...allowedOrigins];
  const allowedMethodsStr = allowedMethods.join(', ');
  const allowedHeadersStr = allowedHeaders.join(', ');

  return (req, res, next) => {
    const origin = req.headers.origin;
    const isAllowed = origin && allAllowedOrigins.includes(origin);

    // Set CORS headers for allowed origins
    if (isAllowed) {
      res.setHeader('Access-Control-Allow-Origin', origin);
      res.setHeader('Vary', 'Origin');
    }

    if (allowCredentials) {
      res.setHeader('Access-Control-Allow-Credentials', 'true');
    }

    // Handle preflight OPTIONS request
    if (req.method === 'OPTIONS') {
      if (isAllowed) {
        res.setHeader('Access-Control-Allow-Methods', allowedMethodsStr);
        res.setHeader('Access-Control-Allow-Headers', allowedHeadersStr);
        res.setHeader('Access-Control-Max-Age', maxAge.toString());
        return res.sendStatus(204);
      }
      // Origin not allowed - don't set CORS headers, return 403
      return res.sendStatus(403);
    }

    // For non-OPTIONS requests, still set headers if origin allowed
    if (isAllowed) {
      res.setHeader('Access-Control-Allow-Methods', allowedMethodsStr);
      res.setHeader('Access-Control-Allow-Headers', allowedHeadersStr);
    }

    next();
  };
}

module.exports = { createCorsMiddleware, DEFAULT_ALLOWED_ORIGINS };
