 * Reads allowed origins from config (array or comma-separated string).
 * Supports credentials and handles preflight automatically.
 */
function createCorsMiddleware(allowedOrigins = []) {
  // Normalize config: accept array or comma-separated string
  const origins = Array.isArray(allowedOrigins)
    ? allowedOrigins
    : String(allowedOrigins).split(',').map(s => s.trim()).filter(Boolean);

  const corsOptions = {
    origin: (origin, callback) => {
      // Allow non-browser requests (no origin header) or whitelisted origins
      if (!origin || origins.includes(origin)) {
        return callback(null, true);
      }
      callback(new Error(`CORS: Origin ${origin} not allowed`));
    },
    credentials: true,                 // Allow cookies/auth headers
    methods: ['GET', 'POST', 'PUT', 'PATCH', 'DELETE', 'OPTIONS'],
    allowedHeaders: ['Content-Type', 'Authorization', 'X-Requested-With'],
    exposedHeaders: ['X-Total-Count'], // Example: expose custom headers
    maxAge: 86400,                     // Cache preflight 24h
    optionsSuccessStatus: 204          // No content for preflight
  };

  return cors(corsOptions);
}

module.exports = { createCorsMiddleware };
```

