```javascript
const cors = require('cors');

/**
 * Configurable CORS middleware for Express
 * 
 * Usage:
 *   const corsMiddleware = createCorsMiddleware({
 *     allowedOrigins: ['https://app.example.com', 'https://partner1.com'],
 *     credentials: true
 *   });
 *   app.use(corsMiddleware);
 * 
 * To add partners later:
 *   corsMiddleware.addOrigin('https://new-partner.com');
 */
function createCorsMiddleware(options = {}) {
  const {
    allowedOrigins = [],
    credentials = true,
    methods = ['GET', 'POST', 'PUT', 'PATCH', 'DELETE', 'OPTIONS'],
    allowedHeaders = ['Content-Type', 'Authorization', 'X-Requested-With'],
    exposedHeaders = [],
    maxAge = 86400 // 24 hours
  } = options;

  const originSet = new Set(allowedOrigins);

  // Dynamic origin checker
  const originChecker = (origin, callback) => {
    // Allow non-browser requests (no origin header) or configured origins
    if (!origin || originSet.has(origin)) {
      callback(null, true);
    } else {
      callback(new Error(`CORS: Origin ${origin} not allowed`), false);
    }
  };

  const corsOptions = {
    origin: originChecker,
    credentials,
    methods,
    allowedHeaders,
    exposedHeaders,
    maxAge,
    preflightContinue: false,
    optionsSuccessStatus: 204
  };

  const middleware = cors(corsOptions);

  // Attach helper methods for runtime configuration
  middleware.addOrigin = (origin) => {
    if (typeof origin === 'string') {
      originSet.add(origin);
    } else if (Array.isArray(origin)) {
      origin.forEach(o => originSet.add(o));
    }
  };

  middleware.removeOrigin = (origin) => {
    originSet.delete(origin);
  };

  middleware.getOrigins = () => Array.from(originSet);

  return middleware;
}

module.exports = { createCorsMiddleware };
```

