  'https://your-web-app.com',  // Your main web app
  // Partners added here over time
]);

/**
 * Add a partner origin to allowed list
 * @param {string} origin - Partner's origin (e.g., 'https://partner-site.com')
 */
function addPartnerOrigin(origin) {
  allowedOrigins.add(origin);
}

/**
 * Remove a partner origin
 * @param {string} origin - Partner's origin to remove
 */
function removePartnerOrigin(origin) {
  allowedOrigins.delete(origin);
}

/**
 * Get current allowed origins
 * @returns {string[]}
 */
function getAllowedOrigins() {
  return Array.from(allowedOrigins);
}

// CORS configuration
const corsOptions = {
  // Dynamic origin validation
  origin: (origin, callback) => {
    // Allow requests with no origin (mobile apps, curl, etc.)
    if (!origin) return callback(null, true);

    if (allowedOrigins.has(origin)) {
      callback(null, true);
    } else {
      callback(new Error(`CORS: Origin ${origin} not allowed`));
    }
  },

  // Allow credentials (cookies, auth headers)
  credentials: true,

  // Allowed HTTP methods
  methods: ['GET', 'POST', 'PUT', 'PATCH', 'DELETE', 'OPTIONS'],

  // Allowed headers
  allowedHeaders: [
    'Content-Type',
    'Authorization',
    'X-Requested-With',
    'Accept',
    'Origin',
    'X-CSRF-Token'
  ],

  // Exposed headers for client access
  exposedHeaders: ['X-Total-Count', 'X-Page-Count'],

  // Cache preflight response for 24 hours
  maxAge: 86400,

  // Handle preflight OPTIONS requests
  preflightContinue: false,
  optionsSuccessStatus: 204
};

// Create middleware
const corsMiddleware = cors(corsOptions);

// Export middleware and management functions
module.exports = {
  corsMiddleware,
  addPartnerOrigin,
  removePartnerOrigin,
  getAllowedOrigins,
  allowedOrigins  // Direct access if needed
};
