router.get('/go', (req, res) => {
  const targetUrl = req.query.url;

  // Validate presence
  if (!targetUrl) {
    return res.status(400).send('Missing required "url" query parameter');
  }

  // Validate URL format and safety (basic check)
  let parsed;
  try {
    parsed = new URL(targetUrl);
    // Only allow http/https
    if (!['http:', 'https:'].includes(parsed.protocol)) {
      throw new Error('Invalid protocol');
    }
  } catch (e) {
    return res.status(400).send('Invalid URL format');
  }

  // Log the click (timestamp, target, referrer, IP)
  const logEntry = {
    timestamp: new Date().toISOString(),
    targetUrl: targetUrl,
    referrer: req.get('Referrer') || 'direct',
    ip: req.ip
  };
  clickLog.push(logEntry);
  console.log('Outbound click:', logEntry);

  // Redirect
  res.redirect(302, targetUrl);
});

module.exports = router;
