const express = require('express');
const router = express.Router();

router.get('/go', (req, res) => {
  const target = req.query.url;

  // Validate presence
  if (!target) {
    return res.status(400).send('Missing required query parameter: url');
  }

  // Basic URL validation (optional but recommended)
  let parsed;
  try {
    parsed = new URL(target);
    // Allow only http/https schemes
    if (!['http:', 'https:'].includes(parsed.protocol)) {
      throw new Error('Invalid protocol');
    }
  } catch (e) {
    return res.status(400).send('Invalid URL supplied');
  }

  // Log the outbound click (replace with your preferred logger)
  console.info(`Outbound click logged: ${target} from IP ${req.ip}`);

  // Perform the redirect
  res.redirect(302, target);
});

module.exports = router;
