    """In‑memory session store with 24‑hour TTL."""

    def __init__(self):
        # session_id -> (user_id, expiry_timestamp)
        self._sessions = {}

    def _now(self):
        """Current time in seconds since epoch."""
        import time
        return time.time()

    def _cleanup_expired(self):
        """Remove sessions whose expiry has passed."""
        now = self._now()
        expired = [sid for sid, (_, exp) in self._sessions.items() if exp <= now]
        for sid in expired:
            del self._sessions[sid]

    def create(self, user_id):
        """Create a new session for user_id and return its session id."""
        import uuid, time
        self._cleanup_expired()
        session_id = uuid.uuid4().hex
        expiry = self._now() + 24 * 3600  # 24 hours
        self._sessions[session_id] = (user_id, expiry)
        return session_id

    def get_user(self, session_id):
        """Return user_id for a valid session, otherwise None."""
        self._cleanup_expired()
        entry = self._sessions.get(session_id)
        if entry:
            user_id, expiry = entry
            if expiry > self._now():
                return user_id
        return None

    def destroy(self, session_id):
        """Remove a session explicitly."""
        self._sessions.pop(session_id, None)

