import uuid
import time

class SessionStore:
    def __init__(self):
        # session_id -> (user_id, expiry_timestamp)
        self._sessions = {}

    def create(self, user_id):
        """Create a new session for user_id, return session_id."""
        session_id = uuid.uuid4().hex
        expiry = time.time() + 24 * 3600  # 24 hours from now
        self._sessions[session_id] = (user_id, expiry)
        return session_id

    def get_user(self, session_id):
        """Return user_id if session exists and not expired, else None."""
        entry = self._sessions.get(session_id)
        if not entry:
            return None
        user_id, expiry = entry
        if time.time() > expiry:
            # expired, clean up
            del self._sessions[session_id]
            return None
        return user_id

    def destroy(self, session_id):
        """Remove session if it exists."""
        self._sessions.pop(session_id, None)

