const cookieParser = require('cookie-parser');

// Secret for signing cookies (should be stored securely in env)
const COOKIE_SECRET = process.env.COOKIE_SECRET || 'your-secret-key';

// Middleware to parse signed cookies
const cookieParserMiddleware = cookieParser(COOKIE_SECRET);

/**
 * Sets a signed remember-me cookie with the user's ID.
 * Call this after successful login.
 * @param {Object} res - Express response object
 * @param {number|string} userId - The user's ID
 */
function setRememberMeCookie(res, userId) {
  // 30 days in milliseconds
  const maxAge = 30 * 24 * 60 * 60 * 1000;
  res.cookie('remember_me', userId, {
    signed: true,      // sign the cookie to prevent tampering
    httpOnly: true,    // prevent client-side JS access
    secure: process.env.NODE_ENV === 'production', // HTTPS only in production
    maxAge,            // expires in 30 days
    sameSite: 'lax'    // CSRF protection
  });
}

/**
 * Middleware that reads the remember-me cookie and attaches the user to req.user.
 * Assumes db.getUserById(id) returns a Promise resolving to the user object or null.
 * @param {Object} db - Database module with getUserById method
 */
function rememberMeMiddleware(db) {
  return async (req, res, next) => {
    // If user already attached (e.g., via session), skip
    if (req.user) return next();

    const userId = req.signedCookies?.remember_me;
    if (!userId) return next();

    try {
      const user = await db.getUserById(userId);
      if (user) {
        req.user = user; // attach user to request
      }
    } catch (err) {
      console.error('Remember-me lookup failed:', err);
    }
    next();
  };
}

module.exports = {
  cookieParserMiddleware,
  setRememberMeCookie,
  rememberMeMiddleware
};

