// rememberMeMiddleware.js
const cookieParser = require('cookie-parser');

// Secret for signing cookies (in production use env variable)
const COOKIE_SECRET = process.env.COOKIE_SECRET || 'your-secret-key';
const REMEMBER_COOKIE_NAME = 'remember_me';
const COOKIE_MAX_AGE = 30 * 24 * 60 * 60 * 1000; // 30 days

/**
 * Middleware to set remember-me cookie after successful login.
 * Expects req.user to be set (authenticated user object with id).
 */
function setRememberMeCookie(req, res, next) {
  if (req.user && req.user.id) {
    res.cookie(REMEMBER_COOKIE_NAME, req.user.id, {
      signed: true,
      maxAge: COOKIE_MAX_AGE,
      httpOnly: true,
      secure: process.env.NODE_ENV === 'production',
      sameSite: 'lax'
    });
  }
  next();
}

/**
 * Middleware to restore req.user from remember-me cookie.
 * Should be placed after cookie-parser(secret) and before routes needing auth.
 */
async function restoreUserFromRememberMe(req, res, next) {
  try {
    const userId = req.signedCookies[REMEMBER_COOKIE_NAME];
    if (userId) {
      const user = await db.getUserById(userId);
      if (user) {
        req.user = user;
      } else {
        // User not found, clear invalid cookie
        res.clearCookie(REMEMBER_COOKIE_NAME);
      }
    }
    next();
  } catch (err) {
    next(err);
  }
}

/**
 * Middleware to clear remember-me cookie on logout.
 */
function clearRememberMeCookie(req, res, next) {
  res.clearCookie(REMEMBER_COOKIE_NAME);
  next();
}

module.exports = {
  setRememberMeCookie,
  restoreUserFromRememberMe,
  clearRememberMeCookie,
  cookieParser: cookieParser(COOKIE_SECRET)
