const cookieParser = require('cookie-parser');
const crypto = require('crypto');

const REMEMBER_COOKIE = 'remember_me';
const COOKIE_MAX_AGE = 30 * 24 * 60 * 60 * 1000; // 30 days

function generateToken() {
  return crypto.randomBytes(32).toString('hex');
}

function hashToken(token) {
  return crypto.createHash('sha256').update(token).digest('hex');
}

function rememberMeMiddleware(db) {
  return [
    cookieParser(),
    async (req, res, next) => {
      // Restore user from remember-me cookie
      const token = req.cookies[REMEMBER_COOKIE];
      if (token && !req.user) {
        const hashed = hashToken(token);
        const user = await db.getUserByRememberToken(hashed);
        if (user && user.remember_expires > Date.now()) {
          req.user = user;
        }
      }
      next();
    }
  ];
}

function setRememberMeCookie(res, user, db) {
  const token = generateToken();
  const hashed = hashToken(token);
  const expires = Date.now() + COOKIE_MAX_AGE;

  db.setUserRememberToken(user.id, hashed, expires);

  res.cookie(REMEMBER_COOKIE, token, {
    httpOnly: true,
    secure: process.env.NODE_ENV === 'production',
    sameSite: 'lax',
    maxAge: COOKIE_MAX_AGE
  });
}

function clearRememberMeCookie(res, user, db) {
  if (user) db.clearUserRememberToken(user.id);
  res.clearCookie(REMEMBER_COOKIE);
}

module.exports = { rememberMeMiddleware, setRememberMeCookie, clearRememberMeCookie };

