const cookieParser = require('cookie-parser');
const crypto = require('crypto');

// Secret for signing cookies (in production, use env variable)
const COOKIE_SECRET = process.env.COOKIE_SECRET || 'super-secret-change-me';
const COOKIE_NAME = 'remember_me';
const COOKIE_OPTIONS = {
  httpOnly: true,
  secure: process.env.NODE_ENV === 'production', // HTTPS only in production
  sameSite: 'lax',
  maxAge: 30 * 24 * 60 * 60 * 1000, // 30 days
  signed: true
};

/**
 * Middleware to parse signed cookies.
 * Use once in your app: app.use(cookieParser(COOKIE_SECRET));
 */
const parseCookies = cookieParser(COOKIE_SECRET);

/**
 * Generates a tamper-proof token payload for the remember-me cookie.
 * @param {string|number} userId
 * @returns {object} { userId, expires, sig }
 */
function createTokenPayload(userId) {
  const expires = Date.now() + COOKIE_OPTIONS.maxAge;
  const data = `${userId}:${expires}`;
  const sig = crypto.createHmac('sha256', COOKIE_SECRET).update(data).digest('hex');
  return { userId, expires, sig };
}

/**
 * Verifies the token payload signature and expiration.
 * @param {object} payload
 * @returns {boolean}
 */
function verifyTokenPayload(payload) {
  if (!payload || !payload.userId || !payload.expires || !payload.sig) return false;
  if (Date.now() > payload.expires) return false;
  const data = `${payload.userId}:${payload.expires}`;
  const expectedSig = crypto.createHmac('sha256', COOKIE_SECRET).update(data).digest('hex');
  return crypto.timingSafeEqual(Buffer.from(payload.sig), Buffer.from(expectedSig));
}

/**
 * Sets the remember-me cookie on successful login.
 * Call this in your login route after authenticating the user.
 * @param {Response} res
 * @param {string|number} userId
 */
function setRememberMeCookie(res, userId) {
  const token = createTokenPayload(userId);
  res.cookie(COOKIE_NAME, token, COOKIE_OPTIONS);
}

/**
 * Clears the remember-me cookie (e.g., on logout).
 * @param {Response} res
 */
function clearRememberMeCookie(res) {
  res.clearCookie(COOKIE_NAME, { ...COOKIE_OPTIONS, maxAge: 0 });
}

/**
 * Express middleware that reads the remember-me cookie and restores req.user.
 * Place this after cookieParser and before routes that need req.user.
 * @param {object} db - Database module with getUserById(userId) method.
 */
function rememberMeMiddleware(db) {
  return async (req, res, next) => {
    // If user already set (e.g., by session), skip
    if (req.user) return next();

    const token = req.signedCookies[COOKIE_NAME];
    if (!token) return next();

    if (!verifyTokenPayload(token)) {
      // Invalid or expired token -> clear cookie
      clearRememberMeCookie(res);
      return next();
    }

    try {
      const user = await db.getUserById(token.userId);
      if (user) {
        req.user = user; // Attach user to request
      } else {
        // User not found -> clear cookie
        clearRememberMeCookie(res);
      }
    } catch (err) {
      console.error('Remember-me lookup failed:', err);
    }
    next();
  };
}

