// In-memory token store (replace with Redis/DB in production)
const tokenStore = new Map();

// Generate secure random token
function generateToken() {
  return crypto.randomBytes(32).toString('hex');
}

// Hash token for storage (never store raw tokens)
function hashToken(token) {
  return crypto.createHash('sha256').update(token).digest('hex');
}

// Middleware to set remember-me cookie on login
function setRememberMeCookie(userId, res) {
  const token = generateToken();
  const tokenHash = hashToken(token);
  const expiresAt = Date.now() + 30 * 24 * 60 * 60 * 1000; // 30 days

  // Store hashed token with userId and expiry
  tokenStore.set(tokenHash, { userId, expiresAt });

  // Set HttpOnly, Secure, SameSite=Lax cookie
  res.cookie('remember_me', token, {
    httpOnly: true,
    secure: process.env.NODE_ENV === 'production',
    sameSite: 'lax',
    maxAge: 30 * 24 * 60 * 60 * 1000,
    path: '/'
  });
}

// Middleware to restore user from remember-me cookie
async function rememberMeMiddleware(req, res, next) {
  const token = req.cookies?.remember_me;
  if (!token) return next();

  const tokenHash = hashToken(token);
  const record = tokenStore.get(tokenHash);

  // Validate token exists and not expired
  if (!record || record.expiresAt < Date.now()) {
    // Clean up expired token
    if (record) tokenStore.delete(tokenHash);
    res.clearCookie('remember_me', { path: '/' });
    return next();
  }

  try {
    // Fetch user from DB
    const user = await db.getUserById(record.userId);
    if (user) {
      req.user = user;
      // Optionally refresh token expiry on activity
      record.expiresAt = Date.now() + 30 * 24 * 60 * 60 * 1000;
    } else {
