const crypto = require('crypto');

// Postgres connection pool (configure via env vars)
const pool = new Pool({
  connectionString: process.env.DATABASE_URL,
  // ssl: process.env.NODE_ENV === 'production' ? { rejectUnauthorized: false } : false
});

/**
 * Initialize the api_keys table (run once at startup).
 */
async function initApiKeysTable() {
  await pool.query(`
    CREATE TABLE IF NOT EXISTS api_keys (
      id           BIGSERIAL PRIMARY KEY,
      customer_id  BIGINT       NOT NULL,
      key_prefix   VARCHAR(16)  NOT NULL UNIQUE,   -- first 12 chars of key for fast lookup
      key_hash     BYTEA        NOT NULL,          -- scrypt hash of full key
      salt         BYTEA        NOT NULL,          -- 16-byte salt
      created_at   TIMESTAMPTZ  DEFAULT NOW(),
      last_used_at TIMESTAMPTZ,
      revoked_at   TIMESTAMPTZ
    );
    CREATE INDEX IF NOT EXISTS idx_api_keys_customer ON api_keys(customer_id);
  `);
}

/**
 * Generate a new API key for a customer.
 * Returns the plain key ONCE – store it securely; only the hash is persisted.
 * @param {number|string} customerId
 * @returns {Promise<string>} plain API key (e.g. "sk_abc123def456...")
 */
async function generateApiKey(customerId) {
  // 1. Generate cryptographically secure random key: prefix (8 bytes) + secret (24 bytes)
  const prefixBytes = crypto.randomBytes(8);
  const secretBytes = crypto.randomBytes(24);
  const prefix = prefixBytes.toString('base64url');   // 11 chars, URL-safe
  const secret = secretBytes.toString('base64url');   // 32 chars
  const plainKey = `sk_${prefix}.${secret}`;          // e.g. "sk_abc123def456.ghijklmnopqrstuvwxyz123456"

  // 2. Hash the full plain key with scrypt (N=16384, r=8, p=1, dkLen=32)
  const salt = crypto.randomBytes(16);
  const hash = await new Promise((resolve, reject) => {
    crypto.scrypt(plainKey, salt, 32, { N: 16384, r: 8, p: 1 }, (err, derivedKey) => {
      if (err) reject(err);
      else resolve(derivedKey);
    });
  });

  // 3. Store only hash + salt + prefix (for lookup)
  await pool.query(
    `INSERT INTO api_keys (customer_id, key_prefix, key_hash, salt)
     VALUES ($1, $2, $3, $4)`,
    [customerId, `sk_${prefix}`, hash, salt]
  );

  return plainKey; // caller must show this to the customer immediately
}

/**
 * Verify a presented API key.
 * @param {string} presentedKey - the full key string from the client
 * @returns {Promise<{valid: boolean, customerId?: number, keyId?: number}>}
 */
async function verifyApiKey(presentedKey) {
  // Basic format check
  if (!presentedKey || !presentedKey.startsWith('sk_')) {
    return { valid: false };
  }

  // Extract prefix (everything before the last dot)
  const lastDot = presentedKey.lastIndexOf('.');
  if (lastDot === -1) return { valid: false };
  const prefix = presentedKey.slice(0, lastDot); // includes "sk_"

  // Look up by prefix
  const res = await pool.query(
    `SELECT id, customer_id, key_hash, salt, revoked_at
     FROM api_keys
     WHERE key_prefix = $1`,
    [prefix]
  );

  if (res.rowCount === 0) return { valid: false };
  const row = res.rows[0];

  if (row.revoked_at) return { valid: false };

  // Recompute hash with stored salt
  const computedHash = await new Promise((resolve, reject) => {
    crypto.scrypt(presentedKey, row.salt, 32, { N: 16384, r: 8, p: 1 }, (err, derivedKey) => {
      if (err) reject(err);
      else resolve(derivedKey);
    });
  });

  // Constant-time comparison
  const match = crypto.timingSafeEqual(row.key_hash, computedHash);
  if (!match) return { valid: false };

  // Update last_used_at (non-blocking)
  pool.query(
    `UPDATE api_keys SET last_used_at = NOW() WHERE id = $1`,
    [row.id]
  ).catch(() => {}); // ignore errors

  return { valid: true, customerId: row.customer_id, keyId: row.id };
}

