const { Pool } = require('pg');
const crypto = require('crypto');

// Configure pool (adjust via env vars in production)
const pool = new Pool({
  connectionString: process.env.DATABASE_URL || 'postgres://user:pass@localhost:5432/db',
});

/**
 * Generate a new API key for a customer, store its hash, return the plain key once.
 * @param {string|number} customerId
 * @returns {Promise<string>} plain API key (show to customer only once)
 */
async function generateApiKey(customerId) {
  // 1. Generate high-entropy key
  const rawKey = crypto.randomBytes(32).toString('hex'); // 64 hex chars
  // 2. Generate per-key salt
  const salt = crypto.randomBytes(16).toString('hex');
  // 3. Hash key with salt (SHA-256)
  const hash = crypto.createHash('sha256').update(rawKey + salt).digest('hex');

  // 4. Store in DB
  const sql = `
    INSERT INTO api_keys (customer_id, key_hash, salt)
    VALUES ($1, $2, $3)
    RETURNING id;
  `;
  await pool.query(sql, [customerId, hash, salt]);

  // 5. Return plain key (caller must show it once)
  return rawKey;
}

/**
 * Verify a presented API key against stored hashes.
 * @param {string} presentedKey
 * @returns {Promise<{valid: boolean, customerId: string|number|null}>}
 */
async function verifyApiKey(presentedKey) {
  // Fetch all keys (or index by hash prefix for large tables)
  const sql = `SELECT customer_id, key_hash, salt FROM api_keys;`;
  const { rows } = await pool.query(sql);

  for (const row of rows) {
    const computedHash = crypto
      .createHash('sha256')
      .update(presentedKey + row.salt)
      .digest('hex');
    if (computedHash === row.key_hash) {
      return { valid: true, customerId: row.customer_id };
    }
  }
  return { valid: false, customerId: null };
}

