const { Pool } = require('pg');
const crypto = require('crypto');

const KEY_BYTES = 32;     // 256-bit entropy
const SALT_BYTES = 16;    // 128-bit salt
const HASH_ALGO = 'sha256';

/**
 * Generate a new API key, store its hash, return the plain key (only once).
 * @param {Pool} pool - pg Pool instance
 * @param {string} customerId - your internal customer identifier
 * @returns {Promise<{key: string, keyId: number}>}
 */
async function generateApiKey(pool, customerId) {
  const rawKey = crypto.randomBytes(KEY_BYTES);
  const salt = crypto.randomBytes(SALT_BYTES);
  const hash = crypto.createHash(HASH_ALGO).update(salt).update(rawKey).digest();

  const keyB64 = rawKey.toString('base64url');   // URL-safe, no padding
  const saltB64 = salt.toString('base64');
  const hashB64 = hash.toString('base64');

  const sql = `
    INSERT INTO api_keys (customer_id, key_hash, salt)
    VALUES ($1, decode($2, 'base64'), decode($3, 'base64'))
    RETURNING id;
  `;
  const { rows } = await pool.query(sql, [customerId, hashB64, saltB64]);
  return { key: keyB64, keyId: rows[0].id };
}

/**
 * Validate a presented API key.
 * @param {Pool} pool
 * @param {string} presentedKey - base64url key from client
 * @returns {Promise<{valid: boolean, customerId?: string, keyId?: number}>}
 */
async function validateApiKey(pool, presentedKey) {
  // Look up candidate rows (could be many customers). We fetch hash+salt for all non-revoked keys.
  const sql = `
    SELECT id, customer_id, key_hash, salt
    FROM api_keys
    WHERE revoked_at IS NULL;
  `;
  const { rows } = await pool.query(sql);

  const presentedBuf = Buffer.from(presentedKey, 'base64url');

  for (const row of rows) {
    const hash = crypto.createHash(HASH_ALGO)
      .update(row.salt)
      .update(presentedBuf)
      .digest();

    // Constant-time compare
    if (crypto.timingSafeEqual(hash, row.key_hash)) {
      // Update last_used_at (fire-and-forget)
      pool.query('UPDATE api_keys SET last_used_at = now() WHERE id = $1', [row.id]).catch(() => {});
      return { valid: true, customerId: row.customer_id, keyId: row.id };
    }
  }
  return { valid: false };
}

module.exports = { generateApiKey, validateApiKey };

