 *
 * @param mysqli $conn   Active MySQLi connection.
 * @return array         Associative rows for the current page.
 */
function getProducts(mysqli $conn): array
{
    // --- Input --------------------------------------------------------------
    $page     = max(1, (int)($_GET['page'] ?? 1));
    $perPage  = 12;                                   // items per page
    $offset   = ($page - 1) * $perPage;

    $allowedSort = ['name', 'price', 'created_at'];   // whitelist
    $sortField   = in_array($_GET['sort'] ?? '', $allowedSort, true)
                 ? $_GET['sort']
                 : 'created_at';
    $sortDir     = (strtoupper($_GET['dir'] ?? 'DESC') === 'ASC') ? 'ASC' : 'DESC';

    $search      = trim($_GET['q'] ?? '');

    // --- Query --------------------------------------------------------------
    $sql = "SELECT id, name, price, created_at
            FROM products
            WHERE 1";

    $params = [];
    $types  = '';

    if ($search !== '') {
        $sql .= " AND name LIKE ?";
        $params[] = "%{$search}%";
        $types   .= 's';
    }

    $sql .= " ORDER BY {$sortField} {$sortDir} LIMIT ? OFFSET ?";
    $params[] = $perPage;
    $params[] = $offset;
    $types   .= 'ii';

    $stmt = $conn->prepare($sql);
    if (!$stmt) {
        error_log('Product list prepare failed: ' . $conn->error);
        return [];
    }

    $stmt->bind_param($types, ...$params);
    $stmt->execute();
    $result = $stmt->get_result();

    $rows = $result ? $result->fetch_all(MYSQLI_ASSOC) : [];
    $stmt->close();

    return $rows;
}
