import subprocess
import re
import sys
from typing import Tuple, Optional


def ping_host(hostname: str, count: int = 4) -> Tuple[bool, Optional[float]]:
    """
    Ping a hostname using the system ping command (Linux/macOS).
    Returns (reachable, average_rtt_ms). If unreachable, average_rtt_ms is None.
    """
    # Build command: ping -c <count> <hostname>
    cmd = ["ping", "-c", str(count), hostname]

    try:
        result = subprocess.run(
            cmd,
            capture_output=True,
            text=True,
            timeout=10  # seconds
        )
    except subprocess.TimeoutExpired:
        return False, None
    except FileNotFoundError:
        raise RuntimeError("ping command not found")

    # Non-zero exit code means unreachable
    if result.returncode != 0:
        return False, None

    # Parse output for average round-trip time
    # Linux: "rtt min/avg/max/mdev = 1.234/2.345/3.456/0.123 ms"
    # macOS: "round-trip min/avg/max/stddev = 1.234/2.345/3.456/0.123 ms"
    output = result.stdout
    # Find line containing rtt or round-trip
    for line in output.splitlines():
        if "rtt" in line or "round-trip" in line:
            # Extract numbers after '=' or ':'
            match = re.search(r"[=:]\s*([\d.]+)/([\d.]+)/([\d.]+)/([\d.]+)\s*ms", line)
            if match:
                avg = float(match.group(2))
                return True, avg
            # Fallback: split by '/' after '='
            parts = line.split("=")[-1].strip().split("/")
            if len(parts) >= 2:
                try:
                    avg = float(parts[1])
                    return True, avg
                except ValueError:
                    pass

    # If parsing fails, assume reachable but unknown RTT
    return True, None


# Example usage
if __name__ == "__main__":
    if len(sys.argv) > 1:
        host = sys.argv[1]
        reachable, avg_rtt = ping_host(host)
        if reachable:
            print(f"{host} is reachable", end="")
            if avg_rtt is not None:
                print(f", avg RTT = {avg_rtt:.3f} ms")
            else:
                print(" (RTT unknown)")
        else:
            print(f"{host} is unreachable")
    else:
        print("Usage: python ping_util.py <hostname>")

