/**
 * Creates a thumbnail using ImageMagick's `convert` CLI.
 * @param {string} inputPath  - Absolute path to the source image.
 * @param {string} outputPath - Absolute path where the thumbnail will be written.
 * @param {number} width      - Desired thumbnail width (height is scaled proportionally).
 * @returns {Promise<void>}   - Resolves when conversion finishes, rejects on error.
 */
async function createThumbnail(inputPath, outputPath, width) {
  // Basic validation – prevent command injection & ensure files exist.
  if (!inputPath || !outputPath || typeof width !== 'number' || width <= 0) {
    throw new Error('Invalid arguments');
  }
  await fs.access(inputPath);               // throws if input missing
  await fs.mkdir(path.dirname(outputPath), { recursive: true });

  // ImageMagick arguments: resize keeping aspect ratio, strip metadata, set quality.
  const args = [
    inputPath,
    '-resize', `${width}>`,   // only shrink, never enlarge
    '-strip',                 // remove profiles/comments
    '-quality', '85',         // reasonable JPEG quality
    outputPath
  ];

  return new Promise((resolve, reject) => {
    const proc = spawn('convert', args, { windowsHide: true });

    let stderr = '';
    proc.stderr.on('data', chunk => (stderr += chunk.toString()));

    proc.on('error', err => reject(new Error(`Failed to start convert: ${err.message}`)));
    proc.on('close', code => {
      if (code === 0) resolve();
      else reject(new Error(`convert exited with code ${code}: ${stderr.trim()}`));
    });
  });
}

