const crypto = require('crypto');

// Secret key for HMAC; in production, set via environment variable
const SECRET = process.env.SIGNING_SECRET || 'default-secret-change-me';

/**
 * Generate a signed query string for a download URL.
 * @param {string} path - The resource path.
 * @param {number|Date} expiresAt - Expiration timestamp (ms since epoch) or Date object.
 * @returns {string} Query string including leading '?'.
 */
function sign(path, expiresAt) {
  const expiry = expiresAt instanceof Date ? expiresAt.getTime() : expiresAt;
  const message = `${path}:${expiry}`;
  const signature = crypto.createHmac('sha256', SECRET).update(message).digest('hex');
  const params = new URLSearchParams({
    path,
    expires: expiry.toString(),
    signature
  });
  return `?${params.toString()}`;
}

/**
 * Verify a signed query string.
 * @param {string} query - Query string (with or without leading '?').
 * @returns {boolean} True if signature valid and not expired.
 */
function verify(query) {
  const searchParams = new URLSearchParams(query.startsWith('?') ? query.slice(1) : query);
  const path = searchParams.get('path');
  const expiresStr = searchParams.get('expires');
  const signature = searchParams.get('signature');
  if (!path || !expiresStr || !signature) return false;

  const expires = parseInt(expiresStr, 10);
  if (isNaN(expires)) return false;

  // Check expiration
  if (Date.now() > expires) return false;

  // Recompute signature
  const message = `${path}:${expires}`;
  const expectedSignature = crypto.createHmac('sha256', SECRET).update(message).digest('hex');

  // Constant-time comparison
  const sigBuffer = Buffer.from(signature, 'hex');
  const expectedBuffer = Buffer.from(expectedSignature, 'hex');
  if (sigBuffer.length !== expectedBuffer.length) return false;
  return crypto.timingSafeEqual(sigBuffer, expectedBuffer);
}

module.exports = { sign, verify };

import os
from flask import Flask, request, jsonify, send_from_directory
from werkzeug.utils import secure_filename

app = Flask(__name__)

UPLOAD_FOLDER = './uploads'
ALLOWED_EXTENSIONS = {'png', 'jpg', 'jpeg'}

app.config['UPLOAD_FOLDER'] = UPLOAD_FOLDER
os.makedirs(UPLOAD_FOLDER, exist_ok=True)

def allowed_file(filename):
    return '.' in filename and filename.rsplit('.', 1)[1].lower() in ALLOWED_EXTENSIONS

@app.route('/avatar', methods=['POST'])
def upload_avatar():
    # Check if the request contains a file part
    if 'file' not in request.files:
        return jsonify({'error': 'No file part'}), 400

    file = request.files['file']

    # If user does not select file, browser may submit an empty part
    if file.filename == '':
        return jsonify({'error': 'No selected file'}), 400

    if not allowed_file(file.filename):
        return jsonify({'error': 'Unsupported file type. Only PNG and JPEG are allowed.'}), 400

    # Secure the filename and save
    filename = secure_filename(file.filename)
    save_path = os.path.join(app.config['UPLOAD_FOLDER'], filename)
    file.save(save_path)

    # Construct URL to fetch the uploaded avatar
    file_url = request.host_url.rstrip('/') + '/uploads/' + filename
    return jsonify({'url': file_url}), 201

@app.route('/uploads/<filename>')
def serve_uploaded_file(filename):
    return send_from_directory(app.config['UPLOAD_FOLDER'], filename)

if __name__ == '__main__':
    app.run(debug=True)

