from fastapi import FastAPI, Request, HTTPException, Header
from fastapi.responses import JSONResponse
import subprocess
import hmac
import hashlib
import os

app = FastAPI()

# GitHub secret for verifying webhook signatures (set in env)
GITHUB_SECRET = os.getenv("GITHUB_WEBHOOK_SECRET", "").encode()

def verify_signature(payload: bytes, signature: str) -> bool:
    """Validate X-Hub-Signature-256 header."""
    if not GITHUB_SECRET:
        return True  # skip verification if secret not set
    expected = "sha256=" + hmac.new(GITHUB_SECRET, payload, hashlib.sha256).hexdigest()
    return hmac.compare_digest(expected, signature)

@app.post("/github/webhook")
async def github_webhook(
    request: Request,
    x_hub_signature_256: str = Header(None),
    x_github_event: str = Header(None),
):
    # Only handle push events
    if x_github_event != "push":
        return JSONResponse({"msg": "ignored"}, status_code=200)

    payload = await request.body()

    # Verify signature
    if not verify_signature(payload, x_hub_signature_256 or ""):
        raise HTTPException(status_code=400, detail="Invalid signature")

    data = await request.json()
    ref = data.get("ref", "")
    # Only deploy on pushes to main branch
    if ref != "refs/heads/main":
        return JSONResponse({"msg": "not main branch"}, status_code=200)

    branch = "main"
    try:
        # Run deploy script with branch name as argument
        result = subprocess.run(
            ["./deploy.sh", branch],
            check=True,
            capture_output=True,
            text=True,
        )
        return JSONResponse({"msg": "deploy triggered", "output": result.stdout})
    except subprocess.CalledProcessError as e:
        raise HTTPException(status_code=500, detail=f"Deploy failed: {e.stderr}")

