#!/usr/bin/env python3
import argparse
import json
import subprocess
import sys
import boto3
from botocore.exceptions import ClientError


def parse_args():
    parser = argparse.ArgumentParser(description="Backup MySQL database to S3")
    parser.add_argument("--host", help="MySQL host")
    parser.add_argument("--database", help="Database name")
    parser.add_argument("--user", help="MySQL user")
    parser.add_argument("--password", help="MySQL password")
    parser.add_argument("--bucket", help="S3 bucket name")
    parser.add_argument("--key", help="S3 object key (default: <database>-<timestamp>.sql)")
    parser.add_argument("--config", help="Path to JSON config file")
    parser.add_argument("--region", default="us-east-1", help="AWS region")
    return parser.parse_args()


def load_config(path):
    with open(path) as f:
        return json.load(f)


def get_config(args):
    config = {}
    if args.config:
        config = load_config(args.config)
    # CLI args override config file
    for k in ["host", "database", "user", "password", "bucket", "key", "region"]:
        v = getattr(args, k)
        if v is not None:
            config[k] = v
    required = ["host", "database", "user", "password", "bucket"]
    for r in required:
        if r not in config:
            sys.exit(f"Missing required parameter: {r}")
    return config


def run_mysqldump(host, database, user, password):
    cmd = [
        "mysqldump",
        f"--host={host}",
        f"--user={user}",
        f"--password={password}",
        "--single-transaction",
        "--routines",
        "--triggers",
        database,
    ]
    proc = subprocess.Popen(cmd, stdout=subprocess.PIPE, stderr=subprocess.PIPE)
    return proc


def upload_to_s3(bucket, key, fileobj, region):
    s3 = boto3.client("s3", region_name=region)
    try:
        s3.upload_fileobj(fileobj, bucket, key)
    except ClientError as e:
        sys.exit(f"S3 upload failed: {e}")


def main():
    args = parse_args()
    cfg = get_config(args)

    key = cfg.get("key") or f"{cfg['database']}-backup.sql"

    dump = run_mysqldump(cfg["host"], cfg["database"], cfg["user"], cfg["password"])
    try:
        upload_to_s3(cfg["bucket"], key, dump.stdout, cfg["region"])
    finally:
        dump.wait()
        stderr = dump.stderr.read().decode()
        if dump.returncode != 0:
            sys.exit(f"mysqldump failed: {stderr}")


if __name__ == "__main__":
    main()

