def _is_sensitive(key: str) -> bool:
    """Check if a configuration key likely contains sensitive data."""
    key_lower = key.lower()
    return any(s in key_lower for s in SENSITIVE_KEYS)

def _redact_value(key: str, value: Any) -> Any:
    """Redact sensitive values while preserving structure."""
    if _is_sensitive(key):
        if isinstance(value, str) and value:
            return f"***REDACTED*** (len={len(value)})"
        return "***REDACTED***"
    return value

def _sanitize_dict(d: Dict[str, Any], prefix: str = "") -> Dict[str, Any]:
    """Recursively sanitize a configuration dictionary."""
    result = {}
    for k, v in d.items():
        full_key = f"{prefix}.{k}" if prefix else k
        if isinstance(v, dict):
            result[k] = _sanitize_dict(v, full_key)
        elif isinstance(v, list):
            result[k] = [
                _sanitize_dict(item, f"{full_key}[{i}]") if isinstance(item, dict)
                else _redact_value(full_key, item)
                for i, item in enumerate(v)
            ]
        else:
            result[k] = _redact_value(full_key, v)
    return result

