// app.js - Express entry point with MongoDB connection and /health endpoint
require('dotenv').config();
const express = require('express');
const mongoose = require('mongoose');

const app = express();
const PORT = process.env.PORT || 3000;
const MONGODB_URI = process.env.MONGODB_URI || 'mongodb://localhost:27017/myapp';

// Middleware to parse JSON bodies
app.use(express.json());

// Health check route
app.get('/health', (req, res) => {
  const dbState = mongoose.connection.readyState; // 1 = connected
  res.json({
    status: 'ok',
    mongodb: dbState === 1 ? 'connected' : 'disconnected',
    uptime: process.uptime()
  });
});

// Connect to MongoDB
mongoose.connect(MONGODB_URI, {
  // Use new URL parser and unified topology (default in Mongoose 6+)
})
  .then(() => {
    console.log(`✅ Connected to MongoDB: ${maskUri(MONGODB_URI)}`);
    // Start HTTP server after successful DB connection
    app.listen(PORT, () => {
      console.log(`🚀 Server listening on http://localhost:${PORT}`);
    });
  })
  .catch(err => {
    console.error('❌ MongoDB connection error:', err);
    process.exit(1);
  });

// Helper to hide credentials in logs
function maskUri(uri) {
  try {
    const url = new URL(uri);
    if (url.password) url.password = '****';
    return url.toString();
  } catch {
    return uri; // fallback
  }
}

const express = require('express');
const { MongoClient } = require('mongodb');

// Config with sensible defaults for local development
const config = {
  port: process.env.PORT || 3000,
  mongoUri: process.env.MONGODB_URI || 'mongodb://localhost:27017',
  dbName: process.env.MONGODB_DB || 'app_dev',
};

const app = express();
let db = null;
let mongoClient = null;

// Health check endpoint
app.get('/health', async (req, res) => {
  const health = {
    status: 'ok',
    timestamp: new Date().toISOString(),
    mongodb: 'disconnected',
  };

  if (db) {
    try {
      // Ping the database to verify connection
      await db.admin().ping();
      health.mongodb = 'connected';
    } catch (err) {
      health.mongodb = 'error';
      health.status = 'degraded';
    }
  } else {
    health.status = 'degraded';
  }

  const statusCode = health.status === 'ok' ? 200 : 503;
  res.status(statusCode).json(health);
});

// Connect to MongoDB
async function connectToMongo() {
  try {
    mongoClient = new MongoClient(config.mongoUri, {
      serverSelectionTimeoutMS: 5000,
    });
    await mongoClient.connect();
    db = mongoClient.db(config.dbName);

    // Log connection details for developers
    const host = mongoClient.topology?.s?.options?.hosts?.[0] || 'unknown';
    console.log(`[startup] MongoDB connected`);
    console.log(`[startup]   URI: ${config.mongoUri}`);
    console.log(`[startup]   Database: ${config.dbName}`);
    console.log(`[startup]   Host: ${host}`);
  } catch (err) {
    console.error('[startup] MongoDB connection failed:', err.message);
    throw err;
  }
}

// Graceful shutdown
async function shutdown(signal) {
  console.log(`[shutdown] Received ${signal}, closing connections...`);
  if (mongoClient) {
    await mongoClient.close();
    console.log('[shutdown] MongoDB connection closed');
  }
  process.exit(0);
}

process.on('SIGTERM', () => shutdown('SIGTERM'));
process.on('SIGINT', () => shutdown('SIGINT'));

// Start server
async function start() {
  try {
    await connectToMongo();
    app.listen(config.port, () => {
      console.log(`[startup] HTTP server listening on http://localhost:${config.port}`);
      console.log(`[startup] Health endpoint: http://localhost:${config.port}/health`);
    });
  } catch (err) {
    console.error('[startup] Failed to start:', err.message);
    process.exit(1);
  }
}

start();

