require('dotenv').config();
const express = require('express');
const mongoose = require('mongoose');

const {
  MONGODB_URI = 'mongodb://localhost:27017/dev',
  PORT = 3000,
  NODE_ENV = 'development'
} = process.env;

const app = express();
app.use(express.json());

// Health check endpoint
app.get('/health', async (req, res) => {
  const dbState = mongoose.connection.readyState; // 0=disconnected, 1=connected, 2=connecting, 3=disconnecting
  const states = ['disconnected', 'connected', 'connecting', 'disconnecting'];
  res.json({
    status: 'ok',
    timestamp: new Date().toISOString(),
    environment: NODE_ENV,
    mongodb: states[dbState] || 'unknown'
  });
});

// Connect to MongoDB with logging
async function connectMongo() {
  mongoose.set('strictQuery', true);
  try {
    await mongoose.connect(MONGODB_URI, {
      autoIndex: NODE_ENV !== 'production',
      serverSelectionTimeoutMS: 5000
    });
    console.log(`[MongoDB] Connected to ${mongoose.connection.host}:${mongoose.connection.port}/${mongoose.connection.name}`);
    console.log(`[MongoDB] Ready state: ${mongoose.connection.readyState} (1=connected)`);
  } catch (err) {
    console.error('[MongoDB] Connection failed:', err.message);
    process.exit(1);
  }
}

// Connection event logging
mongoose.connection.on('connected', () => console.log('[MongoDB] Event: connected'));
mongoose.connection.on('disconnected', () => console.log('[MongoDB] Event: disconnected'));
mongoose.connection.on('error', (err) => console.error('[MongoDB] Event: error', err.message));

// Start server
async function start() {
  await connectMongo();
  const server = app.listen(PORT, () => {
    console.log(`[Server] Listening on http://localhost:${PORT}`);
    console.log(`[Server] Environment: ${NODE_ENV}`);
    console.log(`[Server] Health check: http://localhost:${PORT}/health`);
  });

  // Graceful shutdown
  const shutdown = async (signal) => {
    console.log(`\n[Server] Received ${signal}, shutting down...`);
    server.close(async () => {
      await mongoose.connection.close();
      console.log('[Server] Closed');
      process.exit(0);
    });
    // Force exit after 10s
    setTimeout(() => process.exit(1), 10000);
  };
  process.on('SIGTERM', () => shutdown('SIGTERM'));
  process.on('SIGINT', () => shutdown('SIGINT'));
}

start();
