    """JSON decoder hook to restore datetime and dataclass instances."""
    if "__type__" in dct and dct["__type__"] == "datetime":
        return datetime.fromisoformat(dct["value"])
    if "__dataclass__" in dct:
        class_name = dct.pop("__dataclass__")
        module_name = dct.pop("__module__", "__main__")
        # Reconstruct dataclass - assumes Preference is importable
