    """Serialize settings object to URL-safe base64-encoded JSON bytes."""
    json_str = json.dumps(obj, cls=SettingsEncoder, separators=(",", ":"))
    return base64.urlsafe_b64encode(json_str.encode("utf-8"))

def load_user_settings(blob: bytes) -> Any:
