from typing import Any

def _default_encoder(obj: Any) -> Any:
    """JSON serializer for dates and dataclasses."""
    if isinstance(obj, datetime.datetime):
        return {"__type__": "datetime", "value": obj.isoformat()}
    if isinstance(obj, datetime.date):
        return {"__type__": "date", "value": obj.isoformat()}
    if dataclasses.is_dataclass(obj):
        fields = {f.name: getattr(obj, f.name) for f in dataclasses.fields(obj)}
        return {
            "__dataclass__": f"{obj.__class__.__module__}.{obj.__class__.__qualname__}",
            "fields": fields
        }
    raise TypeError(f"Object of type {type(obj).__name__} is not JSON serializable")

def _object_hook(dct: dict) -> Any:
    """JSON deserializer for dates and dataclasses."""
    if "__type__" in dct:
        if dct["__type__"] == "datetime":
            return datetime.datetime.fromisoformat(dct["value"])
        if dct["__type__"] == "date":
            return datetime.date.fromisoformat(dct["value"])
    if "__dataclass__" in dct:
        class_path = dct["__dataclass__"]
        module_name, class_name = class_path.rsplit(".", 1)
        module = importlib.import_module(module_name)
        cls = getattr(module, class_name)
        # fields dict already processed by object_hook recursively
        return cls(**dct["fields"])
    return dct

def save_user_settings(obj: Any) -> bytes:
    """Serialize preferences object to a UTF-8 JSON byte blob."""
    json_str = json.dumps(obj, default=_default_encoder, separators=(",", ":"))
    return json_str.encode("utf-8")

def load_user_settings(blob: bytes) -> Any:
    """Deserialize preferences object from a UTF-8 JSON byte blob."""
    json_str = blob.decode("utf-8")
    return json.loads(json_str, object_hook=_object_hook)
