def save_user_settings(obj: Any) -> bytes:
    """Serialize preferences object (dicts, lists, dates, dataclasses) to UTF-8 JSON bytes."""
    def default(o: Any) -> Dict:
        # Handle date/datetime
        if isinstance(o, (datetime.date, datetime.datetime)):
            return {"__type__": "datetime", "value": o.isoformat()}
        # Handle any dataclass (including nested)
        if dataclasses.is_dataclass(o):
            fields = {f.name: getattr(o, f.name) for f in dataclasses.fields(o)}
            fields["__type__"] = "dataclass"
            fields["__class__"] = f"{o.__class__.__module__}.{o.__class__.__qualname__}"
            return fields
        raise TypeError(f"Object of type {type(o).__name__} is not JSON serializable")

    json_str = json.dumps(obj, default=default)
    return json_str.encode("utf-8")


def load_user_settings(blob: bytes) -> Any:
    """Deserialize UTF-8 JSON bytes back to preferences object with dates and dataclasses restored."""
    def object_hook(d: Dict) -> Any:
        if "__type__" not in d:
            return d

        if d["__type__"] == "datetime":
            # datetime.datetime.fromisoformat handles both date and datetime strings
            return datetime.datetime.fromisoformat(d["value"])

        if d["__type__"] == "dataclass":
            class_path = d.pop("__class__")
            d.pop("__type__")
            module_name, class_name = class_path.rsplit(".", 1)
            module = __import__(module_name, fromlist=[class_name])
            cls = getattr(module, class_name)
            # Remaining keys are field values (already decoded by recursive object_hook)
            return cls(**d)

        return d

    json_str = blob.decode("utf-8")
    return json.loads(json_str, object_hook=object_hook)

