import xml.etree.ElementTree as ET
from typing import Dict, List, Union, BinaryIO

def parse_invoice_xml(source: Union[str, BinaryIO]) -> Dict:
    """
    Parse an XML invoice file and extract total amount, customer name, and line items.

    Args:
        source: File path (str) or binary file-like object.

    Returns:
        Dict with keys: 'total_amount' (float), 'customer_name' (str), 'line_items' (List[Dict]).
    """
    tree = ET.parse(source)
    root = tree.getroot()

    # Helper to find text by tag (case-insensitive, first match)
    def find_text(tag: str) -> str:
        for elem in root.iter():
            if elem.tag.lower() == tag.lower() and elem.text:
                return elem.text.strip()
        return ""

    # Helper to find float value by tag
    def find_float(tag: str) -> float:
        text = find_text(tag)
        try:
            return float(text) if text else 0.0
        except ValueError:
            return 0.0

    # Extract customer name (common tags)
    customer_name = find_text("CustomerName") or find_text("Name") or find_text("Customer")

    # Extract total amount (common tags)
    total_amount = find_float("TotalAmount") or find_float("Total") or find_float("InvoiceTotal")

    # Extract line items (assume each <LineItem> has child elements)
    line_items: List[Dict] = []
    for item_elem in root.iter():
        if item_elem.tag.lower() == "lineitem":
            item = {}
            for child in item_elem:
                key = child.tag.lower()
                val = child.text.strip() if child.text else ""
                # Convert numeric fields
                if key in {"quantity", "unitprice", "price", "amount", "total"}:
                    try:
                        val = float(val)
                    except ValueError:
                        pass
                item[key] = val
            if item:
                line_items.append(item)

    return {
        "total_amount": total_amount,
        "customer_name": customer_name,
        "line_items": line_items
    }
