// Configure allowed origins - easy to update as partners are added
const partnerOrigins = [
  'https://our-web-app.com',
  'https://partner1.example.com',
  'https://partner2.example.com'
];

app.use(createCorsMiddleware(partnerOrigins));

// To add new partners at runtime:
function addPartner(origin) {
  partnerOrigins.push(origin);
  // allowlist is recreated on each request via closure, so no restart needed
}

module.exports = { createCorsMiddleware, addPartner };

const corsMiddleware = (options = {}) => {
  const {
    allowlist = [],
    allowlistFn = null,
    credentials = true,
    methods = ['GET', 'POST', 'PUT', 'PATCH', 'DELETE', 'OPTIONS'],
    allowedHeaders = ['Content-Type', 'Authorization', 'X-Requested-With'],
    exposedHeaders = [],
    maxAge = 86400
  } = options;

  const isOriginAllowed = (origin) => {
    if (!origin) return false;
    if (allowlistFn && typeof allowlistFn === 'function') {
      return allowlistFn(origin);
    }
    return allowlist.includes(origin) || allowlist.includes('*');
  };

  return (req, res, next) => {
    const origin = req.headers.origin;
    const isAllowed = isOriginAllowed(origin);

    if (isAllowed) {
      res.setHeader('Access-Control-Allow-Origin', origin);
      if (credentials) {
        res.setHeader('Access-Control-Allow-Credentials', 'true');
      }
      if (exposedHeaders.length) {
        res.setHeader('Access-Control-Expose-Headers', exposedHeaders.join(', '));
      }
    }

    if (req.method === 'OPTIONS') {
      if (isAllowed) {
        res.setHeader('Access-Control-Allow-Methods', methods.join(', '));
        res.setHeader('Access-Control-Allow-Headers', allowedHeaders.join(', '));
        if (maxAge) {
          res.setHeader('Access-Control-Max-Age', maxAge.toString());
        }
        return res.sendStatus(204);
      }
      return res.sendStatus(403);
    }

    next();
  };
};

module.exports = corsMiddleware;

