const cors = require('cors');

/**
 * Configurable CORS middleware for Express
 * @param {Object} options - Configuration options
 * @param {string[]|Function} options.allowedOrigins - Array of allowed origins or function(origin, callback)
 * @param {string[]} [options.allowedMethods=['GET','POST','PUT','PATCH','DELETE','OPTIONS']]
 * @param {string[]} [options.allowedHeaders=['Content-Type','Authorization','X-Requested-With']]
 * @param {boolean} [options.credentials=true]
 * @param {number} [options.maxAge=86400] - Preflight cache duration in seconds
 */
function createCorsMiddleware(options = {}) {
  const {
    allowedOrigins = [],
    allowedMethods = ['GET', 'POST', 'PUT', 'PATCH', 'DELETE', 'OPTIONS'],
    allowedHeaders = ['Content-Type', 'Authorization', 'X-Requested-With'],
    credentials = true,
    maxAge = 86400
  } = options;

  // Normalize allowedOrigins to a function for dynamic checking
  const originChecker = typeof allowedOrigins === 'function'
    ? allowedOrigins
    : (origin, callback) => {
        if (!origin || allowedOrigins.includes(origin)) {
          callback(null, true);
        } else {
          callback(new Error('Not allowed by CORS'), false);
        }
      };

  const corsOptions = {
    origin: originChecker,
    methods: allowedMethods,
    allowedHeaders,
    credentials,
    maxAge,
    optionsSuccessStatus: 204 // Some legacy browsers choke on 204
  };

  return cors(corsOptions);
}

