    allowlist = [],
    methods = ['GET', 'POST', 'PUT', 'PATCH', 'DELETE', 'OPTIONS'],
    allowedHeaders = ['Content-Type', 'Authorization', 'X-Requested-With'],
    exposedHeaders = [],
    maxAge = 86400,
    credentials = true
  } = options;

  // Normalize allowlist to function for consistent handling
  const isOriginAllowed = typeof allowlist === 'function'
    ? allowlist
    : (origin, callback) => {
        if (!origin || allowlist.includes(origin) || allowlist.includes('*')) {
          callback(null, true);
        } else {
