/**
 * CORS middleware with configurable allowlist and credentials support
 * @param {Object} options - Configuration options
 * @param {string[]} options.allowlist - Allowed origins (exact match or regex patterns)
 * @param {string} options.webAppOrigin - Primary web app origin
 * @param {boolean} options.credentials - Allow credentials (cookies, auth headers)
 * @param {number} options.maxAge - Preflight cache duration in seconds
 */
function createCorsMiddleware({ 
  allowlist = [], 
  webAppOrigin, 
  credentials = true, 
  maxAge = 86400 
}) {
  // Normalize allowlist: ensure web app origin is included
  const origins = new Set([webAppOrigin, ...allowlist].filter(Boolean));

  // Check if origin is allowed (supports exact match and regex patterns)
  function isOriginAllowed(origin) {
    if (!origin) return false;
    for (const allowed of origins) {
      if (allowed instanceof RegExp) {
        if (allowed.test(origin)) return true;
      } else if (allowed === origin || allowed === '*') {
        return true;
      }
    }
    return false;
  }

  return (req, res, next) => {
    const origin = req.headers.origin;
    const isAllowed = isOriginAllowed(origin);

    // Set CORS headers for allowed origins
    if (isAllowed) {
      res.setHeader('Access-Control-Allow-Origin', origin);
      res.setHeader('Vary', 'Origin');
    }

    if (credentials) {
      res.setHeader('Access-Control-Allow-Credentials', 'true');
    }

    // Handle preflight OPTIONS requests
    if (req.method === 'OPTIONS') {
      // Required headers for preflight
      res.setHeader('Access-Control-Allow-Methods', 'GET,HEAD,PUT,PATCH,POST,DELETE,OPTIONS');
      res.setHeader('Access-Control-Allow-Headers', 'Content-Type,Authorization,X-Requested-With,Accept,Origin');
      res.setHeader('Access-Control-Max-Age', maxAge.toString());

      // Respond to preflight
      return res.sendStatus(204);
    }

    // Expose headers for client access
    res.setHeader('Access-Control-Expose-Headers', 'Content-Length,Content-Range,X-Request-Id');

    next();
  };
}

