function createCorsMiddleware({ allowlist = [], allowlistFn, credentials = true, methods, headers, maxAge = 86400 }) {
  const defaultMethods = ['GET', 'POST', 'PUT', 'PATCH', 'DELETE', 'OPTIONS'];
  const defaultHeaders = ['Content-Type', 'Authorization', 'X-Requested-With', 'Accept', 'Origin'];

  const isOriginAllowed = (origin, callback) => {
    if (!origin) return callback(null, true); // non-browser requests

    const staticAllowed = allowlist.includes(origin);
    const dynamicAllowed = allowlistFn ? allowlistFn(origin) : false;

    if (staticAllowed || dynamicAllowed) {
      callback(null, true);
    } else {
      callback(new Error(`CORS: Origin ${origin} not allowed`), false);
    }
  };

  const corsOptions = {
    origin: isOriginAllowed,
    credentials,
    methods: methods || defaultMethods,
    allowedHeaders: headers || defaultHeaders,
    exposedHeaders: ['X-Total-Count', 'X-Request-ID'],
    maxAge,
    preflightContinue: false,
    optionsSuccessStatus: 204
  };

  const corsMiddleware = cors(corsOptions);

  // Explicit OPTIONS handler for preflight (cors handles this, but explicit is clearer)
  return (req, res, next) => {
    if (req.method === 'OPTIONS') {
      return corsMiddleware(req, res, () => {
        res.status(204).end();
      });
    }
    corsMiddleware(req, res, next);
  };
}

