const express = require('express');

/**
 * Configurable CORS middleware for API with credential support
 * @param {Object} options - Configuration options
 * @param {string[]} options.allowedOrigins - List of allowed origins (exact match)
 * @param {RegExp[]} [options.allowedOriginPatterns] - Regex patterns for dynamic origins
 * @param {string[]} [options.allowedMethods] - HTTP methods to allow
 * @param {string[]} [options.allowedHeaders] - Headers to allow in requests
 * @param {string[]} [options.exposedHeaders] - Headers to expose to clients
 * @param {number} [options.maxAge] - Preflight cache duration in seconds
 */
function corsMiddleware(options = {}) {
  const {
    allowedOrigins = [],
    allowedOriginPatterns = [],
    allowedMethods = ['GET', 'POST', 'PUT', 'PATCH', 'DELETE', 'OPTIONS'],
    allowedHeaders = ['Content-Type', 'Authorization', 'X-Requested-With', 'Accept', 'Origin'],
    exposedHeaders = [],
    maxAge = 86400 // 24 hours
  } = options;

  // Build allowlist for quick lookup
  const originAllowlist = new Set(allowedOrigins);

  function isOriginAllowed(origin) {
    if (!origin) return false;
    if (originAllowlist.has(origin)) return true;
    return allowedOriginPatterns.some(pattern => pattern.test(origin));
  }

  function setCorsHeaders(res, origin) {
    res.setHeader('Access-Control-Allow-Origin', origin);
    res.setHeader('Access-Control-Allow-Credentials', 'true');
    if (exposedHeaders.length) {
      res.setHeader('Access-Control-Expose-Headers', exposedHeaders.join(', '));
    }
  }

  return (req, res, next) => {
    const origin = req.headers.origin;

    // Handle preflight OPTIONS request
    if (req.method === 'OPTIONS') {
      if (origin && isOriginAllowed(origin)) {
        setCorsHeaders(res, origin);
        res.setHeader('Access-Control-Allow-Methods', allowedMethods.join(', '));
        res.setHeader('Access-Control-Allow-Headers', allowedHeaders.join(', '));
        res.setHeader('Access-Control-Max-Age', maxAge.toString());
        return res.sendStatus(204);
      }
      return res.sendStatus(403);
    }

    // Handle actual requests
    if (origin && isOriginAllowed(origin)) {
      setCorsHeaders(res, origin);
    }

    next();
  };
}

