    allowedHeaders = ['Content-Type', 'Authorization', 'X-Requested-With'],
    exposedHeaders = ['X-Total-Count', 'X-Request-Id'],
    maxAge = 86400, // 24 hours
    credentials = true,
  } = options;

  // Convert to Set for O(1) lookups, allow runtime additions
  const originSet = new Set(allowedOrigins);

  // Public API to add origins dynamically
  const addAllowedOrigin = (origin) => originSet.add(origin);
  const removeAllowedOrigin = (origin) => originSet.delete(origin);
  const getAllowedOrigins = () => Array.from(originSet);

  function isOriginAllowed(origin) {
    if (!origin) return false; // non-browser clients
    return originSet.has(origin);
  }

  function setCorsHeaders(res, origin) {
    res.setHeader('Access-Control-Allow-Origin', origin);
    if (credentials) res.setHeader('Access-Control-Allow-Credentials', 'true');
    if (exposedHeaders.length) res.setHeader('Access-Control-Expose-Headers', exposedHeaders.join(', '));
  }

  function setPreflightHeaders(res, origin) {
    setCorsHeaders(res, origin);
    res.setHeader('Access-Control-Allow-Methods', allowedMethods.join(', '));
    res.setHeader('Access-Control-Allow-Headers', allowedHeaders.join(', '));
    res.setHeader('Access-Control-Max-Age', String(maxAge));
  }

  return Object.assign(
    function corsMiddleware(req, res, next) {
      const origin = req.headers.origin;

      // Handle preflight
      if (req.method === 'OPTIONS') {
        if (isOriginAllowed(origin)) {
          setPreflightHeaders(res, origin);
          return res.sendStatus(204);
        }
        return res.sendStatus(403);
      }

      // Actual request
      if (isOriginAllowed(origin)) {
        setCorsHeaders(res, origin);
      }
      // Vary header ensures caches distinguish by Origin
      res.setHeader('Vary', 'Origin');
      next();
    },
    { addAllowedOrigin, removeAllowedOrigin, getAllowedOrigins }
  );
}

