const cors = require('cors');

/**
 * Configurable CORS middleware for API with credential support
 * @param {Object} options - Configuration options
 * @param {string[]|Function} options.allowedOrigins - Static array or async function(origin) => boolean
 * @param {string} options.allowedMethods - Comma-separated HTTP methods
 * @param {string} options.allowedHeaders - Comma-separated request headers
 * @param {number} options.maxAge - Preflight cache duration in seconds
 */
function createCorsMiddleware({
  allowedOrigins = [],
  allowedMethods = 'GET,HEAD,PUT,PATCH,POST,DELETE,OPTIONS',
  allowedHeaders = 'Content-Type,Authorization,X-Requested-With,Accept,Origin',
  maxAge = 86400
} = {}) {
  // Normalize origins to lowercase for case-insensitive matching
  const originAllowlist = Array.isArray(allowedOrigins)
    ? allowedOrigins.map(o => o.toLowerCase())
    : allowedOrigins;

  const corsOptions = {
    origin: async (origin, callback) => {
      // Allow non-browser requests (no origin header) like mobile apps, curl
      if (!origin) return callback(null, true);

      const normalizedOrigin = origin.toLowerCase();
      let isAllowed = false;

      if (typeof originAllowlist === 'function') {
        // Dynamic validation function (e.g., database lookup)
        isAllowed = await originAllowlist(normalizedOrigin);
      } else {
        // Static allowlist check
        isAllowed = originAllowlist.includes(normalizedOrigin);
      }

      if (isAllowed) {
        callback(null, true);
      } else {
        callback(new Error(`CORS policy: Origin ${origin} not allowed`), false);
      }
    },
    methods: allowedMethods,
    allowedHeaders: allowedHeaders,
    credentials: true, // Required for cookies/auth headers
    maxAge: maxAge,    // Cache preflight response
    optionsSuccessStatus: 204 // Some legacy browsers choke on 200
  };

  return cors(corsOptions);
}

