/**
 * Creates a CORS middleware with configurable allowed origins.
 * @param {Object} options
 * @param {string[]|Function} options.allowedOrigins - Array of origins or async function(origin) => boolean
 * @param {string} options.allowedMethods - Comma-separated HTTP methods
 * @param {string} options.allowedHeaders - Comma-separated request headers
 * @param {string} options.exposedHeaders - Comma-separated headers to expose to client
 * @param {number} options.maxAge - Preflight cache duration in seconds
 * @param {boolean} options.credentials - Allow cookies/auth headers
 */
function createCorsMiddleware({
  allowedOrigins = [],
  allowedMethods = 'GET,HEAD,PUT,PATCH,POST,DELETE,OPTIONS',
  allowedHeaders = 'Content-Type,Authorization,X-Requested-With,Accept,Origin',
  exposedHeaders = '',
  maxAge = 86400,
  credentials = true
} = {}) {
  // Normalize allowlist to a Set for O(1) lookups
  const originSet = new Set(Array.isArray(allowedOrigins) ? allowedOrigins : []);
  const isDynamic = typeof allowedOrigins === 'function';

  return async function corsMiddleware(req, res, next) {
    const requestOrigin = req.headers.origin;

    // Determine if origin is allowed
    let allowOrigin = false;
    if (requestOrigin) {
      if (isDynamic) {
        allowOrigin = await allowedOrigins(requestOrigin);
      } else {
        allowOrigin = originSet.has(requestOrigin);
      }
    }

    // No origin header (non-browser client) — skip CORS headers
    if (!requestOrigin) return next();

    // Origin not allowed — respond 403 but don't leak allowlist
    if (!allowOrigin) {
      return res.status(403).json({ error: 'CORS: Origin not allowed' });
    }

    // Set CORS headers for allowed origin
    res.setHeader('Access-Control-Allow-Origin', requestOrigin);
    if (credentials) res.setHeader('Access-Control-Allow-Credentials', 'true');
    if (exposedHeaders) res.setHeader('Access-Control-Expose-Headers', exposedHeaders);

    // Handle preflight OPTIONS request
    if (req.method === 'OPTIONS') {
      res.setHeader('Access-Control-Allow-Methods', allowedMethods);
      res.setHeader('Access-Control-Allow-Headers', allowedHeaders);
      res.setHeader('Access-Control-Max-Age', String(maxAge));
      return res.sendStatus(204);
    }

    next();
  };
}

module.exports = { createCorsMiddleware };
