```javascript
// corsMiddleware.js
/**
 * Flexible CORS middleware for Express.
 * - allowlist: array of origins OR async function (origin, req) => boolean
 * - credentials: allow cookies/auth headers (default true)
 * - methods/headers: customize allowed methods/headers
 */
function createCorsMiddleware(options = {}) {
  const {
    allowlist = [],
    credentials = true,
    methods = ['GET', 'HEAD', 'POST', 'PUT', 'PATCH', 'DELETE', 'OPTIONS'],
    allowedHeaders = ['Content-Type', 'Authorization', 'X-Requested-With', 'Accept', 'Origin'],
    exposedHeaders = [],
    maxAge = 86400, // 24h preflight cache
    // Called when origin not in allowlist; return true to allow anyway
    fallback = () => false
  } = options;

  // Normalize allowlist to a Set for fast lookup
  const allowlistSet = new Set(Array.isArray(allowlist) ? allowlist : []);

  // Resolve whether an origin is allowed (supports async allowlist fn)
  async function isOriginAllowed(origin, req) {
    if (!origin) return false; // non-browser or same-origin
    if (allowlistSet.has(origin)) return true;
    if (typeof allowlist === 'function') {
      return await allowlist(origin, req);
    }
    return fallback(origin, req);
  }

  return async function corsMiddleware(req, res, next) {
    const origin = req.headers.origin;
    const allowed = await isOriginAllowed(origin, req);

    // Vary: Origin tells caches to vary by Origin header
    res.setHeader('Vary', 'Origin');

    if (!allowed) {
      // Not allowed — don't set CORS headers, let request proceed (or 403 if you prefer)
      return next();
    }

    // Allowed origin — echo it back (not '*') when credentials are used
    res.setHeader('Access-Control-Allow-Origin', origin);
    if (credentials) {
      res.setHeader('Access-Control-Allow-Credentials', 'true');
    }
    if (exposedHeaders.length) {
      res.setHeader('Access-Control-Expose-Headers', exposedHeaders.join(', '));
    }

    // Preflight handling
    if (req.method === 'OPTIONS') {
      res.setHeader('Access-Control-Allow-Methods', methods.join(', '));
      res.setHeader('Access-Control-Allow-Headers', allowedHeaders.join(', '));
      if (maxAge) {
        res.setHeader('Access-Control-Max-Age', String(maxAge));
      }
      // Short-circuit: 204 No Content for preflight
      return res.sendStatus(204);
    }

    next();
  };
}

module.exports = { createCorsMiddleware };
