/**
 * Creates a CORS middleware with configurable origin allowlist.
 * @param {Object} options
 * @param {string[]|Function} options.allowlist - Array of allowed origins or async function(origin) => boolean
 * @param {string} options.webAppOrigin - Primary web app origin (always allowed)
 * @param {boolean} options.credentials - Allow credentials (cookies, auth headers)
 * @param {string[]} options.allowedMethods - HTTP methods to allow
 * @param {string[]} options.allowedHeaders - Request headers to allow
 * @param {string[]} options.exposedHeaders - Response headers to expose
 * @param {number} options.maxAge - Preflight cache duration (seconds)
 */
function createCorsMiddleware({
  allowlist = [],
  webAppOrigin,
  credentials = true,
  allowedMethods = DEFAULT_ALLOWED_METHODS,
  allowedHeaders = DEFAULT_ALLOWED_HEADERS,
  exposedHeaders = DEFAULT_EXPOSED_HEADERS,
  maxAge = 86400 // 24 hours
}) {
  // Normalize allowlist to a Set for O(1) lookups
  const staticAllowlist = new Set(Array.isArray(allowlist) ? allowlist : []);
  if (webAppOrigin) staticAllowlist.add(webAppOrigin);

  // Dynamic checker: supports async functions (e.g., DB lookup for partners)
  const dynamicCheck = typeof allowlist === 'function' ? allowlist : null;

  async function isOriginAllowed(origin) {
    if (!origin) return false; // non-browser or same-origin
    if (staticAllowlist.has(origin)) return true;
    if (dynamicCheck) return await dynamicCheck(origin);
    return false;
  }

  return async function corsMiddleware(req, res, next) {
    const origin = req.headers.origin;
    const allowed = await isOriginAllowed(origin);

    // Set CORS headers only for allowed origins
    if (allowed) {
      res.setHeader('Access-Control-Allow-Origin', origin);
      res.setHeader('Access-Control-Allow-Credentials', 'true');
      res.setHeader('Access-Control-Expose-Headers', exposedHeaders.join(', '));
    }

    // Handle preflight OPTIONS request
    if (req.method === 'OPTIONS') {
      if (!allowed) return res.sendStatus(403);

      res.setHeader('Access-Control-Allow-Methods', allowedMethods.join(', '));
      res.setHeader('Access-Control-Allow-Headers', allowedHeaders.join(', '));
      res.setHeader('Access-Control-Max-Age', String(maxAge));
      return res.sendStatus(204);
    }

    // Vary header ensures caches distinguish by Origin
    res.setHeader('Vary', 'Origin');
    next();
  };
}

module.exports = { createCorsMiddleware };
