// Configurable CORS middleware for Express with credentials support

const DEFAULT_ALLOWED_METHODS = ['GET', 'POST', 'PUT', 'PATCH', 'DELETE', 'OPTIONS'];
const DEFAULT_ALLOWED_HEADERS = ['Content-Type', 'Authorization', 'X-Requested-With', 'Accept', 'Origin'];
const DEFAULT_EXPOSED_HEADERS = ['X-Total-Count', 'X-Page-Count'];

function createCorsMiddleware(options = {}) {
  const {
    // Required: your web app origin(s)
    appOrigins = [],
    // Optional: partner origins (add over time via config/env)
    partnerOrigins = [],
    // Optional: allow all subdomains of listed origins
    allowSubdomains = false,
    // Optional: custom methods/headers
    allowedMethods = DEFAULT_ALLOWED_METHODS,
    allowedHeaders = DEFAULT_ALLOWED_HEADERS,
    exposedHeaders = DEFAULT_EXPOSED_HEADERS,
    // Optional: max age for preflight cache (seconds)
    maxAge = 86400,
    // Optional: custom origin validator function
    customValidator = null
  } = options;

  // Build normalized origin list
  const allowedOrigins = [...new Set([...appOrigins, ...partnerOrigins])]
    .map(o => o.toLowerCase().replace(/^https?:\/\//, ''));

  function isOriginAllowed(requestOrigin) {
    if (!requestOrigin) return false;

    const normalized = requestOrigin.toLowerCase().replace(/^https?:\/\//, '');

    // Exact match
    if (allowedOrigins.includes(normalized)) return true;

    // Subdomain match (e.g., partner.example.com matches *.example.com)
    if (allowSubdomains) {
      return allowedOrigins.some(allowed => 
        normalized === allowed || normalized.endsWith('.' + allowed)
      );
    }

    // Custom validator (e.g., database lookup)
    if (customValidator) return customValidator(requestOrigin);

    return false;
  }

  return (req, res, next) => {
    const origin = req.headers.origin;
    const isAllowed = isOriginAllowed(origin);

    // Set CORS headers for allowed origins
    if (isAllowed) {
      res.setHeader('Access-Control-Allow-Origin', origin);
      res.setHeader('Access-Control-Allow-Credentials', 'true');
      res.setHeader('Access-Control-Expose-Headers', exposedHeaders.join(', '));
    }

    // Handle preflight OPTIONS request
    if (req.method === 'OPTIONS') {
      if (!isAllowed) {
        return res.status(403).end('Origin not allowed');
      }

      res.setHeader('Access-Control-Allow-Methods', allowedMethods.join(', '));
      res.setHeader('Access-Control-Allow-Headers', allowedHeaders.join(', '));
      res.setHeader('Access-Control-Max-Age', maxAge.toString());

      return res.status(204).end();
    }

    // Vary header for caching correctness
    res.setHeader('Vary', 'Origin');

    next();
  };
}

module.exports = { createCorsMiddleware };
