const cors = require('cors');

/**
 * Configurable CORS middleware for API with credential support
 * @param {Object} options - Configuration options
 * @param {Array<string>|Function} options.allowedOrigins - Static list or async function(origin, callback) => boolean
 * @param {string} options.webAppOrigin - Primary web app origin (always allowed)
 * @param {Array<string>} [options.allowedMethods] - HTTP methods to allow
 * @param {Array<string>} [options.allowedHeaders] - Headers to allow in requests
 * @param {number} [options.maxAge] - Preflight cache duration in seconds
 */
function createCorsMiddleware({
  allowedOrigins = [],
  webAppOrigin,
  allowedMethods = ['GET', 'POST', 'PUT', 'PATCH', 'DELETE', 'OPTIONS'],
  allowedHeaders = ['Content-Type', 'Authorization', 'X-Requested-With', 'Accept', 'Origin'],
  maxAge = 86400 // 24 hours
}) {
  const originWhitelist = new Set([webAppOrigin, ...allowedOrigins].filter(Boolean));

  // Normalize origin checker to async function
  const checkOrigin = typeof allowedOrigins === 'function'
    ? allowedOrigins
    : async (origin, callback) => {
        if (!origin) return callback(null, true); // Allow non-browser requests
        const allowed = originWhitelist.has(origin);
        callback(null, allowed);
      };

  const corsOptions = {
    origin: async (origin, callback) => {
      try {
        await checkOrigin(origin, callback);
      } catch (err) {
        callback(err, false);
      }
    },
    credentials: true,
    methods: allowedMethods,
    allowedHeaders: allowedHeaders,
    exposedHeaders: ['X-Total-Count', 'X-Rate-Limit-Remaining'],
    maxAge: maxAge,
    preflightContinue: false,
    optionsSuccessStatus: 204
  };

  return cors(corsOptions);
}

