const express = require('express');
const app = express();

app.get('/go', (req, res) => {
  const target = req.query.url;               // get external URL from query string
  if (!target) {
    return res.status(400).send('Missing "url" query parameter'); // 400 if absent
  }

  // basic validation to avoid open redirects to javascript: or data: schemes
  try {
    const parsed = new URL(target);
    if (!['http:', 'https:'].includes(parsed.protocol)) {
      return res.status(400).send('Invalid URL scheme');
    }
  } catch (e) {
    return res.status(400).send('Malformed URL');
  }

  console.log(`Outbound click: ${target}`);   // log the click
  res.redirect(target);                       // redirect user
});

